import { Book } from "@/lib/types";

export const jeremiah: Book = {
  id: "jeremiah",
  name: "Jeremia",
  shortName: "Jer",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Worte Jeremias, des Sohnes Hilkijas, von den Priestern in Anatot* im Land Benjamin*,", heading: "Jeremias Berufung zum Propheten", footnotes: ["℘ Kap. 32,7; Jos 21,18; Esr 2,23", "℘ Kap. 37,12"] },
      { number: 2, text: "zu dem das Wort des HERRN geschah in den Tagen Josias, des Sohnes Amons, des Königs von Juda*, im dreizehnten Jahr seiner Regierung.", footnotes: ["℘ Kap. 25,3; 2Chr 34,1; Zef 1,1"] },
      { number: 3, text: "Und es geschah auch in den Tagen Jojakims*, des Sohnes Josias, des Königs von Juda*, bis zum Ende des elften Jahres Zedekias*, des Sohnes Josias, des Königs von Juda, bis zur Wegführung Jerusalems* im fünften Monat*.", footnotes: ["℘ 2Kö 23,34", "℘ Hos 14,6", "℘ Kap. 39,2", "d. i. die Umsiedlung eines Teiles der Bevölkerung von Jerusalem nach Babylon", "℘ Kap. 52,12-15"] },
      { number: 4, text: "Und das Wort des HERRN geschah zu mir so:" },
      { number: 5, text: "Ehe ich dich im Mutterleib bildete, habe ich dich erkannt*, und ehe du aus dem Mutterschoß hervorkamst, habe ich dich geheiligt*; zum Propheten für die Nationen habe ich dich eingesetzt.", footnotes: ["℘ Ps 139,15.16", "℘ Joh 10,36"] },
      { number: 6, text: "Da sagte ich: Ach, Herr, HERR! Siehe, ich verstehe nicht zu reden*, denn ich bin zu jung.", footnotes: ["℘ 2Mo 4,10"] },
      { number: 7, text: "Der HERR aber sprach zu mir: Sage nicht: Ich bin zu jung. Denn zu allen, zu denen ich dich sende, sollst du gehen, und alles, was ich dir gebiete, sollst du reden*.", footnotes: ["℘ Kap. 26,2; 43,1; 2Mo 6,29; Hes 3,17; Apg 26,17"] },
      { number: 8, text: "Fürchte dich nicht vor ihnen*! Denn ich bin mit dir*, um dich zu retten, spricht der HERR*.", footnotes: ["℘ Hes 2,6; Mt 10,28", "℘ 5Mo 31,6.8; Jos 1,9; Apg 18,10", "w. ist der Ausspruch des HERRN"] },
      { number: 9, text: "Und der HERR streckte seine Hand aus und rührte meinen Mund an*, und der HERR sprach zu mir: Siehe, ich lege meine Worte in deinen Mund*.", footnotes: ["℘ 2Mo 4,15; Jes 6,6.7", "℘ Kap. 15,19; 34,6; 5Mo 18,18; Jes 59,21"] },
      { number: 10, text: "Siehe, ich habe dich an diesem Tag über die Nationen und über die Königreiche bestellt*, um auszureißen und niederzureißen, zugrunde zu richten und abzubrechen, um zu bauen und zu pflanzen*.", footnotes: ["℘ Offb 10,11", "℘ Kap. 18,7.9; 31,28; Pred 3,3; Hos 6,5"] },
      { number: 11, text: "Und das Wort des HERRN geschah zu mir: Was siehst du*, Jeremia? Und ich sagte: Ich sehe einen Mandelzweig*.", footnotes: ["℘ Kap. 24,3; Jes 55,11; Hes 12,28; Am 8,2", "w. Zweig eines Mandelbaums; das Wort für »Mandelbaum« (der als Erster von allen Bäumen im Frühjahr zu blühen beginnt) klingt im Hebr. ähnlich wie das Wort für »wachsam sein«."] },
      { number: 12, text: "Und der HERR sprach zu mir: Du hast recht gesehen; denn ich werde über meinem Wort wachen, es auszuführen*.", footnotes: ["℘ Kap. 24,3; Jes 55,11; Hes 12,28; Am 8,2"] },
      { number: 13, text: "Und das Wort des HERRN geschah zu mir zum zweiten Mal: Was siehst du*? Und ich sagte: Ich sehe einen siedenden Topf*, dessen Oberfläche von Norden her geneigt ist.*", footnotes: ["℘ Kap. 24,3; Jes 55,11; Hes 12,28; Am 8,2", "w. einen Topf, unter dem das Feuer angeblasen ist\n℘ Hes 11,3.7; 24,3", "Mit geringfügiger Änderung lässt sich üs.: Ich sehe einen angefachten Schmelzofen, dessen Vorderseite von Norden her droht; gemeint ist wahrscheinlich ein an einer Kette hängender Kochtopf."] },
      { number: 14, text: "Da sprach der HERR zu mir: Von Norden her wird das Unglück losbrechen über alle Bewohner des Landes*.", footnotes: ["℘ Kap. 4,6; 6,1.22; Joe 2,20"] },
      { number: 15, text: "Denn siehe, ich bin im Begriff, alle Stammesgruppen der Königreiche des Nordens herbeizurufen, spricht der HERR*, dass sie kommen, und jeder seinen Thron aufstellt am Eingang der Tore Jerusalems und gegen all seine Mauern ringsum und gegen alle Städte Judas*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 25,9; 34,1"] },
      { number: 16, text: "Und ich werde meine Urteile über sie sprechen* wegen all ihrer Bosheit, dass sie mich verlassen* und anderen Göttern Rauchopfer dargebracht* und sich vor den Werken ihrer Hände niedergeworfen haben*.", footnotes: ["℘ Kap. 4,12", "℘ Kap. 2,13.19; 5Mo 28,20", "℘ Kap. 7,17.18; 18,15; Hes 16,18", "℘ Kap. 2,28; 2Chr 28,2; Jes 2,8"] },
      { number: 17, text: "Du aber gürte deine Hüften*, mach dich auf und rede zu ihnen alles, was ich dir gebieten werde*! Erschrick nicht vor ihnen, damit ich dich nicht vor ihnen in Schrecken setze*!", footnotes: ["℘ Lk 12,35", "℘ Jon 3,2", "w. Sei nicht niedergeschlagen vor ihnen, damit ich dich nicht vor ihnen zerschmettere"] },
      { number: 18, text: "Und ich, siehe, ich mache dich heute zu einer befestigten Stadt und zu einer eisernen Säule und zu einer ehernen Mauer* gegen das ganze Land, für die Könige von Juda, für seine Obersten, seine Priester und das Volk des Landes*.", footnotes: ["w. zu bronzenen Mauern", "℘ Kap. 6,27; Hes 3,8.9"] },
      { number: 19, text: "Und sie werden gegen dich kämpfen*, dich aber nicht überwältigen, denn ich bin mit dir, spricht der HERR*, um dich zu retten*.", footnotes: ["℘ Kap. 11,19.21; 15,10; 18,18; 20,10.11; 26,8; 30,11", "w. ist der Ausspruch des HERRN", "℘ Kap. 15,20; 42,11"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir:", heading: "Israels Bundesbruch und Abwendung von seinem Retter" },
      { number: 2, text: "Geh und rufe in die Ohren Jerusalems: So spricht der HERR: Ich erinnere mich — dir zugute — an die Treue* deiner Jugendzeit*, an die Liebe deiner Brautzeit*, wie du hinter mir hergingst in der Wüste*, im unbesäten Land.", footnotes: ["o. Gnade; o. Güte", "℘ Hos 2,17; 11,1; Offb 2,4", "℘ Hes 16,8", "℘ 5Mo 2,7; Hl 3,6"] },
      { number: 3, text: "Israel war heilig dem HERRN*, der Erstling* seiner Ernte. Alle, die davon aßen*, machten sich schuldig: Unglück kam über sie*, spricht der HERR*.", footnotes: ["℘ 5Mo 7,6; Am 6,1", "℘ Offb 14,4", "Die Erstlingsgabe durfte man nicht essen.", "℘ Ps 105,14", "w. ist der Ausspruch des HERRN"] },
      { number: 4, text: "Hört das Wort des HERRN, Haus Jakob und alle Sippen des Hauses Israel*!", footnotes: ["℘ Kap. 10,1"] },
      { number: 5, text: "So spricht der HERR: Was haben eure Väter Unrechtes an mir gefunden, dass sie sich von mir entfernt haben und hinter dem Nichts* hergelaufen und selber zu Nichts geworden sind*?", footnotes: ["d. i. eine Bezeichnung für Götzen", "℘ Mi 6,3"] },
      { number: 6, text: "Und sie sagten nicht: Wo ist der HERR*, der uns aus dem Land Ägypten heraufgeführt hat*, der uns leitete in der Wüste*, im Land der Steppe und des Abgrundes, im Land der Dürre und des Dunkels, im Land, durch das niemand zieht und wo kein Mensch wohnt?", footnotes: ["℘ Hi 35,10", "℘ Kap. 5,12; Jes 63,11", "℘ 5Mo 8,2.14.15; Am 2,10"] },
      { number: 7, text: "Und ich brachte euch in das Gartenland*, seine Frucht und sein Bestes* zu essen. Und ihr kamt hin und habt mein Land unrein gemacht*, und mein Erbteil* habt ihr zum Gräuel gemacht*.", footnotes: ["w. ins Land des Fruchtgartens\n℘ 5Mo 8,7-9", "w. sein Gut", "℘ Kap. 3,1; 3Mo 18,25", "℘ 5Mo 32,9", "℘ Neh 9,25.26; Hes 20,24; 23,35"] },
      { number: 8, text: "Die Priester sagten nicht: Wo ist der HERR*? Und die das Gesetz* handhabten, kannten mich nicht*, und die Hirten* haben mit mir gebrochen*. Die Propheten weissagten im Namen des Baal* und sind denen nachgelaufen, die nichts nützen*.", footnotes: ["℘ Hi 35,10", "o. die Weisung", "℘ Kap. 8,8.9; 1Sam 2,12", "d. h. die Könige", "℘ Kap. 10,21", "℘ Kap. 23,13", "℘ Hab 2,18"] },
      { number: 9, text: "Darum muss ich weiter mit euch rechten, spricht der HERR*. Auch mit euren Kindeskindern muss ich rechten*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 50,4.7; Hos 4,1"] },
      { number: 10, text: "Fahrt doch hinüber zu den Inseln der Kittäer* und seht, sendet nach Kedar* und gebt gut acht und seht, ob so etwas dort je geschehen ist*!", footnotes: ["das sind die Bewohner Zyperns und der griech. Inseln\n℘ Jes 23,1; Hes 27,6", "d. i. ein arabischer Stamm im Osten\n℘ Kap. 49,28; Hes 27,21", "℘ Hes 16,16"] },
      { number: 11, text: "Hat irgendeine Nation die Götter vertauscht? — Und jene sind nicht einmal Götter*!* Aber mein Volk hat seine Herrlichkeit vertauscht gegen das, was nichts nützt*.", footnotes: ["o. sind Nichtgötter", "℘ Kap. 5,7; 16,20", "℘ 5Mo 32,16.17; 2Kö 1,3; Ps 106,20"] },
      { number: 12, text: "Entsetze dich darüber, du Himmel*, und schaudere, erstarre völlig vor Schreck!, spricht der HERR*.", footnotes: ["℘ Kap. 18,13; Jes 1,2; 29,9", "w. ist der Ausspruch des HERRN"] },
      { number: 13, text: "Denn zweifach Böses hat mein Volk begangen: Mich, die Quelle lebendigen Wassers*, haben sie verlassen*, um sich Zisternen auszuhauen, rissige Zisternen, die das Wasser nicht halten*.", footnotes: ["℘ Joh 4,10; Offb 7,17", "℘ Kap. 1,16; 15,6; 17,13; 19,4; 2Kö 22,17", "℘ Jes 1,4; Hes 14,5"] },
      { number: 14, text: "Ist Israel ein Sklave, oder ist er gar ein Sklavensohn*? Warum ist er zur Beute geworden?", footnotes: ["o. ein im Haus geborener Sklave; w. ein Hausgeborener"] },
      { number: 15, text: "Junglöwen haben über ihm gebrüllt, ließen ihre Stimme hören. Sie haben sein Land zur Wüste gemacht*. Seine Städte sind verbrannt* und ohne Bewohner*.", footnotes: ["℘ Kap. 5,6; Jes 5,29", "o. verwüstet", "℘ Kap. 4,7; 6,8; 9,10; 10,22; 25,9; 34,22"] },
      { number: 16, text: "Auch die Söhne von Nof* und Tachpanhes* weiden dir den Scheitel ab.", footnotes: ["d. i. Memfis, die Hauptstadt von Unterägypten\n℘ Jes 59,13; Hos 9,6", "ägypt. Grenzfestung östlich vom Delta bei Pelusium\n℘ Kap. 43,7; 46,14.19"] },
      { number: 17, text: "Hast du dir das nicht selbst zugefügt*, indem du den HERRN, deinen Gott, verlassen hast, als er dich auf dem Weg durch die Wüste führte?", footnotes: ["℘ 2Chr 15,2; Hi 34,27; Mi 1,5"] },
      { number: 18, text: "Und nun, was hast du mit dem Weg nach Ägypten zu schaffen*, um das Wasser des Sichor* zu trinken? Und was hast du mit dem Weg nach Assur zu schaffen*, um die Wasser des Stroms* zu trinken?", footnotes: ["℘ Jes 30,1.2", "wahrscheinlich einer der Nilarme\n℘ Jes 23,3", "℘ 2Chr 28,16; Kla 5,6; Hes 16,28", "d. i. der Euphrat"] },
      { number: 19, text: "Deine eigene Bosheit züchtigt dich, und deine Treulosigkeiten strafen dich*. Erkenne doch und sieh, dass es schlimm und bitter ist, wenn du den HERRN, deinen Gott, verlässt* und wenn bei dir keine Furcht vor mir ist!, spricht der Herr, der HERR der Heerscharen*.", footnotes: ["℘ Kap. 4,18; 7,19; 13,22; Spr 5,22", "℘ Kap. 1,16; Ri 10,13; Hes 23,30", "w. ist der Ausspruch des Herrn, des HERRN der Heerscharen"] },
      { number: 20, text: "Denn von jeher hast du dein Joch zerbrochen, deine Stricke* zerrissen und hast gesagt*: Ich will nicht dienen*! Denn auf jedem hohen Hügel und unter jedem grünen Baum hast du dich hingelegt als Hure*.", footnotes: ["w. Fesseln; gemeint sind die Seile, mit denen der Pflug gezogen wird", "so mit LXX; Mas. T.: von jeher habe ich dein Joch zerbrochen, habe ich deine Stricke zerrissen, du aber hast gesagt", "℘ Ri 10,6", "℘ Kap. 3,2.6.13; 13,27; Ri 2,11-13.17; 1Kö 14,23; Jes 1,21; 57,5.7; Hos 9,1"] },
      { number: 21, text: "Ich hatte dich gepflanzt als Edelrebe, lauter echtes Gewächs*. Aber wie hast du dich mir verwandelt in entartete Reben* eines fremdartigen Weinstocks*!", footnotes: ["w. Samen der Wahrheit, o. Setzling der Wahrheit\n℘ Kap. 11,16; Jes 5,1-4", "mit anderer Wortabtrennung: in die stinkende Rebe", "℘ Kap. 5,10; 5Mo 32,32; Ps 80,9; Hes 15,2"] },
      { number: 22, text: "Auch wenn du dich mit Natron wüschest und viel Laugensalz nähmst*; schmutzig bleibt deine Schuld vor mir*, spricht der Herr, HERR*.", footnotes: ["℘ Hi 9,30.31", "℘ Ps 90,8; Hes 24,6", "w. ist der Ausspruch des Herrn, HERRN"] },
      { number: 23, text: "Wie kannst du sagen: Ich habe mich nicht unrein gemacht, ich bin den Baalim nicht nachgelaufen*? Sieh doch deinen Weg im Tal, erkenne, was du getan hast*, du flinke Kamelstute, die sinnlos hin und her läuft*!", footnotes: ["℘ Spr 30,20", "℘ Ps 50,21", "w. die ihre Wege verknotet\n℘ Kap. 31,22; Hos 1,2"] },
      { number: 24, text: "Eine Wildeselin, die Wüste gewohnt*, — in ihrer Gier* schnappt sie nach Luft; ihre Brunst, wer kann sie hemmen? Alle, die sie suchen, brauchen sich nicht müde zu laufen: in ihrer Brunstzeit* werden sie sie finden*.", footnotes: ["Andere nehmen ein Abschreibversehen an und üs.: du flinke Kamelstute . . ., 24 die in die Wüste ausbricht\n℘ Hi 39,5.6", "w. im Begehren ihrer Seele", "w. in ihrem Monat", "℘ Hes 16,33"] },
      { number: 25, text: "Bewahre deinen Fuß vor dem Barfußgehen* und deine Kehle vor dem Durst! Aber du sprichst: »Es ist umsonst, nein! Denn ich liebe die Fremden, und ihnen laufe ich nach*.«", footnotes: ["d. h. vielleicht: Lauf dir nicht die Sohlen ab und die Füße wund durch das Rennen nach den Götzen!", "℘ Kap. 14,10; 18,12; 22,21; 2Chr 28,23"] },
      { number: 26, text: "Wie ein Dieb beschämt dasteht, wenn er ertappt* wird, so muss sich das Haus Israel schämen, sie, ihre Könige, ihre Obersten und ihre Priester und ihre Propheten*,", footnotes: ["w. gefunden", "℘ Kap. 4,9; 22,22; Ps 97,7; Jes 44,9"] },
      { number: 27, text: "die zum Holz sagen: Du bist mein Vater! — und zum Stein: Du hast mich geboren*! Denn sie haben mir den Rücken zugekehrt und nicht das Gesicht*. Aber zur Zeit ihres Unglücks sagen sie: Steh auf und rette uns*!", footnotes: ["℘ Hab 2,18.19", "℘ Kap. 32,33", "℘ Kap. 37,3; 42,2; Jes 26,16"] },
      { number: 28, text: "Wo sind nun deine Götter, die du dir gemacht hast*? Sie sollen aufstehen, wenn sie dich retten können zur Zeit deines Unglücks*! Denn so zahlreich wie deine Städte sind deine Götter geworden, Juda*.", footnotes: ["℘ 5Mo 32,37", "℘ Ri 10,14", "℘ Kap. 1,16; 11,13"] },
      { number: 29, text: "Warum rechtet ihr mit mir? Ihr habt alle mit mir gebrochen*, spricht der HERR*.", footnotes: ["℘ Kap. 5,1", "w. ist der Ausspruch des HERRN"] },
      { number: 30, text: "Vergeblich habe ich eure Söhne geschlagen, sie haben keine Züchtigung angenommen*. Euer Schwert hat eure Propheten gefressen wie ein reißender Löwe*.", footnotes: ["℘ Kap. 5,3", "w. ein Verderben bringender Löwe\n℘ 1Kö 19,10; Mk 12,3-5"] },
      { number: 31, text: "Ihr, die gegenwärtige Generation, seht das Wort des HERRN! Bin ich denn für Israel eine Wüste gewesen oder ein Land tiefer Finsternis? Warum spricht mein Volk: Wir laufen umher*, wir kommen nicht mehr zu dir*?", footnotes: ["Vielleicht ist damit das Bild der hin und her laufenden Kamelstute aus V. 23b wieder aufgenommen. Eine griech. und die lat. Üs. lesen: Wir lehnen uns auf; LXX: Wir lassen uns nicht beherrschen", "℘ Kap. 5,5; Hi 21,14"] },
      { number: 32, text: "Vergisst etwa eine Jungfrau ihren Schmuck, eine Braut ihren Gürtel? Aber mein Volk hat mich vergessen seit unzähligen Tagen*.", footnotes: ["w. seit Tagen ohne Zahl\n℘ Kap. 3,21; 13,25; 23,27; 5Mo 32,15.18; Ri 8,34"] },
      { number: 33, text: "Wie gut kannst du deinen Weg einrichten, um Liebe zu suchen! Darum hast du deine Wege auch an Übeltaten gewöhnt." },
      { number: 34, text: "Ja, an den Säumen* deiner Kleider* findet sich das Blut unschuldiger Armer*. Nicht beim Einbruch hast du sie ertappt*. Wegen all jener Dinge wirst du zur Rechenschaft gezogen*.", footnotes: ["w. Flügeln", "Anstatt »an den Säumen deiner Kleider« ist vielleicht mit LXX zu lesen: an deinen Händen", "w. Blut von Seelen unschuldiger Armer\n℘ Kap. 19,4; 2Kö 21,16; Ps 106,38", "w. gefunden\n℘ 2Mo 22,1", "Mas. T. scheint verderbt zu sein; andere üs. deshalb: All dieses wird dir gegenüber zum Fluch."] },
      { number: 35, text: "Doch du sagst: Ich bin unschuldig, ja, sein Zorn hat sich von mir abgewandt. Siehe, ich werde mit dir vor Gericht treten, weil du sagst: Ich habe nicht gesündigt*.", footnotes: ["℘ Kap. 16,10"] },
      { number: 36, text: "Was läufst du so sehr,* um deinen Weg zu ändern? Auch an Ägypten wirst du zuschanden*, wie du an Assur zuschanden geworden bist*;", footnotes: ["Die griech., syr., altlat. und lat. Üs. lesen: Was nimmst du es so leicht?", "℘ Kap. 37,7", "℘ 2Chr 28,21; Hos 7,11"] },
      { number: 37, text: "auch von diesem Land Ägypten wirst du weggehen mit deinen Händen auf deinem Haupt*. Denn der HERR hat die verworfen, auf die du dein Vertrauen setzt, und du wirst mit ihnen keinen Erfolg haben*.", footnotes: ["℘ 2Sam 13,19", "℘ Kap. 22,20.22; Jes 28,18"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Er spricht*: Wenn ein Mann seine Frau entlässt und sie von ihm weggeht und die Frau eines anderen Mannes wird, darf sie wieder zu ihm zurückkehren*? Würde dieses Land nicht ganz und gar entweiht werden*? Du aber hast mit vielen Liebhabern gehurt*, und du solltest zu mir zurückkehren?, spricht der HERR*.", footnotes: ["w. Folgendes. — Möglicherweise ist hier der Anfang eines einleitenden Satzes »Und der HERR sprach zu mir Folgendes« ausgefallen.", "so mit LXX; Mas. T.: kehrt er wieder zu ihr zurück", "℘ Kap. 2,7; 5Mo 24,1-4", "℘ Hes 16,29.30", "w. ist der Ausspruch des HERRN"] },
      { number: 2, text: "Hebe deine Augen auf zu den kahlen Höhen und sieh! Wo bist du nicht geschändet* worden? An den Wegen saßest du für sie wie ein Araber in der Wüste*. Und du hast das Land entweiht durch deine Hurerei und durch deine Bosheit.", footnotes: ["w. beschlafen", "℘ Kap. 2,20.33"] },
      { number: 3, text: "Darum wurden die Regengüsse* zurückgehalten, und es gab keinen Spätregen*. Aber du hattest die Stirn eines Hurenweibes, hast dich geweigert, dich zu schämen*.", footnotes: ["o. Tau, der schwer wie Regen ist; vgl. Kap. 14,22", "℘ Kap. 5,24.25; 14,1.3; Am 4,7.8", "℘ Kap. 5,3; 6,15; Spr 21,29; Zef 3,5"] },
      { number: 4, text: "Nicht wahr, von jetzt an* rufst du mir zu: Mein Vater, der Freund* meiner Jugend bist du*!", footnotes: ["Andere üs. mit geringfügiger Änderung: auch jetzt noch", "o. der Vertraute", "℘ Kap. 31,22"] },
      { number: 5, text: "Wird er für ewig grollen, wird er für immer Zorn bewahren*? Siehe, so hast du geredet und Böses getan und hast dich durchgesetzt*.", footnotes: ["℘ Ps 85,6", "℘ Kap. 8,5.6"] },
      { number: 6, text: "Und der HERR sprach zu mir in den Tagen des Königs Josia: Hast du gesehen, was Israel, die Abtrünnige*, getan hat? Sie ging auf jeden hohen Berg und unter jeden grünen Baum und hurte dort*.", heading: "Gott gibt Juda den Scheidebrief und dennoch das Angebot zum Neuanfang", footnotes: ["w. die Abtrünnigkeit Israels", "℘ Kap. 2,20; 2Kö 17,10"] },
      { number: 7, text: "Und ich* sprach: Nachdem sie das alles getan hat, wird sie zu mir zurückkehren. Aber sie kehrte nicht zurück*. Und ihre treulose Schwester Juda sah es*.", footnotes: ["d. i. Gott", "℘ 2Kö 17,14", "℘ Hes 23,2-4"] },
      { number: 8, text: "Und sie* sah auch, dass ich Israel, die Abtrünnige, eben deshalb, weil sie die Ehe gebrochen, entließ und ihr den Scheidebrief gab*. Doch ihre Schwester Juda, die Treulose, fürchtete sich nicht, sondern ging hin und trieb selbst auch Hurerei*.", footnotes: ["so mit einer hebr. Handschr. und LXX; Mas. T.: ich sah", "℘ 5Mo 24,1; Hes 23,9.10", "℘ Kap. 5,7; 2Kö 17,19; 2Chr 21,11"] },
      { number: 9, text: "Und es geschah, durch die Leichtfertigkeit* ihrer Hurerei, entweihte sie das Land; denn sie trieb Ehebruch mit Stein und mit Holz*.", footnotes: ["o. durch das Gerücht", "℘ Jes 57,3"] },
      { number: 10, text: "Und selbst bei alldem ist ihre Schwester Juda, die Treulose, nicht mit ihrem ganzen Herzen zu mir zurückgekehrt*, sondern nur zum Schein*, spricht der HERR*.", footnotes: ["℘ Hos 7,14", "w. in Lüge\n℘ Kap. 9,1; Jes 29,13; Mal 2,11", "w. ist der Ausspruch des HERRN"] },
      { number: 11, text: "Und der HERR sprach zu mir: Israel, die Abtrünnige*, hat sich gerechter erwiesen* als Juda, die Treulose*.", footnotes: ["w. die Abtrünnigkeit Israels", "w. hat eine gerechtere Seele", "℘ Hes 16,51; 23,11"] },
      { number: 12, text: "Geh und rufe diese Worte aus nach Norden hin und sprich: Kehre um*, Israel, du Abtrünnige, spricht der HERR*! Ich will nicht finster auf euch blicken*. Denn ich bin gütig, spricht der HERR*, ich werde nicht für ewig grollen*.", footnotes: ["℘ Kap. 31,21; Jes 31,6; Hos 14,2", "w. ist der Ausspruch des HERRN", "w. mein Angesicht nicht gegen euch senken; vgl. auch 4Mo 6,26", "w. ist der Ausspruch des HERRN", "℘ 2Chr 29,10; Ps 103,9; Mi 7,18"] },
      { number: 13, text: "Nur erkenne deine Schuld, dass du mit dem HERRN, deinem Gott, gebrochen hast und unter jeden grünen Baum* zu den fremden Göttern hin und her gelaufen bist*. Aber auf meine Stimme habt ihr nicht gehört*, spricht der HERR*.", footnotes: ["℘ 3Mo 26,40", "w. zu den fremden Göttern deine Wege zerstreut hast", "℘ Kap. 7,24", "w. ist der Ausspruch des HERRN"] },
      { number: 14, text: "Kehrt um*, ihr abtrünnigen Kinder!, spricht der HERR*. Denn ich bin euer Herr*. Und ich werde euch nehmen, einen aus einer Stadt und zwei aus einem Geschlecht*, und euch nach Zion bringen*.", footnotes: ["℘ Jes 44,22; 55,7; Sach 1,4", "w. ist der Ausspruch des HERRN", "w. ich bin euer Eheherr; d. h. das mit der Eheschließung begründete Besitzverhältnis zwischen dem »Ehemann« Gott und der »Ehefrau« Israel ist nicht erloschen\n℘ Kap. 31,32", "℘ Jes 10,22; 27,12", "℘ Kap. 29,14"] },
      { number: 15, text: "Und ich werde euch Hirten geben nach meinem Herzen, und sie werden euch weiden mit Erkenntnis und Verstand*.", footnotes: ["℘ Kap. 23,4; Hes 34,23; Apg 20,28"] },
      { number: 16, text: "Und es wird geschehen, wenn ihr euch im Land vermehrt und fruchtbar seid in jenen Tagen*, spricht der HERR*, wird man nicht mehr sagen: »Die Bundeslade des HERRN«; und sie wird keinem mehr in den Sinn kommen*, und man wird nicht mehr an sie denken noch sie suchen*, und sie wird nicht wiederhergestellt werden.", footnotes: ["℘ Kap. 30,19", "w. ist der Ausspruch des HERRN", "w. wird nicht zum Herzen heraufsteigen", "o. vermissen"] },
      { number: 17, text: "In jener Zeit wird man Jerusalem den Thron des HERRN nennen*, und alle Nationen werden sich zu ihr versammeln wegen des Namens* des HERRN in Jerusalem*. Und sie werden nicht mehr der Verstocktheit ihres bösen Herzens folgen*.", footnotes: ["℘ Kap. 14,21; Hes 43,7; Offb 22,2.3", "o. zum Namen", "℘ 1Kö 8,41; Jes 2,2.3", "℘ Kap. 7,24; Eph 4,17.18"] },
      { number: 18, text: "In jenen Tagen wird das Haus Juda mit dem Haus Israel zusammengehen*, und sie werden miteinander aus dem Land des Nordens* in das Land kommen, das ich euren Vätern zum Erbteil gegeben habe*.", footnotes: ["℘ Kap. 50,4; Hes 37,19; Hos 2,2", "℘ Kap. 16,15", "℘ 1Mo 12,7; Jes 11,13; 43,5.6"] },
      { number: 19, text: "Und ich hatte doch gedacht: Wie will ich dich unter die Söhne aufnehmen* und dir ein köstliches Land geben, ein Erbteil, das die herrlichste Zierde der Nationen ist*! Und ich meinte, ihr würdet mir zurufen: »Mein Vater*!«, und würdet euch nicht mehr von mir* abwenden.", footnotes: ["w. setzen", "℘ Ps 106,24; Hes 20,6.15", "℘ 5Mo 14,1", "w. von der Nachfolge hinter mir her"] },
      { number: 20, text: "Fürwahr, wie eine Frau ihren Gefährten treulos verlässt, so habt ihr treulos an mir gehandelt, Haus Israel, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Kap. 5,11; Hes 16,25.32"] },
      { number: 21, text: "Eine Stimme hört man auf den kahlen Höhen, ein Weinen, ein Flehen der Söhne Israel*, weil sie ihren Weg verkehrt und den HERRN, ihren Gott, vergessen haben*. —", heading: "Israels Bußlied und Gottes Antwort", footnotes: ["℘ Hes 7,16", "℘ Kap. 2,32; Hos 8,14"] },
      { number: 22, text: "Kehrt um, ihr abtrünnigen Kinder*! Ich will eure Treulosigkeiten heilen*. — Hier sind wir, wir kommen zu dir*; denn du bist der HERR, unser Gott.", footnotes: ["℘ Jes 31,6; Hes 18,30-32; Joe 2,12", "℘ Hos 14,5", "℘ Hos 3,5; Lk 15,18"] },
      { number: 23, text: "Fürwahr, trügerisch klingt von den Hügeln das Getöse der Berge*; fürwahr, nur im HERRN, unserm Gott, ist das Heil* Israels*!", footnotes: ["wahrscheinlich die lärmende Anrufung der Götzen; vgl. 1Kö 18,26ff", "o. die Rettung", "℘ Ps 3,9; Jes 10,20; 12,2; 63,16"] },
      { number: 24, text: "Denn die Schande* hat den Erwerb unserer Väter gefressen von unserer Jugend an, ihre Schafe und ihre Rinder, ihre Söhne und ihre Töchter*.", footnotes: ["d. i. der Schandgötze; andere vermuten, dass der Text ursprünglich lautete: Baal hat . . . verzehrt\n℘ Kap. 9,18; 11,13; Hos 9,10", "℘ Hes 16,19-21"] },
      { number: 25, text: "In unserer Schande* müssen wir daliegen, und unsere Schmach bedeckt uns! Denn wir haben gegen den HERRN, unsern Gott, gesündigt, wir und unsere Väter, von unserer Jugend an bis auf diesen Tag*, und wir haben nicht auf die Stimme des HERRN, unseres Gottes, gehört*.", footnotes: ["℘ Kap. 9,18; 11,13; Hos 9,10", "℘ Esr 9,6.7; Hes 2,3; Zef 1,17", "℘ Kap. 7,19; 12,13; 14,20; 22,21; Hes 44,13"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Wenn du umkehrst, Israel, spricht der HERR*, zu mir umkehrst* und wenn du deine Scheusale von meinem Angesicht entfernst, dann brauchst du nicht mehr umherzuschweifen*!", footnotes: ["w. ist der Ausspruch des HERRN", "o. dann kehre zu mir um!", "℘ 1Sam 7,3; 2Chr 34,33"] },
      { number: 2, text: "Und wenn du schwörst: So wahr der HERR lebt*! — in Wahrheit*, in Recht* und in Gerechtigkeit —, dann werden die Nationen sich in ihm* segnen* und sich in ihm* rühmen*.", footnotes: ["℘ 1Sam 20,3", "o. Treue\n℘ Kap. 5,2; 12,16; 5Mo 6,13", "d. i. in gerechtem Verhalten", "Andere lesen mit Textänderung: in dir", "d. h. mit seinem Namen Segen wünschen\n℘ 1Mo 22,18", "d. h. mit seinem Namen Segen wünschen", "℘ Mal 1,11"] },
      { number: 3, text: "Denn so spricht der HERR zu den Männern von Juda und zu Jerusalem: Pflügt euch Neuland* und sät nicht unter die Dornen*!", footnotes: ["w. Brecht einen Neubruch für euch\n℘ Hos 10,12", "℘ Mt 13,7"] },
      { number: 4, text: "Beschneidet euch für den HERRN und entfernt die Vorhäute eurer Herzen*, ihr Männer von Juda und ihr Bewohner von Jerusalem, damit mein Zorn nicht ausbricht wie ein Feuer und unauslöschlich brennt wegen der Bosheit eurer Taten*!", footnotes: ["℘ Kap. 9,25; 5Mo 10,16; Röm 2,28.29", "℘ Kap. 15,14; 21,12; 2Chr 34,25"] },
      { number: 5, text: "Verkündigt es in Juda und lasst es in Jerusalem hören und sagt: Stoßt ins Horn auf dem Land*! Ruft aus voller Kehle und sagt: Versammelt euch und lasst uns in die befestigten Städte ziehen*!", heading: "Babylon, der Feind aus dem Norden — Jeremias Leiden an seiner Gerichtsvision", footnotes: ["℘ 4Mo 10,2.3; Hos 8,1", "℘ Kap. 8,14"] },
      { number: 6, text: "Richtet ein Feldzeichen auf nach Zion hin! Flieht, bleibt nicht stehen! Denn ich bringe Unglück von Norden her und einen großen Zusammenbruch*.", footnotes: ["℘ Kap. 1,14; 10,22; Hes 9,2"] },
      { number: 7, text: "Ein Löwe* steigt herauf aus seinem Dickicht, und ein Zerstörer der Nationen bricht auf. Er zieht von seinem Ort aus, um dein Land zur Wüste zu machen, deine Städte verfallen, sind ohne Bewohner*.", footnotes: ["℘ Kap. 5,6; 49,19; Dan 7,4", "℘ Kap. 2,15; 8,16; 22,6; 3Mo 26,31"] },
      { number: 8, text: "Darum gürtet euch Sacktuch um, klagt und jammert*! Denn die Glut des Zornes des HERRN hat sich nicht von uns abgewandt*.", footnotes: ["℘ Jes 22,12; 32,11; Mi 1,16", "℘ Jes 5,25"] },
      { number: 9, text: "Und es wird geschehen an jenem Tag, spricht der HERR*, da wird das Herz* des Königs und das Herz* der Obersten vergehen. Und die Priester werden sich entsetzen und die Propheten erstarrt sein*.", footnotes: ["w. ist der Ausspruch des HERRN", "d. h. der Mut", "d. h. der Mut", "℘ Kap. 2,26; 25,34; Jes 28,19"] },
      { number: 10, text: "Da sprach ich*: Ach, Herr, HERR! Fürwahr, bitter getäuscht hast du dieses Volk und Jerusalem, als du sprachst: Ihr werdet Frieden haben! — und nun dringt uns das Schwert bis an die Seele*.", footnotes: ["Mehrere alte Üs. lesen: Da sprachen sie", "℘ Kap. 6,14; 14,13.14"] },
      { number: 11, text: "In jener Zeit wird diesem Volk und Jerusalem gesagt werden: Ein heißer Wind von den kahlen Höhen* in der Wüste kommt geradewegs zur Tochter meines Volkes, nicht zum Worfeln und nicht zum Läutern*, sondern", footnotes: ["o. Karawanenwegen", "℘ Kap. 23,19; 30,23; 51,1; Hos 4,19"] },
      { number: 12, text: "ein Wind, stärker als dieser, wird von mir kommen. Nun will auch ich Gerichtsurteile über sie sprechen*.", footnotes: ["℘ Kap. 1,16"] },
      { number: 13, text: "Siehe, wie Wolken zieht er herauf, und wie der Sturmwind sind seine Wagen*, schneller als Adler seine Pferde*. Wehe uns! Denn wir sind überwältigt.", footnotes: ["℘ Kap. 46,18; Sach 6,1", "℘ Kap. 6,23; 48,40; 5Mo 28,49"] },
      { number: 14, text: "Wasche dein Herz rein* von Bosheit, Jerusalem, damit du gerettet wirst! Wie lange sollen deine heillosen Pläne in deinem Innern schlummern*?", footnotes: ["℘ Kap. 18,11", "w. die Nacht über bleiben\n℘ Kap. 13,27"] },
      { number: 15, text: "Denn eine Stimme berichtet von Dan* her und verkündet Unheil* vom Gebirge Ephraim aus.", footnotes: ["℘ Kap. 8,16", "o. Ja, horch! Ein Bote von Dan — und einer, der Unheil verkündet"] },
      { number: 16, text: "Ruft es den Nationen ins Gedächtnis*, siehe, verkündet es Jerusalem*: Belagerer kommen aus einem fernen Land* und lassen ihre Stimme erschallen gegen die Städte Judas!", footnotes: ["℘ Kap. 6,18.19", "Andere üs. mit Änderung des Textes: Ruft es ins Gedächtnis, meldet es in Juda, verkündet es in Jerusalem", "℘ Kap. 6,22; Jes 39,3"] },
      { number: 17, text: "Wie Wächter auf dem Feld sind sie ringsumher gegen Jerusalem*. Denn gegen mich ist es widerspenstig gewesen*, spricht der HERR*.", footnotes: ["w. gegen sie\n℘ Kap. 6,3; 52,4", "℘ 5Mo 9,24; Kla 1,18; Dan 9,7-14", "w. ist der Ausspruch des HERRN"] },
      { number: 18, text: "Dein Weg und deine Taten haben dir das gebracht*; das ist deine Bosheit*, dass es bitter ist* und bis an dein Herz dringt.", footnotes: ["℘ Kap. 2,17.19; 14,16; Jes 50,1", "d. h. die Folge deiner Bosheit", "℘ Kla 3,15"] },
      { number: 19, text: "Meine Eingeweide, meine Eingeweide*! Ich muss mich winden. Die Wände meines Herzens! Es tobt in mir mein Herz*. Ich kann nicht schweigen*. Denn du, meine Seele, hörst den Schall des Horns, Kriegsgeschrei*;", footnotes: ["d. i. der Sitz der Gefühle", "℘ Kap. 8,18; Hab 3,16", "℘ Kap. 20,9", "℘ 2Kö 8,11; Am 3,6"] },
      { number: 20, text: "Zusammenbruch über Zusammenbruch wird ausgerufen. Denn das ganze Land ist überwältigt. Plötzlich sind meine Zelte überwältigt, meine Zeltdecken in einem Augenblick*.", footnotes: ["℘ Kap. 9,18; 10,20"] },
      { number: 21, text: "Wie lange muss ich das Feldzeichen sehen, den Schall des Horns hören? —" },
      { number: 22, text: "Denn mein Volk ist närrisch*, mich kennen sie nicht*. Törichte Kinder sind sie und unverständig*. Weise sind sie, Böses zu tun; aber Gutes zu tun, verstehen sie nicht*. —", footnotes: ["℘ 5Mo 32,6.28", "℘ Kap. 8,7; 9,2.5", "℘ Ps 36,4; Spr 28,5; Hos 4,1.6; Röm 3,11.17", "℘ Mi 7,3; Tit 1,16"] },
      { number: 23, text: "Ich schaue die Erde, und siehe, sie ist wüst und leer*, und zum Himmel, und sein Licht ist nicht da*.", footnotes: ["℘ 1Mo 1,2", "℘ Jes 5,30; Offb 6,12"] },
      { number: 24, text: "Ich schaue die Berge, und siehe, sie beben, und alle Hügel schwanken*.", footnotes: ["℘ Jes 5,25; 13,13; 24,20; Hes 38,20"] },
      { number: 25, text: "Ich schaue, und siehe, kein Mensch ist da; und alle Vögel des Himmels sind entflohen*.", footnotes: ["℘ Kap. 9,9.10; Zef 1,3"] },
      { number: 26, text: "Ich schaue, und siehe, das Fruchtland* ist eine Wüste*; und alle seine Städte sind niedergerissen vor dem HERRN, vor der Glut seines Zornes.", footnotes: ["hebr. Karmel", "℘ Kap. 7,34; 25,11; 3Mo 26,31.32; Kla 2,7; Zef 1,18"] },
      { number: 27, text: "Denn so spricht der HERR: Öde soll das ganze Land werden*; doch will ich nicht ein Ende mit ihm machen*.", footnotes: ["℘ Kap. 7,34; 25,11; 3Mo 26,31.32; Kla 2,7; Zef 1,18", "℘ Kap. 5,10.18; Jes 17,6"] },
      { number: 28, text: "Darum wird die Erde trauern*, und der Himmel oben schwarz werden. Denn ich habe es geredet, ich habe beschlossen, und ich werde es nicht bereuen und nicht davon ablassen*.", footnotes: ["℘ Hos 4,3", "w. umkehren\n℘ Kap. 7,16; 4Mo 23,19"] },
      { number: 29, text: "Vor dem Geschrei der Reiter und Bogenschützen flieht jede Stadt; sie* gehen ins Dickicht und ersteigen die Felsen. Jede Stadt ist verlassen, und kein Mensch wohnt mehr darin*.", footnotes: ["d. h. die Bewohner", "℘ Offb 6,15"] },
      { number: 30, text: "Und du, Überwältigte, was wirst du tun*? Wenn du dich auch in Karmesin kleidest, wenn du mit goldenem Schmuck dich schmückst, wenn du deine Augen mit Schminke vergrößerst*; vergeblich machst du dich schön. Die Liebhaber verschmähen dich, sie trachten dir nach dem Leben*.", footnotes: ["℘ Kap. 5,31; Jes 10,3", "w. aufreißt\n℘ Spr 7,10", "℘ Kap. 30,14; Ob 7"] },
      { number: 31, text: "Denn eine Stimme wie die von einer Kreißenden höre ich, das Klagegeschrei* wie von einer Erstgebärenden*, die Stimme der Tochter Zion. Sie seufzt, sie breitet ihre Hände aus*: Wehe mir! Denn meine Seele erliegt den Mördern*.", footnotes: ["so mit LXX; Mas. T.: Bedrängnis", "℘ Kap. 6,24; 13,21; 22,23; 30,6; Hos 13,13; Mi 4,10", "℘ Kla 1,17; 1Thes 5,3", "℘ Kap. 10,19; Jes 26,17; Kla 2,21"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Durchstreift die Gassen Jerusalems, seht doch und erkundet und sucht auf ihren Plätzen, ob ihr jemanden findet, ob einer da ist, der Recht übt, der Treue* sucht*: so will ich ihr vergeben*!", heading: "Geringe und Mächtige haben Gott die Treue gebrochen", footnotes: ["o. Zuverlässigkeit; o. Wahrhaftigkeit; o. Wahrheit", "℘ Kap. 2,29; 8,6; Ps 14,2.3; Spr 20,6", "℘ 1Mo 18,26.32"] },
      { number: 2, text: "Und wenn sie sagen: So wahr der HERR lebt!, so schwören sie darum doch falsch*. —", footnotes: ["℘ Kap. 4,2; 7,9; 9,2.7; Jes 48,1"] },
      { number: 3, text: "HERR, sind deine Augen nicht auf die Treue* gerichtet*? Du hast sie geschlagen, aber es hat sie nicht geschmerzt. Du hast sie aufgerieben, aber sie haben sich geweigert, Zucht anzunehmen*. Sie haben ihr Gesicht härter gemacht als Fels*, sie haben sich geweigert umzukehren*.", footnotes: ["o. Zuverlässigkeit; o. Wahrhaftigkeit; o. Wahrheit", "℘ Ps 51,8", "℘ Kap. 2,30; 7,28; 17,23; Jes 26,11; 42,25; Zef 3,2.7", "℘ Jes 48,4; Sach 7,12", "℘ Kap. 3,3; 8,5; 15,7; 44,10; 3Mo 26,23; 1Kö 13,33"] },
      { number: 4, text: "Ich aber, ich sagte: Nur die Geringen sind so; diese handeln töricht, weil sie den Weg des HERRN, das Recht ihres Gottes, nicht kennen*.", footnotes: ["℘ Joh 7,49"] },
      { number: 5, text: "Ich will doch zu den Großen gehen und mit ihnen reden; denn sie kennen den Weg des HERRN, das Recht ihres Gottes*. Doch sie haben alle zusammen das Joch zerbrochen, die Stricke zerrissen*.", footnotes: ["℘ Mi 3,1", "℘ Kap. 2,31; 8,7; 30,14; 2Chr 36,14; Jes 1,23"] },
      { number: 6, text: "Darum schlägt sie ein Löwe aus dem Wald*, ein Wolf der Steppen überwältigt sie, ein Leopard lauert an ihren Städten; jeder, der aus ihnen hinausgeht, wird zerrissen. Denn ihre Vergehen sind viele, zahlreich ihre Treulosigkeiten*. —", footnotes: ["℘ Kap. 2,15; 4,7; Hos 13,7", "℘ Kap. 2,31; 8,7; 30,14; 2Chr 36,14; Jes 1,23"] },
      { number: 7, text: "Weshalb sollte ich dir vergeben? Deine Söhne haben mich verlassen und schwören bei Nichtgöttern*. Obwohl ich sie schwören ließ*, haben sie Ehebruch getrieben* und laufen scharenweise ins Hurenhaus.", footnotes: ["℘ Kap. 2,11; 5Mo 32,21; Jos 23,7", "Andere lesen: sie sättigte", "℘ Kap. 3,8; 9,1; Hes 22,11; Hos 4,2; 7,4"] },
      { number: 8, text: "Feiste, geile* Pferde sind sie; sie wiehern, jeder nach der Frau seines Nächsten*.", footnotes: ["o. umherschweifende", "℘ Kap. 13,27; 23,10; Hi 31,9"] },
      { number: 9, text: "Sollte ich dies nicht* heimsuchen?, spricht der HERR*. Oder sollte sich meine Seele an einer Nation wie dieser nicht rächen*?", footnotes: ["o. Sollte ich sie deshalb nicht", "w. ist der Ausspruch des HERRN", "℘ Kap. 6,11; 9,8; 44,22; Spr 6,29"] },
      { number: 10, text: "Ersteigt seine* Mauern* und zerstört sie! Doch richtet sie nicht völlig zugrunde*! Reißt seine Ranken weg, denn dem HERRN gehören sie nicht*!", footnotes: ["Gemeint ist Jerusalem.", "Gemeint sind die Stützmauern des Weinbergs; Jerusalem wird hier bildlich als Weinberg dargestellt (vgl. Jes 5).\n℘ Kap. 39,8", "w. Aber ein Ende macht nicht\n℘ Kap. 4,27; 30,11", "℘ Kap. 2,21"] },
      { number: 11, text: "Denn das Haus Israel und das Haus Juda haben sehr treulos an mir gehandelt, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Kap. 3,20"] },
      { number: 12, text: "Sie haben den HERRN verleugnet* und gesagt: Er ist nicht da*. Kein Unglück wird über uns kommen*, Schwert und Hunger werden wir nicht sehen*.", footnotes: ["℘ Kap. 2,6; 2Petr 2,1", "℘ Ps 14,1", "℘ Jes 28,15; Mi 3,11", "℘ Kap. 6,14; 14,13; 23,17"] },
      { number: 13, text: "Und die Propheten werden zu Wind werden, und das Wort des HERRN ist nicht in ihnen; aber so wird es ihnen selbst ergehen." },
      { number: 14, text: "Darum, so spricht der HERR, der Gott der Heerscharen: Weil ihr dieses Wort redet, siehe, so will ich meine Worte in deinem Mund zu Feuer machen und dieses Volk zu Holz, und es soll sie verzehren*.", footnotes: ["℘ Kap. 23,29; Hos 6,5; Offb 11,5"] },
      { number: 15, text: "Siehe, ich bringe über euch eine Nation aus der Ferne*, Haus Israel, spricht der HERR*. Es ist eine unverwüstliche* Nation. Es ist eine Nation von alters her, eine Nation, deren Sprache du nicht kennst und deren Rede du nicht verstehst*.", footnotes: ["℘ Am 6,14", "w. ist der Ausspruch des HERRN", "o. beständige; w. immer wasserführende", "℘ Jes 5,26; 28,11; 33,19"] },
      { number: 16, text: "Ihr Köcher ist wie ein offenes Grab. Sie sind alle Helden*.", footnotes: ["℘ Kap. 6,22.23"] },
      { number: 17, text: "Und sie wird deine Ernte verzehren und dein Brot, sie werden deine Söhne und deine Töchter verzehren. Sie wird verzehren deine Schafe und deine Rinder*, verzehren deinen Weinstock und deinen Feigenbaum. Deine befestigten Städte, auf die du dich verlässt, wird sie mit dem Schwert zerstören*.", footnotes: ["℘ Ri 6,4", "℘ 3Mo 26,16; Joe 2,3"] },
      { number: 18, text: "Aber auch in jenen Tagen, spricht der HERR*, werde ich nicht ein Ende mit euch machen*. —", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Hab 1,12"] },
      { number: 19, text: "Und es soll geschehen, wenn ihr sagt: Weshalb hat der HERR, unser Gott, uns dies alles getan*? — dann sage zu ihnen: Genauso wie ihr mich verlassen und in eurem Land fremden Göttern gedient habt, so sollt ihr Fremden dienen in einem Land*, das euch nicht gehört*.", footnotes: ["℘ Kap. 13,22", "℘ Kap. 9,12", "℘ Kap. 17,4; 5Mo 29,24-27"] },
      { number: 20, text: "Verkündet das im Haus Jakob und lasst es hören in Juda:" },
      { number: 21, text: "Hört doch dieses, törichtes Volk ohne Verstand, die Augen haben und nicht sehen, die Ohren haben und nicht hören*!", footnotes: ["℘ Kap. 7,13; Hes 12,2"] },
      { number: 22, text: "Solltet ihr nicht mich fürchten, spricht der HERR*, und vor mir nicht zittern*, der ich dem Meer den Sand als Grenze gesetzt habe, eine ewige Schranke*, die es nicht überschreiten wird? Branden auch seine Wogen, sie vermögen doch nichts, und ob die Wellen brausen, sie überschreiten sie* nicht*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 5Mo 28,58; Hi 37,24; Offb 15,4", "o. Ordnung", "d. i. die Schranke", "℘ Kap. 31,35; Hi 38,11"] },
      { number: 23, text: "Aber dieses Volk hat ein störrisches und widerspenstiges Herz*; sie sind abgewichen und weggegangen*.", footnotes: ["℘ 5Mo 31,27", "℘ Kap. 6,28"] },
      { number: 24, text: "Und sie haben nicht in ihrem Herzen gesagt: Lasst uns doch den HERRN, unseren Gott, fürchten, der Regen gibt, sowohl Frühregen als auch Spätregen, zu seiner Zeit*; der die bestimmten Wochen der Ernte für uns einhält*!", footnotes: ["℘ Kap. 10,13; Sach 10,1; Apg 14,17", "℘ 5Mo 11,14"] },
      { number: 25, text: "Eure Missetaten haben diese Gaben abgewendet, und eure Sünden haben das Gute von euch ferngehalten*.", footnotes: ["℘ Kap. 3,3; 14,1-7; Ps 107,34"] },
      { number: 26, text: "Denn in meinem Volk finden sich Gottlose*. Man lauert, wie Vogelsteller sich ducken; sie stellen Fallen*, fangen Menschen*.", footnotes: ["℘ 1Kor 5,1", "w. Verderben", "℘ Spr 1,11"] },
      { number: 27, text: "Wie ein Käfig voll Vögel, so sind ihre Häuser voll Betrug*; darum sind sie groß und reich geworden*.", footnotes: ["o. Hinterlist", "℘ Jes 3,14; Hos 12,8.9"] },
      { number: 28, text: "Sie sind fett*, sie sind glatt*; ja, sie überschreiten das Maß der Bosheit*. Das Recht führen sie nicht aus, das Recht der Waise, dass sie es zum Erfolg führten; und den Rechtsanspruch der Armen setzen sie nicht durch*.", footnotes: ["℘ Ps 73,4", "℘ Kap. 12,1; Hi 12,6", "w. die Worte des Bösen, o. die Dinge des Bösen", "℘ Spr 15,25; Jes 1,23; Sach 7,10.11"] },
      { number: 29, text: "Sollte ich sie dafür nicht zur Rechenschaft ziehen?, spricht der HERR*. Oder sollte meine Seele sich nicht an einer Nation wie dieser rächen*? —", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 6,6; Mal 3,5"] },
      { number: 30, text: "Entsetzliches und Abscheuliches ist im Land geschehen*:", footnotes: ["℘ Kap. 18,13; 23,14; Hos 6,10"] },
      { number: 31, text: "Die Propheten weissagen falsch*, und die Priester herrschen auf eigene Faust*, und mein Volk liebt es so. Was werdet ihr aber am Ende von all dem tun*?", footnotes: ["℘ Kap. 14,14; 1Kö 22,6; Mi 2,11; Lk 6,26; 2Tim 4,3.4; Zef 3,4", "w. unter ihrer Hand; das kann auch bedeuten: herrschen auf Befehl der Propheten\n℘ Jes 5,26; 28,11; 33,19", "℘ Kap. 4,30; 5Mo 32,20.29; Spr 17,4; Kla 1,9"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Flieht, ihr Söhne Benjamin, aus Jerusalem hinaus, in Tekoa* stoßt ins Horn und richtet ein Signal* auf über Bet-Kerem*! Denn Unheil erhebt sich drohend von Norden*: ein großer Zusammenbruch*.", heading: "Weil Juda sich weigert umzukehren, nimmt Gott seine Verheißung von Jerusalem", footnotes: ["℘ Neh 3,5.14", "w. eine Erhebung", "℘ Jes 5,26; 28,11; 33,19", "w. blickt . . . von Norden herunter", "℘ Kap. 1,14"] },
      { number: 2, text: "Die Schöne und die Verzärtelte vernichte ich — die Tochter Zion.*", footnotes: ["Andere nehmen einen Schreibfehler an und vermuten, V. 2 habe ursprünglich gelautet: Gleicht denn die Tochter Zion noch einer lieblichen Aue?"] },
      { number: 3, text: "Über sie kommen Hirten mit ihren Herden. Sie schlagen rings um sie her Zelte auf, weiden sie ab*, jeder seinen Bereich*.", footnotes: ["℘ Kap. 4,17; 12,10", "o. seine Seite"] },
      { number: 4, text: "»Heiligt einen Krieg* gegen sie*! Macht euch auf und lasst uns noch am Mittag hinaufziehen*!« — »Wehe uns! Denn der Tag hat sich geneigt, schon strecken sich die Abendschatten.« —", footnotes: ["d. h. Rüstet euch zum heiligen Krieg", "℘ Joe 4,9; Mi 3,5", "℘ Kap. 15,8"] },
      { number: 5, text: "»Macht euch auf und lasst uns in der Nacht hinaufziehen und ihre Paläste zerstören*!« —", footnotes: ["℘ Kap. 52,7.13"] },
      { number: 6, text: "Denn so hat der HERR der Heerscharen gesprochen: Fällt Bäume und schüttet einen Wall gegen Jerusalem auf*! Sie ist die Stadt, die heimgesucht werden soll*; sie ist voll Unterdrückung in ihrem Innern*.", footnotes: ["℘ Kap. 32,24", "℘ Kap. 5,9.29", "℘ Zef 3,1"] },
      { number: 7, text: "Wie ein Brunnen sein Wasser quellen lässt, so lässt sie ihre Bosheit quellen. Von Gewalttat und Zerstörung hört man in ihr*, ihre Krankheit und ihre Wunde* sind beständig vor meinem Angesicht*.", footnotes: ["℘ Zef 3,1", "o. Plage", "℘ Kap. 8,22; 20,8; 30,12"] },
      { number: 8, text: "Lass dich zurechtweisen*, Jerusalem, damit meine Seele sich nicht von dir losreißt, damit ich dich nicht zur Öde mache, zu einem unbewohnten Land!*", footnotes: ["℘ Zef 3,7", "℘ Kap. 2,15; Hos 2,5"] },
      { number: 9, text: "So spricht der HERR der Heerscharen: Wie am Weinstock wird man gründliche Nachlese halten* am Rest Israels. Lege noch einmal deine Hand an wie der Winzer an die Ranken*!", footnotes: ["Andere üs.: halte Nachlese", "℘ Ob 5.6"] },
      { number: 10, text: "»Zu wem soll ich noch reden und wen warnen*, dass sie hören*? Siehe, ihr Ohr ist unbeschnitten, und sie können nicht achtgeben*. Siehe, das Wort des HERRN ist ihnen zum Hohn* geworden, sie haben kein Gefallen daran*.", footnotes: ["o. wen zum Zeugen aufrufen", "℘ Jes 28,9", "℘ Kap. 7,13; Hes 3,7", "o. zur Schmach", "℘ Kap. 35,13"] },
      { number: 11, text: "Und ich bin voll von der Zornglut des HERRN, habe mich vergeblich abgemüht, ihn zurückzuhalten*.« Gieße sie aus über die Kinder auf der Gasse und zugleich über den Kreis der jungen Männer*! Denn Mann und Frau werden getroffen*, der Alte wie der Hochbetagte*.", footnotes: ["℘ Kap. 5,9; 15,17; 20,9; Hes 3,14", "℘ Kap. 9,20", "d. h. vom Zorn", "w. der, dessen Tage voll sind\n℘ Hes 9,6"] },
      { number: 12, text: "*Und ihre Häuser werden anderen übereignet, Felder und Frauen ebenfalls*. Denn ich strecke meine Hand gegen die Bewohner des Landes aus*, spricht der HERR*.", footnotes: ["℘ V. 12-15: Kap. 8,10-12", "℘ 5Mo 28,30-33; Kla 5,2", "℘ Jes 5,25", "w. ist der Ausspruch des HERRN"] },
      { number: 13, text: "Denn von ihrem Kleinsten bis zu ihrem Größten machen sie alle unrechten Gewinn*. Und vom Propheten bis zum Priester üben alle Falschheit*,", footnotes: ["℘ Kap. 23,11; Jes 56,11; 57,17; Hes 22,12", "℘ Kla 4,13"] },
      { number: 14, text: "und sie heilen den Bruch der Tochter meines Volkes oberflächlich und sagen: Friede, Friede*! — und da ist doch kein Friede*.", footnotes: ["℘ Kap. 5,12; 1Thes 5,3", "℘ Kap. 4,10; Hes 13,10.16; Mi 3,5"] },
      { number: 15, text: "Sie werden zuschanden*, weil sie Gräuel verübt haben. Doch sie schämen sich keineswegs, ja, Scham kennen sie nicht*. Darum werden sie fallen, wenn alles fällt*. Zur Zeit, da ich sie heimsuche, werden sie stürzen*, spricht der HERR.", footnotes: ["w. Sie sind zuschanden geworden", "℘ Kap. 3,3", "w. fallen unter den Fallenden", "℘ Kap. 14,15; Hos 4,5"] },
      { number: 16, text: "So spricht der HERR: Tretet auf die Wege, seht und fragt nach den Pfaden der Vorzeit*, wo denn der Weg zum Guten sei, und geht ihn*! So werdet ihr Ruhe finden für eure Seelen*. Aber sie sagen: Wir wollen ihn nicht gehen*.", footnotes: ["℘ Kap. 18,15; Jes 46,9", "℘ Kap. 7,3; 31,21; Jes 30,21", "℘ Jes 57,2; Mt 11,29", "℘ Kap. 7,24; 44,16; Jes 28,12; Mt 23,37"] },
      { number: 17, text: "Und ich habe Wächter über euch bestellt*, die rufen: Achtet auf den Schall des Horns! Aber sie sagen: Wir wollen nicht darauf achten*.", footnotes: ["℘ Hes 3,17", "℘ Kap. 8,5; 18,12; Hes 3,7"] },
      { number: 18, text: "Darum hört, ihr Nationen, und erkenne, du Gemeinde, was mit ihnen* geschieht!", footnotes: ["o. gegen sie"] },
      { number: 19, text: "Höre es, Erde*! Siehe, ich bringe Unheil über dieses Volk, die Frucht ihrer Gedanken*. Denn auf meine Worte haben sie nicht geachtet, und mein Gesetz — sie haben es verworfen*.", footnotes: ["℘ Kap. 4,16; 22,29; Jes 1,2; Mi 1,2", "o. Pläne\n℘ Kap. 21,14; Spr 1,31; Gal 6,7", "℘ Kap. 8,5.6.9; Jes 5,24; Dan 9,11"] },
      { number: 20, text: "Wozu soll mir denn Weihrauch aus Saba kommen* und das gute Würzrohr aus fernem Land*? Eure Brandopfer sind mir nicht wohlgefällig, und eure Schlachtopfer sind mir nicht angenehm*.", footnotes: ["℘ Jes 60,6", "℘ 2Mo 30,23", "℘ Kap. 7,21; 14,12; Spr 15,8"] },
      { number: 21, text: "Darum, so spricht der HERR: Siehe, ich lege diesem Volk Anstöße in den Weg, dass sie darüber stürzen, Väter und Söhne miteinander; der Nachbar und sein Nächster kommen um*.", footnotes: ["℘ Jes 8,14.15"] },
      { number: 22, text: "So spricht der HERR: Siehe, ein Volk kommt aus dem Land des Nordens*, eine große Nation macht sich auf* vom äußersten Ende der Erde*.", footnotes: ["℘ Kap. 1,14.15; 13,20; 47,2", "w. regt sich", "℘ Kap. 4,16; 25,32; 50,41.42; Hab 1,6"] },
      { number: 23, text: "Bogen und Kurzschwert führen sie, sie sind grausam und ohne Erbarmen*. Ihre Stimme braust wie das Meer*, und auf Pferden reiten sie*. Sie sind gerüstet gegen dich, Tochter Zion, wie ein Mann zum Krieg*. —", footnotes: ["℘ Kap. 4,16; 25,32; 50,41.42; Hab 1,6", "℘ Jes 5,30", "℘ Kap. 4,13; 8,16", "℘ Kap. 5,16; Hes 23,22-24"] },
      { number: 24, text: "Wir haben die Kunde von ihm vernommen: Unsere Hände sind schlaff geworden. Angst hat uns ergriffen, Wehen wie bei einer Gebärenden*. —", footnotes: ["℘ Kap. 4,31; 48,41; Hes 7,17"] },
      { number: 25, text: "Zieh nicht hinaus aufs Feld und geh nicht* auf dem Weg! Denn der Feind hat ein Schwert — Schrecken ringsum*!", footnotes: ["Viele alte Handschr. lesen: Zieht nicht . . . geht nicht", "℘ Kap. 8,15; 20,3.10; 46,5; 49,5.29; Kla 2,22"] },
      { number: 26, text: "Tochter meines Volkes, gürte dir Sacktuch um und wälze dich in Asche*, trauere wie um den einzigen Sohn! Stimme bittere Klage an*! Denn plötzlich wird der Verwüster über uns kommen*.", footnotes: ["℘ Jes 3,24; Hes 27,30; Jon 3,6", "℘ Am 8,10", "℘ Kap. 15,8; 30,5; Hi 15,21; Hes 7,18"] },
      { number: 27, text: "Ich habe dich zum Prüfer in meinem Volk eingesetzt, als eine Festung*, damit du ihren Weg erkennst und prüfst.", footnotes: ["℘ Kap. 1,18"] },
      { number: 28, text: "Sie alle sind die Widerspenstigsten der Widerspenstigen*. Sie gehen als Verleumder* umher*, sie sind Bronze und Eisen*. Alle sind sie Verderber*.", footnotes: ["℘ Kap. 5,23; Hes 2,7", "w. als Verleumdung", "℘ Kap. 7,28; 9,3-5; 3Mo 19,16", "d. h. unedles Metall\n℘ Hes 22,18", "℘ Ps 14,1-3"] },
      { number: 29, text: "Versengt vom Feuer ist der Blasebalg, das Blei ist zu Ende*. Vergebens hat man geschmolzen und geschmolzen: die Bösen sind nicht ausgeschieden worden*.", footnotes: ["o. Es schnaubt der Blasebalg, vom Feuer unversehrt blieb das Blei. — Gemeint ist das Blei, das zugesetzt wird, um die Masse in Fluss zu bringen, damit das Silber von den Schlacken befreit wird.", "℘ Hes 24,12"] },
      { number: 30, text: "Verworfenes Silber* nennt man sie*; denn der HERR hat sie verworfen*.", footnotes: ["d. h. weil die Gewinnung des Silbers misslang, wurde der Inhalt des Schmelzofens weggeschüttet", "℘ Jes 1,22; Mt 5,13", "℘ Kap. 23,33; 2Kö 17,20; Kla 5,22"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "*Das Wort, das vom HERRN zu Jeremia geschah:", heading: "Die Tempelrede", footnotes: ["℘ Kap. 7,1-34: Kap. 25,1-11"] },
      { number: 2, text: "Stell dich in das Tor des Hauses des HERRN, rufe dort dieses Wort aus* und sprich: Hört das Wort des HERRN, ganz Juda, die ihr durch diese Tore kommt, um den HERRN anzubeten!", footnotes: ["℘ Kap. 17,19; 26,2; 36,6"] },
      { number: 3, text: "So spricht der HERR der Heerscharen, der Gott Israels: Macht gut eure Wege und eure Taten*, dann will ich euch an diesem Ort wohnen lassen*!", footnotes: ["℘ Kap. 6,16; 18,11; Esr 10,11", "Eine griech. und die lat. Üs. lesen: so werde ich bei euch wohnen\n℘ Kap. 26,13; 35,15; Jes 1,19"] },
      { number: 4, text: "Und verlasst euch nicht auf Lügenworte, wenn sie sagen: Der Tempel des HERRN, der Tempel des HERRN, der Tempel des HERRN ist dies*!", footnotes: ["℘ Mi 3,11; Mt 3,9"] },
      { number: 5, text: "Denn nur wenn ihr eure Wege und eure Taten wirklich gut macht, wenn ihr wirklich Recht übt untereinander*,", footnotes: ["w. zwischen einem Mann und seinem Nächsten\n℘ Hes 18,5"] },
      { number: 6, text: "den Fremden, die Waise und die Witwe nicht unterdrückt*, kein unschuldiges Blut an diesem Ort vergießt* und nicht anderen Göttern nachlauft zu eurem Unheil*,", footnotes: ["℘ 3Mo 19,33; Spr 23,10", "℘ Kap. 22,3.17", "℘ 5Mo 6,14.15"] },
      { number: 7, text: "dann will ich euch an diesem Ort, in dem Land, das ich euren Vätern gegeben habe, wohnen lassen* von Ewigkeit zu Ewigkeit*.", footnotes: ["℘ Kap. 26,13; 35,15; Jes 1,19", "℘ Kap. 17,25; 2Chr 33,8"] },
      { number: 8, text: "Siehe, ihr verlasst euch auf Lügenworte*, die nichts nützen.", footnotes: ["℘ Kap. 13,25; Jes 59,4"] },
      { number: 9, text: "Wie? Stehlen, morden und Ehebruch treiben, falsch schwören, dem Baal Rauchopfer darbringen und anderen Göttern nachlaufen*, die ihr nicht kennt*!", footnotes: ["℘ Kap. 5,2.7; 11,13.17; Hes 20,30", "d. h. die euch nichts angehen\n℘ Kap. 19,4"] },
      { number: 10, text: "Und dann kommt ihr und tretet vor mein Angesicht in diesem Haus, über dem mein Name ausgerufen ist*, und sagt: Wir sind gerettet, — um all diese Gräuel weiter zu verüben*!", footnotes: ["℘ Kap. 34,15; 1Kö 9,3", "℘ Hes 5,11"] },
      { number: 11, text: "Ist denn dieses Haus, über dem mein Name ausgerufen ist*, eine Räuberhöhle geworden in euren Augen*? Doch ich, siehe, ich habe das alles gesehen*, spricht der HERR*.", footnotes: ["℘ Dan 9,18", "℘ Jes 1,12; Mt 21,13", "℘ Kap. 16,17", "w. ist der Ausspruch des HERRN"] },
      { number: 12, text: "Denn geht doch hin zu meinem Anbetungsort, der in Silo war*, wo ich früher meinen Namen wohnen ließ*, und seht, was ich mit ihm getan habe wegen der Bosheit meines Volkes Israel!", footnotes: ["℘ Jos 18,1; Ps 78,60", "℘ 5Mo 12,5"] },
      { number: 13, text: "Und nun, weil ihr all diese Taten getan habt, spricht der HERR*, und ich zu euch geredet habe, früh mich aufmachend und redend, ihr aber nicht gehört habt*, und ich euch gerufen, ihr aber nicht geantwortet habt*;", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 5,21; 6,10; 11,8; 13,10; 26,5; 29,19; 35,14", "℘ Spr 1,24"] },
      { number: 14, text: "so werde ich mit diesem Haus, über dem mein Name ausgerufen ist, worauf ihr euch verlasst, und mit dem Ort, den ich euch und euren Vätern gegeben, ebenso verfahren, wie ich mit Silo verfahren bin*.", footnotes: ["℘ Kap. 12,7; 26,4-9; 1Kö 9,7.8; Lk 21,6"] },
      { number: 15, text: "Und ich werde euch von meinem Angesicht verwerfen*, so wie ich alle eure Brüder, alle Nachkommen Ephraims verworfen habe*.", footnotes: ["℘ Kap. 23,39", "℘ Kap. 15,1; 23,33; 2Kö 17,18-20.23; Hes 33,25.26; Hos 9,17"] },
      { number: 16, text: "Du aber, bitte nicht für dieses Volk und erhebe weder Flehen noch Gebet für sie und dringe nicht in mich! Denn ich werde nicht auf dich hören*.", heading: "Gott weist Jeremias Fürbitte ab — Gericht über Juda wegen Götzenkult", footnotes: ["℘ Kap. 4,28; 11,14; 14,11; 15,1; 1Jo 5,16"] },
      { number: 17, text: "Siehst du nicht, was sie in den Städten Judas und auf den Straßen von Jerusalem tun?" },
      { number: 18, text: "Die Kinder lesen Holz auf, und die Väter zünden das Feuer an, und die Frauen kneten den Teig, um für die Königin des Himmels* Kuchen zu machen. Und anderen Göttern spendet man Trankopfer, um mich zu kränken*.", footnotes: ["℘ Kap. 44,17", "℘ Kap. 1,16; 19,13; 32,29.32; 44,4; Jes 65,11; Hes 8,16; 1Kor 10,22"] },
      { number: 19, text: "Kränken sie denn mich, spricht der HERR*, nicht vielmehr sich selbst* zu ihrer eigenen Schande*?", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 2,19", "w. zur Beschämung ihres Gesichts\n℘ Kap. 3,25; Dan 9,7.8"] },
      { number: 20, text: "Darum, so spricht der Herr, HERR: Siehe, mein Zorn und mein Grimm wird sich über diesen Ort ergießen, über die Menschen und über das Vieh und über die Bäume des Feldes und über die Frucht des Landes; und er wird brennen und nicht erlöschen*.", footnotes: ["℘ Kap. 17,4.27; 42,18; 3Mo 26,28; 2Kö 22,17; Kla 2,3.4"] },
      { number: 21, text: "So spricht der HERR der Heerscharen, der Gott Israels: Fügt nur weiter eure Brandopfer zu euren Schlachtopfern und esst Opferfleisch*!", footnotes: ["℘ Kap. 6,20; 5Mo 12,27; Ps 50,8; Hos 8,13"] },
      { number: 22, text: "Denn ich habe nicht mit euren Vätern darüber geredet und ihnen nichts geboten über das Brandopfer und das Schlachtopfer* an dem Tag, da ich sie aus dem Land Ägypten herausführte;", footnotes: ["℘ 1Sam 15,22"] },
      { number: 23, text: "sondern dieses Wort habe ich ihnen geboten: Hört auf meine Stimme, dann werde ich euer Gott sein, und ihr werdet mein Volk sein*! Und geht auf dem ganzen Weg, den ich euch gebiete, damit es euch wohlgeht*!", footnotes: ["w. für euch zum Gott . . . für mich zum Volk sein\n℘ Kap. 11,4.7; 2Mo 19,5.6; 3Mo 26,12", "℘ Kap. 42,6; 5Mo 4,40; 13,5; Hi 36,11"] },
      { number: 24, text: "Aber sie haben nicht gehört und ihr Ohr nicht geneigt*, sondern sind nach den Ratschlägen und in der Verstocktheit ihres bösen Herzens gegangen*; und sie haben mir den Rücken zugekehrt und nicht das Gesicht*.", footnotes: ["℘ Kap. 3,13; 17,23; 22,21; 32,23; Dan 9,6; Sach 7,11", "℘ Kap. 3,17; 11,8; 13,10; 16,12; 17,9; 18,12; 23,17; Ps 81,13", "℘ Kap. 6,16; 8,5; 15,6; 32,33"] },
      { number: 25, text: "Von dem Tag an, da eure Väter aus dem Land Ägypten auszogen, bis auf diesen Tag habe ich alle meine Knechte, die Propheten, zu euch gesandt, täglich früh mich aufmachend und sendend*.", footnotes: ["℘ Kap. 11,7; 35,15; 44,4; 2Chr 36,15; Hebr 1,1"] },
      { number: 26, text: "Aber sie haben nicht auf mich gehört und ihr Ohr nicht geneigt*. Und sie haben ihren Nacken verhärtet*, haben es schlimmer gemacht als ihre Väter*.", footnotes: ["℘ Kap. 3,13; 17,23; 22,21; 32,23; Dan 9,6; Sach 7,11", "℘ Kap. 19,15; 2Kö 17,14.15; Neh 9,16; Hos 11,7", "℘ Kap. 9,13; 1Kö 14,9.22; 2Chr 33,23; Lk 20,10"] },
      { number: 27, text: "Und wenn du all diese Worte zu ihnen redest, so werden sie doch nicht auf dich hören. Und rufst du ihnen zu, so werden sie dir nicht antworten*.", footnotes: ["℘ Hes 3,7"] },
      { number: 28, text: "So sprich denn zu ihnen: Dies ist das Volk, das nicht auf die Stimme des HERRN, seines Gottes, hört und keine Zucht annimmt*! Die Treue* ist verloren gegangen und aus ihrem Mund getilgt*.", footnotes: ["℘ Kap. 5,3; 32,33; Jes 30,9", "o. Zuverlässigkeit; o. Wahrhaftigkeit; o. Wahrheit", "℘ Kap. 6,28; Ps 12,2.3"] },
      { number: 29, text: "Schere* dein langes Haar* und wirf es weg und erhebe Totenklage auf den kahlen Höhen! Denn der HERR hat die Generation, der er zürnt*, verworfen und verstoßen*.", footnotes: ["Gemeint ist die Tochter Zion.", "℘ Hi 1,20; Mi 1,16", "w. die Generation seines Grimmes", "℘ Kap. 9,16-20"] },
      { number: 30, text: "Denn die Söhne Juda haben getan, was in meinen Augen böse ist, spricht der HERR*. Sie haben ihre Scheusale in das Haus gestellt, über dem mein Name ausgerufen ist, um es unrein zu machen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 23,11; 2Kö 21,4.7; Hes 8,3"] },
      { number: 31, text: "Und sie haben die Höhen des Tofet* gebaut, das im Tal Ben-Hinnom* ist, um ihre Söhne und ihre Töchter im Feuer zu verbrennen, was ich nicht geboten habe und mir nie in den Sinn gekommen ist*.", footnotes: ["w. Gespei, o. Gräuel; daher auch Gräuelstätte\n℘ 2Kö 23,10", "℘ Jos 15,8", "w. aufgestiegen ist in mein Herz\n℘ Kap. 19,2.5; 32,34.35; 3Mo 18,21; 2Chr 28,3; 33,6; Hes 20,31"] },
      { number: 32, text: "Darum siehe, Tage kommen, spricht der HERR*, da wird man nicht mehr sagen Tofet* noch Tal Ben-Hinnom, sondern Tal des Schlachtens. Und man muss im Tofet begraben, weil kein Platz mehr da ist*.", footnotes: ["w. ist der Ausspruch des HERRN", "w. Gespei, o. Gräuel; daher auch Gräuelstätte", "℘ Kap. 19,6.11; 31,40; Hes 6,5"] },
      { number: 33, text: "Und die Leichen dieses Volkes werden den Vögeln des Himmels und den Tieren der Erde zum Fraß werden*, und niemand wird sie wegscheuchen.*", footnotes: ["℘ Kap. 16,4; 19,7; 34,20; 5Mo 8,20", "℘ Kap. 9,21; Ps 79,2"] },
      { number: 34, text: "Und ich werde in den Städten Judas und auf den Straßen von Jerusalem die Stimme der Wonne und die Stimme der Freude aufhören lassen, die Stimme des Bräutigams und die Stimme der Braut*; denn das Land soll zu Trümmerstätten werden*.", footnotes: ["℘ Kap. 16,9; 25,10; 33,11; Ps 78,63; Jes 24,8; Offb 18,23", "℘ Kap. 4,27; Hes 7,11"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "In jener Zeit, spricht der HERR*, wird man die Gebeine der Könige von Juda und die Gebeine seiner Obersten und die Gebeine der Priester und die Gebeine der Propheten und die Gebeine der Bewohner von Jerusalem aus ihren Gräbern herausholen.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 2, text: "Und man wird sie ausbreiten vor der Sonne und vor dem Mond und vor dem ganzen Heer des Himmels*, die sie geliebt und denen sie gedient haben und denen sie nachgelaufen sind, die sie gesucht* und vor denen sie sich niedergeworfen haben*. Sie werden nicht wieder eingesammelt noch begraben werden, zu Dünger auf der Fläche des Erdbodens sollen sie werden*.", footnotes: ["d. h. vor den Sternen", "o. befragt", "℘ 5Mo 4,19; Hes 6,5; 8,16; Apg 7,42", "℘ Kap. 9,21; 16,4; 25,33; 2Kö 9,37; Ps 83,11"] },
      { number: 3, text: "Und der Tod wird dem Leben vorgezogen* von dem ganzen Rest, der von diesem bösen Geschlecht übrig bleibt an allen Orten, wohin ich die Übriggebliebenen verstoße*, spricht der HERR* der Heerscharen.", footnotes: ["℘ Offb 9,6", "℘ Kap. 44,2.6; 3Mo 26,33", "w. ist der Ausspruch des HERRN"] },
      { number: 4, text: "Und sage zu ihnen: So spricht der HERR: Fällt man denn und steht nicht gleich wieder auf? Oder wendet man sich ab und kehrt nicht gern wieder zurück?", heading: "Judas Weigerung zur Umkehr: Es gibt keinen Frieden" },
      { number: 5, text: "Warum kehrt sich dieses Volk Jerusalems ab in immerwährender Abkehr*? Sie halten fest am Trug, sie weigern sich umzukehren*.", footnotes: ["℘ Kap. 7,24; Hos 13,2", "℘ Kap. 5,3; 6,17; Hos 11,5; Offb 9,20"] },
      { number: 6, text: "Ich habe achtgegeben und gehört: sie reden, was nicht recht ist*. Da ist keiner, der seine Bosheit bereut und sagt: Was habe ich getan*! Alle wenden sie sich weiter ab in ihrem Lauf* wie ein in den Kampf stürmendes Pferd*.", footnotes: ["℘ Kap. 5,1", "℘ Hi 34,31.32", "℘ Jes 57,17; Zef 3,7", "℘ Kap. 3,5; Hi 39,24; Dan 9,11"] },
      { number: 7, text: "Selbst der Storch am Himmel kennt seine bestimmten Zeiten, und Turteltaube, Schwalbe und Drossel* halten die Zeit ihres Kommens ein; aber mein Volk kennt das Recht des HERRN nicht*.", footnotes: ["o. Taube; o. Mauersegler; o. Kranich", "℘ Kap. 4,22; 5,4.5; Hab 1,4"] },
      { number: 8, text: "Wie könnt ihr sagen: Wir sind weise, und das Gesetz des HERRN ist bei uns*? In der Tat! Siehe, zur Lüge hat es* der Lügengriffel der Schriftgelehrten* gemacht*.", footnotes: ["℘ Röm 2,17.18", "d. h. das Gesetz", "w. Schreiber; das Wort wurde auch als Titel für hohe Hofbeamte gebraucht", "℘ Mt 15,6"] },
      { number: 9, text: "Die Weisen werden beschämt, sie sind schreckerfüllt und werden gefangen. Siehe, das Wort des HERRN haben sie verworfen. Und was für eine Weisheit haben sie nun*? —", footnotes: ["℘ Kap. 2,8; 6,19; Hi 5,13; Jes 43,27; Röm 1,22"] },
      { number: 10, text: "*Darum werde ich ihre Frauen anderen geben, ihre Felder anderen Besitzern*. Denn vom Kleinsten bis zum Größten machen sie alle unrechten Gewinn*, vom Propheten bis zum Priester üben sie alle Falschheit*.", footnotes: ["℘ V. 10-12: Kap. 6,12-15", "w. ihre Felder solchen, die in Besitz nehmen", "℘ Kap. 22,17; Tit 1,11", "o. Lüge\n℘ Kap. 14,14"] },
      { number: 11, text: "Und den Bruch der Tochter meines Volkes heilen sie oberflächlich, indem sie sagen: Friede, Friede*! — und da ist doch kein Friede.", footnotes: ["℘ 1Thes 5,3"] },
      { number: 12, text: "Sie werden zuschanden, weil sie Gräuel verübt haben. Doch sie schämen sich keineswegs, ja, Scham* kennen sie nicht. Darum werden sie fallen, wenn alles fällt*. Zur Zeit ihrer Heimsuchung werden sie stürzen*, spricht der HERR.", footnotes: ["w. das Sich-Schämen", "w. fallen unter den Fallenden", "℘ Kap. 23,12; 5Mo 32,35"] },
      { number: 13, text: "Wegnehmen, wegraffen werde ich sie*, spricht der HERR*. Keine Trauben sind am Weinstock und keine Feigen am Feigenbaum*, und das Blatt ist verwelkt: so will ich ihnen Menschen bestellen, die sie verheeren werden*.", footnotes: ["℘ Kap. 14,15; Hes 22,31", "w. ist der Ausspruch des HERRN", "℘ Mt 21,19", "w. so setze ich für sie solche, die sie feindlich überziehen werden"] },
      { number: 14, text: "Wozu bleiben wir sitzen? Sammelt euch, und lasst uns in die befestigten Städte ziehen* und dort umkommen*! Denn der HERR, unser Gott, lässt uns umkommen und hat uns mit giftigem Wasser getränkt, weil wir gegen den HERRN gesündigt haben*.", footnotes: ["℘ Kap. 4,5", "w. bewegungslos (o. still) sein", "℘ Kap. 9,14"] },
      { number: 15, text: "Man hofft auf Frieden*, und da ist nichts Gutes, auf eine Zeit der Heilung, und siehe da: Schrecken*. —", footnotes: ["o. Heil; o. Wohlergehen", "℘ Kap. 6,25; 12,12; 14,19; Hi 30,26; Hes 7,25; 1Thes 5,3"] },
      { number: 16, text: "Von Dan her hört man das Schnauben seiner Pferde*; vom lauten Wiehern* seiner starken Pferde erzittert das ganze Land. Und sie kommen und fressen das Land, die Städte und ihre Bewohner*.", footnotes: ["℘ Kap. 4,15; 6,23", "w. von der Stimme seines Wieherns", "℘ Kap. 4,7"] },
      { number: 17, text: "Denn siehe, ich sende unter euch Schlangen, Ottern, gegen die es keine Beschwörung gibt; und sie werden euch beißen*, spricht der HERR*.", footnotes: ["℘ 4Mo 21,6; 5Mo 32,24", "w. ist der Ausspruch des HERRN"] },
      { number: 18, text: "Unheilbar steigt Kummer in mir auf!* Mein Herz ist krank in mir*.", heading: "Jeremias Trauer über sein Volk — Gottes Trauer um sein Volk und erneute Gerichtsankündigung", footnotes: ["so ein Übersetzungsversuch mit LXX und der alten lat. Üs.; Mas. T.: Ist meine Erheiterung auf mir mein Kummer?", "℘ Kap. 4,19"] },
      { number: 19, text: "Da, horch! Geschrei der Tochter meines Volkes kommt aus einem fernen Land*: »Ist der HERR nicht in Zion, oder ist sein König nicht darin*?« — Warum haben sie mich gereizt durch ihre geschnitzten Bilder, durch Nichtigkeiten* aus der Fremde*?* —", footnotes: ["o. weit und breit im Land", "℘ 5Mo 31,17; Ps 137,1; Zef 3,15", "d. i. eine Bezeichnung für Götzen", "d. h. durch die leeren Kulte der fremden Völker", "℘ 5Mo 32,16.21"] },
      { number: 20, text: "»Vorüber ist die Ernte, die Obstlese ist zu Ende, und wir sind nicht gerettet!«" },
      { number: 21, text: "Über dem Zusammenbruch der Tochter meines Volkes bin ich zerbrochen; ich trauere, Entsetzen hat mich ergriffen*.", footnotes: ["℘ Kla 3,1"] },
      { number: 22, text: "Ist denn kein Balsam in Gilead* oder kein Arzt dort? Ja, warum ist die Genesung der Tochter meines Volkes ausgeblieben*?*", footnotes: ["℘ Kap. 22,6; 46,11; 1Mo 37,25; 4Mo 32,1; Jes 1,6; Hes 27,17", "w. Ja, warum ist nicht heraufgestiegen (o. neu gewachsen) die Fleischschicht über die Wunde der Tochter meines Volkes", "℘ Kap. 6,7; 9,11; 30,12-15"] },
      { number: 23, text: "Dass doch mein Haupt Wasser wäre und mein Auge eine Tränenquelle, dann wollte ich Tag und Nacht die Erschlagenen der Tochter meines Volkes beweinen*!", footnotes: ["℘ Kap. 9,17; 13,17; 14,17; Est 8,6; Jes 22,4; Kla 1,2; Am 6,6; Lk 19,41"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Dass ich doch Unterkunft für Durchreisende in der Wüste hätte*, dann würde ich mein Volk verlassen und von ihnen fortgehen! Denn sie sind alle Ehebrecher*, eine Bande von Treulosen*.", footnotes: ["℘ Ps 55,7.8", "℘ Kap. 5,7.8; Hos 7,4", "℘ Kap. 3,10; Hes 22,12"] },
      { number: 2, text: "Sie spannen ihre Zunge als ihren Bogen*, im Lügen und nicht in der Wahrheit* sind sie stark im Land*. Denn sie schreiten fort von Bosheit zu Bosheit*, mich aber erkennen sie nicht*, spricht der HERR*.", footnotes: ["d. h. sie legen die Lüge an wie einen Pfeil, der abgeschossen werden soll", "o. Treue; o. Zuverlässigkeit", "℘ Kap. 5,1-3; Jes 59,3.4.13; Röm 3,13", "℘ Kap. 23,10; 2Tim 3,13", "℘ Kap. 4,22; Ri 2,10", "w. ist der Ausspruch des HERRN"] },
      { number: 3, text: "Hütet euch, ein jeder vor seinem Freund, und setzt auf keinen Bruder Vertrauen! Denn jeder Bruder treibt Hinterlist, und jeder Freund geht als Verleumder* umher*.", footnotes: ["w. als Verleumdung", "℘ Kap. 6,28; 12,6; Jes 9,18; Mi 7,5.6; Lk 21,16"] },
      { number: 4, text: "Und sie betrügen einer den andern, Wahrheit reden sie nicht. Sie lehren ihre Zunge, Lügen zu reden, sie mühen sich ab, böse zu handeln*.", footnotes: ["℘ Spr 4,16.17; Jes 9,16"] },
      { number: 5, text: "Deine Wohnung ist mitten im Betrug*. Vor lauter Betrug* weigern sie sich, mich zu erkennen*, spricht der HERR*.", footnotes: ["o. Hinterlist\n℘ Spr 12,5", "o. Hinterlist", "℘ Kap. 4,22; Ri 2,10", "w. ist der Ausspruch des HERRN"] },
      { number: 6, text: "Darum, so spricht der HERR der Heerscharen: Siehe, ich will sie schmelzen und läutern*; denn wie sollte ich sonst verfahren mit der Tochter meines Volkes*?", footnotes: ["℘ Jes 1,25; Sach 13,9", "℘ Hos 11,8"] },
      { number: 7, text: "Ihre Zunge ist ein mörderischer Pfeil*, man redet Betrug*. Mit seinem Mund redet man Frieden zu seinem Nächsten, in seinem Innern aber legt man ihm einen Hinterhalt*.", footnotes: ["℘ Ps 120,4", "o. Hinterlist\n℘ Kap. 5,1-3; Jes 59,3.4.13; Röm 3,13", "℘ 2Sam 13,26; Ps 55,22; 62,5; Hos 4,1.2"] },
      { number: 8, text: "Sollte ich so etwas nicht an ihnen heimsuchen?, spricht der HERR*. Oder sollte sich meine Seele an einer Nation wie dieser nicht rächen?*", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 5,9.29"] },
      { number: 9, text: "Über die Berge will ich ein Weinen und eine Totenklage erheben und über die Weideplätze der Steppe ein Klagelied*. Denn sie sind verbrannt, so dass niemand mehr hindurchzieht und man den Lärm der Herde nicht mehr hört. Sowohl die Vögel des Himmels als auch das Vieh sind geflohen, weggezogen*.", footnotes: ["℘ Am 5,1", "℘ Kap. 4,25; 12,4; Hos 4,3; Joe 1,19"] },
      { number: 10, text: "Und ich werde Jerusalem zu Steinhaufen machen*, zur Wohnung der Schakale* und werde die Städte von Juda zur Öde machen — ohne Bewohner*.", footnotes: ["℘ Mi 3,12", "℘ Kla 5,18", "℘ Kap. 2,15; 4,25; 12,11; Hes 6,6"] },
      { number: 11, text: "*Wer ist der weise Mann, dass er dies versteht*? Und zu wem hat der Mund des HERRN geredet, dass er es mitteilt, warum das Land zugrunde geht und verbrannt wird* wie die Wüste, so dass niemand hindurchzieht?", footnotes: ["℘ V. 11-15: Kap. 16,10-13; 5Mo 29,23-27", "℘ Ps 107,43", "℘ Kap. 8,22"] },
      { number: 12, text: "Und der HERR sprach: Weil sie mein Gesetz verlassen haben, das ich ihnen vorgelegt habe, und auf meine Stimme nicht gehört und nicht darin gelebt haben*,", footnotes: ["℘ Kap. 5,19; Hos 4,10"] },
      { number: 13, text: "sondern der Verstocktheit ihres Herzens und den Baalim nachgelaufen sind, was ihre Väter sie gelehrt haben*,", footnotes: ["℘ Kap. 7,26; 13,10"] },
      { number: 14, text: "darum, so spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich will sie, dieses Volk, mit Wermut speisen und sie mit giftigem Wasser tränken*", footnotes: ["℘ Kap. 8,14; 23,15; Hi 9,18; Kla 3,15; Offb 8,11"] },
      { number: 15, text: "und sie unter die Völker zerstreuen, die sie nicht gekannt haben, weder sie noch ihre Väter*. Und ich will das Schwert hinter ihnen hersenden, bis ich sie vernichtet habe*.", footnotes: ["℘ 5Mo 28,36.64", "℘ Kap. 24,10; 44,27; 49,37; Hes 5,2.12"] },
      { number: 16, text: "So spricht der HERR der Heerscharen: Gebt acht und ruft Klageweiber*, dass sie kommen, und schickt zu den weisen Frauen, dass sie kommen", footnotes: ["℘ Pred 12,5; Am 5,16; Mi 2,4"] },
      { number: 17, text: "und schnell eine Wehklage über uns erheben, damit unsere Augen von Tränen fließen und unsere Wimpern von Wasser strömen*!", footnotes: ["℘ Kap. 8,23"] },
      { number: 18, text: "Denn laute Wehklage* wird aus Zion gehört: »Wie sind wir verwüstet! Wir sind völlig zuschanden geworden*. Wir haben das Land verlassen müssen, denn sie haben unsere Wohnungen zerstört*.«", footnotes: ["w. eine Stimme der Wehklage", "℘ Kap. 3,25", "℘ Kap. 4,20; Kla 2,13"] },
      { number: 19, text: "Denn hört, ihr Frauen, das Wort des HERRN, und euer Ohr nehme das Wort seines Mundes auf*. Und lehrt eure Töchter die Totenklage, und eine lehre die andere den Klagegesang*:", footnotes: ["℘ Jes 32,9", "℘ Hes 27,2"] },
      { number: 20, text: "»Ja, der Tod ist durch unsere Fenster gestiegen, er ist in unsere Paläste gekommen, um das Kind auszurotten von der Straße, die jungen Männer von den Plätzen*!«", footnotes: ["℘ Kap. 6,11; 14,16; Kla 2,19-21; Jer 7,29.33; 8,2"] },
      { number: 21, text: "Rede: So spricht der HERR*: Ja, die Leichen der Menschen werden fallen wie Dünger auf die Fläche des Feldes und wie eine Garbe hinter dem Schnitter, doch niemand sammelt*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Am 5,2; Zef 1,17"] },
      { number: 22, text: "So spricht der HERR: Der Weise rühme sich nicht seiner Weisheit*, und der Starke rühme sich nicht seiner Stärke*, der Reiche rühme sich nicht seines Reichtums*;", footnotes: ["℘ Hi 5,13", "℘ 5Mo 8,17; Hab 1,11; 2Kor 12,9", "℘ 2Kö 20,13.15; Spr 18,11; 23,4; 1Kor 4,7; Jak 1,10"] },
      { number: 23, text: "sondern wer sich rühmt, rühme sich dessen: Einsicht zu haben und mich zu erkennen*, dass ich der HERR bin*, der Gnade, Recht und Gerechtigkeit übt auf der Erde; denn daran habe ich Gefallen*, spricht der HERR*.", footnotes: ["℘ Kap. 31,34; Ps 34,3; 44,9; Phil 3,8", "℘ 1Kor 1,31; 2Kor 10,17", "℘ Ps 33,5; Mi 6,8", "w. ist der Ausspruch des HERRN"] },
      { number: 24, text: "Siehe, Tage kommen, spricht der HERR*, da werde ich alle an der Vorhaut Beschnittenen* heimsuchen:", footnotes: ["w. ist der Ausspruch des HERRN", "o. alle Beschnittenen zusammen mit der Vorhaut; d. h. zusammen mit den Unbeschnittenen"] },
      { number: 25, text: "Ägypten und Juda und Edom und die Söhne Ammon und Moab und alle mit geschorenen Haarrändern*, die in der Wüste wohnen. Denn alle Nationen sind unbeschnitten*, und das ganze Haus Israel hat ein unbeschnittenes Herz*.", footnotes: ["℘ Kap. 25,23; 49,32; 3Mo 19,27", "℘ Hes 44,7; Röm 2,25", "℘ Kap. 4,4; 3Mo 26,41"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "*Hört das Wort, das der HERR zu euch redet, Haus Israel*!", heading: "Die vergänglichen Götterbilder und der ewige Gott", footnotes: ["℘ V. 1-11: Jes 40,18-26; 44,6-21", "℘ Kap. 2,4"] },
      { number: 2, text: "So spricht der HERR: Gewöhnt euch nicht an den Weg der Nationen* und erschreckt nicht vor den Zeichen des Himmels, auch wenn die Nationen vor ihnen erschrecken!", footnotes: ["℘ 3Mo 18,3; 5Mo 18,9"] },
      { number: 3, text: "Denn die Ordnungen der Völker — ein Götze* ist es, der sie gab. Ja, ihre Götzen sind Holz, das einer aus dem Wald geschlagen hat, ein Werk von Künstlerhänden, mit dem Schnitzmesser* hergestellt.", footnotes: ["w. ein Nichts; d. i. eine verächtliche Bezeichnung für die Götzen\n℘ Kap. 16,19", "o. Beil"] },
      { number: 4, text: "Man schmückt es mit Silber und mit Gold. Mit Nägeln und mit Hämmern befestigen sie es, dass es nicht wackelt." },
      { number: 5, text: "Sie sind wie eine Vogelscheuche im Gurkenfeld und reden nicht; sie müssen getragen werden, denn sie gehen nicht*. Fürchtet euch nicht vor ihnen*! Denn sie tun nichts Böses, und Gutes tun können sie auch nicht.", footnotes: ["℘ 5Mo 4,28; Jes 46,1.7", "℘ 2Chr 25,15; Jes 41,23; 44,10"] },
      { number: 6, text: "Keiner ist dir gleich, HERR. Du bist groß, und groß ist dein Name durch deine Macht*.", footnotes: ["℘ 1Chr 16,25; Ps 86,8; 147,5; Mal 1,11"] },
      { number: 7, text: "Wer sollte dich nicht fürchten*, König der Nationen? Denn das gebührt dir*! Denn unter allen Weisen der Nationen und in all ihren Königreichen ist niemand dir gleich*.", footnotes: ["℘ Offb 15,4", "℘ Ps 47,3.9", "℘ 1Chr 16,25; Ps 86,8; 147,5; Mal 1,11"] },
      { number: 8, text: "Sie sind allesamt dumm und töricht; die Unterweisung der Nichtigkeiten* — Holz ist sie*.", footnotes: ["w. ein Nichts; d. i. eine verächtliche Bezeichnung für die Götzen", "d. h. die Unterweisung der nichtigen Götzen ist ihnen gleich: Holz\n℘ Hab 2,18; Sach 10,2"] },
      { number: 9, text: "Dünn geschlagenes Silber wird aus Tarsis* gebracht und Gold aus Ufas*, ein Werk des Kunsthandwerkers und der Hände des Goldschmieds. Violetter und roter Purpur ist ihr Gewand, sie alle sind nur ein Werk von Kunstfertigen*.", footnotes: ["℘ 2Chr 9,21", "℘ Dan 10,5", "℘ Hos 8,6"] },
      { number: 10, text: "Aber der HERR ist in Wahrheit Gott*. Er ist der lebendige Gott* und ein ewiger König*. Vor seinem Grimm erbebt die Erde, und seinen Zorn können die Nationen nicht ertragen*.", footnotes: ["℘ Ps 100,3; Joh 17,3", "℘ Kap. 23,36; Jos 3,10", "℘ 1Chr 29,11; Ps 10,16; 74,12; Jes 40,28; Dan 3,33; 6,27; 1Tim 1,17", "℘ Ps 76,8; Nah 1,5.6"] },
      { number: 11, text: "So sollt ihr zu ihnen sagen: Die Götter, die den Himmel und die Erde nicht gemacht haben, die werden von der Erde und unter diesem Himmel verschwinden*.", footnotes: ["Dieser Vers ist bis auf ein Wort in aram. Sprache verfasst.\n℘ Kap. 43,12.13; 50,2; 51,18; 1Sam 5,4; Jes 57,12"] },
      { number: 12, text: "*Er ist es, der die Erde gemacht hat durch seine Kraft*, der den Erdkreis gegründet durch seine Weisheit und den Himmel ausgespannt durch seine Einsicht*,", footnotes: ["℘ V. 12-16: Kap. 51,15-19", "℘ Ps 65,7", "℘ Kap. 32,17; 1Mo 1,1; 1Chr 16,26; Ps 104,24; 136,5; Jes 44,24"] },
      { number: 13, text: "auf dessen Befehl sich die Menge des Wassers am Himmel ergießt*, der Wolken aufsteigen lässt vom Ende der Erde, Blitze macht für den Regen* und den Wind aus seinen Kammern* herauslässt*.", footnotes: ["T.; Andere üs. mit Textänderung: Wenn er die Stimme erhebt, gibt es Wasserrauschen am Himmel; Mas. T.: Bei der Stimme seines Erhebens gibt es eine Menge oder ein Rauschen des Wassers am Himmel\n℘ Hi 38,26", "℘ Kap. 5,24; 14,22; Ps 104,13; 135,7; Sach 10,1", "w. Vorräten, o. Vorratskammern", "℘ Am 4,13"] },
      { number: 14, text: "Dumm steht da jeder Mensch, ohne Erkenntnis*, beschämt jeder Goldschmied wegen des Götterbildes. Denn Lüge sind seine gegossenen Bilder, Leben haben sie nicht*,", footnotes: ["℘ Ps 115,8", "o. Denn ein Trugbild hat er gegossen, es ist kein Atem darin."] },
      { number: 15, text: "Nichtigkeit* sind sie, ein Werk zum Gespött*. Zur Zeit ihrer Heimsuchung sind sie verloren*.", footnotes: ["w. ein Nichts; d. i. eine verächtliche Bezeichnung für die Götzen", "℘ 1Sam 5,4", "℘ Kap. 43,12.13; 50,2; 51,18; 1Sam 5,4; Jes 57,12"] },
      { number: 16, text: "Jakobs Anteil* aber ist nicht wie diese. Denn er, der HERR, ist es, der das All gebildet hat*, und Israel ist der Stamm seines Erbteils*, HERR der Heerscharen ist sein Name*.", footnotes: ["»Jakobs Anteil« ist ein Name für Gott.\n℘ Ps 16,5", "℘ Ps 33,6", "℘ 2Mo 34,9; 5Mo 32,9", "℘ Kap. 31,35; 32,18; 46,18; 50,34"] },
      { number: 17, text: "Raffe dein Gepäck von der Erde zusammen, die du in der Belagerung sitzt*!", heading: "Das Exil in Babylon — Klagegebet über die Zerstörung Jerusalems", footnotes: ["℘ Hes 12,3.11"] },
      { number: 18, text: "Denn so spricht der HERR: Siehe, ich werde diesmal die Bewohner des Landes wegschleudern* und sie bedrängen, damit sie* sie finden. —", footnotes: ["℘ Kap. 16,13; Jes 22,17.18", "d. h. die Feinde"] },
      { number: 19, text: "Wehe mir wegen meines Zusammenbruchs! Unheilbar ist meine Wunde*. Doch ich sage: Ja, das ist meine Krankheit, und ich will sie tragen*.", footnotes: ["℘ Kap. 4,31; Kla 1,12.13", "℘ Kap. 14,7; Kla 3,39"] },
      { number: 20, text: "Mein Zelt ist verwüstet, und alle meine Stricke sind zerrissen*. Meine Kinder sind von mir weggezogen und sind nicht mehr da*. Da ist niemand*, der noch mein Zelt ausspannt und meine Zeltdecken befestigt*.", footnotes: ["℘ Kap. 4,20", "℘ Kap. 31,15", "℘ Jes 51,18", "℘ Kap. 30,17"] },
      { number: 21, text: "Denn die Hirten sind dumm geworden und haben den HERRN nicht gesucht*. Darum haben sie nicht verständig gehandelt*, und ihre ganze Herde hat sich zerstreut*. —", footnotes: ["℘ Kap. 2,8", "o. haben sie kein Gelingen gehabt", "℘ Kap. 23,1.2; Hes 34,6"] },
      { number: 22, text: "Horch! eine Nachricht: Siehe, sie kommt, und ein großes Getöse vom Land des Nordens*, um die Städte Judas zur Öde zu machen, zur Wohnung der Schakale*.", footnotes: ["℘ Kap. 4,6", "℘ Kap. 2,15"] },
      { number: 23, text: "Ich habe erkannt, HERR, dass der Weg des Menschen nicht in seiner Macht steht und dass es keinem*, der geht, gegeben ist, seinen Schritt zu lenken*.", footnotes: ["w. keinem Mann", "℘ Spr 16,1.9; Dan 5,23"] },
      { number: 24, text: "Züchtige mich, HERR, doch mit rechtem Maß*, nicht in deinem Zorn, damit du mich nicht aufreibst*!", footnotes: ["w. entsprechend deinem Recht", "w. wenig machst; o. zu wenigen machst\n℘ Kap. 30,11; Ps 6,2; Jes 28,28"] },
      { number: 25, text: "Gieße deinen Grimm über die Nationen aus, die dich nicht kennen*, und über die Geschlechter, die deinen Namen nicht anrufen! Denn sie haben Jakob gefressen, ja, sie haben ihn gefressen und ihn vernichtet und seinen Weideplatz öde gemacht*.", footnotes: ["℘ 1Thes 4,5; Offb 16,1", "o. seine Wohnstätte menschenleer gemacht\n℘ Kap. 30,16; Ps 79,6.7"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Das Wort, das von dem HERRN zu Jeremia geschah:", heading: "Bundesbruch des Volkes und Gottes Gericht" },
      { number: 2, text: "Hört auf die Worte dieses Bundes und redet zu den Männern von Juda und zu den Bewohnern von Jerusalem!" },
      { number: 3, text: "Und sage zu ihnen: So spricht der HERR, der Gott Israels: Verflucht ist der Mann, der nicht auf die Worte dieses Bundes hört*,", footnotes: ["℘ 5Mo 27,26; Gal 3,10"] },
      { number: 4, text: "den ich euren Vätern geboten habe an dem Tag, da ich sie herausführte aus dem Land Ägypten*, aus dem eisernen Schmelzofen*, indem ich sprach: Hört auf meine Stimme und handelt danach, nach allem, was ich euch gebiete, dann werdet ihr mein Volk, und ich werde euer Gott sein*,", footnotes: ["℘ 5Mo 5,2-6", "℘ 5Mo 4,20", "℘ Kap. 7,23; 30,22"] },
      { number: 5, text: "damit ich den Schwur aufrechthalte, den ich euren Vätern geschworen habe: ihnen ein Land zu geben, das von Milch und Honig überfließt*, wie es an diesem Tag ist! Ich antwortete und sprach: Amen, HERR*!", footnotes: ["℘ Kap. 32,22; 2Mo 3,8.17; Ps 105,8-11", "℘ Kap. 28,6"] },
      { number: 6, text: "Und der HERR sprach zu mir: Rufe alle diese Worte aus in den Städten Judas und auf den Straßen von Jerusalem und sprich: Hört die Worte dieses Bundes und handelt danach*!", footnotes: ["℘ 5Mo 4,1; Jak 1,22"] },
      { number: 7, text: "Denn ich habe euren Vätern eindringlich bezeugt schon an dem Tag, als ich sie aus dem Land Ägypten heraufführte, bis zu diesem Tag, früh mich aufmachend und bezeugend*, indem ich sprach: Hört auf meine Stimme*!", footnotes: ["℘ Kap. 7,25; 25,4", "℘ 2Mo 15,26; 2Kö 17,13; Hos 4,1"] },
      { number: 8, text: "Aber sie haben nicht gehört und ihr Ohr nicht geneigt*, sondern sie lebten alle* in der Verstocktheit ihres bösen Herzens*. Und ich brachte über sie alle Worte dieses Bundes, den ich zu befolgen gebot und den sie nicht befolgt haben*.", footnotes: ["℘ Kap. 7,13; 34,14", "w. gingen ein jeder", "℘ Kap. 7,24; Hebr 3,12", "℘ Kap. 32,23; 5Mo 28,15"] },
      { number: 9, text: "Und der HERR sprach zu mir: Es hat sich eine Verschwörung gefunden unter den Männern von Juda und unter den Bewohnern von Jerusalem*.", footnotes: ["℘ Hes 22,25-29"] },
      { number: 10, text: "Sie sind zurückgekehrt zu den Sünden der Väter vor ihnen, die sich auch schon geweigert hatten, auf meine Worte zu hören. So sind auch sie anderen Göttern nachgelaufen, um ihnen zu dienen*. Das Haus Israel und das Haus Juda haben meinen Bund gebrochen*, den ich mit ihren Vätern geschlossen habe*.", footnotes: ["℘ Hes 20,18-31", "℘ Hes 16,59", "℘ Kap. 22,9; 31,32; Jes 24,5"] },
      { number: 11, text: "Darum, so spricht der HERR: Siehe, ich bringe Unheil über sie, dem sie nicht entgehen können*, und sie werden zu mir um Hilfe schreien, aber ich werde nicht auf sie hören*.", footnotes: ["℘ Kap. 19,15; 35,17", "℘ Kap. 14,12"] },
      { number: 12, text: "Und die Städte von Juda und die Bewohner von Jerusalem werden hingehen und zu den Göttern um Hilfe schreien, denen sie Rauchopfer dargebracht haben; aber die werden sie nicht retten zur Zeit ihres Unglücks*.", footnotes: ["℘ 5Mo 32,37; Jes 46,7"] },
      { number: 13, text: "Denn so zahlreich wie deine Städte sind deine Götter geworden, Juda*. Und nach der Zahl der Straßen von Jerusalem habt ihr der Schande* Altäre gesetzt*, Altäre, um dem Baal Rauchopfer darzubringen*. —", footnotes: ["℘ Kap. 2,28", "d. i. ein Schimpfwort für Baal", "℘ Kap. 3,24; 17,1", "℘ Kap. 7,9; 18,15; 44,5.21; 2Chr 28,25; Hos 10,1"] },
      { number: 14, text: "Du aber, bitte nicht für dieses Volk und erhebe weder Flehen noch Gebet für sie*! Denn ich werde nicht hören zu der Zeit, da sie wegen ihres Unglücks zu mir rufen werden*.", footnotes: ["℘ Kap. 7,16", "℘ Kap. 14,12"] },
      { number: 15, text: "Was hat mein Geliebter* in meinem Haus zu schaffen, da sie doch alle nur Ränke schmieden*? Wird heiliges Opferfleisch deine Bosheit von dir wegnehmen? Dann kannst du jubeln.*", footnotes: ["Juda ist gemeint.", "℘ Kap. 23,11", "Andere üs.: Ränke schmieden, und heiliges Fleisch an dir vorübergeht? Wenn dein Unglück kommt, dann kannst du jubeln."] },
      { number: 16, text: "Einen grünen Ölbaum mit schön gewachsener Frucht* hatte der HERR dich genannt*. Ein großes Geprassel: Feuer hat er an ihn gelegt, und seine Äste brechen ab*.", footnotes: ["w. von schöner Fruchtgestalt", "℘ Kap. 2,21; Röm 11,17", "℘ Ps 80,17"] },
      { number: 17, text: "Und der HERR der Heerscharen, der dich gepflanzt, hat Unheil über dich beschlossen* wegen der Bosheit des Hauses Israel und des Hauses Juda, die sie verübt haben*, um mich zu reizen, indem sie dem Baal Rauchopfer darbrachten*.", footnotes: ["w. hat Böses über dich geredet", "o. wegen des Bösen, das sie sich selbst angetan haben\n℘ Kap. 40,2.3", "℘ Kap. 7,9; 18,15; 44,5.21; 2Chr 28,25; Hos 10,1"] },
      { number: 18, text: "Der HERR hat es mich erkennen lassen, da erkannte ich es. Damals zeigtest du mir ihre Taten*.", heading: "Mordpläne gegen Jeremia — Sein Klagegebet — Gottes Antwort", footnotes: ["℘ 1Sam 23,11.12; 2Kö 6,32"] },
      { number: 19, text: "Und ich war wie ein zutrauliches Lamm, das zum Schlachten geführt wird. Ich hatte nicht erkannt, dass sie Anschläge* gegen mich planten*: Lasst uns den Baum mit seiner Frucht verderben und ihn aus dem Land der Lebendigen ausrotten, dass man sich nicht mehr an seinen Namen erinnert*!", footnotes: ["w. Pläne", "℘ Kap. 1,19; Ps 37,32; Hos 9,8", "℘ Lk 20,14"] },
      { number: 20, text: "Aber du, HERR der Heerscharen, der du gerecht richtest*, Nieren* und Herz prüfst*, lass mich deine Rache an ihnen sehen!* Denn dir habe ich meine Rechtssache anvertraut*.", footnotes: ["℘ Kap. 12,1; 2Tim 4,8", "Die Nieren gelten als Innerstes des Menschen und als Sitz des Gewissens.", "℘ Kap. 17,10; 1Chr 28,9; 1Thes 2,4; Offb 2,23", "℘ Kap. 15,15; 17,18", "℘ Kap. 20,12; 2Kö 19,14; Hi 5,8; Kla 3,58.59; Röm 12,19"] },
      { number: 21, text: "Darum, so spricht der HERR über die Männer von Anatot, die nach deinem* Leben trachten* und sagen: Du sollst nicht weissagen im Namen des HERRN*, sonst wirst du durch unsere Hände sterben! —", footnotes: ["LXX: meinem", "℘ Kap. 1,19; 12,6; Mt 13,57", "℘ Jes 30,10"] },
      { number: 22, text: "darum, so spricht der HERR der Heerscharen: Siehe, ich suche sie heim. Die jungen Männer werden durchs Schwert sterben, ihre Söhne und ihre Töchter werden vor Hunger sterben*,", footnotes: ["℘ Kap. 18,21.22"] },
      { number: 23, text: "und kein Rest wird von ihnen bleiben; denn ich bringe Unglück über die Männer von Anatot im Jahr ihrer Heimsuchung*.", footnotes: ["℘ Kap. 23,12"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Du bleibst im Recht*, HERR, wenn ich mit dir einen Rechtsstreit führe. Dennoch möchte ich Rechtssachen mit dir bereden: Warum ist der Weg der Gottlosen* erfolgreich*, warum haben Ruhe alle, die Treulosigkeit üben*?", footnotes: ["w. Du bist gerecht\n℘ Kap. 11,20; Ps 51,6; Dan 9,7", "o. Ungerechten", "℘ Kap. 5,28; Ps 73,3-5; Mal 2,17; 3,15", "℘ Hab 1,13"] },
      { number: 2, text: "Du hast sie gepflanzt, sie haben auch Wurzel geschlagen; sie wachsen*, tragen auch Frucht*. Nahe bist du in ihrem Mund, doch fern von ihren Nieren*.", footnotes: ["w. gehen", "℘ Hi 24,12; Ps 37,35", "Die Nieren gelten als Innerstes des Menschen und als Sitz des Gewissens.\n℘ Jes 29,13; Hos 7,14; Tit 1,16"] },
      { number: 3, text: "Du aber, HERR, du kennst mich, du siehst mich und prüfst mein Herz, wie es zu dir steht*. Reiße sie fort wie Schafe zur Schlachtung und weihe sie* für den Tag des Abschlachtens*!", footnotes: ["℘ Hi 23,10; Ps 17,3", "o. sondere sie aus", "℘ Kap. 17,18; Ps 55,24; Jak 5,5"] },
      { number: 4, text: "Wie lange soll das Land vertrocknen* und das Kraut des ganzen Feldes welken?* Wegen der Bosheit seiner Bewohner sind Vieh und Vögel zugrunde gegangen*; denn sie sagen: Er* wird unser Ende* nicht sehen. —", footnotes: ["o. trauern", "℘ Kap. 14,2-6; 23,10; Joe 1,18", "℘ Kap. 9,9; Ps 107,34; Jes 24,4-6", "d. i. Gott", "LXX und die alte lat. Üs.: unsere Wege"] },
      { number: 5, text: "Wenn du mit Fußgängern läufst und sie dich schon ermüden, wie willst du dann mit Pferden um die Wette laufen? Und wenn du dich nur im Land des Friedens sicher fühlst, wie willst du es dann machen in der Pracht* des Jordan?*", footnotes: ["Gemeint ist das Dickicht am Jordan.", "℘ Kap. 49,19; 50,44"] },
      { number: 6, text: "Denn auch deine Brüder und das Haus deines Vaters, auch sie sind treulos gegen dich*, auch sie rufen dir nach aus voller Kehle. Glaube ihnen nicht, wenn sie freundlich mit dir reden*!", footnotes: ["℘ Kap. 9,3; 11,21", "℘ Ps 12,3; Spr 23,8; 26,25"] },
      { number: 7, text: "Ich habe mein Haus verlassen, mein Erbteil verstoßen, ich habe den Liebling* meiner Seele in die Hand seiner Feinde gegeben*.", heading: "Gottes Klage über die Folgen seines Gerichts — Unheil und Heil für Israels Nachbarvölker", footnotes: ["℘ 5Mo 33,12; Offb 20,9", "℘ Kap. 7,14; 14,19; 22,5; 2Kö 21,14; Ps 106,40.41; Mt 23,38; Lk 13,35"] },
      { number: 8, text: "Mein Erbteil ist mir geworden wie ein Löwe im Wald. Es hat seine Stimme gegen mich erhoben, darum hasse ich es." },
      { number: 9, text: "Ist mir mein Erbteil etwa ein bunter Raubvogel, so dass andere Raubvögel ringsum über ihn herfallen? Auf! Versammelt alle Tiere des Feldes, bringt sie zum Fressen herbei*!", footnotes: ["℘ Jes 56,9"] },
      { number: 10, text: "Viele Hirten haben meinen Weinberg verdorben*, mein Feldstück zertreten; sie haben mein kostbares Feldstück zur wüsten Einöde gemacht*.", footnotes: ["o. vernichtet", "℘ Kap. 6,3; 25,37.38; Jes 3,14; Hes 34,5"] },
      { number: 11, text: "Man* hat es zur Einöde gemacht: verödet trauert es vor mir. Das ganze Land ist verödet*, weil niemand es zu Herzen nahm*.", footnotes: ["o. Er (der Feind)", "℘ Kap. 9,9.10", "℘ Jes 42,25"] },
      { number: 12, text: "Über alle kahlen Höhen in der Steppe* sind Verwüster gekommen. Denn ein Schwert des HERRN frisst von einem Ende des Landes bis zum anderen Ende des Landes*: Kein Friede allem Fleisch*!", footnotes: ["d. i. überall, wo Weide zu finden war", "℘ Kap. 47,6; Hes 21,8-10", "℘ Kap. 8,15"] },
      { number: 13, text: "Sie haben Weizen gesät und Dornen geerntet; sie haben sich abgemüht, nichts ausgerichtet*. So werdet zuschanden an euren Erträgen* vor der Glut des Zornes des HERRN!*", footnotes: ["℘ 3Mo 26,16.20; Hos 8,7; Hag 1,6.9-11", "o. So sind sie zuschanden geworden an ihren Erträgen", "℘ Kap. 3,25; Ps 78,62"] },
      { number: 14, text: "So spricht der HERR: Über alle meine bösen Nachbarn, die das Erbteil antasten*, das ich mein Volk Israel habe erben lassen: Siehe, ich werde sie aus ihrem Land herausreißen*, und das Haus Juda werde ich aus ihrer Mitte ausreißen*.", footnotes: ["℘ Hes 36,5", "℘ Kap. 25,9-11; 46-50; Hes 25,8.15; Ob 10-16; Zef 2,8-10", "℘ Kap. 32,37; Hes 28,25.26"] },
      { number: 15, text: "Und es soll geschehen, nachdem ich sie herausgerissen habe, werde ich mich wieder über sie erbarmen und sie zurückbringen, einen jeden in sein Erbteil und einen jeden in sein Land*.", footnotes: ["℘ Kap. 16,15; 24,6"] },
      { number: 16, text: "Und es soll geschehen, wenn sie* die Wege meines Volkes wirklich lernen, so dass sie bei meinem Namen schwören: »So wahr der HERR lebt!« — wie sie mein Volk gelehrt haben, beim Baal zu schwören, so sollen sie mitten in meinem Volk aufgebaut werden*.", footnotes: ["d. h. die anderen Völker", "℘ Kap. 4,2; Jes 2,3"] },
      { number: 17, text: "Wenn sie aber nicht hören, dann werde ich eine solche Nation endgültig ausreißen und verloren geben*, spricht der HERR*.", footnotes: ["℘ Jes 41,11; 60,12; Mi 5,14", "w. ist der Ausspruch des HERRN"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "So hat der HERR zu mir gesprochen: Geh und kaufe dir einen leinenen Hüftschurz* und lege ihn um deine Hüften! Aber ins Wasser sollst du ihn nicht bringen.", heading: "Zwei prophetische Zeichenhandlungen", footnotes: ["℘ Kap. 18,2; 19,1; 27,2; 43,9; Jes 20,3"] },
      { number: 2, text: "Und ich kaufte den Hüftschurz nach dem Wort des HERRN und legte ihn um meine Hüften." },
      { number: 3, text: "Und das Wort des HERRN geschah zu mir zum zweiten Mal:" },
      { number: 4, text: "Nimm den Hüftschurz, den du gekauft hast, der um deine Hüften ist, und mach dich auf, geh an den Euphrat und verbirg ihn dort in einer Felsspalte*!", footnotes: ["℘ Kap. 51,63"] },
      { number: 5, text: "Da ging ich hin und verbarg ihn am Euphrat, wie der HERR mir geboten hatte." },
      { number: 6, text: "Und es geschah am Ende von vielen Tagen, da sprach der HERR zu mir: Mach dich auf, geh an den Euphrat und hole von dort den Hüftschurz, den dort zu verbergen ich dir geboten habe!" },
      { number: 7, text: "Da ging ich an den Euphrat und grub und nahm den Hüftschurz von der Stelle, wo ich ihn verborgen hatte; und siehe, der Hüftschurz war verdorben, taugte zu gar nichts mehr*. —", footnotes: ["℘ Kap. 24,8"] },
      { number: 8, text: "Und das Wort des HERRN geschah zu mir:" },
      { number: 9, text: "So spricht der HERR: So werde ich den Hochmut Judas und den großen Hochmut Jerusalems verderben*.", footnotes: ["℘ Kap. 25,18; Jes 2,12"] },
      { number: 10, text: "Dieses böse Volk, das sich weigert, meine Worte zu hören*, das da lebt in der Verstocktheit seines Herzens* und anderen Göttern nachläuft, um ihnen zu dienen und sich vor ihnen niederzuwerfen*: es soll werden wie dieser Hüftschurz, der zu gar nichts taugt.", footnotes: ["℘ Kap. 7,13; 16,12", "℘ Kap. 7,24", "℘ Kap. 9,13"] },
      { number: 11, text: "Denn ebenso wie der Hüftschurz sich an die Hüften eines Mannes anschließt, so hatte ich das ganze Haus Israel und das ganze Haus Juda an mich angeschlossen*, spricht der HERR*, damit sie mir zum Volk* und zum Ruhm* und zum Preis und zum Schmuck seien*; aber sie haben nicht gehört*.", footnotes: ["w. an mir haften lassen", "w. ist der Ausspruch des HERRN", "℘ 2Mo 19,5", "w. zum Namen", "℘ Kap. 33,9; 5Mo 26,18.19", "℘ Kap. 19,15"] },
      { number: 12, text: "Und nun sage dieses Wort zu ihnen: So spricht der HERR, der Gott Israels: Jeder Krug wird mit Wein gefüllt. Und wenn sie zu dir sagen: Wissen wir nicht sehr wohl, dass jeder Krug mit Wein gefüllt wird? —" },
      { number: 13, text: "dann sage ihnen: So spricht der HERR: Siehe, ich werde alle Bewohner dieses Landes und die Könige, die auf dem Thron Davids sitzen*, und die Priester und die Propheten und alle Bewohner von Jerusalem mit Trunkenheit erfüllen*.", footnotes: ["w. die dem David (o. von David) auf seinem Thron sitzen", "℘ Jes 29,9"] },
      { number: 14, text: "Und ich werde sie zerschmettern*, einen am anderen, die Väter zusammen mit den Kindern, spricht der HERR*. Ich werde kein Mitleid haben noch sie schonen* noch mich erbarmen, dass ich sie nicht verderbe*.", footnotes: ["℘ Ps 2,9", "w. ist der Ausspruch des HERRN", "w. noch wird mein Auge ihretwegen fließen (d. h. weinen)", "℘ Kap. 15,6; 16,5.13; 21,7; 25,16; Jes 27,11; Hes 7,3.4"] },
      { number: 15, text: "Hört und nehmt zu Ohren, überhebt euch nicht! Denn der HERR hat geredet*.", footnotes: ["℘ Jes 1,2"] },
      { number: 16, text: "Gebt dem HERRN, eurem Gott, Ehre*, bevor er es finster macht und bevor eure Füße sich an Bergen der Dämmerung stoßen und ihr auf Licht wartet und er es in Finsternis verwandelt und zur Dunkelheit macht*.", footnotes: ["℘ Jos 7,19; Ps 29,2; Mal 2,2; Offb 14,7", "℘ Kap. 23,12; Jes 59,10; Joe 2,2; Am 8,9; Joh 12,35"] },
      { number: 17, text: "Wenn ihr aber nicht hört, wird meine Seele im Verborgenen weinen* wegen eures Hochmuts. Und bitter weinen wird mein Auge und von Tränen fließen, weil die Herde des HERRN gefangen weggeführt wird*.", footnotes: ["℘ Ps 119,136; Phil 3,18", "℘ Kap. 8,23; Kla 1,16; Lk 19,41"] },
      { number: 18, text: "Sprich zum König und zur Herrin*: Setzt euch tief herunter! Denn von euren Häuptern ist herabgesunken* die Krone eurer Herrlichkeit*.", footnotes: ["Gemeint ist die Königinmutter.", "w. denn herabgesunken ist, was euch zu Häupten war", "℘ Kap. 22,24-28"] },
      { number: 19, text: "Die Städte des Südens sind verschlossen, und niemand öffnet*. Ganz Juda wird weggeführt, vollständig weggeführt*.", footnotes: ["d. i. weil sie schon vom Feind eingenommen sind", "℘ Kap. 24,1; 28,4; 52,28; 1Chr 9,1"] },
      { number: 20, text: "Erhebt eure Augen und seht*, wie die Feinde von Norden kommen*! Wo ist die Herde, die dir gegeben war, deine herrlichen Schafe*?", footnotes: ["LXX: Hebe deine Augen auf, Jerusalem, und sieh", "℘ Kap. 6,22-24", "℘ Spr 14,28"] },
      { number: 21, text: "Was wirst du sagen, wenn er deine Liebhaber — du hast sie ja selbst an dich gewöhnt — als Oberhaupt über dich setzen wird*? Werden dich nicht Wehen ergreifen wie eine Frau, die gebiert*?", footnotes: ["℘ 2Kö 16,7", "℘ Kap. 4,31"] },
      { number: 22, text: "Und wenn du in deinem Herzen sagst: Warum ist mir dies zugestoßen*? — wegen der Größe deiner Schuld sind deine Säume* aufgedeckt und deine Fersen misshandelt worden*.", footnotes: ["℘ Kap. 5,19", "o. Schleppen des Kleides", "d. h. bist du vergewaltigt worden\n℘ Kap. 2,17.19; 16,10.11; Hos 2,5"] },
      { number: 23, text: "Kann ein Schwarzer* seine Haut ändern, ein Leopard seine Flecken*? Dann könntet auch ihr Gutes tun, die ihr an Bösestun gewöhnt seid*.", footnotes: ["w. ein Kuschit", "℘ Pred 1,15", "℘ Mt 12,34.35"] },
      { number: 24, text: "So werde ich sie zerstreuen wie Strohstoppeln, die vor dem Wind der Wüste dahinfahren*.", footnotes: ["℘ Kap. 18,17; Ps 1,4"] },
      { number: 25, text: "Das ist dein Los, dein von mir zugemessenes Teil*, spricht der HERR*, weil du mich vergessen* und auf Lüge vertraut hast*.", footnotes: ["℘ Hi 20,29; Ps 11,6", "w. ist der Ausspruch des HERRN", "℘ Kap. 2,32; 18,15; Hes 23,35", "℘ Kap. 7,8; Jes 28,15; Röm 1,25"] },
      { number: 26, text: "Und so werde auch ich deine Säume* hochheben* über dein Gesicht, dass deine Schande gesehen wird*.", footnotes: ["o. Schleppen des Kleides", "w. entblößen, o. abstreifen", "℘ Jes 47,3; Kla 1,8; Hes 16,37; Hos 2,12"] },
      { number: 27, text: "Dein Ehebrechen und dein Wiehern, die Schandtat* deiner Hurerei auf den Hügeln und im Feld: deine Gräuel habe ich gesehen*. Wehe dir, Jerusalem*! Du wirst nicht rein werden — wie lange wird es noch dauern?*", footnotes: ["o. das Laster", "℘ Kap. 2,20; 5,7.8; Hes 6,13", "℘ Hes 16,23", "℘ Kap. 4,14; Hes 24,13; Hos 8,5; Mk 7,21"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Was als Wort des HERRN zu Jeremia geschah aus Anlass der Dürre*:", heading: "In Hungersnot und Kriegsgefahr weist Gott das Gebet des Volkes und die Fürbitte des Propheten ab", footnotes: ["o. der lang anhaltenden Dürre\n℘ Kap. 3,3"] },
      { number: 2, text: "Juda trauert, und seine Tore welken dahin*, sie liegen in Trauer* am Boden, und Jerusalems Klagegeschrei steigt empor*.", footnotes: ["d. h. das Leben in seinen Städten", "o. im Trauergewand", "℘ Kap. 12,4; Jes 24,11; Joe 1,14"] },
      { number: 3, text: "Seine Mächtigen schicken ihre Untergebenen* nach Wasser. Sie kommen zu den Zisternen und finden kein Wasser, sie kommen mit leeren Händen zurück mit ihren Gefäßen*; sie sind enttäuscht und beschämt und verhüllen ihr Haupt*.", footnotes: ["w. ihre Jungen, o. ihre Kleinen", "℘ Am 4,8", "℘ 2Sam 15,30"] },
      { number: 4, text: "Wegen des Erdbodens, der zerbrochen ist, weil kein Regen im Land ist*, sind die Bauern beschämt und verhüllen ihr Haupt*.", footnotes: ["℘ 3Mo 26,18-20", "℘ Joe 1,11"] },
      { number: 5, text: "Ja, auch die Hirschkuh auf dem Feld gebiert und lässt ihr Kalb im Stich; denn kein Gras ist da." },
      { number: 6, text: "Und die Wildesel stehen auf den kahlen Höhen, schnappen nach Luft wie die Schakale; ihre Augen erlöschen, denn kein Kraut ist da." },
      { number: 7, text: "Wenn unsere Sünden gegen uns aussagen, HERR, so handle um deines Namens willen* gnädig an uns! Denn zahlreich sind unsere Treulosigkeiten; gegen dich haben wir gesündigt*.", footnotes: ["℘ V. 20.21; Ps 25,11; 79,9", "℘ Kap. 5,25; 10,19; Jes 59,12; Dan 9,9; Mi 7,9"] },
      { number: 8, text: "Du Hoffnung Israels*, sein Retter in der Zeit der Bedrängnis*, warum willst du wie ein Fremdling im Land sein und wie ein Wanderer, der nur zum Übernachten eingekehrt ist?", footnotes: ["℘ Kap. 17,13; 50,7", "℘ Kap. 16,19; Ps 46,2; Jes 33,2"] },
      { number: 9, text: "Warum willst du wie ein erschrockener* Mann sein, wie ein Held, der nicht zu retten vermag?* Du bist doch in unserer Mitte*, HERR, und über uns ist dein Name ausgerufen*. Verlass uns nicht!*", footnotes: ["o. überfallener", "℘ Ps 10,1", "℘ 2Mo 29,45; Sach 8,3", "℘ Kap. 15,16; 5Mo 28,10; 2Chr 7,14; Jes 43,7; 63,19", "℘ Kap. 51,5; 1Sam 12,22; Kla 5,20"] },
      { number: 10, text: "So spricht der HERR zu diesem Volk: Umherzuschweifen, so liebten sie es, sie hielten ihre Füße nicht zurück*. Und der HERR hat kein Gefallen an ihnen*: nun wird er an ihre Missetaten denken* und ihre Sünden heimsuchen*. —", footnotes: ["℘ Kap. 2,23-25", "℘ Ps 95,10; Hebr 10,38", "℘ Hos 7,2", "℘ Hos 8,13"] },
      { number: 11, text: "Und der HERR sprach zu mir: Bitte nicht für dieses Volk zum Guten*!", footnotes: ["℘ Kap. 7,16"] },
      { number: 12, text: "Wenn sie fasten, werde ich nicht auf ihr Flehen hören*. Und wenn sie Brandopfer und Speisopfer opfern, werde ich kein Gefallen an ihnen haben*; sondern ich werde sie durch das Schwert und durch den Hunger und durch die Pest vernichten*.", footnotes: ["℘ Kap. 11,11.14; Spr 28,9; Jes 1,15; Mi 3,4; Sach 7,13", "℘ Kap. 6,20", "℘ Kap. 15,1-3; 21,7-9; 24,10; Hes 5,12.17"] },
      { number: 13, text: "Und ich sprach: Ach, Herr, HERR! Siehe, die Propheten sagen zu ihnen: Ihr werdet kein Schwert sehen, und Hunger wird euch nicht treffen, sondern ich werde euch einen beständigen Frieden geben an diesem Ort*.", footnotes: ["℘ Kap. 4,10; 5,12; 23,17; 37,19"] },
      { number: 14, text: "Und der HERR sprach zu mir: Die Propheten weissagen Lüge in meinem Namen. Ich habe sie nicht gesandt und sie nicht beauftragt — auch nicht zu ihnen geredet. Sie weissagen euch Lügenvision, Wahrsagerei, Nichtiges* und den Trug ihres Herzens*.", footnotes: ["Andere ziehen »Wahrsagung« und »Nichtiges« zusammen zu »Götzenorakel«.", "℘ Kap. 5,31; 8,10; 23,16.21.26; 27,10.14.15; Hes 13,2.6; Mt 7,15; 24,5"] },
      { number: 15, text: "Darum, so spricht der HERR: Über die Propheten, die in meinem Namen weissagen — und ich habe sie doch nicht gesandt —, die sagen: »Weder Schwert noch Hunger wird es in diesem Land geben«; diese Propheten sollen durch das Schwert und durch den Hunger umkommen*.", footnotes: ["℘ Kap. 6,15; 8,12.13; 5Mo 18,20; Hes 13,9-16; 14,10; 33,6"] },
      { number: 16, text: "Und das Volk, dem sie weissagen, soll, von Hunger und Schwert hingeworfen, auf den Straßen von Jerusalem daliegen*, und niemand wird sie begraben*, sie, ihre Frauen, ihre Söhne und ihre Töchter. Und ich werde ihre Bosheit über sie ausschütten*.", footnotes: ["w. sie werden Hingeworfene sein", "℘ Kap. 9,20.21; 16,4; Ps 79,3", "℘ Kap. 4,18; 20,6; 27,15"] },
      { number: 17, text: "Und du sollst dieses Wort zu ihnen sagen: Nacht und Tag fließen meine Augen von Tränen und kommen nicht zur Ruhe. Denn die Jungfrau, die Tochter meines Volkes, liegt mit schwerer Verletzung*, mit einer sehr schmerzenden Wunde zerbrochen da*.", footnotes: ["w. großem Zerbruch", "℘ Kap. 8,21.23; Kla 2,11; 3,48.49"] },
      { number: 18, text: "Wenn ich aufs Feld hinausgehe, siehe da: vom Schwert Durchbohrte! Und wenn ich in die Stadt komme, siehe da: Hungerkrankheiten!* Ja, sowohl Propheten als auch Priester ziehen im Land umher und wissen keinen Rat*.", footnotes: ["℘ Kla 1,20; 2,19-21", "w. und erkennen nicht. — Andere üs.: müssen als Händler in einem Land umherstreifen, das sie nicht kennen"] },
      { number: 19, text: "Hast du Juda ganz und gar verworfen? Oder verabscheut deine Seele Zion*? Warum hast du uns geschlagen, so dass keine Heilung für uns da ist*? Man hofft auf Frieden*, und da ist nichts Gutes, und auf die Zeit der Heilung, und siehe da: Schrecken*.", footnotes: ["℘ Kap. 12,7.8; Kla 2,22", "℘ Kap. 15,18; 30,12.13; Kla 2,13", "o. Heil; o. Wohlergehen", "℘ Kap. 8,15; Spr 29,1"] },
      { number: 20, text: "HERR, wir kennen unsere Gottlosigkeiten*, die Schuld unserer Väter; denn wir haben gegen dich gesündigt*.", footnotes: ["o. Ungerechtigkeiten", "℘ Kap. 3,25; Ps 106,6; Kla 1,20; Dan 9,5.8"] },
      { number: 21, text: "Um deines Namens willen* verschmähe uns nicht! Entehre nicht* den Thron deiner Herrlichkeit*! Denk an uns, mache deinen Bund mit uns nicht ungültig!*", footnotes: ["℘ V. 7", "w. Behandle nicht verächtlich", "℘ Kap. 3,17; 17,12", "℘ Ps 74,20"] },
      { number: 22, text: "Gibt es unter den Nichtigkeiten* der Nationen Regenspender, oder kann der Himmel von selbst Regengüsse geben*? Bist du es nicht, HERR, unser Gott*? Wir hoffen auf dich; denn du, du hast dies alles gemacht*.", footnotes: ["d. i. eine Bezeichnung für Götzen", "℘ Kap. 10,12-15; 1Kö 18,1; Apg 14,15.17", "℘ Hi 5,10; 28,26", "℘ Mi 5,6"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und der HERR sprach zu mir: Selbst wenn Mose* und Samuel* vor mir ständen, würde sich meine Seele nicht zu diesem Volk wenden*. Treibe sie von meinem Angesicht weg, dass sie fortgehen*.", footnotes: ["℘ 2Mo 32,11", "℘ 1Sam 12,23", "℘ Kap. 7,16; Hes 14,14", "℘ Kap. 7,15; Hos 9,15"] },
      { number: 2, text: "Und es soll geschehen, wenn sie zu dir sagen: Wohin sollen wir gehen? — dann sage zu ihnen: So spricht der HERR: Wer zum Tod bestimmt ist, gehe zum Tod; und wer zum Schwert, zum Schwert; und wer zum Hunger, zum Hunger; und wer zur Gefangenschaft, zur Gefangenschaft*.", footnotes: ["℘ Kap. 16,4; 43,11; Jes 10,4; Hes 5,2.12; Offb 13,10"] },
      { number: 3, text: "Denn ich bestelle über sie vier Arten von Verderben, spricht der HERR*: das Schwert zum Umbringen und die Hunde zum Herumzerren und die Vögel des Himmels und die Tiere der Erde zum Fressen und zum Vertilgen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 14,12; 5Mo 32,24"] },
      { number: 4, text: "Und ich will sie zum Entsetzen machen für alle Königreiche* der Erde* um Manasses willen, des Sohnes Hiskias, des Königs von Juda, wegen all dessen, was er in Jerusalem getan hat*. —", footnotes: ["viell. auch: ich will sie zur Misshandlung hingeben allen Königreichen", "℘ Kap. 24,9; 34,17", "℘ Kap. 29,18; 3Mo 26,33; 2Kö 21,11-16"] },
      { number: 5, text: "Denn wer wird mit dir Mitleid haben, Jerusalem, und wer dir Beileid bekunden*, und wer wird bei dir einkehren, um nach deinem Wohlergehen zu fragen*?", footnotes: ["w. wer wird deinetwegen den Kopf schütteln zum Zeichen der Trauer", "o. dir den Friedensgruß zu entbieten\n℘ Jes 51,19; Kla 1,16.17"] },
      { number: 6, text: "Du hast mich verworfen, spricht der HERR*, du hast mir den Rücken zugekehrt*. So werde ich meine Hand gegen dich ausstrecken* und dich zugrunde richten*. Ich bin es müde*, Mitleid zu haben.", footnotes: ["w. ist der Ausspruch des HERRN", "o. gehst rückwärts\n℘ Kap. 2,13; 7,24", "w. und so habe ich . . . ausgestreckt. — Die Verben stehen in der Vergangenheit bis zum Schluss von V. 8.", "℘ Kap. 13,14", "℘ Kap. 44,22; Am 7,8"] },
      { number: 7, text: "Und ich werde sie mit der Worfschaufel zu den Toren des Landes hinausworfeln*. Ich werde mein Volk kinderlos machen, es verloren geben. Sie sind von ihren Wegen nicht umgekehrt*.", footnotes: ["℘ Kap. 51,2", "℘ Kap. 5,3; Jes 9,12"] },
      { number: 8, text: "Ihre Witwen werden mir zahlreicher sein als der Sand der Meere. Ich bringe ihnen über die Mutter des jungen Mannes* am hellen Mittag einen Verwüster, lasse plötzlich Aufregung und Entsetzen auf sie* fallen*.", footnotes: ["o. über die Mutter und den jungen Mann", "d. i. die Mutter", "℘ Kap. 6,4.26"] },
      { number: 9, text: "Sie welkt dahin, die einst sieben Söhne gebar*; sie haucht ihre Seele aus. Ihre Sonne ist untergegangen, als es noch Tag war*; sie ist zuschanden und in ihrer Hoffnung getäuscht worden. Den Rest von ihnen werde ich dem Schwert ausliefern vor ihren Feinden*, spricht der HERR*.", footnotes: ["℘ 1Sam 2,5", "℘ Am 8,9", "℘ Hes 5,12", "w. ist der Ausspruch des HERRN"] },
      { number: 10, text: "Wehe mir, meine Mutter, dass du mich geboren hast*, einen Mann des Streites und einen Mann des Zankes für das ganze Land! Ich habe weder verliehen, noch hat man mir geliehen; dennoch fluchen mir alle*. —", heading: "Ein Klagegebet Jeremias — Gottes bedingte Heilszusage", footnotes: ["℘ Kap. 20,14.17; Hi 3,1", "℘ Kap. 1,19"] },
      { number: 11, text: "Der HERR spricht: Wenn ich dich nicht zum Guten stärken*, wenn ich nicht machen werde, dass dich der Feind zur Zeit des Unglücks und zur Zeit der Bedrängnis anfleht*!*", footnotes: ["mit anderer Lesart: befreien", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "℘ Kap. 39,12"] },
      { number: 12, text: "Kann man Eisen zerbrechen — Eisen aus dem Norden — und Bronze zerbrechen*?", footnotes: ["o. Kann Eisen . . . zerbrechen"] },
      { number: 13, text: "Dein Vermögen und deine Schätze will ich zur Plünderung dahingeben ohne Kaufpreis*, und zwar wegen all deiner Sünden, und zwar in deinem ganzen Gebiet*.", footnotes: ["℘ Kap. 20,5", "℘ Kap. 17,3"] },
      { number: 14, text: "Und ich werde dich zum Sklaven deiner Feinde machen in einem Land*, das du nicht kennst*. Denn ein Feuer ist entbrannt in meinem Zorn, über euch wird es brennen*.", footnotes: ["so mit mehreren hebr. Handschr., LXX, syr. und der alten lat. Üs.; Mas. T.: ich werde deine Feinde hinüberziehen lassen in ein Land. — Andere Handschr. lesen: Ich werde deine Feinde zu Sklaven machen in einem Land", "℘ Kap. 16,13", "℘ Kap. 4,4; 17,4; 5Mo 32,22"] },
      { number: 15, text: "HERR, du weißt es ja*. Denk an mich* und nimm dich meiner an und räche mich an meinen Verfolgern*! Raffe mich nicht weg nach deiner Langmut*! Erkenne, dass ich deinetwegen Schmach trage*!", footnotes: ["℘ Kap. 17,16", "℘ Ri 16,28", "℘ Kap. 11,20; 18,23; Neh 3,36.37; Kla 3,64-66", "d. h. indem du meinen Feinden gegenüber langmütig bist; o. In deiner Langmut lass mich leben.", "℘ Kap. 20,8; Ps 69,8; Mt 5,11"] },
      { number: 16, text: "Fanden sich Worte von dir*, dann habe ich sie gegessen, und deine Worte waren* mir zur Wonne und zur Freude meines Herzens*; denn dein Name ist über mir ausgerufen*, HERR, Gott der Heerscharen.", footnotes: ["Gemeint ist das Empfangen eines Gotteswortes.", "Viele hebr. Handschr. und die alten Üs. lesen: dein Wort war", "℘ Neh 8,12; Ps 119,16; Hes 3,3", "℘ Kap. 14,9"] },
      { number: 17, text: "Nie saß ich im Kreis der Scherzenden und war fröhlich*. Wegen deiner Hand* saß ich allein, weil du mich mit deinem Grimm erfüllt hast*.", footnotes: ["℘ Ps 1,1", "d. h. weil du deine Hand auf mich legst, um mir deine Worte zu verkünden", "℘ Kap. 6,11"] },
      { number: 18, text: "Warum ist mein Schmerz dauernd da und meine Wunde unheilbar? Sie will nicht heilen*. Ja, du bist für mich wie ein trügerischer Bach, wie Wasser, die nicht zuverlässig sind*. —", footnotes: ["℘ Kap. 14,19; 20,18; 30,12.15", "℘ Hi 6,15"] },
      { number: 19, text: "Darum, so spricht der HERR: Wenn du umkehrst, will ich dich umkehren lassen, dass du vor mir stehst*. Und wenn du Edles vorbringst und nicht Gemeines absonderst, sollst du wie mein Mund sein*. Sie sollen zu dir umkehren, du aber sollst nicht zu ihnen umkehren.", footnotes: ["d. h. mir dienst", "℘ Kap. 1,9"] },
      { number: 20, text: "Und ich werde dich für dieses Volk zu einer festen, ehernen Mauer machen, und sie werden gegen dich kämpfen, aber dich nicht überwältigen; denn ich bin mit dir, um dich zu retten und dich zu befreien, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Kap. 1,8.18.19; Ps 37,39; Hes 3,8"] },
      { number: 21, text: "Und ich werde dich aus der Hand der Bösen befreien und dich aus der Faust der Gewalttätigen erlösen*.", footnotes: ["℘ Kap. 20,13; 26,24; 2Tim 4,18"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zu mir:", heading: "Jeremias Ehelosigkeit als Zeichen des Gerichts über Jerusalem" },
      { number: 2, text: "Du sollst dir keine Frau nehmen und weder Söhne noch Töchter haben an diesem Ort." },
      { number: 3, text: "Denn so spricht der HERR über die Söhne und über die Töchter, die an diesem Ort geboren werden, und über ihre Mütter, die sie gebären, und über ihre Väter, die sie zeugen in diesem Land:" },
      { number: 4, text: "Sie sollen an tödlichen Krankheiten* sterben*, sie sollen nicht beklagt noch begraben werden, zu Dünger auf der Fläche des Erdbodens sollen sie werden*. Und durch Schwert und durch Hunger sollen sie umkommen*, und ihre Leichen sollen den Vögeln des Himmels und den Tieren der Erde zum Fraß dienen*.", footnotes: ["w. an Todesarten von Krankheiten", "℘ Kap. 21,6; 5Mo 28,22", "℘ Kap. 8,2; 22,18.19", "℘ Kap. 14,16; 15,2", "℘ Kap. 7,33"] },
      { number: 5, text: "Denn so spricht der HERR: Geh nicht in ein Haus der Klage*, geh nicht hin, um zu klagen, und bekunde ihnen kein Beileid*! Denn ich habe meinen Frieden von diesem Volk weggenommen, spricht der HERR*, die Gnade und das Erbarmen*.", footnotes: ["w. Haus des Geschreis", "w. schüttle für sie nicht den Kopf zum Zeichen der Trauer", "w. ist der Ausspruch des HERRN", "℘ V. 13; Kap. 13,14; Kla 3,17"] },
      { number: 6, text: "Große und Kleine werden in diesem Land sterben, ohne begraben zu werden*. Und man wird nicht um sie trauern und sich ihretwegen nicht ritzen* und sich ihretwegen nicht kahl scheren*.", footnotes: ["℘ Kap. 8,2; 22,18.19", "Das Ritzen der Haut ist ein Trauerbrauch, wie er bei den Kanaanäern üblich war.", "℘ Kap. 41,5; 47,5; 48,37; 3Mo 19,27.28"] },
      { number: 7, text: "Und man wird ihnen nicht Brot brechen bei der Trauer, um jemanden wegen eines Toten zu trösten, noch wird man sie den Becher des Trostes trinken lassen wegen jemandes Vater und wegen jemandes Mutter*.", footnotes: ["℘ 5Mo 26,14; Hes 24,17-23"] },
      { number: 8, text: "Auch in ein Haus, in dem ein Gastmahl stattfindet, sollst du nicht gehen, um bei ihnen zu sitzen, zu essen und zu trinken." },
      { number: 9, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich werde an diesem Ort vor euren Augen und in euren Tagen aufhören lassen die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut*.", footnotes: ["℘ Kap. 7,34"] },
      { number: 10, text: "*Und es soll geschehen, wenn du diesem Volk all diese Worte verkündigst, und sie zu dir sagen: Warum hat der HERR all dieses große Unheil über uns ausgesprochen? Was ist unsere Schuld und was unsere Sünde, die wir gegen den HERRN, unseren Gott, begangen haben*? —", footnotes: ["℘ V. 10-13: Kap. 9,11-15", "℘ Kap. 2,23.35"] },
      { number: 11, text: "dann sollst du zu ihnen sagen: Weil eure Väter mich verlassen haben, spricht der HERR*, und anderen Göttern nachgelaufen sind und ihnen gedient und sich vor ihnen niedergeworfen, mich aber verlassen und mein Gesetz nicht beachtet haben*,", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 13,22; 22,9; 44,3; Ri 2,12.13; Kla 5,7; Dan 9,10-12"] },
      { number: 12, text: "und ihr es noch schlimmer getrieben habt als eure Väter* — und siehe, ihr folgt* ein jeder der Verstocktheit seines bösen Herzens, ohne auf mich zu hören* —:", footnotes: ["℘ Kap. 7,24-26; 22,28", "w. geht", "℘ Kap. 13,10; Ri 2,19"] },
      { number: 13, text: "So werde ich euch aus diesem Land wegschleudern in ein Land, das ihr nicht kennt, weder ihr noch eure Väter*. Dort werdet* ihr anderen Göttern dienen Tag und Nacht, weil ich euch keine Gnade schenke*.", footnotes: ["℘ Kap. 10,18; 15,14; 2Kö 25,21", "o. dürft", "℘ V. 5; 5Mo 4,28"] },
      { number: 14, text: "Darum siehe, Tage kommen, spricht der HERR*, da wird man nicht mehr sagen: So wahr der HERR lebt, der die Söhne Israel aus dem Land Ägypten heraufgeführt hat*! —", heading: "Verheißung der Rückführung nach Israel — Alle Völker werden sich dem HERRN zuwenden", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 23,7; 2Mo 20,2"] },
      { number: 15, text: "sondern: So wahr der HERR lebt, der die Söhne Israel aus dem Land des Nordens* heraufgeführt hat und aus all den Ländern, wohin er sie vertrieben hatte*! Und ich werde sie in ihr Land zurückbringen, das ich ihren Vätern gegeben habe*.", footnotes: ["℘ Kap. 3,18; 23,3.8", "℘ Kap. 31,8", "℘ Kap. 12,15; 29,14; 30,3; 32,37; Jes 14,1.2; Hes 37,21; Am 9,14.15"] },
      { number: 16, text: "Siehe, ich will zu vielen Fischern senden*, spricht der HERR*, die sollen sie fischen*. Und danach will ich zu vielen Jägern senden*, die sollen sie jagen* von jedem Berg und von jedem Hügel und aus den Felsenklüften.", footnotes: ["d. h. um sie kommen zu lassen", "w. ist der Ausspruch des HERRN", "℘ Am 4,2; Hab 1,15", "w. ist der Ausspruch des HERRN", "℘ Kla 4,19"] },
      { number: 17, text: "Denn meine Augen sind auf alle ihre Wege gerichtet. Sie sind vor mir nicht verborgen, und ihre Schuld ist nicht verhüllt vor meinen Augen*.", footnotes: ["℘ Kap. 7,11; 23,24; 32,19; Hi 10,14; 31,4; 34,22; Ps 33,15; 90,8; Spr 5,21; Jes 66,18"] },
      { number: 18, text: "Doch zuerst will ich ihre Schuld und ihre Sünde zweifach vergelten*, weil sie mein Land mit dem Aas ihrer abscheulichen Opfertiere entweiht und mein Erbteil mit ihren Gräueln erfüllt haben*.", footnotes: ["℘ Jes 40,2; 65,7", "℘ 3Mo 26,30; Hes 36,18"] },
      { number: 19, text: "HERR, meine Stärke und mein Schutz* und meine Zuflucht am Tag der Bedrängnis*! Zu dir werden Nationen kommen von den Enden der Erde* und sagen: Nur Lüge haben unsere Väter geerbt, Nichtigkeiten*; und unter ihnen ist keiner, der etwas nützt*.", footnotes: ["o. meine Bergfestung", "℘ Kap. 14,8; 17,17; Ps 18,3; Jes 25,4", "℘ Ps 65,3; Jes 2,2.3", "d. i. eine Bezeichnung für Götzen", "℘ Kap. 10,3-5; Am 2,4"] },
      { number: 20, text: "Kann denn ein Mensch sich Götter machen? Das sind doch keine Götter*!", footnotes: ["℘ Kap. 2,11; 2Kö 19,18; Gal 4,8"] },
      { number: 21, text: "Darum siehe, ich werde sie zur Erkenntnis bringen. Diesmal werde ich sie meine Hand und meine Macht erkennen lassen; und sie werden erkennen, dass mein Name Jahwe ist*.", footnotes: ["℘ Kap. 33,2; Ps 83,19; Offb 15,4"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Die Sünde Judas ist geschrieben mit eisernem Griffel*, mit diamantener Spitze; sie ist eingegraben in die Tafel ihres Herzens* und an die Hörner eurer Altäre*.", heading: "Gottes Antwort auf Judas Götzendienst: Rücknahme der Landverheißung", footnotes: ["℘ Hi 19,24", "℘ Kap. 31,33; Spr 3,3", "℘ Kap. 11,13; Hos 8,11"] },
      { number: 2, text: "Wie an ihre Kinder, so denken sie an ihre Altäre und ihre Ascherim* bei den grünen Bäumen, auf den hohen Hügeln*,", footnotes: ["das sind Gedenksäulen", "℘ 5Mo 12,2"] },
      { number: 3, text: "auf den Bergen* im Gefilde*. Dein Vermögen, alle deine Schätze werde ich zur Plünderung preisgeben, auch deine Höhen, um der Sünde willen, die in deinem ganzen Gebiet begangen wurde*.", footnotes: ["Mas. T.: meinem Berg; andere üs.: auf den hohen Hügeln. 3 Oh, mein Berg . . .!", "℘ Kap. 21,13", "℘ Kap. 15,13; Hes 23,46"] },
      { number: 4, text: "Und du wirst, und zwar durch dich selbst*, dein Erbteil loslassen müssen, das ich dir gegeben habe*, und ich werde dich zum Sklaven deiner Feinde machen in einem Land, das du nicht kennst*. Denn ihr habt ein Feuer angezündet in meinem Zorn, es wird ewig brennen*.", footnotes: ["d. h. durch deine eigene Schuld", "℘ Kla 5,2", "℘ Kap. 5,19", "℘ Kap. 7,20; 15,14; Jes 50,11"] },
      { number: 5, text: "So spricht der HERR: Verflucht ist der Mann, der auf Menschen vertraut* und Fleisch zu seinem Arm macht* und dessen Herz vom HERRN weicht!", heading: "Weisheitssprüche", footnotes: ["℘ Ps 146,3", "℘ 2Chr 32,8"] },
      { number: 6, text: "Er wird sein wie ein kahler Strauch in der Steppe* und nicht sehen, dass Gutes kommt*. Und an dürren Stätten in der Wüste wird er wohnen, in einem salzigen Land, wo sonst niemand wohnt.", footnotes: ["℘ Kap. 48,6", "d. h. nichts Gutes erfahren"] },
      { number: 7, text: "Gesegnet ist der Mann, der auf den HERRN vertraut und dessen Vertrauen der HERR ist*!", footnotes: ["℘ Ps 84,13; 146,5; Jes 30,18; Zef 3,12"] },
      { number: 8, text: "Er wird sein wie ein Baum, der am Wasser gepflanzt ist* und am Bach seine Wurzeln ausstreckt und sich nicht fürchtet, wenn die Hitze kommt. Sein Laub ist grün, im Jahr der Dürre ist er unbekümmert, und er hört nicht auf, Frucht zu tragen*.", footnotes: ["℘ Jes 58,11", "℘ Ps 1,3"] },
      { number: 9, text: "Trügerisch* ist das Herz, mehr als alles, und unheilbar ist es*. Wer kennt sich mit ihm aus?*", footnotes: ["o. Schwierig; w. Uneben, o. Höckerig", "℘ Kap. 7,24; 1Mo 6,5; Mk 7,21-23; 15,19", "℘ Ps 64,7"] },
      { number: 10, text: "Ich, der HERR, bin es, der das Herz erforscht und die Nieren prüft*, und zwar um einem jeden zu geben nach seinen Wegen, nach der Frucht seiner Taten*. —", footnotes: ["℘ Kap. 11,20; 20,12; Ps 139,1; Spr 17,3; Joh 2,25", "℘ Kap. 21,14; 23,2; 32,19; Hi 34,11; Offb 2,23"] },
      { number: 11, text: "Wie ein Rebhuhn, das brütet, ohne gelegt zu haben*, so ist, wer Reichtum erwirbt, aber nicht mit Recht; in der Mitte seiner Tage muss er ihn lassen, und an seinem Ende wird er ein Tor sein*.", footnotes: ["Andere üs.: das Eier ausbrütet, die es nicht gelegt hat", "℘ Spr 13,11; 15,27; Hab 2,6.9"] },
      { number: 12, text: "Thron der Herrlichkeit*, erhaben* von Anbeginn, Stätte unseres Heiligtums*!", footnotes: ["℘ Kap. 14,21", "w. Höhe", "℘ Hes 43,7"] },
      { number: 13, text: "Hoffnung Israels*, HERR! Alle, die dich verlassen, werden zuschanden werden*. — Und die von mir abweichen, werden in die Erde geschrieben werden*; denn sie haben den HERRN, die Quelle lebendigen Wassers, verlassen*.", footnotes: ["℘ Kap. 14,8", "℘ Ps 73,27", "d. h. so, dass die Schrift bald verwischt oder verweht wird\n℘ Ps 69,29; Joh 8,6", "℘ Kap. 2,13"] },
      { number: 14, text: "Heile mich*, HERR, so werde ich geheilt! Rette mich, so werde ich gerettet*! Denn du bist mein Ruhm*.", heading: "Klagegebet Jeremias mit der Bitte um Anerkennung beim Volk", footnotes: ["℘ Ps 6,3", "℘ Kap. 31,18", "℘ 5Mo 10,21"] },
      { number: 15, text: "Siehe, sie sagen zu mir: Wo ist das Wort des HERRN? Es soll doch kommen*!", footnotes: ["℘ Jes 5,19"] },
      { number: 16, text: "Ich aber habe mich dem Hirtendienst nicht entzogen* und habe den unheilvollen Tag nicht herbeigewünscht; du kennst es ja*. Was aus meinen Lippen hervorging, war vor deinem Angesicht*.", footnotes: ["w. ich habe mich nicht fortgedrängt vom Hirte-Sein dir nach. — Syr. Üs.: in böser Absicht dir hinterhergedrängt\n℘ Kap. 20,7", "℘ Kap. 15,15", "℘ 2Kor 2,17"] },
      { number: 17, text: "Werde mir nicht zum Schrecken! Du bist doch meine Zuflucht am Tag des Unglücks*!", footnotes: ["℘ Kap. 16,19"] },
      { number: 18, text: "Lass meine Verfolger zuschanden werden*, aber mich lass nicht zuschanden werden*! Lass sie schreckerfüllt sein, aber mich lass nicht schreckerfüllt sein! Bringe über sie den Tag des Unglücks, und mit doppelter Zerschmetterung zerschmettere sie*!", footnotes: ["℘ Kap. 20,11", "℘ Ps 25,2", "℘ Kap. 11,20; 12,3; 18,20-23; 5Mo 33,11"] },
      { number: 19, text: "So spricht der HERR zu mir: Geh und stell dich in das Tor der Söhne des Volkes, durch das die Könige von Juda einziehen und durch das sie ausziehen, und in alle Tore Jerusalems*", heading: "Verheißung im Blick auf Sabbatheiligung", footnotes: ["℘ Kap. 7,2"] },
      { number: 20, text: "und sage zu ihnen: Hört das Wort des HERRN, ihr Könige von Juda und ganz Juda und alle Bewohner von Jerusalem, die ihr durch diese Tore einzieht*!", footnotes: ["℘ Kap. 19,3; 22,2"] },
      { number: 21, text: "So spricht der HERR: Hütet euch bei eurem Leben*, dass ihr am Tag des Sabbats keine Last tragt und durch die Tore Jerusalems hereinbringt*!", footnotes: ["℘ 5Mo 4,9.15", "℘ Neh 13,19"] },
      { number: 22, text: "Und ihr sollt am Tag des Sabbats keine Last aus euren Häusern herausbringen und sollt keinerlei Arbeit tun! Sondern heiligt den Tag des Sabbats, wie ich euren Vätern geboten habe*!", footnotes: ["℘ 2Mo 20,8-11; Joh 5,10"] },
      { number: 23, text: "Aber sie haben nicht gehört und ihr Ohr nicht geneigt, sondern sie haben ihren Nacken verhärtet, um nicht zu hören und keine Zucht anzunehmen*.", footnotes: ["℘ Kap. 5,3; 7,24.26; 19,15; Ri 6,10; Zef 3,7; Sach 7,11.12"] },
      { number: 24, text: "Und es wird geschehen, wenn ihr wirklich auf mich hört, spricht der HERR*, so dass ihr am Tag des Sabbats keine Last durch die Tore dieser Stadt hereinbringt und ihr den Tag des Sabbats heiligt, indem ihr keinerlei Arbeit an ihm tut,", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 25, text: "dann werden durch die Tore dieser Stadt Könige und Oberste einziehen, die auf dem Thron Davids sitzen, mit Wagen und Pferden fahren, sie und ihre Obersten, die Männer von Juda und die Bewohner von Jerusalem*; und diese Stadt wird ewig bewohnt werden*.", footnotes: ["℘ Kap. 22,4", "℘ Kap. 7,3.7"] },
      { number: 26, text: "Dann werden Leute kommen aus den Städten Judas und aus der Umgebung von Jerusalem, aus dem Land Benjamin, aus der Niederung*, vom Gebirge und aus dem Süden*, die Brandopfer, Schlachtopfer, Speisopfer und Weihrauch bringen und die Lobopfer bringen in das Haus des HERRN*.", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 32,44; 33,13", "℘ Kap. 33,11; Jes 58,13.14"] },
      { number: 27, text: "Wenn ihr aber nicht auf mich hört, den Tag des Sabbats heilig zu halten und keine Last zu tragen und nicht durch die Tore Jerusalems einzugehen am Tag des Sabbats, dann werde ich Feuer in seinen Toren anzünden, und es wird die Paläste Jerusalems verzehren und nicht verlöschen*.", footnotes: ["℘ Kap. 7,20; 21,14; Kla 4,11; Hes 21,3; Am 2,4.5"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Das Wort, das durch den HERRN zu Jeremia geschah:", heading: "Die Arbeit des Töpfers" },
      { number: 2, text: "Mache dich auf und geh in das Haus des Töpfers hinab*, und dort werde ich dich mein Wort hören lassen!", footnotes: ["℘ Kap. 13,1"] },
      { number: 3, text: "Und ich ging in das Haus des Töpfers hinab, und siehe, er war gerade mit einer Arbeit auf der Scheibe beschäftigt." },
      { number: 4, text: "Und das Gefäß, das er aus dem Ton machte, missriet in der Hand des Töpfers. Und er machte wieder ein anderes Gefäß daraus, wie es in den Augen des Töpfers recht war zu tun*.", footnotes: ["℘ Röm 9,20.21"] },
      { number: 5, text: "Und das Wort des HERRN geschah zu mir:" },
      { number: 6, text: "Kann ich mit euch nicht ebenso verfahren wie dieser Töpfer, Haus Israel?, spricht der HERR*. Siehe, wie der Ton in der Hand des Töpfers, so seid ihr in meiner Hand, Haus Israel*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Jes 45,9"] },
      { number: 7, text: "Einmal rede ich über ein Volk und über ein Königreich, es ausreißen, niederbrechen und zugrunde richten zu wollen*.", footnotes: ["℘ Kap. 1,10"] },
      { number: 8, text: "Kehrt aber jenes Volk, über das ich geredet habe, von seiner Bosheit um, lasse ich mich des Unheils gereuen, das ich ihm zu tun gedachte*.", footnotes: ["℘ Kap. 26,3; 36,3; 42,10; Ps 106,45; Joe 2,13.14; Am 5,15"] },
      { number: 9, text: "Und ein anderes Mal rede ich über ein Volk und über ein Königreich, es bauen und pflanzen zu wollen." },
      { number: 10, text: "Tut es aber, was in meinen Augen böse ist, indem es auf meine Stimme nicht hört, so lasse ich mich des Guten gereuen, das ich ihm zu erweisen zugesagt habe*.", footnotes: ["℘ 4Mo 14,23; 1Sam 15,11; Hes 33,12-16"] },
      { number: 11, text: "Und nun rede zu den Männern von Juda und zu den Bewohnern von Jerusalem und sage: So spricht der HERR: Siehe, ich bereite ein Unglück gegen euch vor und plane einen Anschlag* gegen euch*! Kehrt doch um, jeder von seinem bösen Weg, und bessert eure Wege und eure Taten*!", footnotes: ["w. plane einen Plan", "℘ Kap. 19,3.15; 1Kö 22,23", "℘ Kap. 4,14; 7,3; 2Kö 17,13; Jes 1,16"] },
      { number: 12, text: "Aber sie sagen: Es ist umsonst. Wir wollen vielmehr unseren Gedanken nachgehen, und jeder kann nach der Verstocktheit seines bösen Herzens handeln*.", footnotes: ["℘ Kap. 2,25; 6,17; 7,24; Jes 65,2"] },
      { number: 13, text: "Darum, so spricht der HERR: Fragt doch unter den Nationen! Wer hat je so etwas gehört? Ganz Abscheuliches hat die Jungfrau Israel getan*.", footnotes: ["℘ Kap. 2,10-13; 5,30.31; Am 5,2"] },
      { number: 14, text: "Schwindet wohl der Schnee des Libanon vom Fels des Feldes*? Oder versiegt weither kommendes, kaltes, rieselndes Wasser?", footnotes: ["d. h. den über das umliegende Land hervorragenden Fels; wahrscheinlich ist der mit ewigem Schnee bedeckte Hermon gemeint."] },
      { number: 15, text: "Aber mein Volk hat mich vergessen*. Den nichtigen Götzen* bringen sie Rauchopfer dar*; und die haben sie auf ihren Wegen hinstürzen lassen, auf den Pfaden der Vorzeit*, dass sie Steige gehen, einen Weg, der nicht gebahnt ist,", footnotes: ["℘ Kap. 13,25; Neh 9,17", "w. dem Nichts; o. dem Gehaltlosen", "℘ Kap. 1,16; 11,12.13; 5Mo 32,21", "℘ Kap. 6,16"] },
      { number: 16, text: "damit sie ihr Land zum Entsetzen machen, zu ewigem Gezisch*; jeder, der daran vorüberzieht, wird sich entsetzen und den Kopf schütteln*.", footnotes: ["Gemeint ist wohl ein Pfeifen oder Zischen, das angesichts eines erschreckenden Anblicks Verachtung oder Furcht ausdrücken soll.\n℘ Kap. 19,8; 25,9.18; 29,18; 49,17; 50,13; 51,37; 2Chr 29,8", "℘ 3Mo 26,32"] },
      { number: 17, text: "Wie der Ostwind werde ich sie vor dem Feind zerstreuen*. Den Rücken und nicht das Gesicht werde ich sie sehen lassen an dem Tag ihres Verderbens*.", footnotes: ["℘ Kap. 13,24", "o. endgültigen Unglücks"] },
      { number: 18, text: "Da sagten sie: Auf, lasst uns Anschläge gegen Jeremia planen*! Denn nicht geht dem Priester das Gesetz verloren* noch der Rat dem Weisen noch das Wort dem Propheten*. Auf, wir wollen ihn mit der Zunge* schlagen* und nicht achten auf all seine Worte*! —", heading: "Anschläge gegen Jeremia — Sein Rachegebet", footnotes: ["w. Pläne . . . planen\n℘ Kap. 1,19; 2Chr 24,21", "℘ Mal 2,7", "℘ Mi 3,6.7", "o. mit seinen eigenen Worten", "℘ Lk 20,20", "℘ Kap. 44,16"] },
      { number: 19, text: "Achte du, HERR, auf mich und höre die Stimme meiner Gegner*!", footnotes: ["℘ Ps 64,2.3"] },
      { number: 20, text: "Soll Böses für Gutes vergolten werden*? Denn sie haben meiner Seele eine Grube gegraben*. Denke daran, dass ich vor dir gestanden habe, um Gutes über sie zu reden, um deinen Zorn von ihnen abzuwenden.", footnotes: ["℘ Ps 35,12; Spr 17,13", "℘ Ps 35,7"] },
      { number: 21, text: "Darum gib ihre Kinder dem Hunger preis und überliefere sie der Gewalt des Schwertes, damit ihre Frauen kinderlos und Witwen werden und ihre Männer vom Tod umgebracht, ihre jungen Männer vom Schwert erschlagen werden im Krieg*!", footnotes: ["℘ Kap. 11,22.23; Ps 63,11; Jes 9,16"] },
      { number: 22, text: "Geschrei soll man hören aus ihren Häusern, wenn du plötzlich Streifscharen über sie bringst. Denn sie haben eine Grube gegraben, um mich zu fangen, und meinen Füßen haben sie heimlich Fallen gestellt*.", footnotes: ["w. Klappnetze (zum Vogelfang) versteckt\n℘ Ps 142,4"] },
      { number: 23, text: "Doch du, HERR, du kennst alle ihre Mordanschläge gegen mich*. Vergib nicht ihre Schuld und lösche ihre Sünde vor deinem Angesicht nicht aus, sondern niedergestürzt sollen sie vor dir liegen! Zur Zeit deines Zornes tu es ihnen an*!", footnotes: ["℘ Ps 37,32; Kla 3,60.61", "℘ Kap. 15,15; 17,18; Ps 56,8; Röm 2,5"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "*So spricht der HERR: Geh und kauf vom Töpfer einen Tonkrug* und nimm mit dir einige von den Ältesten* des Volkes und von den Ältesten der Priester!", heading: "Der zerbrochene Krug", footnotes: ["℘ Hes 5,1-17", "℘ Kap. 13,1", "so mit der syr. und aram. Üs.; Mas. T.: Krug und von den Ältesten"] },
      { number: 2, text: "Und geh hinaus in das Tal Ben-Hinnom*, das vor dem Eingang des Scherbentores liegt, und rufe dort die Worte aus, die ich zu dir reden werde,", footnotes: ["℘ Jos 15,8"] },
      { number: 3, text: "und sage: Hört das Wort des HERRN, ihr Könige von Juda und ihr Bewohner von Jerusalem*! So spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich bringe Unheil über diesen Ort*, dass jedem, der es hört, die Ohren gellen werden*.", footnotes: ["℘ Kap. 17,20", "℘ Kap. 18,11; 25,29; 2Kö 21,12; Hes 7,5", "℘ 1Sam 3,11"] },
      { number: 4, text: "Darum, weil sie mich verlassen* und mir diesen Ort entfremdet* und an ihm andern Göttern Rauchopfer dargebracht haben, Göttern, die sie nicht kennen, weder sie noch ihre Väter* noch die Könige von Juda, und weil sie diesen Ort mit dem Blut Unschuldiger angefüllt haben*", footnotes: ["℘ Kap. 2,13.19", "o. und diesen Ort verkannt haben", "℘ Kap. 7,9; 44,3; 5Mo 32,17", "℘ Kap. 2,34; 22,17; Hes 8,11"] },
      { number: 5, text: "und die Höhen des Baal gebaut, um ihre Kinder als Brandopfer für den Baal im Feuer zu verbrennen, was ich nicht befohlen noch geredet habe und was mir nicht in den Sinn gekommen ist*.", footnotes: ["℘ Kap. 7,31; 2Kö 21,6; Hes 16,20"] },
      { number: 6, text: "Darum siehe, Tage kommen, spricht der HERR*, da dieser Ort nicht mehr Tofet* noch Tal Ben-Hinnom genannt werden wird, sondern Tal des Schlachtens*.", footnotes: ["w. ist der Ausspruch des HERRN", "d. h. Feuerstätte, o. Herd; aber auch Gespei, o. Auswurf. Viell. spielt die folgende Umbenennung von Tofet auf beide Bedeutungen an.", "w. des Mordens"] },
      { number: 7, text: "Da werde ich den Plan von Juda und Jerusalem vereiteln* an diesem Ort und werde sie durchs Schwert fallen lassen vor ihren Feinden und durch die Hand derer, die ihnen nach ihrem Leben trachten*. Und ich werde ihre Leichen den Vögeln des Himmels und den Tieren der Erde zum Fraß geben*.", footnotes: ["℘ Ps 33,10; Jes 29,14", "℘ Kap. 21,7; 3Mo 26,25; 2Kö 21,14", "℘ Kap. 7,33; 1Sam 17,46"] },
      { number: 8, text: "Und ich werde diese Stadt zum Entsetzen und zum Gezisch* machen: jeder, der an ihr vorübergeht, wird sich entsetzen und zischen* über all ihre Plagen*.", footnotes: ["o. zum Pfeifen/und pfeifen; als Ausdruck der Verachtung oder der Furcht", "o. zum Pfeifen/und pfeifen; als Ausdruck der Verachtung oder der Furcht", "o. Wunden\n℘ Kap. 18,16; 50,13; Kla 2,15.16; Mi 6,16"] },
      { number: 9, text: "Und ich werde sie das Fleisch ihrer Söhne und das Fleisch ihrer Töchter essen lassen, und sie sollen einer das Fleisch des anderen essen während der Belagerung und der Bedrängnis, mit der ihre Feinde und die nach ihrem Leben trachten sie bedrängen werden*.", footnotes: ["℘ Kap. 38,9; 3Mo 26,29; 2Kö 25,3; Kla 2,20"] },
      { number: 10, text: "Und du sollst den Krug vor den Augen der Männer zerbrechen, die mit dir gegangen sind*,", footnotes: ["℘ Kap. 51,63"] },
      { number: 11, text: "und zu ihnen sagen: So spricht der HERR der Heerscharen: Ebenso werde ich dieses Volk und diese Stadt zerbrechen, wie man ein Gefäß des Töpfers zerbricht, das nicht wiederhergestellt werden kann*. Und man wird im Tofet* begraben, weil kein Platz zum Begraben mehr da ist*.", footnotes: ["℘ Kap. 25,34; Ps 2,9; Jes 30,14; Kla 4,2", "s. Anm. zu V. 6", "℘ Kap. 7,32"] },
      { number: 12, text: "Ebenso werde ich mit diesem Ort verfahren, spricht der HERR*, und seinen Bewohnern, um diese Stadt dem Tofet gleichzumachen.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 13, text: "Und die Häuser von Jerusalem und die Häuser der Könige von Juda sollen unrein werden wie der Ort Tofet; all die Häuser, auf deren Dächern sie dem ganzen Heer des Himmels Rauchopfer dargebracht und andern Göttern Trankopfer gespendet haben*.", footnotes: ["℘ Kap. 7,18; 2Kö 23,12; Jes 22,1"] },
      { number: 14, text: "Und Jeremia kam vom Tofet*, wohin ihn der HERR gesandt hatte zu weissagen, und er trat in den Vorhof des Hauses des HERRN und sprach zum ganzen Volk*:", heading: "Die Folgen der Gerichtsbotschaft: Misshandlung durch Paschhur", footnotes: ["s. Anm. zu V. 6", "℘ Kap. 26,2"] },
      { number: 15, text: "So spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich will über diese Stadt und über alle ihre Städte all das Unheil bringen, das ich über sie geredet habe*. Denn sie haben ihren Nacken verhärtet, um meine Worte nicht zu hören*.", footnotes: ["℘ Kap. 11,11; Kla 2,2", "℘ Kap. 7,26; 13,11; 17,23; 18,11; 25,4.7.8; 36,31; Sach 7,11-14"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und als der Priester Paschhur, der Sohn des Immer* — er war Oberaufseher im Haus des HERRN —, Jeremia diese Worte weissagen hörte,", footnotes: ["℘ 1Chr 24,14"] },
      { number: 2, text: "da schlug Paschhur den Propheten Jeremia und legte ihn in den Block* im oberen Tor Benjamin, das am Haus des HERRN ist*.", footnotes: ["℘ Kap. 29,26; 37,15; 1Kö 13,4", "℘ Kap. 26,8.10; Hebr 11,36"] },
      { number: 3, text: "Und es geschah am folgenden Tag, als Paschhur Jeremia aus dem Block herausholen ließ, sagte Jeremia zu ihm: Nicht Paschhur nennt der HERR deinen Namen, sondern Magor-Missabib*.", footnotes: ["d. h. Schrecken ringsum\n℘ Kap. 6,25"] },
      { number: 4, text: "Denn so spricht der HERR: Siehe, ich mache dich zum Schrecken für dich selbst und für all deine Freunde. Sie sollen durch das Schwert ihrer Feinde fallen, und deine Augen werden es sehen. Und ich werde ganz Juda in die Hand des Königs von Babel geben, damit er sie nach Babel gefangen wegführt und sie mit dem Schwert erschlägt*.", footnotes: ["℘ Kap. 21,6.7; 52,24-27"] },
      { number: 5, text: "Und ich werde den ganzen Reichtum dieser Stadt dahingeben und all ihren Erwerb und alle ihre Kostbarkeiten. Und alle Schätze der Könige von Juda werde ich in die Hand ihrer Feinde geben. Und sie werden sie plündern und wegnehmen und nach Babel bringen*.", footnotes: ["℘ Kap. 15,13; 27,21.22; 2Kö 20,17.18; 24,13"] },
      { number: 6, text: "Und du, Paschhur, und alle Bewohner deines Hauses, ihr werdet in die Gefangenschaft gehen. Und du wirst nach Babel kommen und dort sterben und dort begraben werden, du und alle deine Freunde, denen du falsch geweissagt hast*. —", footnotes: ["℘ Kap. 14,13-16; 28,15.16; 29,21.32"] },
      { number: 7, text: "HERR, du hast mich betört, und ich habe mich betören lassen. Du hast mich ergriffen und überwältigt*. Ich bin zum Gelächter geworden den ganzen Tag, jeder spottet über mich*.", heading: "Ein Klagegebet Jeremias: sein Leiden an Gottes Botenauftrag", footnotes: ["℘ Kap. 17,16; 2Mo 5,22; Jes 8,11", "℘ Ps 69,12; Kla 3,14.63"] },
      { number: 8, text: "Ja, sooft ich rede, muss ich schreien, »Gewalttat« und »Zerstörung« rufen*; ja, das Wort des HERRN ist mir zur Verhöhnung und zur Verspottung geworden den ganzen Tag*.", footnotes: ["℘ Kap. 6,6.7", "℘ Kap. 15,10.15; 2Kö 2,23; Jes 57,4; Hebr 11,36"] },
      { number: 9, text: "Doch sooft ich mir sage*: Ich will nicht mehr an ihn denken und nicht mehr in seinem Namen reden, wird es in meinem Herzen wie brennendes Feuer, eingeschlossen in meinen Gebeinen. Und ich habe mich vergeblich abgemüht, es weiter auszuhalten, ich kann nicht mehr*!", footnotes: ["o. Da sagte ich mir", "℘ Kap. 4,19; 6,11; Hi 32,18.19; Ps 39,3.4; Apg 4,20"] },
      { number: 10, text: "Ja, ich habe das Gerede* von vielen gehört: Schrecken ringsum!* Zeigt ihn an! Wir wollen ihn anzeigen! Alle meine Freunde lauern auf meinen Fall*: Vielleicht lässt er sich verleiten, so dass wir ihn überwältigen und unsere Rache an ihm nehmen können.", footnotes: ["o. das Tuscheln", "℘ Kap. 6,25; Ps 31,14", "℘ Ps 41,10"] },
      { number: 11, text: "Aber der HERR ist mit mir wie ein gewaltiger Held, darum werden meine Verfolger hinstürzen und mich nicht überwältigen*. Sie werden völlig zuschanden werden, weil sie nicht verständig gehandelt haben*; eine ewige Schande, die nicht vergessen wird*.", footnotes: ["o. nicht die Oberhand haben\n℘ Kap. 1,18.19; Ps 27,1.2", "o. weil es ihnen nicht gelungen ist", "℘ Kap. 17,18; 23,40; Ps 35,26"] },
      { number: 12, text: "Und du, HERR der Heerscharen, der du den Gerechten prüfst*, Nieren und Herz siehst*, lass mich deine Rache an ihnen sehen! Denn dir habe ich meine Rechtssache anvertraut*.", footnotes: ["℘ Ps 11,5", "℘ Kap. 17,10", "℘ Kap. 11,20"] },
      { number: 13, text: "Singt dem HERRN, lobt den HERRN! Denn er hat die Seele des Armen gerettet aus der Hand der Übeltäter*.", footnotes: ["℘ Kap. 15,21; Ps 35,10"] },
      { number: 14, text: "Verflucht sei der Tag, an dem ich geboren wurde*; der Tag, an dem meine Mutter mich gebar, sei nicht gesegnet!", footnotes: ["℘ Hi 3,1"] },
      { number: 15, text: "Verflucht sei der Mann, der meinem Vater die frohe Botschaft brachte und sagte: »Ein Sohn* ist dir geboren«, und der ihn damit hoch erfreute!", footnotes: ["w. Ein Sohn, und zwar ein männlicher"] },
      { number: 16, text: "Dieser Mann werde den Städten gleich, die der HERR umgekehrt hat*, ohne es zu bereuen! Und er höre Geschrei am Morgen und Kriegsgeschrei zur Mittagszeit,", footnotes: ["℘ 1Mo 19,24.25; 5Mo 29,22"] },
      { number: 17, text: "weil er mich im Mutterleib* nicht schon getötet hat, so dass meine Mutter mir zu meinem Grab geworden und ihr Leib ewig schwanger geblieben wäre*!", footnotes: ["w. von Mutterleib an", "℘ Kap. 15,10; Hi 3,11"] },
      { number: 18, text: "Wozu nur bin ich aus dem Mutterleib hervorgekommen? Um Mühsal und Kummer zu sehen*? Und dass meine Tage in Schande vergehen?* —", footnotes: ["℘ Hi 14,1; Kla 3,1", "℘ Kap. 15,18; 1Kö 19,4"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Das Wort, das von dem HERRN zu Jeremia geschah, als der König Zedekia Paschhur, den Sohn des Malkija*, und den Priester Zefanja, den Sohn des Maaseja*, zu ihm sandte und ihm sagen ließ:", heading: "Gott wird das belagerte Jerusalem nicht retten, aber alle, die zum Feind überlaufen", footnotes: ["℘ Kap. 38,1; 1Chr 9,12", "℘ Kap. 29,25.29; 35,4; 37,3; 2Kö 25,18"] },
      { number: 2, text: "Befrage doch den HERRN für uns*, denn Nebukadnezar, der König von Babel, führt Krieg gegen uns*! Vielleicht wird der HERR so an uns handeln wie bei all seinen früheren Wundern, so dass er von uns abzieht*.", footnotes: ["℘ Kap. 37,3; 1Kö 22,5; 2Kö 22,13; Hes 14,3", "℘ Kap. 34,1; 52,4", "℘ 2Chr 32,21"] },
      { number: 3, text: "Da sprach Jeremia zu ihnen: So sollt ihr zu Zedekia sagen:" },
      { number: 4, text: "So spricht der HERR, der Gott Israels: Siehe, ich will die Kriegswaffen umwenden, die in eurer Hand sind, mit denen ihr außerhalb der Mauer gegen den König von Babel und gegen die Chaldäer kämpft, die euch belagern, und will sie* ins Innere dieser Stadt hereinziehen*.", footnotes: ["d. h. die Kriegswaffen", "℘ Kap. 32,5; 37,8-10; 39,3"] },
      { number: 5, text: "Und ich selbst werde gegen euch kämpfen mit ausgestreckter Hand und mit starkem Arm und mit Zorn und mit Grimm und mit großer Wut*.", footnotes: ["℘ Kla 2,4; Hes 20,33"] },
      { number: 6, text: "Und ich werde die Bewohner dieser Stadt schlagen, sowohl Menschen als Vieh. An einer großen Pest sollen sie sterben*.", footnotes: ["℘ Kap. 16,4; Hes 14,19"] },
      { number: 7, text: "Und danach, spricht der HERR*, werde ich Zedekia, den König von Juda, und seine Hofbeamten* und das Volk, und zwar die, die in dieser Stadt von der Pest, vom Schwert und vom Hunger übrig geblieben sind*, in die Hand Nebukadnezars, des Königs von Babel, geben und in die Hand ihrer Feinde und in die Hand derer, die nach ihrem Leben trachten*. Und er wird sie schlagen mit der Schärfe des Schwertes, er wird sie nicht verschonen* noch Mitleid haben noch sich erbarmen*.", footnotes: ["w. ist der Ausspruch des HERRN", "w. Knechte", "℘ Kap. 14,12", "℘ Kap. 19,7; 32,4; 37,17; 52,8-11.24-27", "w. sein Auge wird nicht fließen (d. h. weinen) über sie", "℘ Kap. 13,14; 20,4; 36,29; 50,17; 5Mo 28,50; 2Kö 25,7; Kla 2,20-22"] },
      { number: 8, text: "Und zu diesem Volk sollst du sagen: So spricht der HERR: Siehe, ich lege euch den Weg des Lebens vor und den Weg des Todes*.", footnotes: ["℘ 5Mo 30,15.19"] },
      { number: 9, text: "Wer in dieser Stadt bleibt, wird sterben durch das Schwert und durch den Hunger und durch die Pest. Wer aber hinausgeht und zu den Chaldäern, die euch belagern, überläuft, wird leben und seine Seele als Beute haben*.", footnotes: ["℘ Kap. 27,12.13; 38,2.17.18; 39,18"] },
      { number: 10, text: "Denn ich habe mein Angesicht gegen diese Stadt gerichtet zum Bösen und nicht zum Guten, spricht der HERR*. Sie wird in die Hand des Königs von Babel gegeben werden, und er wird sie mit Feuer verbrennen*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ Kap. 39,16; 44,11.27; Am 9,4", "℘ Kap. 32,28.29; 34,2.22; 38,18; 39,8"] },
      { number: 11, text: "Und zum Haus des Königs von Juda sollst du sagen: Hört das Wort des HERRN*!", heading: "Botschaft an die Regierung — Drohworte gegen die Könige Schallum, Jojakim und Konja", footnotes: ["℘ Kap. 22,1.18"] },
      { number: 12, text: "Haus David, so spricht der HERR: Haltet jeden Morgen Gericht und befreit den Beraubten aus der Hand des Bedrückers*, damit mein Grimm nicht ausbricht wie ein Feuer und unauslöschlich brennt wegen der Bosheit eurer Taten!*", footnotes: ["℘ Kap. 22,3.15.16; Ps 82,3.4; Spr 31,8.9", "℘ Kap. 4,4"] },
      { number: 13, text: "Siehe, ich will an dich, die du über dem Tal* thronst, über dem Felsen der Ebene*, spricht der HERR*, — die ihr sagt: Wer wird gegen uns hinabziehen, und wer wird in unsere Wohnungen kommen*?", footnotes: ["℘ Jes 22,1.5", "w. du Bewohnerin des Tales, des Felsens der Ebene; gemeint ist Jerusalem\n℘ Kap. 17,3", "w. ist der Ausspruch des HERRN", "℘ Kap. 49,4.5; Kla 4,12"] },
      { number: 14, text: "Und ich will euch heimsuchen nach der Frucht eurer Taten*, spricht der HERR*. Und ich will in ihrem Wald ein Feuer anzünden, dass es alles um sie herum frisst*.", footnotes: ["℘ Kap. 17,10; Spr 1,31; 12,14; Mi 7,13", "w. ist der Ausspruch des HERRN", "℘ Kap. 6,19; 17,27; 22,7; Hes 21,3"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "So spricht der HERR: Geh hinab in das Haus des Königs von Juda* und rede dort dieses Wort", footnotes: ["℘ Kap. 21,11"] },
      { number: 2, text: "und sage: Höre das Wort des HERRN, König von Juda, der du auf dem Thron Davids sitzt, du und deine Knechte und dein Volk, die ihr durch diese Tore einzieht!*", footnotes: ["℘ Kap. 17,20"] },
      { number: 3, text: "So spricht der HERR: Übt* Recht und Gerechtigkeit und befreit den Beraubten aus der Hand des Unterdrückers*! Und den Fremden, die Waise und die Witwe unterdrückt und vergewaltigt nicht* und vergießt nicht unschuldiges Blut an diesem Ort*!", footnotes: ["o. Schafft", "℘ Kap. 21,12", "℘ 5Mo 24,17; Hes 18,7", "℘ Kap. 7,5.6; Ps 82,4; Am 5,15"] },
      { number: 4, text: "Denn wenn ihr dieses Wort wirklich tut, werden durch die Tore dieses Hauses Könige einziehen, die auf dem Thron Davids sitzen*, die mit Wagen und Pferden fahren, er und seine Knechte und sein Volk*.", footnotes: ["w. die dem David (o. von David) auf seinem Thron sitzen", "℘ Kap. 17,25"] },
      { number: 5, text: "Wenn ihr aber nicht auf diese Worte hört, soll dieses Haus — ich habe es bei mir geschworen*, spricht der HERR* — zur Trümmerstätte werden*.", footnotes: ["℘ Kap. 44,26; 1Mo 22,16", "w. ist der Ausspruch des HERRN", "℘ Kap. 12,7; 2Chr 7,21.22; Mi 3,12"] },
      { number: 6, text: "Denn so spricht der HERR über das Haus des Königs von Juda: Wie Gilead* warst du mir, wie der Gipfel des Libanon*. Wenn ich dich nicht zur Wüste mache, zu unbewohnten Städten*!", footnotes: ["Gilead ist noch heute durch seine Waldungen berühmt.\n℘ Kap. 8,22", "℘ Jes 37,24", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.\n℘ Kap. 4,7"] },
      { number: 7, text: "Und ich werde Verderber gegen dich heiligen, jeden mit seinen Waffen, und sie werden deine auserlesenen Zedern umhauen und ins Feuer werfen*.", footnotes: ["℘ Kap. 21,14; Jes 10,33; Sach 11,1"] },
      { number: 8, text: "Und viele Nationen werden an dieser Stadt vorüberziehen, und sie werden zueinander sagen: Warum hat der HERR das an dieser großen Stadt getan*?", footnotes: ["℘ 1Kö 9,8.9"] },
      { number: 9, text: "Und man wird sagen: Weil sie den Bund des HERRN, ihres Gottes, verlassen und sich vor anderen Göttern niedergeworfen und ihnen gedient haben*.", footnotes: ["℘ Kap. 11,10; 16,11; 40,2.3; 5Mo 29,24.25; 2Kö 22,17"] },
      { number: 10, text: "Weint nicht um einen Toten* und klagt nicht um ihn*! Weint vielmehr um den, der fortgeht*, denn er wird nicht mehr zurückkehren und das Land seiner Geburt nicht mehr sehen*.", footnotes: ["Gemeint ist wohl König Josia, der 609 v. Chr. in der Schlacht von Megiddo fiel.", "w. schüttelt seinetwegen nicht den Kopf zum Zeichen der Trauer", "Gemeint ist König Joahas (d. i. Schallum), der vom Pharao Necho abgesetzt und nach Ägypten gebracht wurde.", "℘ V. 27; 2Kö 23,29.34"] },
      { number: 11, text: "Denn so spricht der HERR über Schallum*, den Sohn des Josia, den König von Juda, der anstelle seines Vaters Josia König wurde und der von diesem Ort weggegangen ist*: Er wird nicht mehr hierher zurückkehren*.", footnotes: ["℘ 1Chr 3,15", "℘ 2Chr 36,1-4", "℘ V. 27; 2Kö 23,29.34"] },
      { number: 12, text: "Sondern an dem Ort, wohin sie ihn gefangen weggeführt haben, dort wird er sterben*, und dieses Land wird er nicht mehr sehen*.", footnotes: ["℘ Kap. 42,18; 3Mo 26,38", "℘ Kap. 42,18; 3Mo 26,38"] },
      { number: 13, text: "Wehe dem, der sein Haus mit Ungerechtigkeit baut und seine Obergemächer mit Unrecht*, der seinen Nächsten umsonst arbeiten lässt und ihm seinen Lohn nicht gibt*,", footnotes: ["w. mit Nicht-Gerechtigkeit . . . mit Nicht-Recht\n℘ Mi 3,10; Hab 2,9.12", "℘ 3Mo 19,13; Hi 31,39; Jak 5,4"] },
      { number: 14, text: "der sagt: »Ich will mir ein geräumiges Haus bauen und luftige* Obergemächer«, und er bricht sich Fenster* aus und täfelt es mit Zedernholz*, und er streicht es mit roter Farbe an*.", footnotes: ["w. winddurchwehte", "T.; das Wort im Mas. T. steht in einer grammatisch nicht bestimmbaren Form.", "T.; Mas. T.: und getäfelt mit Zedernholz\n℘ Am 6,8", "℘ Hes 23,14"] },
      { number: 15, text: "Bist du dadurch König, dass du in Zedernholzbauten wetteiferst? Hat dein Vater nicht auch gegessen und getrunken und trotzdem Recht und Gerechtigkeit geübt*? Ging es ihm damals nicht gut?*", footnotes: ["℘ 2Sam 8,15; 2Kö 23,25; 2Chr 35,22", "℘ Jes 3,10"] },
      { number: 16, text: "Er hat dem Elenden* und dem Armen zum Recht verholfen. Darum ging es ihm gut. Heißt das nicht mich erkennen?, spricht der HERR*.", footnotes: ["o. Unterdrückten", "w. ist der Ausspruch des HERRN\n℘ 1Chr 28,9; Mi 6,8"] },
      { number: 17, text: "Doch deine Augen und dein Herz* sind auf nichts gerichtet als auf deinen ungerechten Gewinn* und auf das Blut des Unschuldigen, es zu vergießen*, und auf Unterdrückung und Erpressung, sie zu verüben*.", footnotes: ["o. Sinn", "℘ Kap. 8,10; 1Sam 8,3", "℘ Kap. 7,6; 19,4; 26,23; 2Kö 23,37; 24,4; Hes 22,6", "℘ Hes 19,7; Mi 2,2"] },
      { number: 18, text: "Darum, so spricht der HERR über Jojakim*, den Sohn des Josia, den König von Juda*: Man wird nicht um ihn klagen*: »Wehe, mein Bruder*!« und: »Wehe, Schwester!« Man wird nicht um ihn klagen*: »Wehe, Herr!«* und: »Wehe, seine Majestät!«", footnotes: ["℘ 1Chr 3,15", "℘ Kap. 21,11", "℘ Kap. 16,4.6", "℘ 1Kö 13,30", "℘ Kap. 42,18; 3Mo 26,38", "℘ Kap. 34,5"] },
      { number: 19, text: "Ein Eselsbegräbnis wird er erhalten; man wird ihn fortschleifen und wegwerfen, weit weg vom Tore Jerusalems*.", footnotes: ["℘ Kap. 36,30; 2Chr 36,6; Hes 19,8.9"] },
      { number: 20, text: "Steige auf den Libanon und schreie und erhebe deine Stimme auf dem Gebirge Baschan und schreie vom Abarim* her! Denn zerschmettert sind all deine Liebhaber*.", footnotes: ["d. i. eine Landschaft östlich des Toten Meeres\n℘ 5Mo 32,49", "℘ Kap. 2,36.37"] },
      { number: 21, text: "Ich redete zu dir in den Tagen deines Wohlergehens. Du aber sagtest: Ich will nicht hören*. Das war dein Weg von deiner Jugend an, dass du auf meine Stimme nicht hörtest*.", footnotes: ["℘ Kap. 2,25", "℘ Kap. 3,25; 7,23-28; 25,4.7.8; Zef 3,2"] },
      { number: 22, text: "All deine Hirten wird der Wind weiden*, und deine Liebhaber werden in die Gefangenschaft gehen*. Ja, dann wirst du beschämt und zuschanden werden wegen all deiner Bosheit*.", footnotes: ["d. h. wegraffen\n℘ Kap. 23,1.2", "℘ Kap. 2,36.37", "℘ Kap. 2,26-28"] },
      { number: 23, text: "Die du auf dem Libanon wohnst und auf den Zedern nistest*, wie erbarmungswürdig wirst du sein*, wenn Geburtsschmerzen über dich kommen, Wehen wie bei der Gebärenden*!", footnotes: ["℘ Hes 17,3; Hab 2,9", "LXX, syr. und lat. Üs.: wie wirst du stöhnen", "℘ Kap. 4,30.31"] },
      { number: 24, text: "*So wahr ich lebe, spricht der HERR*, wenn auch Konja*, der Sohn Jojakims, der König von Juda, ein Siegelring an meiner rechten Hand wäre*, würde ich dich doch von dort wegreißen*.", footnotes: ["℘ 2Kö 24,8-17; 2Chr 36,9.10", "w. ist der Ausspruch des HERRN", "Der Name Konja oder Jechonja ist gleichbedeutend mit Jojachin.\n℘ Kap. 37,1; 1Chr 3,16", "℘ Hl 8,6", "℘ Kap. 13,18"] },
      { number: 25, text: "Und ich werde dich in die Hand derer geben, die nach deinem Leben trachten, und in die Hand derer, vor denen du dich fürchtest, und in die Hand Nebukadnezars, des Königs von Babel, und in die Hand der Chaldäer." },
      { number: 26, text: "Und ich werde dich und deine Mutter, die dich geboren hat, in ein anderes* Land schleudern, wo ihr nicht geboren seid. Dort werdet ihr sterben*.", footnotes: ["so mit LXX; Mas. T.: in das andere", "℘ 2Kö 25,27-30"] },
      { number: 27, text: "In das Land aber, in das zurückzukehren sie Verlangen tragen, dorthin werden sie nicht zurückkehren*.", footnotes: ["℘ V. 10.11"] },
      { number: 28, text: "Ist denn dieser Mann Konja* ein verachtetes Gefäß zum Zertrümmern oder ein Gerät, an dem niemand Gefallen hat?* Warum wurden sie weggeschleudert, er und seine Nachkommen, und in ein Land geworfen, das sie nicht kannten*? —", footnotes: ["s. Anm. zu V. 24", "℘ Kap. 48,38; Hos 8,8", "℘ Kap. 16,12.13; 24,1"] },
      { number: 29, text: "Land, Land, Land, höre das Wort des HERRN*!", footnotes: ["℘ Kap. 6,19"] },
      { number: 30, text: "So spricht der HERR: Schreibt diesen Mann auf als kinderlos, als einen Mann, dem nichts gelingt* in seinen Tagen! Denn von seinen Nachkommen wird es nicht einem gelingen, auf dem Thron Davids zu sitzen und weiterhin* über Juda zu herrschen*.", footnotes: ["o. der nichts taugt", "o. wieder", "℘ Kap. 36,30; Hi 18,19"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "*Wehe den Hirten, die die Schafe meiner Weide zugrunde richten und zerstreuen*!, spricht der HERR*.", heading: "Weheruf über die falschen Hirten — Verheißung eines gerechten Königs", footnotes: ["℘ V. 1.2: Hes 34,1-10; Sach 11,15-17", "℘ Kap. 10,21; 22,22; 25,34.35; 50,6; Joh 10,1.8", "w. ist der Ausspruch des HERRN"] },
      { number: 2, text: "Darum, so spricht der HERR, der Gott Israels, über die Hirten, die mein Volk weiden: Ihr habt meine Schafe zerstreut und sie vertrieben und habt nicht nach ihnen gesehen*. Siehe, ich werde die Bosheit eurer Taten an euch heimsuchen*, spricht der HERR*.", footnotes: ["o. euch ihrer nicht angenommen\n℘ Apg 20,29", "℘ Kap. 17,10; 2Mo 32,34; Sach 10,3", "w. ist der Ausspruch des HERRN"] },
      { number: 3, text: "*Und ich selbst werde den Rest meiner Schafe sammeln aus all den Ländern, wohin ich sie vertrieben habe*. Und ich werde sie auf ihre Weideplätze zurückbringen*. Da werden sie fruchtbar sein und sich mehren*.", footnotes: ["℘ V. 3.4: Hes 34,11-19", "℘ Kap. 29,14; 31,8; 32,37; 5Mo 30,3-5; Mi 2,12; Zef 3,20", "℘ Kap. 50,19", "℘ 3Mo 26,9; Hes 36,11"] },
      { number: 4, text: "Und ich werde Hirten über sie erwecken, die werden sie weiden*. Und sie sollen sich nicht mehr fürchten und nicht erschrecken noch vermisst werden*, spricht der HERR*.", footnotes: ["℘ Kap. 3,15; Zef 3,13", "℘ Hes 34,25", "w. ist der Ausspruch des HERRN"] },
      { number: 5, text: "Siehe, Tage kommen, spricht der HERR*, da werde ich dem David einen gerechten Spross* erwecken*. Der wird als König regieren und verständig handeln und Recht und Gerechtigkeit im Land üben*.", footnotes: ["w. ist der Ausspruch des HERRN", "o. einen rechtmäßigen Nachkommen", "℘ 2Sam 23,3.5; Jes 4,2; 11,1; Sach 3,8; Mt 22,42; Röm 1,3", "℘ Ps 99,4; Jes 9,5.6; 52,13; Hes 34,16; Mi 5,3; Lk 1,32.33.69.70; Hebr 1,8; 7,2"] },
      { number: 6, text: "In seinen Tagen wird Juda gerettet werden und Israel in Sicherheit wohnen*. Und dies wird sein Name sein, mit dem man ihn nennen wird: »Der HERR, unsere Gerechtigkeit«*.", footnotes: ["℘ Kap. 30,10; 5Mo 33,28; Jes 32,18; Sach 14,11", "℘ Kap. 31,23; 33,15.16; Ps 45,5; Jes 32,1; 33,5; 45,24; Mal 3,20; Phil 3,9"] },
      { number: 7, text: "Darum siehe, Tage kommen, spricht der HERR*, da wird man nicht mehr sagen: So wahr der HERR lebt, der die Söhne Israel aus dem Land Ägypten heraufgeführt hat*! —", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 16,14.15; Jes 11,11; 43,5.6; Mi 7,15"] },
      { number: 8, text: "sondern: So wahr der HERR lebt, der die Nachkommen des Hauses Israel heraufgeführt und sie gebracht hat aus dem Land des Nordens und aus all den Ländern, wohin ich sie vertrieben hatte*! Und sie sollen in ihrem Land wohnen*.", footnotes: ["℘ Kap. 16,14.15; Jes 11,11; 43,5.6; Mi 7,15", "℘ Hes 36,35"] },
      { number: 9, text: "*Über die Propheten: Gebrochen ist mein Herz in meinem Innern, es zittern alle meine Gebeine. Ich bin wie ein Betrunkener und wie ein Mann, den der Wein überwältigt hat, vor dem HERRN und wegen seiner heiligen Worte*.", heading: "Aussprüche über die falschen Propheten", footnotes: ["℘ V. 9-32: Hes 13,3-16", "℘ Kap. 36,16.24"] },
      { number: 10, text: "Denn das Land ist voll von Ehebrechern* — denn wegen des Fluches* vertrocknet das Land, verdorren die Weideplätze der Steppe* —, und ihr Lauf ist Bosheit*, und ihre Stärke* ist Unrecht.", footnotes: ["℘ Kap. 5,7.8", "2 hebr. und 3 griech. Handschr. lesen: ihretwegen; d. h. wegen der Ehebrecher", "℘ Kap. 12,4", "℘ Kap. 6,13; Esr 10,18; Zef 3,4", "o. Macht"] },
      { number: 11, text: "Ja, selbst Propheten und Priester sind ruchlos*. Sogar in meinem Haus habe ich ihre Bosheit gefunden*, spricht der HERR*.", footnotes: ["℘ Kap. 6,13; Esr 10,18; Zef 3,4", "℘ Kap. 7,30; 11,15; Hes 44,10", "w. ist der Ausspruch des HERRN"] },
      { number: 12, text: "Darum wird ihnen ihr Weg sein wie schlüpfrige Stellen, ein Weg, auf dem sie in der Dunkelheit gestoßen werden* und fallen*; denn ich bringe Unheil über sie, das Jahr ihrer Heimsuchung*, spricht der HERR*.", footnotes: ["℘ Kap. 13,16; Ps 35,6; Spr 4,19", "℘ Kap. 8,12", "℘ Kap. 11,23; 48,44", "w. ist der Ausspruch des HERRN"] },
      { number: 13, text: "Auch bei den Propheten Samarias habe ich Anstößiges gesehen: Sie traten im Namen des Baal als Propheten auf* und führten mein Volk Israel irre*.", footnotes: ["℘ Kap. 2,8; 1Kö 18,19.20", "℘ V. 32; Hos 4,11.12"] },
      { number: 14, text: "Aber bei den Propheten Jerusalems habe ich Schauderhaftes gesehen*: Ehebrechen und in der Lüge leben*! Und sie stärken dabei noch die Hände der Übeltäter, damit sie nicht umkehren, jeder von seiner Bosheit*. Sie alle sind für mich wie Sodom und seine* Bewohner wie Gomorra*.", footnotes: ["℘ Kap. 5,30; Mi 1,5", "℘ Kap. 29,21-23", "℘ Hes 13,22; 22,25", "d. i. Jerusalem", "℘ 1Mo 13,13; 19,24.25; Jes 1,10; Kla 4,6; Jud 7"] },
      { number: 15, text: "Darum, so spricht der HERR der Heerscharen über die Propheten: Siehe, ich will sie mit Wermut speisen und sie mit giftigem Wasser tränken*; denn von den Propheten Jerusalems ist Ruchlosigkeit ausgegangen über das ganze Land.", footnotes: ["℘ Kap. 9,14"] },
      { number: 16, text: "So spricht der HERR der Heerscharen: Hört nicht auf die Worte der Propheten, die euch weissagen. Sie täuschen euch, die Vision ihres Herzens reden sie, nichts aber aus dem Mund des HERRN*.", footnotes: ["℘ Kap. 14,14; 2Chr 18,5; Mt 7,15; 1Jo 4,1"] },
      { number: 17, text: "Sie sagen stets zu denen, die mich verworfen haben: »Der HERR hat geredet*: Ihr werdet Frieden haben«,* und zu jedem, der in der Verstocktheit seines Herzens lebt*, sagen sie: »Kein Unglück wird über euch kommen*.«", footnotes: ["LXX: die das Wort des HERRN verwerfen", "℘ Kap. 5,12; 5Mo 29,18", "℘ Kap. 7,24", "℘ Kap. 14,13; Mi 3,11"] },
      { number: 18, text: "Denn wer hat im Rat des HERRN gestanden, dass er sein Wort gesehen und gehört hätte*? Wer hat auf sein Wort gelauscht und gehört?", footnotes: ["℘ Jes 40,13"] },
      { number: 19, text: "Siehe, ein Sturmwind des HERRN, sein Grimm, ist hervorgebrochen, ein wirbelnder Sturmwind; auf den Kopf der Gottlosen wirbelt er herab*.", footnotes: ["℘ Kap. 4,11-13; 25,31.32; Spr 1,27; Hes 13,13"] },
      { number: 20, text: "Nicht wendet sich der Zorn des HERRN, bis er getan und bis er ausgeführt hat die Pläne seines Herzens. Am Ende der Tage werdet ihr das voll verstehen*.", footnotes: ["w. das mit Verständnis verstehen\n℘ Kap. 30,24; Jes 14,24; Hes 21,10; Sach 1,6"] },
      { number: 21, text: "Ich habe die Propheten nicht gesandt, und doch sind sie gelaufen. Ich habe nicht zu ihnen geredet, und doch haben sie geweissagt*.", footnotes: ["℘ Kap. 14,14; 29,9; 2Petr 2,1"] },
      { number: 22, text: "Hätten sie aber in meinem Rat gestanden, dann würden sie mein Volk meine Worte hören lassen und es abbringen von seinem bösen Weg und von der Bosheit seiner Taten." },
      { number: 23, text: "Bin ich nur ein Gott aus der Nähe, spricht der HERR*, und nicht auch ein Gott aus der Ferne*?", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Apg 17,27"] },
      { number: 24, text: "Oder kann sich jemand in Schlupfwinkeln verbergen, und ich, ich sähe ihn nicht?*, spricht der HERR*. Bin ich es nicht, der den Himmel und die Erde erfüllt?*, spricht der HERR*.", footnotes: ["℘ Kap. 16,17; 49,10; Hi 22,13", "w. ist der Ausspruch des HERRN", "℘ 2Chr 6,18; Ps 139,8", "w. ist der Ausspruch des HERRN"] },
      { number: 25, text: "Ich habe gehört, was die Propheten sagen, die in meinem Namen Lüge weissagen und sprechen: Mir träumte, mir träumte*!", footnotes: ["℘ Kap. 29,8"] },
      { number: 26, text: "Wie lange noch? Haben die Propheten etwa im Sinn — sie, die Lüge weissagen und Propheten des Truges ihres Herzens sind* —,", footnotes: ["℘ Kap. 14,14"] },
      { number: 27, text: "beabsichtigen sie etwa, meinen Namen bei meinem Volk in Vergessenheit zu bringen durch ihre Träume, die sie einer dem anderen erzählen, so wie ihre Väter meinen Namen über dem Baal vergaßen?*", footnotes: ["℘ Kap. 2,32; 5Mo 8,11"] },
      { number: 28, text: "Der Prophet, der einen Traum hat, erzähle den Traum! Wer aber mein Wort hat, rede mein Wort in Wahrheit*! Was hat das Stroh mit dem Korn gemeinsam*?, spricht der HERR*.", footnotes: ["o. der verkündige mein Wort in Beständigkeit\n℘ Kap. 42,4; 1Kö 22,14.16; Jes 21,10", "℘ 2Kor 6,14", "w. ist der Ausspruch des HERRN"] },
      { number: 29, text: "Ist mein Wort nicht brennend wie Feuer, spricht der HERR*, und wie ein Hammer, der Felsen zerschmettert*?", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 5,14; Lk 4,32"] },
      { number: 30, text: "Darum siehe, ich will an die Propheten, spricht der HERR*, die einer vom anderen meine Worte stehlen.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 31, text: "Siehe, ich will an die Propheten, spricht der HERR*, die ihre eigene Zunge nehmen und sprechen: Ausspruch des HERRN*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 28,15-17; 5Mo 18,20; 1Kö 22,11"] },
      { number: 32, text: "Siehe, ich will an die, die Lügenträume weissagen, spricht der HERR*, und die sie erzählen und mein Volk irreführen* mit ihren Lügen und mit ihrer Flunkerei! Ich aber, ich habe sie nicht gesandt und ihnen nichts befohlen*. Sie nützen diesem Volk gar nichts, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ V. 13", "℘ Kap. 29,23", "w. ist der Ausspruch des HERRN"] },
      { number: 33, text: "*Und wenn dieses Volk oder ein Prophet oder ein Priester dich fragt: Was ist die Last* des HERRN? — dann sage zu ihnen: Ihr seid die Last! Aber ich* werde euch abwerfen*, spricht der HERR*.", footnotes: ["℘ Hes 12,21-25", "Der hebr. Ausdruck hat eine doppelte Bedeutung: »Last« und »wichtiger Ausspruch« (vgl. Jes 13,1; 15,1).", "so mit anderer Wortabtrennung; Mas. T.: Was die Last ist? — Ja, ich", "℘ Kap. 6,30; 7,15.29; 2Kö 23,27", "w. ist der Ausspruch des HERRN"] },
      { number: 34, text: "Und der Prophet und der Priester und das Volk, die sagen: »Last des HERRN«, einen solchen Mann und sein Haus* werde ich heimsuchen*.", footnotes: ["d. h. seine Familie", "℘ 2Petr 2,12"] },
      { number: 35, text: "So sollt ihr sagen, jeder zu seinem Nächsten und jeder zu seinem Bruder: Was hat der HERR geantwortet? oder: Was hat der HERR geredet*?", footnotes: ["℘ Ps 85,9"] },
      { number: 36, text: "Aber das Wort »Last des HERRN« sollt ihr nicht mehr erwähnen*, denn die Last wird für jeden sein eigenes Wort sein*. Denn ihr verdreht die Worte des lebendigen Gottes*, des HERRN der Heerscharen, unseres Gottes.*", footnotes: ["so mit LXX; Mas. T.: An das Wort »Last des HERRN« sollt ihr nicht mehr denken", "℘ Jes 3,8; Mt 12,36", "℘ Kap. 10,10", "Manche nehmen an, dass ein geringfügiger Schreibfehler vorliegt, und üs.: Ja, sollte sein Wort für einen Menschen eine Last sein, dass ihr die Worte . . . unseres Gottes verdreht habt?"] },
      { number: 37, text: "So sollst du zum Propheten sagen: Was hat der HERR dir geantwortet? oder: Was hat der HERR geredet*?", footnotes: ["℘ Ps 85,9"] },
      { number: 38, text: "Wenn ihr aber sagt: »Last des HERRN« — darum, so spricht der HERR: Weil ihr dieses Wort sagt: »Last des HERRN«, obwohl ich euch habe ausrichten lassen*: Ihr sollt nicht sagen: »Last des HERRN« —", footnotes: ["w. und ich doch zu euch gesandt habe mit den Worten"] },
      { number: 39, text: "darum, siehe, ich werde euch ganz vergessen* und euch und die Stadt, die ich euch und euren Vätern gegeben habe, von meinem Angesicht verwerfen*.", footnotes: ["einige hebr. Handschr., LXX, Vulg. und die syr. Üs.: ich will euch hochheben, ja wie eine Last hochheben", "℘ Kap. 7,15; 32,31; 2Kö 23,27"] },
      { number: 40, text: "Und ich werde ewige Schmach auf euch legen und ewige Schande, die nicht vergessen wird.*", footnotes: ["℘ Kap. 20,11; Hes 16,52"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Der HERR ließ mich sehen — und siehe, zwei Körbe Feigen* waren vor dem Tempel des HERRN aufgestellt* —, nachdem Nebukadnezar, der König von Babel, Jechonja, den Sohn Jojakims, den König von Juda, und die Obersten von Juda und die Schmiede und die Schlosser* aus Jerusalem gefangen weggeführt und sie nach Babel gebracht hatte*.", heading: "Die Botschaft der beiden Feigenkörbe", footnotes: ["℘ Am 8,1", "T.; Mas. T.: bezeugt oder beordert", "Schmiede: ursprünglich Arbeiter an Holz, Stein oder Eisen, also allgemeine Handwerker, Facharbeiter; Schlosser: unsichere Bedeutung; andere üs. Schreiner, Goldschmiede oder Fachleute für Schanzenarbeiten", "℘ Kap. 13,19; 22,24-28; 27,20; Hes 17,4"] },
      { number: 2, text: "Der eine Korb enthielt sehr gute Feigen wie die Frühfeigen* und der andere Korb sehr schlechte Feigen, die vor Schlechtigkeit nicht mehr gegessen werden konnten.", footnotes: ["℘ Hos 9,10"] },
      { number: 3, text: "Und der HERR sprach zu mir: Was siehst du*, Jeremia? Ich sagte: Feigen; die guten Feigen sind sehr gut und die schlechten sehr schlecht, so dass sie vor Schlechtigkeit nicht gegessen werden können.", footnotes: ["℘ Kap. 1,11"] },
      { number: 4, text: "Da geschah das Wort des HERRN zu mir:" },
      { number: 5, text: "So spricht der HERR, der Gott Israels: Wie diese guten Feigen, so sehe ich die Weggeführten von Juda zum Guten an*, die ich von diesem Ort in das Land der Chaldäer weggeschickt habe.", footnotes: ["℘ 3Mo 26,44"] },
      { number: 6, text: "Ich richte mein Auge auf sie zum Guten und bringe sie in dieses Land zurück. Ich baue sie auf und breche nicht ab, pflanze sie ein und reiße nicht aus*.", footnotes: ["℘ Kap. 12,15; 29,10.11; 31,28; 32,37.41; 42,10; Jes 14,1; 60,21"] },
      { number: 7, text: "Und ich gebe ihnen ein Herz*, mich zu erkennen, dass ich der HERR bin. Und sie werden mein Volk sein, und ich werde ihr Gott sein*; denn sie werden mit ihrem ganzen Herzen zu mir umkehren*. —", footnotes: ["℘ Kap. 32,39; 5Mo 30,6", "℘ Kap. 30,22; 31,33; 32,38; Hes 11,17-20", "℘ Kap. 29,13; Hos 2,22"] },
      { number: 8, text: "Aber wie die schlechten Feigen, die vor Schlechtigkeit nicht gegessen werden können* — ja, so spricht der HERR —, so mache ich Zedekia*, den König von Juda, und seine Obersten und den Rest von Jerusalem, die, die in diesem Land übrig geblieben sind, sowie die, die sich im Land Ägypten niedergelassen haben*.", footnotes: ["℘ Kap. 13,7", "℘ 1Chr 3,15", "℘ Kap. 29,16.17; 44,1"] },
      { number: 9, text: "Und ich mache sie zum Entsetzen*, zum Unglück für alle Königreiche der Erde, zur Schmach und zum Sprichwort, zur Spottrede und zum Fluch an allen Orten, wohin ich sie vertreibe*.", footnotes: ["viell. auch: ich gebe sie hin zur Misshandlung", "℘ Kap. 15,4; 25,18; 26,6; 29,18; 42,18; 44,12; 5Mo 28,37; Jes 43,28"] },
      { number: 10, text: "Und ich sende das Schwert, den Hunger und die Pest unter sie*, bis sie ausgerottet sind aus dem Land, das ich ihnen und ihren Vätern gegeben habe*.", footnotes: ["℘ Kap. 9,15; 14,12; 29,17.18; 32,24; 42,22; Hes 6,12", "℘ 5Mo 28,21; 1Kö 14,15"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "*Das Wort, das zu Jeremia geschah über das ganze Volk Juda im vierten Jahr Jojakims, des Sohnes Josias, des Königs von Juda*, das ist das erste Jahr Nebukadnezars, des Königs von Babel*,", heading: "Nebukadnezar als Vollstrecker des Gottesgerichts — Begrenzung der babylonischen Herrschaft auf 70 Jahre", footnotes: ["℘ V. 1-11: Kap. 7,1-34", "℘ Kap. 35,1; 36,1; 46,2", "℘ 2Kö 24,1.2; Dan 1,1"] },
      { number: 2, text: "das der Prophet Jeremia zum ganzen Volk Juda und zu allen Bewohnern von Jerusalem redete:" },
      { number: 3, text: "Vom dreizehnten Jahr Josias*, des Sohnes Amons, des Königs von Juda, bis auf diesen Tag, jetzt schon 23 Jahre, ist das Wort des HERRN zu mir geschehen. Und ich habe zu euch geredet, früh mich aufmachend und redend*, aber ihr habt nicht gehört*.", footnotes: ["℘ Kap. 1,2", "so mit 17 hebr. Handschr.; Mas. T.: ich will mich früh aufmachen und reden", "℘ Kap. 19,15; 22,21; 29,19; 2Chr 24,19; Sach 1,4"] },
      { number: 4, text: "Und der HERR hat all seine Knechte, die Propheten, zu euch gesandt, früh sich aufmachend und sendend*. Aber ihr habt nicht gehört und habt eure Ohren nicht geneigt, um zu hören*,", footnotes: ["℘ Kap. 11,7; 26,5", "℘ Kap. 19,15; 22,21; 29,19; 2Chr 24,19; Sach 1,4"] },
      { number: 5, text: "wenn er sprach*: Kehrt doch um, jeder von seinem bösen Weg und von der Bosheit eurer Taten*, dann sollt ihr in dem Land, das der HERR euch und euren Vätern gegeben hat, wohnen von Ewigkeit zu Ewigkeit!", footnotes: ["o. wenn ich sprach", "℘ 2Kö 17,13"] },
      { number: 6, text: "Und lauft nicht anderen Göttern nach, um ihnen zu dienen und euch vor ihnen niederzuwerfen*! Und reizt mich nicht durch das Tun eurer Hände*, dass ich euch nicht Böses antue*!", footnotes: ["℘ 2Kö 17,35", "℘ Kap. 32,30", "℘ 5Mo 6,14.15"] },
      { number: 7, text: "Aber ihr habt nicht auf mich gehört*, spricht der HERR*, um mich durch das Tun eurer Hände zu reizen, euch zum Unheil*.", footnotes: ["℘ Kap. 19,15; 22,21; 29,19; 2Chr 24,19; Sach 1,4", "w. ist der Ausspruch des HERRN", "℘ Kap. 44,7.8"] },
      { number: 8, text: "Darum, so spricht der HERR der Heerscharen: Weil ihr auf meine Worte nicht gehört habt*,", footnotes: ["℘ Kap. 19,15; 22,21; 29,19; 2Chr 24,19; Sach 1,4"] },
      { number: 9, text: "siehe, so sende ich hin und hole alle Geschlechter des Nordens*, spricht der HERR*, und zu meinem Knecht Nebukadnezar, dem König von Babel*, und lasse sie über dieses Land kommen und über seine Bewohner* und über all diese Nationen ringsum. Und ich vollstrecke an ihnen den Bann und mache sie zum Entsetzen, zum Gezisch* und zu ewigen Trümmerstätten*.", footnotes: ["℘ Kap. 1,14.15; 35,11; 46,20", "w. ist der Ausspruch des HERRN", "℘ Kap. 27,6; 49,19; Jes 44,28", "℘ Kap. 2,15; 12,14; 2Kö 24,2; Hes 16,40; Hab 1,12", "Gemeint ist wohl ein Pfeifen oder Zischen, das angesichts eines erschreckenden Anblicks Verachtung oder Angst ausdrücken soll.", "LXX: zur ewigen Schmach\n℘ V. 17-27; Kap. 18,16"] },
      { number: 10, text: "Und ich lasse unter ihnen verloren gehen die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut, das Geräusch der Mühlen und das Licht der Lampe*.", footnotes: ["℘ Kap. 7,34"] },
      { number: 11, text: "Und dieses ganze Land wird zur Trümmerstätte, zur Wüste werden*; und diese Nationen werden dem König von Babel dienen siebzig Jahre lang*.", footnotes: ["℘ V. 38; Kap. 4,26.27; Hes 6,14; 12,19", "℘ Kap. 27,7; 29,10; 2Chr 36,20.21; Jes 23,15.17; Hes 29,11"] },
      { number: 12, text: "Und es wird geschehen, wenn siebzig Jahre voll sind, suche ich am König von Babel und an diesem Volk ihre Schuld heim*, spricht der HERR*, und am Land der Chaldäer; und ich mache es zu ewigen Einöden*.", footnotes: ["℘ Dan 5,26; Hab 1,17", "w. ist der Ausspruch des HERRN", "℘ Kap. 50,13; 51,26.62"] },
      { number: 13, text: "Und ich lasse über dieses Land alle meine Worte kommen, die ich über es geredet habe: alles, was in diesem Buch geschrieben steht, was Jeremia über alle Nationen geweissagt hat*.", footnotes: ["℘ Jes 55,11"] },
      { number: 14, text: "Denn viele Nationen und große Könige werden auch sie* dienstbar machen*. So vergelte ich ihnen nach ihrem Tun und nach dem Werk ihrer Hände*.", footnotes: ["d. h. die Chaldäer", "℘ Kap. 27,7; 51,27; Jes 13,4", "℘ Kap. 32,19; 50,29"] },
      { number: 15, text: "Ja, so hat der HERR, der Gott Israels, zu mir gesprochen: Nimm diesen Becher Zornwein aus meiner Hand und gib ihn all den Nationen zu trinken, zu denen ich dich sende*,", heading: "Der Zornweinbecher", footnotes: ["℘ Kap. 46,1; Ps 75,9; Jes 14,26; 34,2; Offb 14,10"] },
      { number: 16, text: "damit sie trinken und taumeln und sich wie toll aufführen wegen des Schwertes, das ich unter sie sende*! —", footnotes: ["℘ Kap. 13,12-14; 45,5; 48,26; 51,7"] },
      { number: 17, text: "Da nahm ich den Becher aus der Hand des HERRN und ließ all die Nationen trinken, zu denen der HERR mich gesandt hatte:" },
      { number: 18, text: "Jerusalem und die Städte von Juda und ihre Könige, ihre Obersten, um sie zur Trümmerstätte, zum Entsetzen, zum Gezisch* und zum Fluch zu machen, wie es am heutigen Tag ist*, —", footnotes: ["Gemeint ist wohl ein Pfeifen oder Zischen, das angesichts eines erschreckenden Anblicks Verachtung oder Angst ausdrücken soll.", "℘ Kap. 13,3-9; 24,9; 44,22; Esr 9,7"] },
      { number: 19, text: "den Pharao, den König von Ägypten, und seine Knechte, seine Obersten und sein ganzes Volk*", footnotes: ["℘ Kap. 43,9-13; 46,2-26; Hes 29,2"] },
      { number: 20, text: "und das ganze Völkergemisch* und alle Könige des Landes Uz* und alle Könige des Landes der Philister, Aschkelon, Gaza und Ekron sowie den Rest von Aschdod* —", footnotes: ["℘ Hes 30,5", "℘ 1Mo 22,21; Hi 1,1", "℘ Kap. 47,1-7; Ri 1,18; Zef 2,4"] },
      { number: 21, text: "Edom*, Moab* und die Söhne Ammon*", footnotes: ["℘ Kap. 49,7-22; Ob 1", "℘ Kap. 48,1", "℘ Kap. 27,2-6; 49,1-6; Hes 25,1.7.11"] },
      { number: 22, text: "und alle Könige von Tyrus* und alle Könige von Sidon* und die Könige der Wüste*, die jenseits des Meeres liegt,", footnotes: ["℘ Jes 23,1-14; Hes 26; 27; 28,1-19", "℘ Hes 28,20-23", "o. der Insel"] },
      { number: 23, text: "Dedan* und Tema* und Bus* und alle mit geschorenen Haarrändern* —", footnotes: ["℘ Kap. 49,7.8; Hi 6,19", "℘ Kap. 43,9-13; 46,2-26; Hes 29,2", "℘ 1Mo 22,21", "℘ Kap. 9,25"] },
      { number: 24, text: "und alle Könige von Arabien* und alle Könige des Völkergemischs, die in der Wüste wohnen*,", footnotes: ["℘ Jes 21,13", "℘ Kap. 49,28-33; 1Kö 10,15"] },
      { number: 25, text: "und alle Könige von Simri, alle Könige von Elam* und alle Könige von Medien*", footnotes: ["℘ Kap. 49,34-39", "℘ Jes 21,2"] },
      { number: 26, text: "und alle Könige des Nordens*, die nahen und die fernen, einen nach dem andern*, und alle Königreiche der Erde, die auf der Fläche des Erdbodens sind. — Und der König von Scheschach* soll nach ihnen trinken*.", footnotes: ["℘ Hes 32,30", "w. jeder zu seinem Bruder", "d. i. eine durch künstliche Buchstabenversetzung entstandene Bezeichnung für Babel", "℘ Kap. 50; 51"] },
      { number: 27, text: "Und sage zu ihnen: So spricht der HERR der Heerscharen, der Gott Israels: Trinkt, werdet berauscht und speit, fallt hin und steht nicht wieder auf, wegen des Schwertes, das ich unter euch sende*!", footnotes: ["℘ Am 8,14; Nah 3,11"] },
      { number: 28, text: "Und es soll geschehen, wenn sie sich weigern, den Becher aus deiner Hand zu nehmen, um zu trinken, dann sollst du zu ihnen sagen: So spricht der HERR der Heerscharen: Ihr müsst trinken*.", footnotes: ["℘ Kap. 27,8; 49,12; Ob 16"] },
      { number: 29, text: "Denn siehe, bei der Stadt, über der mein Name ausgerufen ist, beginne ich Unheil zu wirken*, und ihr, solltet ihr etwa ungestraft bleiben*? Ihr werdet nicht ungestraft bleiben; denn ein Schwert rufe ich herbei über alle Bewohner der Erde, spricht der HERR* der Heerscharen.", footnotes: ["℘ Kap. 19,3; Hes 9,6", "℘ 1Petr 4,17", "w. ist der Ausspruch des HERRN"] },
      { number: 30, text: "Und du, weissage ihnen alle diese Worte und sprich zu ihnen: Der HERR brüllt aus der Höhe und erhebt seine Stimme* aus seiner heiligen Wohnung*. Laut brüllt er über seine Weide; ein Jauchzen wie die Kelterer stimmt er an gegen alle Bewohner der Erde*.", footnotes: ["℘ Joe 4,16; Am 1,2", "℘ Sach 2,17", "℘ Jes 42,13; Hos 11,10; Offb 10,11"] },
      { number: 31, text: "Ein Getöse dringt bis ans Ende der Erde, denn einen Rechtsstreit hat der HERR mit den Nationen*, er hält Gericht mit allem Fleisch*; die Gottlosen gibt er dem Schwert preis, spricht der HERR*.", footnotes: ["℘ Hes 30,3", "℘ Jes 34,2.3; Joe 4,2", "w. ist der Ausspruch des HERRN"] },
      { number: 32, text: "So spricht der HERR der Heerscharen: Siehe, Unheil geht aus von Nation zu Nation, und ein gewaltiger Sturm macht sich auf* vom äußersten Ende der Erde*.", footnotes: ["w. regt sich", "℘ Kap. 6,22; 23,19"] },
      { number: 33, text: "Und die Erschlagenen des HERRN werden an jenem Tag daliegen von einem Ende der Erde bis zum andern Ende der Erde. Sie werden nicht beklagt, und ihre Leichen werden weder eingesammelt noch begraben; zu Dünger auf der Fläche des Erdbodens sollen sie werden*. —", footnotes: ["℘ Kap. 8,2; Hes 29,4.5"] },
      { number: 34, text: "Heult, ihr Hirten, und schreit um Hilfe! Und wälzt euch in der Asche, ihr Mächtigen der Herde! Denn eure Tage sind erfüllt, euch zu schlachten* — und die Tage eurer Zerstreuung —, und ihr sollt hinfallen wie ein kostbares Gefäß*.", footnotes: ["℘ Kap. 4,8.9; 23,1; Jak 5,1", "℘ Kap. 19,11"] },
      { number: 35, text: "Und verloren ist all die Zuflucht für die Hirten und jedes Entrinnen für die Mächtigen der Herde*.", footnotes: ["℘ Kap. 32,4; 37,17"] },
      { number: 36, text: "*Horch! Geschrei* der Hirten und Heulen der Mächtigen der Herde! Denn der HERR verwüstet ihre Weide*,", footnotes: ["w. Stimme des Geschreis", "w. Stimme des Geschreis", "℘ Sach 11,3"] },
      { number: 37, text: "und die Weideplätze des Friedens sind zerstört vor der Glut des Zorns des HERRN." },
      { number: 38, text: "Er hat wie ein Junglöwe sein Dickicht verlassen. Denn ihr Land ist zur Wüste geworden* vor dem gewalttätigen Schwert* und vor der Glut seines Zornes.", footnotes: ["℘ V. 11; Kap. 12,10", "Die Üs. »Schwert« ergibt sich im Vergleich mit Kap. 46,16; 50,16; Mas. T.: vor der gewalttätigen Glut"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "Im Anfang der Regierung Jojakims*, des Sohnes Josias, des Königs von Juda, geschah von dem HERRN dieses Wort:", heading: "Die Tempelrede und ihre Folgen für Jeremia — Justizmord am Propheten Uria", footnotes: ["℘ 1Chr 3,15; 2Chr 36,4.5"] },
      { number: 2, text: "So spricht der HERR: Tritt in den Vorhof des Hauses des HERRN* und zu allen Städten Judas, die kommen, um im Haus des HERRN anzubeten*, rede all die Worte, die ich dir geboten habe, zu ihnen zu reden*; lass kein Wort weg*!", footnotes: ["℘ Kap. 19,14", "℘ Kap. 7,2", "℘ Kap. 1,7.17", "w. verkürze kein Wort, o. verkürze nicht um ein Wort\n℘ 5Mo 4,2"] },
      { number: 3, text: "Vielleicht werden sie hören und jeder von seinem bösen Weg umkehren; dann werde ich mich des Unheils gereuen lassen, das ich ihnen zu tun gedenke wegen der Bosheit ihrer Taten*.", footnotes: ["℘ V. 19; Kap. 18,7.8; Hes 12,3; 18,21.27"] },
      { number: 4, text: "Und sage zu ihnen: So spricht der HERR: Wenn ihr nicht auf mich hört, dass ihr in meinem Gesetz lebt*, das ich euch vorgelegt habe*,", footnotes: ["w. geht", "℘ 5Mo 28,15"] },
      { number: 5, text: "und dass ihr auf die Worte meiner Knechte, der Propheten, hört, die ich zu euch sende, früh mich aufmachend und sendend, aber ihr habt nicht gehört*;", footnotes: ["℘ Kap. 7,13.25.26; 25,3.4"] },
      { number: 6, text: "dann will ich mit diesem Haus wie mit Silo verfahren*, und diese Stadt will ich zum Fluch machen für alle Nationen der Erde*.", footnotes: ["℘ Kap. 7,12-14", "℘ Kap. 24,9; 29,18; 44,22; 2Kö 22,19; Kla 2,15.16"] },
      { number: 7, text: "Und die Priester und die Propheten und das ganze Volk hörten Jeremia diese Worte im Haus des HERRN reden." },
      { number: 8, text: "Und es geschah, als Jeremia alles zu Ende geredet, was der HERR geboten hatte, zum ganzen Volk zu reden, da ergriffen ihn die Priester und die Propheten und das ganze Volk und sagten: Du musst sterben*!", footnotes: ["℘ Kap. 1,19; Am 7,10"] },
      { number: 9, text: "Warum hast du im Namen des HERRN geweissagt: Dieses Haus wird wie Silo werden, und diese Stadt wird in Trümmern liegen, ohne Bewohner*? Und das ganze Volk versammelte sich gegen Jeremia im Haus des HERRN*.", footnotes: ["℘ Kap. 32,3", "℘ Am 7,10-12"] },
      { number: 10, text: "Und als die Obersten von Juda* diese Worte hörten, gingen sie aus dem Haus des Königs hinauf zum Haus des HERRN und setzten sich in den Eingang des neuen Tores im Haus des HERRN*.", footnotes: ["℘ Kap. 36,12", "℘ Kap. 20,2; 2Chr 27,3"] },
      { number: 11, text: "Da sagten die Priester und die Propheten zu den Obersten und zum ganzen Volk: Dieser Mann verdient das Todesurteil, denn er hat gegen diese Stadt geweissagt, wie ihr mit euren eigenen Ohren gehört habt*.", footnotes: ["℘ Kap. 38,4; Apg 6,13; 21,28"] },
      { number: 12, text: "Jeremia aber sagte zu den Obersten und zum ganzen Volk: Der HERR hat mich gesandt, gegen dieses Haus und gegen diese Stadt all die Worte zu weissagen, die ihr gehört habt*.", footnotes: ["℘ Hes 21,7; Am 3,8"] },
      { number: 13, text: "Und nun bessert* eure Wege und Taten und hört auf die Stimme des HERRN, eures Gottes: dann wird der HERR sich des Unheils gereuen lassen, das er über euch geredet hat*!", footnotes: ["w. macht gut", "℘ Kap. 7,3"] },
      { number: 14, text: "Ich aber, siehe, ich bin in eurer Hand. Tut mit mir, wie es gut und recht ist in euren Augen*.", footnotes: ["℘ Jos 9,25"] },
      { number: 15, text: "Doch sollt ihr eindeutig wissen, dass ihr, wenn ihr mich tötet, unschuldiges Blut auf euch bringt und auf diese Stadt und auf ihre Bewohner*. Denn in Wahrheit, der HERR hat mich zu euch gesandt, all diese Worte vor euren Ohren zu reden.", footnotes: ["℘ 4Mo 35,33; 2Chr 24,22"] },
      { number: 16, text: "Da sagten die Obersten und das ganze Volk zu den Priestern und zu den Propheten: Dieser Mann hat das Todesurteil nicht verdient; denn er hat im Namen des HERRN, unseres Gottes, zu uns geredet*.", footnotes: ["℘ Jak 5,10"] },
      { number: 17, text: "Und es erhoben sich Männer von den Ältesten des Landes, und sie sagten* zu der ganzen Versammlung des Volkes:", footnotes: ["o. Es hatten sich nämlich . . . erhoben und gesagt"] },
      { number: 18, text: "Micha, der Moreschtiter*, hat in den Tagen Hiskias, des Königs von Juda, geweissagt* und zum ganzen Volk Juda gesprochen: So spricht der HERR der Heerscharen: »Zion wird zum Acker gepflügt, und Jerusalem wird zu Trümmerhaufen und der Berg des Hauses* zu Waldeshöhen*.«", footnotes: ["d. h. von Moreschet-Gat", "℘ Mi 1,1.14", "d. h. des Tempels", "℘ Mi 3,12"] },
      { number: 19, text: "Haben ihn etwa Hiskia, der König von Juda, und ganz Juda getötet? Hat er* nicht den HERRN gefürchtet und den HERRN angefleht*, so dass der HERR sich des Unheils gereuen ließ, das er über sie geredet hatte*? Und wir wollen ein so großes Unrecht* gegen unser Leben tun?*", footnotes: ["d. i. Hiskia", "w. das zornige Angesicht des HERRN besänftigt", "℘ V. 3; 2Mo 32,14; 2Chr 32,26", "w. Böses", "℘ Apg 5,39"] },
      { number: 20, text: "Damals gab es noch einen Mann, der im Namen des HERRN weissagte, Uria, der Sohn des Schemaja, aus Kirjat-Jearim*; und er weissagte gegen diese Stadt und gegen dieses Land, ganz wie es die Worte Jeremias taten.", footnotes: ["℘ 1Sam 6,21"] },
      { number: 21, text: "Als aber der König Jojakim und all seine Heerführer und alle Obersten seine Worte hörten, suchte der König ihn zu töten*. Und als Uria es hörte, fürchtete er sich und floh, und er kam nach Ägypten.", footnotes: ["℘ 1Kö 18,10"] },
      { number: 22, text: "Da sandte der König Jojakim Männer nach Ägypten, Elnatan, den Sohn des Achbor*, und einige Männer mit ihm nach Ägypten.", footnotes: ["℘ Kap. 29,3; 36,12.25; 39,14; 2Kö 22,12.14; Hes 8,11"] },
      { number: 23, text: "Und sie holten Uria aus Ägypten und führten ihn zum König Jojakim. Und er erschlug ihn mit dem Schwert und warf seine Leiche auf die Gräber der Kinder des Volkes*.", footnotes: ["d. h. auf die Gräber des einfachen Volkes\n℘ Kap. 22,17; 2Kö 23,37; Mt 23,37"] },
      { number: 24, text: "Doch die Hand Ahikams, des Sohnes des Schafan*, war mit Jeremia, so dass man ihn nicht in die Hand des Volkes gab, ihn zu töten*.", footnotes: ["℘ Kap. 29,3; 36,12.25; 39,14; 2Kö 22,12.14; Hes 8,11", "℘ Kap. 15,21; 36,19.26"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Im Anfang der Regierung Zedekias*, des Sohnes Josias, des Königs von Juda*, geschah vom HERRN dieses Wort zu Jeremia:", heading: "Das Rinderjoch", footnotes: ["Mas. T.: Jojakims; vgl. V. 3 und 12", "℘ Kap. 28,1; 32,1"] },
      { number: 2, text: "So sprach der HERR zu mir: Mach dir Stricke und Jochstangen* und lege sie auf deinen Hals*", footnotes: ["℘ Kap. 13,1", "℘ Kap. 28,10; 1Kö 22,11; Hes 12,3"] },
      { number: 3, text: "und sende sie an den König von Edom, an den König von Moab, an den König der Söhne Ammon, an den König von Tyrus und an den König von Sidon* durch die Boten, die zu Zedekia, dem König von Juda, nach Jerusalem gekommen sind!", footnotes: ["℘ Kap. 25,20-22"] },
      { number: 4, text: "Und befiehl ihnen, zu ihren Herren zu sagen: So spricht der HERR der Heerscharen, der Gott Israels: So sollt ihr euren Herren sagen:" },
      { number: 5, text: "Ich habe die Erde gemacht, die Menschen und das Vieh, die auf der Fläche der Erde sind, durch meine große Kraft und durch meinen ausgestreckten Arm*; und ich gebe sie, wem ich will*!", footnotes: ["℘ Kap. 32,17; 2Mo 6,6; Jes 45,12", "w. dem, dem zu geben recht ist in meinen Augen\n℘ Esr 1,2; Neh 9,22; Dan 4,14.22; Röm 13,1"] },
      { number: 6, text: "Und nun, ich habe all diese Länder in die Hand meines Knechtes Nebukadnezar*, des Königs von Babel, gegeben*. Und auch die Tiere des Feldes habe ich ihm gegeben, dass sie ihm dienen.", footnotes: ["℘ Kap. 25,9; 43,10", "℘ Kap. 28,14; 2Chr 36,23; Dan 2,38"] },
      { number: 7, text: "Und alle Nationen werden ihm dienen* und seinem Sohn und seinem Enkel*, bis die Zeit auch seines Landes gekommen ist und viele Völker und große Könige ihn dienstbar machen*.", footnotes: ["℘ Hes 30,24", "℘ Kap. 25,11", "℘ Kap. 25,12.14; 50,18.27.31"] },
      { number: 8, text: "Und es wird geschehen, die Nation und das Königreich, die ihm, Nebukadnezar, dem König von Babel, nicht dienen und ihren Hals nicht unter* das Joch des Königs von Babel geben wollen, diese Nation, spricht der HERR*, werde ich heimsuchen mit dem Schwert und mit dem Hunger und mit der Pest, bis ich sie ganz in seine Hand gegeben habe*.", footnotes: ["w. in", "w. ist der Ausspruch des HERRN", "℘ Kap. 25,9.28.29; Röm 13,2"] },
      { number: 9, text: "Ihr aber, hört nicht auf eure Propheten, auf eure Wahrsager, auf eure Träume*, auf eure Zauberer und auf eure Beschwörer*, die zu euch sagen: Ihr werdet dem König von Babel nicht dienen!", footnotes: ["Alte Üs. lesen: Träumer\n℘ 5Mo 13,2", "℘ 5Mo 18,10; Jes 8,19"] },
      { number: 10, text: "Denn sie weissagen euch Lüge*, um euch aus eurem Land wegzubringen, dass ich euch vertreibe und ihr umkommt*.", footnotes: ["℘ Kla 2,14; Sach 10,2", "℘ Kap. 29,3; 36,12.25; 39,14; 2Kö 22,12.14; Hes 8,11"] },
      { number: 11, text: "Die Nation aber, die ihren Hals in das Joch des Königs von Babel steckt und ihm dient, die werde ich in ihrem Land lassen, spricht der HERR*; und sie wird es bebauen und darin wohnen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 40,9"] },
      { number: 12, text: "Und zu Zedekia, dem König von Juda, redete ich nach all diesen Worten: Steckt eure Hälse in das Joch des Königs von Babel und dient ihm und seinem Volk, dann werdet ihr am Leben bleiben*!", footnotes: ["℘ Kap. 21,9"] },
      { number: 13, text: "Warum wollt ihr, du und dein Volk, durch das Schwert, durch den Hunger und durch die Pest sterben, wie der HERR über die Nation geredet hat, die dem König von Babel nicht dient?" },
      { number: 14, text: "Und hört nicht auf die Worte der Propheten, die zu euch sagen: Ihr werdet dem König von Babel nicht dienen! Denn sie weissagen euch Lüge*.", footnotes: ["℘ Kla 2,14; Sach 10,2"] },
      { number: 15, text: "Denn ich habe sie nicht gesandt, spricht der HERR*, sondern sie weissagen in meinem Namen Lüge*, damit ich euch vertreibe und ihr umkommt, ihr und die Propheten, die euch weissagen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 14,14; 29,8.9; 38,22; 1Jo 4,1", "℘ Kap. 14,14-16; Mt 7,22"] },
      { number: 16, text: "Und zu den Priestern und zu diesem ganzen Volk redete ich: So spricht der HERR: Hört nicht auf die Worte eurer Propheten, die euch weissagen: Siehe, die Geräte des Hauses des HERRN werden nun bald aus Babel zurückgebracht werden! Denn sie weissagen euch Lüge*.", footnotes: ["℘ Kap. 28,3"] },
      { number: 17, text: "Hört nicht auf sie! Dient dem König von Babel, dann werdet ihr am Leben bleiben! Warum sollte diese Stadt zur Trümmerstätte werden?" },
      { number: 18, text: "Wenn sie aber Propheten sind und wenn das Wort des HERRN bei ihnen ist, dann sollen sie doch bei dem HERRN der Heerscharen Fürbitte tun, damit die Geräte, die im Haus des HERRN und im Haus des Königs von Juda und in Jerusalem übrig geblieben sind, nicht nach Babel kommen*.", footnotes: ["so mit 2 hebr. Handschr.; Mas. T. enthält die Befehlsform"] },
      { number: 19, text: "Denn so spricht der HERR der Heerscharen über die Säulen, über das kupferne Meer und über die Gestelle* und über den Rest der Geräte, die in dieser Stadt übrig geblieben sind*,", footnotes: ["℘ 1Kö 7,15.23.27", "℘ 2Chr 36,18; Kla 1,10"] },
      { number: 20, text: "die Nebukadnezar, der König von Babel, nicht weggenommen hat, als er Jechonja, den Sohn des Jojakim, den König von Juda, samt allen Edlen von Juda und Jerusalem von Jerusalem nach Babel gefangen wegführte* —", footnotes: ["℘ Kap. 24,1; Mt 1,11"] },
      { number: 21, text: "denn so spricht der HERR der Heerscharen, der Gott Israels, über die Geräte, die im Haus des HERRN und im Haus des Königs von Juda und in Jerusalem übrig geblieben sind*:", footnotes: ["℘ 2Chr 36,18; Kla 1,10"] },
      { number: 22, text: "Sie sollen nach Babel gebracht werden* und sollen dort bleiben bis zu dem Tag, da ich nach ihnen sehe*, spricht der HERR*, und ich sie heraufhole und sie an diesen Ort zurückbringe*.", footnotes: ["℘ Kap. 20,5; 52,17-23", "o. mich ihrer annehme", "w. ist der Ausspruch des HERRN", "℘ Kap. 29,10; Esr 1,7-11; 7,19"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Und es geschah in demselben Jahr, im Anfang der Regierung Zedekias, des Königs von Juda*, im vierten Jahr, im fünften Monat, da sagte zu mir der Prophet Hananja, der Sohn des Asur, der von Gibeon war, im Haus des HERRN vor den Augen der Priester und des ganzen Volkes:", heading: "Jeremias Auseinandersetzung mit Hananja, dem Propheten des Heils", footnotes: ["℘ Kap. 27,1"] },
      { number: 2, text: "So spricht der HERR der Heerscharen, der Gott Israels: Ich zerbreche das Joch des Königs von Babel*.", footnotes: ["℘ 3Mo 26,13"] },
      { number: 3, text: "Nach zwei Jahren* bringe ich alle Geräte des Hauses des HERRN an diesen Ort zurück*, die Nebukadnezar, der König von Babel, von diesem Ort weggenommen und nach Babel gebracht hat*.", footnotes: ["w. Nach zwei Jahren von Tagen; d. h. nach genau zwei Jahren", "℘ Kap. 27,16", "℘ 2Chr 36,7.10"] },
      { number: 4, text: "Und Jechonja, den Sohn Jojakims, den König von Juda, und alle Weggeführten von Juda, die nach Babel gekommen sind*, bringe ich an diesen Ort zurück, spricht der HERR*; denn ich zerbreche das Joch des Königs von Babel*.", footnotes: ["℘ Kap. 13,19; 29,1.2; 2Kö 24,14-16", "w. ist der Ausspruch des HERRN", "℘ 3Mo 26,13"] },
      { number: 5, text: "Da sagte der Prophet Jeremia zum Propheten Hananja vor den Augen der Priester und vor den Augen des ganzen Volkes, das im Haus des HERRN stand," },
      { number: 6, text: "der Prophet Jeremia sagte: Amen, so tue der HERR!* Der HERR bestätige deine Worte, die du geweissagt hast, dass er die Geräte des Hauses des HERRN und alle Weggeführten von Babel an diesen Ort zurückbringen wird!", footnotes: ["℘ Kap. 11,5; 1Kö 1,36"] },
      { number: 7, text: "Nur höre doch dieses Wort, das ich vor deinen Ohren und vor den Ohren des ganzen Volkes rede*:", footnotes: ["℘ 1Kö 22,28"] },
      { number: 8, text: "Die Propheten, die von alters her vor mir und vor dir gewesen sind, die haben auch über viele* Länder und über große Königreiche geweissagt* von Krieg, von Unheil und von Pest!", footnotes: ["o. mächtige", "℘ Jes 13,1; Am 1,1; Jon 3,1-4; Nah 1,1"] },
      { number: 9, text: "Der Prophet, der von Frieden weissagt, wird dadurch, dass das Wort des Propheten eintrifft, als der Prophet erkannt, den der HERR in Wahrheit gesandt hat*.", footnotes: ["℘ 5Mo 18,21.22; Hes 33,33"] },
      { number: 10, text: "Da nahm der Prophet Hananja das Joch* vom Hals des Propheten Jeremia und zerbrach es*.", footnotes: ["w. die Jochstange", "℘ Kap. 27,2"] },
      { number: 11, text: "Dann sagte Hananja vor den Augen des ganzen Volkes: So spricht der HERR: Ebenso werde ich nach zwei Jahren* das Joch Nebukadnezars, des Königs von Babel, zerbrechen vom Hals aller Nationen. Der Prophet Jeremia aber ging seines Weges*.", footnotes: ["w. Nach zwei Jahren von Tagen; d. h. nach genau zwei Jahren", "℘ Spr 14,7"] },
      { number: 12, text: "Und das Wort des HERRN geschah zu Jeremia, nachdem der Prophet Hananja das Joch* vom Hals des Propheten Jeremia zerbrochen hatte*:", footnotes: ["w. die Jochstange", "℘ Kap. 27,2"] },
      { number: 13, text: "Geh und sage zu Hananja: So spricht der HERR: Ein hölzernes Joch* hast du zerbrochen, aber an seiner Stelle hast du ein eisernes Joch* gemacht*!", footnotes: ["w. Hölzerne Jochstangen", "w. eiserne Jochstangen", "LXX: habe ich ein eisernes Joch gemacht\n℘ 5Mo 28,48"] },
      { number: 14, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Ein eisernes Joch habe ich auf den Hals all dieser Nationen gelegt, damit sie Nebukadnezar, dem König von Babel, dienen, und sie werden ihm dienen; und auch die Tiere des Feldes habe ich ihm gegeben*.", footnotes: ["℘ Kap. 27,4-7"] },
      { number: 15, text: "Und der Prophet Jeremia sagte zum Propheten Hananja: Höre doch, Hananja! Der HERR hat dich nicht gesandt, sondern du hast dieses Volk auf eine Lüge vertrauen lassen*.", footnotes: ["℘ Kap. 29,31; Kla 2,14; Hes 13,6.22"] },
      { number: 16, text: "Darum, so spricht der HERR: Siehe, ich werfe dich vom Erdboden weg. Dieses Jahr wirst du sterben*; denn du hast Ungehorsam gegen den HERRN gepredigt*.", footnotes: ["℘ Kap. 20,6; Am 7,17", "℘ Kap. 29,32; 5Mo 13,6"] },
      { number: 17, text: "Und der Prophet Hananja starb in demselben Jahr, im siebten Monat*.", footnotes: ["℘ Kap. 23,31; 5Mo 18,20; Jes 44,25.26"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "Und dies sind die Worte des Briefes, den der Prophet Jeremia von Jerusalem an den Rest der Ältesten der Weggeführten und an die Priester und an die Propheten und an das ganze Volk sandte, das Nebukadnezar von Jerusalem nach Babel gefangen weggeführt hatte*", heading: "Jeremias Brief an die Exilgemeinde: Verheißung für die Verschleppten — Gericht über die Heilspropheten", footnotes: ["℘ V. 20; Kap. 28,4; 2Kö 24,12"] },
      { number: 2, text: "— nachdem der König Jechonja und die Herrin* und die Hofbeamten*, die Obersten von Juda und Jerusalem und die Schmiede und Schlosser* Jerusalem verlassen hatten* —,", footnotes: ["d. i. die Mutter des Königs", "w. Eunuchen", "s. Anm. zu Kap. 24,1", "℘ V. 20; Kap. 28,4; 2Kö 24,12"] },
      { number: 3, text: "durch Elasa, den Sohn des Schafan*, und Gemarja, den Sohn des Hilkija, die Zedekia, der König von Juda, nach Babel zu Nebukadnezar, dem König von Babel, sandte:", footnotes: ["℘ Kap. 26,24"] },
      { number: 4, text: "So spricht der HERR der Heerscharen, der Gott Israels: An alle Weggeführten, die ich von Jerusalem nach Babel gefangen weggeführt habe:" },
      { number: 5, text: "Baut Häuser und wohnt darin! Pflanzt Gärten und esst ihre Früchte*!", footnotes: ["℘ V. 28"] },
      { number: 6, text: "Nehmt Frauen und zeugt Söhne und Töchter! Und nehmt Frauen für eure Söhne, und eure Töchter gebt Männern, damit sie Söhne und Töchter gebären, damit ihr euch dort vermehrt und nicht vermindert!" },
      { number: 7, text: "Und sucht den Frieden* der Stadt, in die ich euch gefangen weggeführt habe, und betet für sie zum HERRN! Denn in ihrem Frieden werdet ihr Frieden haben.", footnotes: ["o. das Wohl"] },
      { number: 8, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Lasst euch von euren Propheten, die in eurer Mitte sind, und von euren Wahrsagern nicht täuschen! Und hört nicht auf eure Träume, die ihr euch träumen lasst*!", footnotes: ["LXX und syr. Üs.: auf ihre Träume, die sie träumen\n℘ Kap. 23,16.25; 27,14.15; Mk 13,5"] },
      { number: 9, text: "Denn Lüge weissagen sie euch in meinem Namen; ich habe sie nicht gesandt*, spricht der HERR*.", footnotes: ["℘ V. 21; Kap. 23,21; Kla 2,14", "w. ist der Ausspruch des HERRN"] },
      { number: 10, text: "Denn so spricht der HERR: Erst wenn siebzig Jahre für Babel voll sind*, werde ich mich euer annehmen und mein gutes Wort, euch an diesen Ort zurückzubringen, an euch erfüllen*.", footnotes: ["℘ Kap. 25,11.12; Ps 102,14", "℘ Kap. 27,22; 33,14; Esr 1,1-3; Hes 11,17"] },
      { number: 11, text: "Denn ich kenne ja die Gedanken, die ich über euch denke, spricht der HERR*, Gedanken* des Friedens und nicht zum Unheil*, um euch Zukunft* und Hoffnung zu gewähren*.", footnotes: ["w. ist der Ausspruch des HERRN", "w. die Pläne, die ich über euch plane, . . . Pläne", "℘ Kap. 24,5.6; 33,6; Jes 27,4; Sach 8,14.15", "o. Ausgang", "℘ Kap. 31,17; Ps 85,9"] },
      { number: 12, text: "Ruft ihr mich an, geht ihr hin und betet zu mir, dann werde ich auf euch hören*.", footnotes: ["℘ Kap. 33,3; 51,50; 2Chr 33,13; Hi 22,27; Jes 26,16; 30,19; Dan 9,3; Hos 14,9"] },
      { number: 13, text: "Und sucht ihr mich, so werdet ihr mich finden, ja, fragt ihr mit eurem ganzen Herzen* nach mir,", footnotes: ["℘ Kap. 24,7; 50,4; 5Mo 4,29; 1Kö 8,48; Ps 145,18; Jes 65,10"] },
      { number: 14, text: "so werde ich mich von euch finden lassen*, spricht der HERR*. Und ich werde euer Geschick* wenden* und euch sammeln aus allen Nationen und aus allen Orten, wohin ich euch vertrieben habe, spricht der HERR*. Und ich werde euch an den Ort zurückbringen, von dem ich euch gefangen weggeführt habe*.", footnotes: ["LXX: so werde ich euch erscheinen\n℘ 1Chr 28,9; Jes 45,19; 55,6; Mt 7,8", "w. ist der Ausspruch des HERRN", "o. eure Gefangenschaft", "℘ Kap. 30,18; 31,23; 33,7.11; Ps 126,1-4; Hes 39,25; Joe 4,1; Zef 3,20", "o. eure Gefangenschaft", "℘ Kap. 3,14; 16,15; 23,3; 31,16.17; Jes 14,1"] },
      { number: 15, text: "Wenn ihr sagt: »Der HERR hat uns in Babel Propheten erweckt«," },
      { number: 16, text: "ja, so spricht der HERR über den König, der auf dem Thron Davids sitzt*, und über das ganze Volk, das in dieser Stadt wohnt, eure Brüder, die nicht mit euch in die Gefangenschaft* weggezogen sind —", footnotes: ["℘ 2Chr 36,11", "w. in die Wegführung"] },
      { number: 17, text: "so spricht der HERR der Heerscharen: Siehe, ich sende unter sie das Schwert, den Hunger und die Pest* und mache sie wie die abscheulichen Feigen, die vor Schlechtigkeit nicht gegessen werden können*.", footnotes: ["℘ Kap. 24,10; 34,17", "℘ Kap. 24,8"] },
      { number: 18, text: "Und ich jage ihnen nach mit dem Schwert, mit dem Hunger und mit der Pest*. Und ich mache sie zum Entsetzen für alle Königreiche* der Erde*, zum Fluch und zum Entsetzen und zum Gezisch* und zur Schmach unter allen Nationen, wohin ich sie vertrieben habe*;", footnotes: ["℘ Kap. 24,10; 34,17", "viell. auch: ich gebe sie zur Misshandlung hin allen Königreichen", "℘ Kap. 15,4; 26,6", "Gemeint ist wohl ein Pfeifen oder Zischen, das angesichts eines erschreckenden Anblicks Verachtung oder Furcht ausdrücken soll.", "℘ Kap. 18,16; 24,9; Hes 5,15; Sach 8,13"] },
      { number: 19, text: "weil sie auf meine Worte nicht gehört haben, spricht der HERR*, womit ich meine Knechte, die Propheten, zu ihnen sandte, früh mich aufmachend und sendend. Aber ihr habt nicht gehört*, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 7,13.25; 25,3-8; 44,3.4", "w. ist der Ausspruch des HERRN"] },
      { number: 20, text: "Ihr nun, hört das Wort des HERRN, all ihr Weggeführten, die ich von Jerusalem nach Babel weggeschickt habe*!", footnotes: ["℘ V. 1.2.4; Hes 3,11"] },
      { number: 21, text: "So spricht der HERR der Heerscharen, der Gott Israels, über Ahab, den Sohn des Kolaja, und über Zedekia, den Sohn des Maaseja, die euch Lügen weissagen in meinem Namen*: Siehe, ich gebe sie in die Hand Nebukadnezars, des Königs von Babel, damit er sie vor euren Augen erschlägt.", footnotes: ["℘ V. 8.9"] },
      { number: 22, text: "Und von ihnen wird ein Fluch genommen* bei allen Weggeführten Judas, die in Babel sind, dass man sagt: Der HERR mache dich wie Zedekia und wie Ahab, die der König von Babel im Feuer geröstet hat*!", footnotes: ["℘ Jes 65,15", "℘ Dan 3,6"] },
      { number: 23, text: "Denn sie haben eine Torheit* in Israel begangen und Ehebruch getrieben mit den Frauen ihrer Nächsten* und in meinem Namen Lügenworte geredet, was ich ihnen nicht geboten hatte*; und ich, ich weiß es und bin Zeuge*, spricht der HERR*. —", footnotes: ["hier abschwächend für Gottlosigkeit", "℘ Kap. 23,14", "℘ Kap. 23,16.32", "℘ Mal 2,14", "w. ist der Ausspruch des HERRN"] },
      { number: 24, text: "Und zu Schemaja, dem Nehelamiter, sollst du sagen:" },
      { number: 25, text: "So spricht der HERR der Heerscharen, der Gott Israels: Weil du in deinem Namen einen Brief gesandt hast an das ganze Volk, das in Jerusalem ist, und an den Priester Zefanja, den Sohn des Maaseja*, und an all die Priester und gesagt:", footnotes: ["℘ Kap. 21,1"] },
      { number: 26, text: "»Der HERR hat dich anstelle des Priesters Jojada zum Priester bestellt, *damit Aufseher für das Haus des HERRN da sind* für jeden Rasenden* und den, der als Prophet auftritt, damit du ihn in den Block* und in das Halseisen legst.", footnotes: ["LXX, syr. und lat. Üs.: zum Aufseher im Haus des HERRN", "LXX, syr. und lat. Üs.: zum Aufseher im Haus des HERRN", "w. für jeden Mann der Raserei. — Gemeint sind die in prophetischer Ergriffenheit redenden Propheten.\n℘ 2Kö 9,11", "℘ Kap. 20,2"] },
      { number: 27, text: "Und nun, warum bist du nicht gegen Jeremia aus Anatot eingeschritten*, der bei euch als Prophet auftritt?", footnotes: ["w. warum hast du Jeremia . . . nicht angeschrien"] },
      { number: 28, text: "Denn er hat doch zu uns nach Babel gesandt und gesagt: Es wird lange dauern; baut Häuser und wohnt darin und pflanzt Gärten und esst ihre Früchte*!« —", footnotes: ["℘ V. 5"] },
      { number: 29, text: "Der Priester Zefanja aber hatte diesen Brief vor den Ohren des Propheten Jeremia gelesen. —" },
      { number: 30, text: "Da geschah das Wort des HERRN zu Jeremia:" },
      { number: 31, text: "Sende hin zu allen Weggeführten und sage: So spricht der HERR zu Schemaja, dem Nehelamiter: Weil Schemaja euch geweissagt, ich ihn aber nicht gesandt habe und er euch auf Lügen hat vertrauen lassen*,", footnotes: ["℘ Kap. 28,15"] },
      { number: 32, text: "darum, so spricht der HERR: Siehe, ich will Schemaja, den Nehelamiter, und seine Nachkommen heimsuchen: er soll keinen Nachkommen haben, der inmitten dieses Volkes wohnt, und er soll das Gute nicht sehen, das ich meinem Volk tun werde*, spricht der HERR*; denn er hat Ungehorsam gegen den HERRN gepredigt*.", footnotes: ["℘ V. 10-14", "w. ist der Ausspruch des HERRN", "℘ Kap. 20,6; 28,16; Hes 20,38; Am 7,17; 9,10"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Das Wort, das von dem HERRN zu Jeremia geschah:", heading: "Ankündigung von Gerichtsnot und Erlösung für Israel und Juda" },
      { number: 2, text: "So spricht der HERR, der Gott Israels: Schreibe dir alle Worte, die ich zu dir geredet habe, in ein Buch*!", footnotes: ["℘ Kap. 36,2.4; 51,60; 2Mo 17,14; Jes 8,1"] },
      { number: 3, text: "Denn siehe, Tage kommen, spricht der HERR*, da wende ich das Geschick meines Volkes Israel und Juda*, spricht der HERR. Und ich bringe sie in das Land zurück, das ich ihren Vätern gegeben habe, damit sie es in Besitz nehmen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 29,14; Am 9,14", "℘ Kap. 16,15; Hes 34,13; Zef 2,7"] },
      { number: 4, text: "Und das sind die Worte, die der HERR über Israel und über Juda geredet hat." },
      { number: 5, text: "Denn so spricht der HERR: Eine Stimme des Schreckens haben wir* gehört. Da ist Furcht* und kein Friede*.", footnotes: ["Andere üs.: habe ich; LXX: habt ihr", "w. Beben vor Schrecken", "℘ Kap. 6,22-26; Hab 1,6-10"] },
      { number: 6, text: "Fragt doch nach und seht, ob ein Mann* gebären kann! Warum sehe ich die Hände eines jeden Mannes auf seinen Lenden, einer Gebärenden gleich*, und alle Gesichter in Blässe verwandelt?*", footnotes: ["w. ein Männliches", "℘ Kap. 4,31", "℘ Joe 2,6"] },
      { number: 7, text: "Wehe! Denn groß ist jener Tag*, keiner ist wie er*, und es ist eine Zeit der Bedrängnis für Jakob; doch wird er aus ihr gerettet werden*.", footnotes: ["℘ Joe 2,11; Zef 1,14.15; Offb 6,17; 7,14", "℘ Dan 9,12; Hab 3,16", "℘ Dan 12,1; Mi 4,9.10"] },
      { number: 8, text: "Denn an jenem Tag wird es geschehen, spricht der HERR* der Heerscharen, da zerbreche ich sein Joch von deinem Hals und zerreiße ich deine Stricke, und Fremde sollen ihn* nicht mehr dienstbar machen*;", footnotes: ["w. ist der Ausspruch des HERRN", "d. i. Jakob bzw. das Volk Israel", "℘ Jes 10,27; 14,1-5; Hes 34,27"] },
      { number: 9, text: "sondern sie* werden dem HERRN, ihrem Gott, dienen und ihrem König David, den ich ihnen erwecke*.", footnotes: ["d. i. Jakob bzw. das Volk Israel", "℘ Hes 34,24; Hos 3,5"] },
      { number: 10, text: "*Und du, fürchte dich nicht, mein Knecht Jakob, spricht der HERR*, und erschrick nicht, Israel*! Denn siehe, ich will dich retten aus der Ferne* und deine Nachkommen aus dem Land ihrer Gefangenschaft*. Und Jakob wird zurückkehren und Ruhe haben, er wird sicher sein, und niemand wird ihn aufschrecken*.", footnotes: ["℘ V. 10.11: Kap. 46,27.28", "w. ist der Ausspruch des HERRN", "℘ Jes 41,13.14", "℘ Jes 49,12.25", "℘ Dan 12,1; Mi 4,9.10", "℘ Kap. 23,6; Hes 34,28; Hos 2,20; 6,11; Mi 4,4; Lk 1,71.74"] },
      { number: 11, text: "Denn ich bin mit dir, spricht der HERR*, um dich zu retten*. Denn ich werde ein Ende machen mit* allen Nationen, unter die ich dich zerstreut habe. Nur mit dir werde ich kein Ende machen, sondern dich mit rechtem Maß* züchtigen* und dich keineswegs ungestraft lassen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 1,19", "w. unter", "w. entsprechend meinem Recht", "℘ Kap. 10,24; Hos 11,9", "℘ Kap. 5,10; 2Mo 34,7; 2Sam 24,12; Jes 27,7; Am 9,8.9"] },
      { number: 12, text: "Denn so spricht der HERR: Unheilbar ist dein Bruch*, bösartig ist deine Wunde!", footnotes: ["℘ Kap. 6,7; 15,18; Jes 1,6; Kla 2,13; Mi 1,9; Nah 3,19"] },
      { number: 13, text: "Niemand führt deine Rechtssache, für das Geschwür gibt es keine Heilung, keine heilende Haut* für dich!*", footnotes: ["w. kein Überzug; d. i. die Fleischschicht, die eine heilende Wunde überzieht", "so mit Versetzung eines Satzzeichens und Änderung eines Vokals; Mas. T.: tödlich ist deine Wunde — 13 niemand führt deine Rechtssache — bis zum Verfaulen. Eine Heilung, ein Pflaster gibt es nicht für dich.\n℘ Kap. 8,22; 14,19"] },
      { number: 14, text: "All deine Liebhaber haben dich vergessen, sie fragen nicht nach dir*. Denn ich habe dich verwundet, wie man einen Feind verwundet*. Deine Züchtigung war grausam* um der Größe deiner Schuld willen, weil deine Sünden zahlreich sind*.", footnotes: ["℘ Kap. 4,30; Kla 1,2.19", "w. mit der Wunde eines Feindes", "Mas. T.: mit der Züchtigung eines Grausamen\n℘ Kla 2,1-6", "℘ Kap. 5,6; 32,29-35; Dan 9,5-14"] },
      { number: 15, text: "Was schreist du um Hilfe über deinen Bruch, dass dein Schmerz unheilbar ist*? Um der Größe deiner Schuld willen, weil deine Sünden zahlreich sind, habe ich dir das angetan*.", footnotes: ["℘ Kap. 6,7; 15,18; Jes 1,6; Kla 2,13; Mi 1,9; Nah 3,19", "℘ Kla 3,39"] },
      { number: 16, text: "Darum sollen alle, die dich fressen, gefressen werden*, und alle deine Bedränger sollen insgesamt in die Gefangenschaft gehen. Und deine Plünderer sollen der Plünderung verfallen, und alle, die dich beraubt haben, werde ich dem Raub preisgeben*.", footnotes: ["Andere üs. mit Textänderung: Aber alle, die dich gefressen haben, sollen gefressen werden", "℘ Kap. 10,25; 5Mo 30,7; 1Sam 17,53; Spr 22,23; Sach 1,15; 2,12.13"] },
      { number: 17, text: "Denn ich will dir Genesung bringen* und dich von deinen Wunden heilen*, spricht der HERR*, weil man dich eine Verstoßene nennt: »Das ist Zion, nach dem niemand fragt!«*", footnotes: ["w. ich will dir heraufsteigen lassen (o. neu wachsen lassen) eine Fleischschicht über deine Wunde", "℘ Kap. 33,6; Jes 30,26; 57,18.19; Hos 6,1", "w. ist der Ausspruch des HERRN", "℘ Kap. 10,20; Jes 54,6"] },
      { number: 18, text: "So spricht der HERR: Siehe, ich will das Geschick der Zelte Jakobs wenden*, und über seine Wohnungen will ich mich erbarmen*. Und die Stadt wird auf ihrem Hügel wieder erbaut, und der Palast wird an seinem rechten Platz stehen*;", footnotes: ["℘ Kap. 32,44; Jes 44,26", "℘ Ps 102,14; Sach 1,16", "o. in seiner alten Weise bewohnt werden"] },
      { number: 19, text: "und Lobgesang und die Stimme der Spielenden* soll wieder von ihnen ausgehen*. Und ich will sie vermehren, und sie werden sich nicht vermindern. Und ich will sie herrlich machen*, und sie werden nicht gering geachtet werden*.", footnotes: ["o. Tanzenden", "℘ Kap. 31,4; Jes 51,11; Sach 8,5", "℘ Zef 3,19", "℘ Kap. 3,16; Jes 26,15; Hes 36,10.11.37; Sach 10,8"] },
      { number: 20, text: "Und seine Söhne werden sein wie früher*, und seine Gemeinde wird vor mir fest stehen*; alle seine Unterdrücker aber werde ich heimsuchen*.", footnotes: ["℘ Ps 102,29", "℘ Kla 5,21; Sach 10,6", "℘ Kap. 50,33.34"] },
      { number: 21, text: "Und sein Mächtiger wird wieder aus ihm selbst sein und sein Herrscher aus seiner Mitte hervorgehen*. Und ich will ihm Zutritt gewähren, und er wird mir nahen. Denn wer ist es, der sein Herz verpfändet, um zu mir zu nahen?, spricht der HERR*.", footnotes: ["℘ 5Mo 17,15", "w. ist der Ausspruch des HERRN"] },
      { number: 22, text: "Und ihr werdet mein Volk, und ich werde euer Gott sein*.", footnotes: ["℘ Kap. 11,4; 24,7; 31,1; Hes 11,20; 36,28; Hos 2,25; Sach 8,8"] },
      { number: 23, text: "Siehe, ein Sturmwind des HERRN, sein Grimm ist hervorgebrochen, ein wirbelnder Sturmwind*; auf den Kopf der Gottlosen wirbelt er herab*.", footnotes: ["so mit Angleichung an Kap. 23,19; Mas. T.: ein Sturmwind, der sich als Fremder aufhält\n℘ Kap. 4,11", "℘ Kap. 23,19.20"] },
      { number: 24, text: "Nicht wendet sich die Glut des Zornes des HERRN, bis er getan und bis er ausgeführt hat die Pläne seines Herzens. Am Ende der Tage werdet ihr das verstehen*.", footnotes: ["℘ Kap. 23,19.20"] },
    ]},
    { number: 31, verses: [
      { number: 1, text: "In jener Zeit, spricht der HERR*, werde ich der Gott aller Sippen Israels sein, und sie werden mein Volk sein*.", heading: "Zukünftiges Heil für Israel und Juda", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 30,22; Hes 34,24; 36,28"] },
      { number: 2, text: "So spricht der HERR: Das Volk derer, die dem Schwert entronnen sind, hat Gnade* gefunden in der Wüste*, als Israel wanderte, um zu seiner Ruhe zu kommen.*", footnotes: ["o. Gunst", "℘ Hes 20,35", "o. So spricht der HERR: Es fand Gnade wie in der Wüste das Volk derer, die dem Schwert entronnen sind; ich will gehen, um Israel zu seiner Ruhe zu bringen.\n℘ 5Mo 12,9; Hebr 4,9"] },
      { number: 3, text: "Der HERR ist ihm* von ferne erschienen: »Ja, mit ewiger Liebe habe ich dich geliebt*; darum habe ich dir meine Güte* bewahrt.", footnotes: ["so mit LXX; Mas. T.: mir", "℘ 5Mo 33,3; 1Kö 10,9; Jes 43,4; 49,14.15; Röm 11,28", "o. Gnade"] },
      { number: 4, text: "Ich will dich wieder bauen, und du wirst gebaut sein, Jungfrau Israel*! Du wirst dich wieder mit deinen Tamburinen schmücken und ausziehen im Reigen der Tanzenden*.", footnotes: ["℘ Jes 14,1", "℘ Kap. 30,19; Ps 149,3"] },
      { number: 5, text: "Du wirst wieder Weinberge pflanzen auf den Bergen Samarias; die Pflanzer werden pflanzen und genießen*.", footnotes: ["w. entweihen; vgl. Anm. zu 5Mo 20,6\n℘ Ps 107,37; Jes 62,8.9; 65,21"] },
      { number: 6, text: "Denn es wird einen Tag geben, an dem die Wächter auf dem Gebirge Ephraim rufen: Macht euch auf und lasst uns nach Zion hinaufziehen zum HERRN, unserm Gott*!«", footnotes: ["℘ Jes 27,13; Sach 8,21"] },
      { number: 7, text: "Denn so spricht der HERR: Jubelt über Jakob mit Freuden und jauchzt über das Haupt der Nationen*! Verkündet, lobsingt und sprecht: Gerettet hat der HERR sein Volk,* den Rest Israels*!", footnotes: ["w. gegen die Nationen bzw. an der Spitze der Nationen", "so mit LXX und der aram. Üs.; Mas. T.: Rette, HERR, dein Volk!", "℘ Ps 126,2-4"] },
      { number: 8, text: "Siehe, ich bringe sie herbei aus dem Land des Nordens und sammle sie von dem äußersten Ende der Erde*, unter ihnen Blinde und Lahme*, Schwangere und Gebärende, sie alle zusammen; als eine große Volksversammlung kehren sie hierher zurück.", footnotes: ["℘ Kap. 16,15; 23,3; Hes 20,34", "℘ Mi 4,6.7"] },
      { number: 9, text: "Mit Weinen kommen sie*, und unter Flehen* führe ich sie. Ich bringe sie zu Wasserbächen auf einem ebenen Weg, auf dem sie nicht stürzen*. Denn ich bin Israel wieder zum Vater geworden*, und Ephraim ist mein Erstgeborener*.", footnotes: ["℘ Kap. 50,4", "LXX und die alte lat. Üs.: unter Tröstungen", "℘ Jes 42,16; 43,19; 49,10", "℘ Jes 63,16; 2Kor 6,18", "℘ V. 20; 2Mo 4,22"] },
      { number: 10, text: "Hört das Wort des HERRN, ihr Nationen, und meldet es auf den fernen Inseln und sagt: Der Israel zerstreut hat, wird es wieder sammeln und wird es hüten wie ein Hirte seine Herde*!", footnotes: ["℘ Ps 147,2; Hes 34,12"] },
      { number: 11, text: "Denn der HERR hat Jakob losgekauft und hat ihn erlöst aus der Hand dessen, der stärker war als er*.", footnotes: ["℘ Jes 48,20; 49,25; Kla 3,58; Lk 1,68.71"] },
      { number: 12, text: "Und sie werden kommen und jubeln auf der Höhe Zions* und herbeiströmen zu all dem Guten* des HERRN*: zum Korn, zum Most, zum Öl* und zu den jungen Schafen und Rindern. Und ihre Seele wird sein wie ein bewässerter Garten*, und sie werden nicht mehr länger verschmachten.", footnotes: ["℘ Jes 35,10; Hes 20,40", "o. und vor Freude strahlen über das Gute", "℘ Jes 52,8; Hes 36,30", "℘ Hos 2,24; Sach 8,12", "℘ Jes 58,11; Kap. 33,11"] },
      { number: 13, text: "Dann wird die Jungfrau sich erfreuen am Reigen, junge Männer und Greise miteinander*. Und ich will ihre Trauer in Freude verwandeln und will sie trösten und erfreuen in* ihrem Kummer*.", footnotes: ["℘ Ps 148,12.13", "w. weg von", "℘ Ps 126,5; Jes 12,1; 51,3; Sach 8,19"] },
      { number: 14, text: "Und ich will die Seele der Priester mit Fett laben*, und mein Volk wird sich an all meinem Guten sättigen*, spricht der HERR*.", footnotes: ["℘ Ps 63,6", "℘ Kap. 33,9; 5Mo 33,23; Ps 85,13; Hes 34,14", "w. ist der Ausspruch des HERRN"] },
      { number: 15, text: "So spricht der HERR: Horch! In Rama* hört man Totenklage, bitteres Weinen. Rahel beweint ihre Kinder. Sie will sich nicht trösten lassen* über ihre Kinder, weil sie nicht mehr da sind*.", footnotes: ["℘ Kap. 40,1; Jos 18,25", "w. Sie weigert sich, sich trösten zu lassen", "℘ Kap. 10,20; 1Mo 37,35; Mt 2,18"] },
      { number: 16, text: "So spricht der HERR: Halte deine Stimme zurück vom Weinen und deine Augen von Tränen! Denn es gibt Lohn für deine Mühe*, spricht der HERR*: Sie werden aus dem Land des Feindes zurückkehren*;", footnotes: ["℘ 2Chr 15,7; Jes 40,10; Hebr 10,35; 11,6", "w. ist der Ausspruch des HERRN", "℘ Kap. 29,14; Hes 37,21"] },
      { number: 17, text: "und Hoffnung ist da für deine Zukunft*, spricht der HERR*, und deine Kinder werden in ihr Gebiet zurückkehren*.", footnotes: ["o. für dein Ende\n℘ Kap. 29,11; Sach 9,12", "w. ist der Ausspruch des HERRN", "℘ Kap. 29,14; Hes 37,21"] },
      { number: 18, text: "Deutlich habe ich Ephraim wehklagen hören: Du hast mich gezüchtigt, und ich wurde gezüchtigt wie ein nicht ans Joch gewöhntes Kalb*. Lass mich umkehren, dass ich umkehre*, denn du, HERR, bist mein Gott*.", footnotes: ["℘ Hos 4,16", "℘ Kap. 17,14; Kla 5,21", "℘ Ps 31,15"] },
      { number: 19, text: "Denn nach meiner Umkehr empfinde ich Reue, und nachdem ich zur Erkenntnis gelangt bin, schlage ich mir auf die Hüften*. Ich schäme mich und bin auch zuschanden geworden, denn ich trage die Schmach meiner Jugend*. —", footnotes: ["℘ Hes 21,17", "℘ Hi 13,26"] },
      { number: 20, text: "Ist mir Ephraim ein teurer Sohn oder ein Kind, an dem ich Freude habe*? Denn sooft ich auch gegen ihn geredet habe, muss ich doch immer wieder an ihn denken. Darum ist mein Innerstes um ihn erregt*. Ich muss mich über ihn erbarmen*, spricht der HERR*.", footnotes: ["w. ein Kind der Wonne", "℘ Lk 15,20", "℘ Kap. 33,26; 3Mo 26,44; Ri 10,16; Jes 30,18; 63,15; Kla 3,22.32; Hos 11,8", "w. ist der Ausspruch des HERRN"] },
      { number: 21, text: "Richte dir Wegweiser* auf, setze dir Wegzeichen, richte dein Herz auf die Straße, auf den Weg, den du gegangen bist*! Kehre um, Jungfrau Israel, kehre um* in diese deine Städte!", footnotes: ["w. Steinmale", "℘ Kap. 6,16", "℘ Kap. 3,12.22"] },
      { number: 22, text: "Wie lange willst du dich hin und her wenden, du abtrünnige Tochter*? Denn der HERR hat ein Neues geschaffen* auf der Erde: Die Frau wird den Mann umgeben*!*", footnotes: ["℘ Kap. 2,18.23.36", "Hier steht ein Wort, das ausschließlich für das Schaffen Gottes verwendet wird.", "Andere üs.: Die Frau kehrt zum Mann um. — Viell. ein Hinweis auf den neuen Ehebund, den Gott mit seinem Volk schließen will.", "℘ Kap. 3,1.4"] },
      { number: 23, text: "So spricht der HERR der Heerscharen, der Gott Israels: Dieses Wort wird man wieder sprechen im Land Juda und in seinen Städten, wenn ich ihr Geschick wende*: Der HERR segne dich*, du Weide der Gerechtigkeit*, du heiliger Berg*!", footnotes: ["℘ Kap. 29,14", "℘ Rt 2,4", "℘ Kap. 23,6; 50,7; Jes 1,26", "℘ Jes 11,9; Ob 17"] },
      { number: 24, text: "Und Juda und alle seine Städte werden miteinander darin wohnen, Bauern und die, die mit der Herde umherziehen*.", footnotes: ["so mit 2 griech. Handschr., der aram. und lat. Üs.; Mas. T.: und sie werden mit ihrer Herde umherziehen\n℘ Kap. 33,12.13"] },
      { number: 25, text: "Denn ich habe die erschöpfte Seele reichlich getränkt und jede schmachtende Seele gefüllt*.", footnotes: ["℘ Ps 23,3; 107,9; Jes 41,17; Mt 5,6; 11,28"] },
      { number: 26, text: "Darum heißt es: »Ich wachte auf* und sah umher — mein Schlaf war mir köstlich gewesen.«", footnotes: ["℘ Ps 17,15; Sach 4,1"] },
      { number: 27, text: "Siehe, Tage kommen, spricht der HERR*, da säe ich das Haus Israel und das Haus Juda: Samen von Menschen* und Samen von Vieh.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 107,41; Hes 36,10.11"] },
      { number: 28, text: "Und es wird geschehen, wie ich über sie gewacht habe, um auszureißen, abzubrechen, niederzureißen, zugrunde zu richten und zu vernichten, ebenso werde ich über sie wachen, um zu bauen und zu pflanzen*, spricht der HERR*.", footnotes: ["℘ Kap. 1,10; 24,6; 32,42; 42,10; Sach 8,14.15", "w. ist der Ausspruch des HERRN"] },
      { number: 29, text: "In jenen Tagen wird man nicht mehr sagen: Die Väter haben unreife Trauben gegessen, und die Zähne der Söhne sind stumpf geworden*;", footnotes: ["℘ Hes 18,2"] },
      { number: 30, text: "sondern jeder wird wegen seiner Schuld sterben*: Jeder Mensch, der unreife Trauben isst, dessen Zähne sollen stumpf werden.", footnotes: ["℘ 5Mo 24,16"] },
      { number: 31, text: "*Siehe, Tage kommen, spricht der HERR*, da schließe ich mit dem Haus Israel und mit dem Haus Juda einen neuen Bund*:", heading: "Verheißung eines neuen Bundes", footnotes: ["℘ V. 31-34: Hebr 8,8-12; 10,16-18", "w. ist der Ausspruch des HERRN", "℘ Kap. 32,40; Hes 37,26; Mt 26,28; Röm 9,4"] },
      { number: 32, text: "nicht wie der Bund, den ich mit ihren Vätern geschlossen habe* an dem Tag, als ich sie bei der Hand fasste, um sie aus dem Land Ägypten herauszuführen* — diesen meinen Bund haben sie gebrochen*, obwohl ich doch ihr Herr* war*, spricht der HERR*.", footnotes: ["℘ 2Mo 24,8", "℘ 5Mo 29,24", "℘ Kap. 11,3-10; 2Mo 32,8; 3Mo 26,15; 5Mo 31,16.20; Ps 78,37", "w. Eheherr", "℘ Kap. 3,14; Hes 16,8", "w. ist der Ausspruch des HERRN"] },
      { number: 33, text: "Sondern das ist der Bund, den ich mit dem Haus Israel nach jenen Tagen schließen werde, spricht der HERR*: Ich werde mein Gesetz in ihr Inneres legen und werde es auf ihr Herz schreiben*. Und ich werde ihr Gott sein, und sie werden mein Volk sein*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 17,1; Ps 40,9; Spr 7,3; Hes 11,19", "℘ Kap. 24,7; 2Mo 6,7; Sach 13,9"] },
      { number: 34, text: "Dann wird nicht mehr einer seinen Nächsten oder einer seinen Bruder lehren und sagen: Erkennt den HERRN*! Denn sie alle werden mich erkennen von ihrem Kleinsten bis zu ihrem Größten*, spricht der HERR*. Denn ich werde ihre Schuld vergeben und an ihre Sünde nicht mehr denken*.", footnotes: ["℘ Kap. 9,23", "℘ Jes 11,9; 29,24; 52,6; 54,13; 1Jo 5,20", "w. ist der Ausspruch des HERRN", "℘ Kap. 50,20; Ps 25,7; Mi 7,19; Lk 1,77; Röm 11,27"] },
      { number: 35, text: "So spricht der HERR, der die Sonne gesetzt hat zum Licht für den Tag, die Ordnungen des Mondes und der Sterne zum Licht für die Nacht*, der das Meer erregt, dass seine Wogen brausen*, HERR der Heerscharen ist sein Name*:", footnotes: ["℘ Kap. 33,20; 1Mo 1,16; Ps 136,9", "℘ Kap. 5,22; Hi 26,12", "℘ Kap. 10,16"] },
      { number: 36, text: "Wenn diese Ordnungen vor meinem Angesicht weichen*, spricht der HERR*, dann soll auch die Nachkommenschaft Israels aufhören, eine Nation zu sein vor meinem Angesicht alle Tage*.", footnotes: ["℘ Ps 148,6", "w. ist der Ausspruch des HERRN", "℘ Kap. 33,24-26; Jes 54,9.10; Röm 11,1"] },
      { number: 37, text: "So spricht der HERR: Wenn der Himmel oben gemessen werden kann und die Grundfesten der Erde unten erforscht werden können, dann will ich auch die ganze Nachkommenschaft Israels verwerfen wegen all dessen, was sie getan haben*, spricht der HERR*.", footnotes: ["℘ Kap. 33,24-26; Jes 54,9.10; Röm 11,1", "w. ist der Ausspruch des HERRN"] },
      { number: 38, text: "Siehe, Tage kommen, spricht der HERR*, da diese Stadt für den HERRN wieder gebaut werden wird*, vom Turm Hananel* bis zum Ecktor*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 102,17", "℘ Neh 3,1", "℘ 2Kö 14,13; 2Chr 26,9"] },
      { number: 39, text: "Und die Messschnur* wird weiter fortlaufen geradeaus über den Hügel Gareb und sich nach Goa wenden.", footnotes: ["℘ Sach 2,5.6"] },
      { number: 40, text: "Und das ganze Tal der Leichen* und der Fettasche* und alle Terrassengärten bis zum Bach* Kidron, bis zur Ecke des Rosstors* nach Osten zu, wird für den HERRN heilig sein*. Die Stadt soll nicht mehr niedergerissen* noch zerstört werden in Ewigkeit*.", footnotes: ["℘ Kap. 7,32", "d. i. Asche, die sich auf dem Altar aus verbranntem Holz und Fett bildet", "o. Tal", "℘ Neh 3,28", "℘ Joe 4,17; Sach 14,11", "o. vertrieben; w. ausgerissen", "d. h. für alle Zeiten\n℘ Ps 48,9"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "*Das Wort, das von dem HERRN zu Jeremia geschah im zehnten Jahr Zedekias, des Königs von Juda*; dieses Jahr war das achtzehnte Jahr Nebukadnezars*.", heading: "Jeremias Kauf eines Feldes", footnotes: ["℘ V. 1-5: Kap. 34,1-6", "℘ Kap. 27,1", "℘ Kap. 52,29"] },
      { number: 2, text: "Das Heer des Königs von Babel belagerte damals Jerusalem*. Der Prophet Jeremia aber wurde im Wachhof gefangen gehalten*, der im Haus des Königs von Juda ist.", footnotes: ["℘ 2Kö 25,1.2", "℘ Kap. 33,1; 37,15.21; 38,13.28; Neh 3,25"] },
      { number: 3, text: "Denn Zedekia, der König von Juda, hielt ihn gefangen und hatte gesagt: »Warum weissagst du: So spricht der HERR: Siehe, ich gebe diese Stadt in die Hand des Königs von Babel, dass er sie einnimmt*.", footnotes: ["℘ V. 28; Kap. 26,9; 36,29; 38,3"] },
      { number: 4, text: "Und Zedekia, der König von Juda, wird der Hand der Chaldäer nicht entrinnen, sondern ganz bestimmt in die Hand des Königs von Babel gegeben werden*. Und sein Mund wird mit dessen Mund reden, und seine Augen werden dessen Augen sehen.", footnotes: ["℘ Kap. 21,7; 25,35; 38,18.23; Hes 17,15"] },
      { number: 5, text: "Und er wird Zedekia nach Babel führen*, und dort wird er sein, bis ich mich seiner annehme*, spricht der HERR*. Wenn ihr mit den Chaldäern kämpft, werdet ihr keinen Erfolg haben*.«", footnotes: ["℘ Kap. 39,4-7", "o. bis ich ihn heimsuche; vgl. Hes 12,13", "w. ist der Ausspruch des HERRN", "℘ Kap. 21,4.5; 33,5"] },
      { number: 6, text: "Und Jeremia sprach: Das Wort des HERRN geschah zu mir:" },
      { number: 7, text: "Siehe, Hanamel, der Sohn des Schallum, deines Onkels, wird zu dir kommen und sagen: Kauf dir meinen Acker, der in Anatot* liegt! Denn du hast das Lösungsrecht*, um ihn zu kaufen*.", footnotes: ["℘ Kap. 1,1", "o. das Rückkaufsrecht", "℘ 3Mo 25,24-31"] },
      { number: 8, text: "Und Hanamel, der Sohn meines Onkels, kam zu mir nach dem Wort des HERRN in den Wachhof und sagte zu mir: Kauf doch meinen Acker, der in Anatot im Land Benjamin liegt! Denn du hast das Erbrecht*, und du hast das Lösungsrecht*. Kauf ihn dir! Da erkannte ich, dass es das Wort des HERRN war*.", footnotes: ["w. das Eigentumsrecht", "o. das Rückkaufsrecht", "℘ Sach 11,11"] },
      { number: 9, text: "Und ich kaufte von Hanamel, dem Sohn meines Onkels, den Acker, der in Anatot liegt, und wog ihm das Geld dar: siebzehn Schekel Silber." },
      { number: 10, text: "Und ich schrieb einen Kaufbrief* und versiegelte ihn und nahm Zeugen*, und ich wog das Geld auf der Waage dar*.", footnotes: ["w. schrieb in den Brief", "℘ V. 44; Rt 4,11", "℘ 1Mo 23,16"] },
      { number: 11, text: "Dann nahm ich den Kaufbrief, den versiegelten, die Festsetzung und die Bestimmungen und auch den offenen*.", footnotes: ["D. i. eine Abschrift der Urkunde, die unversiegelt war, damit in Zweifelsfällen die Übereinstimmung mit dem Original festgestellt werden konnte."] },
      { number: 12, text: "Und ich gab den Kaufbrief Baruch*, dem Sohn Nerijas*, des Sohnes Machsejas, vor den Augen meines Vetters* Hanamel und vor den Augen der Zeugen, die den Kaufbrief unterschrieben hatten, vor den Augen aller Judäer, die im Wachhof saßen.", footnotes: ["℘ Kap. 36,4; 43,3; 45,1", "℘ Kap. 51,59", "so mit mehreren hebr. Handschr., der griech. und syr. Üs.; Mas. T.: meines Onkels"] },
      { number: 13, text: "Und ich befahl Baruch vor ihren Augen:" },
      { number: 14, text: "So spricht der HERR der Heerscharen, der Gott Israels: Nimm diese Briefe, diesen Kaufbrief, sowohl den versiegelten als auch diesen offenen Brief, und lege sie in ein Tongefäß, damit sie viele Tage erhalten bleiben!" },
      { number: 15, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Es werden wieder Häuser, Felder und Weinberge in diesem Land gekauft werden*.", footnotes: ["℘ V. 43.44"] },
      { number: 16, text: "Und nachdem ich Baruch, dem Sohn des Nerija, den Kaufbrief gegeben hatte, betete ich zum HERRN:" },
      { number: 17, text: "Ach, Herr, HERR! Siehe, du hast den Himmel und die Erde gemacht durch deine große Kraft und durch deinen ausgestreckten Arm*, kein Ding ist dir unmöglich*;", footnotes: ["℘ Kap. 10,12; 27,5; 2Kö 19,15; Neh 9,6; Jes 40,28", "w. zu wunderbar\n℘ V. 27; 1Mo 18,14; Hi 42,2; Mt 19,26"] },
      { number: 18, text: "der du Gnade übst an Tausenden und die Schuld der Väter vergiltst in den Schoß ihrer Kinder nach ihnen*; du großer, mächtiger Gott*, dessen Name Jahwe der Heerscharen ist*,", footnotes: ["℘ 2Mo 20,5.6", "℘ 5Mo 10,17; Ps 89,9", "℘ Kap. 10,16; 33,2"] },
      { number: 19, text: "groß an Rat* und mächtig an Tat*; du, dessen Augen über alle Wege der Menschenkinder offen sind*, um jedem nach seinen Wegen und nach der Frucht seiner Taten zu geben*;", footnotes: ["℘ Jes 28,29", "℘ Ps 92,6; 111,2", "℘ Kap. 16,17; 2Chr 16,9; Ps 33,14; Sach 9,1", "℘ Kap. 17,10; 25,14; Jes 59,18"] },
      { number: 20, text: "der du Zeichen und Wunder* getan hast im Land Ägypten* bis auf diesen Tag*, sowohl an Israel als auch an anderen Menschen, und dir einen Namen gemacht hast, wie es an diesem Tag ist*.", footnotes: ["o. Wahrzeichen", "℘ 2Mo 3,20; 5Mo 11,3; 2Sam 7,23; Jes 63,12-14", "℘ Dan 6,28", "℘ Neh 9,10.11"] },
      { number: 21, text: "Und du hast dein Volk Israel aus dem Land Ägypten* herausgeführt mit Zeichen und mit Wundern* und mit starker Hand und mit ausgestrecktem Arm und mit großem Schrecken*", footnotes: ["℘ 2Mo 3,20; 5Mo 11,3; 2Sam 7,23; Jes 63,12-14", "o. Wahrzeichen", "℘ 5Mo 4,34"] },
      { number: 22, text: "und hast ihnen dieses Land gegeben, das du ihren Vätern zugeschworen hattest, ihnen zu geben*, ein Land, das von Milch und Honig überfließt*.", footnotes: ["℘ 1Mo 15,18; 5Mo 1,8.35", "℘ Kap. 11,5"] },
      { number: 23, text: "Und sie sind hineingekommen und haben es in Besitz genommen*. Aber sie hörten nicht auf deine Stimme, und in deinem Gesetz lebten* sie nicht: sie haben nichts getan von allem, was du ihnen zu tun geboten hattest*. Da hast du ihnen all dieses Unheil widerfahren lassen*.", footnotes: ["℘ Jos 21,43", "w. gingen", "℘ Kap. 7,24-26; Neh 9,26", "℘ Kap. 11,8; Jos 23,16"] },
      { number: 24, text: "Siehe, die Wälle reichen schon bis an die Stadt, sie einzunehmen*. Und durch das Schwert, durch den Hunger, durch die Pest* ist die Stadt in die Hand der Chaldäer gegeben, die gegen sie kämpfen*. Und was du geredet hast, ist geschehen*; und siehe, du siehst es.", footnotes: ["℘ Kap. 6,6; 33,4; Hes 4,2; 21,27; Hab 1,10", "℘ V. 36", "℘ Kap. 24,10; 34,17", "℘ Sach 1,6"] },
      { number: 25, text: "Und da sagst du zu mir, Herr, HERR: Kauf dir den Acker für Geld und nimm Zeugen*, wo doch die Stadt in die Hand der Chaldäer gegeben ist*!", footnotes: ["℘ V. 15.43.44", "℘ Kap. 24,10; 34,17"] },
      { number: 26, text: "Da geschah das Wort des HERRN zu Jeremia:" },
      { number: 27, text: "Siehe, ich bin der HERR, der Gott alles Fleisches*! Sollte mir irgendein Ding unmöglich* sein*?", footnotes: ["℘ 4Mo 16,22", "w. zu wunderbar", "℘ V. 17; 4Mo 11,23"] },
      { number: 28, text: "Darum, so spricht der HERR: Siehe, ich gebe diese Stadt in die Hand der Chaldäer und in die Hand Nebukadnezars, des Königs von Babel, dass er sie einnimmt*.", footnotes: ["℘ V. 3"] },
      { number: 29, text: "Und die Chaldäer, die gegen diese Stadt kämpfen, werden hineinkommen und diese Stadt in Brand stecken und sie niederbrennen* samt den Häusern, auf deren Dächern sie dem Baal Rauchopfer dargebracht und andern Göttern Trankopfer gespendet haben, um mich zu reizen*.", footnotes: ["℘ Kap. 21,10; 37,8.10; 52,12.13; 2Chr 36,19; Hes 23,47", "℘ Kap. 7,17.18; Jes 22,1"] },
      { number: 30, text: "Denn die Söhne Israel und die Söhne Juda taten von ihrer Jugend an nur, was in meinen Augen böse ist. Denn die Söhne Israel haben mich durch das Werk ihrer Hände immer nur gereizt*, spricht der HERR*.", footnotes: ["℘ Kap. 25,6; 44,8; Hes 20,28", "w. ist der Ausspruch des HERRN"] },
      { number: 31, text: "Denn Anlass zu meinem Zorn und zu meinem Grimm ist mir diese Stadt gewesen von dem Tag an, als man sie gebaut hat, bis auf diesen Tag, so dass ich sie von meinem Angesicht entfernen muss*", footnotes: ["℘ Kap. 23,39"] },
      { number: 32, text: "wegen all der Bosheit der Söhne Israel und der Söhne Juda, die sie verübt haben, um mich zu reizen*, sie, ihre Könige, ihre Obersten, ihre Priester und ihre Propheten und die Männer von Juda und die Bewohner von Jerusalem*.", footnotes: ["℘ Kap. 7,17.18; Jes 22,1", "℘ Dan 9,6.8"] },
      { number: 33, text: "Und sie haben mir den Rücken zugekehrt und nicht das Gesicht*. Und obwohl ich sie lehrte, früh mich aufmachend und lehrend, so hörten sie doch nicht und nahmen keine Zucht an*.", footnotes: ["℘ Kap. 2,27", "℘ Kap. 7,13.24-28; 35,13"] },
      { number: 34, text: "Und in das Haus, über dem mein Name ausgerufen ist, haben sie ihre Scheusale gesetzt, um es unrein zu machen*.", footnotes: ["℘ Kap. 7,30.31; 30,14; 2Kö 21,4; 2Chr 36,14"] },
      { number: 35, text: "Und sie haben die Höhen des Baal gebaut, die im Tal Ben-Hinnom stehen, um ihre Söhne und ihre Töchter für den Moloch* durch das Feuer gehen zu lassen* — was ich nicht geboten habe und mir nicht in den Sinn gekommen ist*, dass sie solche Gräuel verüben sollten —, um so Juda zur Sünde zu verleiten.", footnotes: ["hebr. molech", "℘ 1Kö 11,7", "℘ Kap. 7,30.31; 30,14; 2Kö 21,4; 2Chr 36,14"] },
      { number: 36, text: "Nun aber — darum spricht der HERR, der Gott Israels, jetzt so über diese Stadt, von der ihr sagt: Sie ist in die Hand des Königs von Babel gegeben durch das Schwert, durch den Hunger und durch die Pest*:", footnotes: ["℘ V. 24"] },
      { number: 37, text: "Siehe, ich werde sie aus all den Ländern sammeln, wohin ich sie vertrieben habe in meinem Zorn und in meinem Grimm und in großer Entrüstung*. Und ich werde sie an diesen Ort zurückbringen* und sie in Sicherheit wohnen lassen*.", footnotes: ["w. Wut", "℘ Kap. 16,15; Hes 20,34; 36,24", "℘ Kap. 12,14; 23,3.6.8; Hes 28,26; 39,25"] },
      { number: 38, text: "Und sie werden mein Volk und ich werde ihr Gott sein*.", footnotes: ["℘ Kap. 24,7; Hes 36,28; 2Kor 6,16"] },
      { number: 39, text: "Und ich werde ihnen einerlei Sinn und einerlei Wandel* geben*, damit sie mich alle Tage fürchten, ihnen und ihren Kindern nach ihnen zum Guten*.", footnotes: ["w. ein Herz und einen Weg", "℘ 2Chr 30,12; Jer 24,7; Hes 11,19.20", "℘ 5Mo 6,2.24; Hes 37,24"] },
      { number: 40, text: "Und ich werde einen ewigen Bund mit ihnen schließen*, dass ich mich nicht von ihnen abwende*, ihnen Gutes zu tun. Und ich werde meine Furcht in ihr Herz legen, damit sie nicht von mir abweichen*.", footnotes: ["℘ Kap. 31,31-33; 50,5; Jes 55,3; Hebr 13,20", "w. nicht hinter ihnen weg umkehre", "℘ Ps 80,19; Hes 36,27; Mi 4,5"] },
      { number: 41, text: "Und ich werde meine Freude an ihnen haben, ihnen Gutes zu tun*, und ich werde sie in diesem Land pflanzen* in Treue*, mit meinem ganzen Herzen und mit meiner ganzen Seele*.", footnotes: ["℘ 5Mo 30,9", "℘ Kap. 24,6; Hes 36,36", "o. Wahrheit", "℘ Jes 60,21; 62,4; Hos 14,5"] },
      { number: 42, text: "Denn so spricht der HERR: Ebenso wie ich über dieses Volk all dies große Unheil gebracht habe, so will ich über sie auch all das Gute bringen, das ich über sie rede*.", footnotes: ["℘ Kap. 31,28; 33,14; Jos 23,15"] },
      { number: 43, text: "Und es sollen Felder gekauft werden in diesem Land, von dem ihr sagt: Es ist Ödland, ohne Menschen und ohne Vieh; es ist in die Hand der Chaldäer gegeben*.", footnotes: ["℘ V. 15.25; Kap. 33,10"] },
      { number: 44, text: "Man wird Felder für Geld kaufen und Kaufbriefe schreiben*, sie versiegeln und Zeugen hinzunehmen* im Land Benjamin, in der Umgebung von Jerusalem und in den Städten Judas, sowohl in den Städten des Gebirges als auch in den Städten der Niederung* und in den Städten des Südens*. Denn ich werde ihr Geschick wenden*, spricht der HERR*.", footnotes: ["w. und in den Brief schreiben", "℘ V. 10-12", "hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 17,26; Ob 20", "℘ Kap. 30,18; 33,7.11.26", "w. ist der Ausspruch des HERRN"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Und das Wort des HERRN geschah zum zweiten Mal zu Jeremia, als er noch im Wachhof eingeschlossen war*:", heading: "Verheißung der Wiederherstellung Israels und eines ewigen Bundes mit dem Haus Juda und dem Haus Levi", footnotes: ["℘ Kap. 32,2.3"] },
      { number: 2, text: "So spricht der HERR, der es tut, der HERR, der es bildet, um es festzusetzen*, Jahwe ist sein Name*:", footnotes: ["LXX: So spricht der HERR, der die Erde gemacht und sie gebildet hat, um sie festzusetzen", "℘ Kap. 16,21; 32,18; 2Mo 15,3; Jes 42,8; Am 5,8"] },
      { number: 3, text: "Rufe mich an, dann will ich dir antworten* und will dir Großes und Unfassbares* mitteilen, das du nicht kennst*.", footnotes: ["℘ Kap. 29,12; Ps 91,15", "w. Unzugängliches", "℘ Dan 2,22.23; 1Kor 2,9.10"] },
      { number: 4, text: "Denn so spricht der HERR, der Gott Israels, über die Häuser dieser Stadt und über die Häuser der Könige von Juda, die abgebrochen werden, um im Kampf gegen die Belagerungswälle und zur Abwehr* Verwendung zu finden.", footnotes: ["w. zum Schwert\n℘ Kap. 32,24; Jes 22,10"] },
      { number: 5, text: "Man kommt nur zusammen*, um gegen die Chaldäer zu kämpfen und die Häuser* mit den Leichen der Menschen zu füllen, die ich in meinem Zorn und in meinem Grimm geschlagen und um all deren Bosheit willen ich mein Angesicht vor dieser Stadt verborgen habe*:", footnotes: ["Der Text ist sehr schlecht erhalten. Andere üs. entsprechend Hes 6,10: Gegen die Belagerungswälle wird man umsonst angehen, um gegen die Chaldäer zu kämpfen", "w. sie", "℘ Kap. 32,5; 5Mo 31,18"] },
      { number: 6, text: "Siehe, ich will ihr Genesung und Heilung bringen* und sie heilen*, und ich will ihnen eine Fülle von Frieden* und Treue* offenbaren*.", footnotes: ["w. will ihr über ihre Wunde neues Fleisch und Heilung heraufkommen lassen", "℘ Kap. 30,17; Ps 147,3; Jes 57,18; Mal 3,20", "o. Wohl; o. Heil\n℘ Kap. 29,11", "o. Wahrheit", "℘ Mi 7,20"] },
      { number: 7, text: "Und ich werde das Geschick Judas und das Geschick Israels wenden und werde sie bauen wie im Anfang*.", footnotes: ["℘ V. 26; Kap. 29,14; 30,3.18; Jes 52,8; Am 9,14"] },
      { number: 8, text: "Und ich werde sie reinigen von all ihrer Schuld, mit der sie gegen mich gesündigt haben*. Und ich werde alle ihre Verschuldungen vergeben, mit denen sie gegen mich gesündigt und durch die sie mit mir gebrochen haben*.", footnotes: ["℘ 3Mo 16,30; Hes 36,25", "℘ Kap. 50,20; Ps 130,8"] },
      { number: 9, text: "Und es* soll mir zum Freudennamen sein, zum Ruhm und zum Schmuck bei allen Nationen der Erde*, die all das Gute hören, das ich ihnen tue. Und sie werden zittern und beben* über all das Gute und über all den Frieden, den ich ihm* angedeihen lasse*.", footnotes: ["d. i. Jerusalem", "℘ Kap. 13,11; Jes 43,21; 55,13; 62,2; Zef 3,19.20", "℘ Jes 60,5", "d. i. Jerusalem", "℘ Kap. 31,14; 5Mo 30,5; Sach 1,17"] },
      { number: 10, text: "So spricht der HERR: An diesem Ort, von dem ihr sagt: Er ist verwüstet, ohne Menschen und ohne Vieh!* — in den Städten Judas und auf den Straßen Jerusalems, die öde sind, ohne Menschen und ohne Bewohner und ohne Vieh, dort wird wieder gehört werden", footnotes: ["℘ Kap. 32,43"] },
      { number: 11, text: "die Stimme der Wonne und die Stimme der Freude, die Stimme des Bräutigams und die Stimme der Braut*, die Stimme derer, die sagen: Preist den HERRN der Heerscharen, denn gütig ist der HERR, ewig währt seine Gnade*! — die Stimme derer, die Lob in das Haus des HERRN bringen*. Denn ich werde das Geschick des Landes wenden* wie im Anfang*, spricht der HERR.", footnotes: ["℘ Kap. 7,34; Ps 147,13; Jes 51,3", "℘ 1Chr 16,34; Ps 100,5", "℘ Kap. 17,26; 31,13; Ps 85,7", "℘ Kap. 32,44", "℘ V. 26; Kap. 29,14; 30,3.18; Jes 52,8; Am 9,14"] },
      { number: 12, text: "So spricht der HERR der Heerscharen: An diesem Ort, der verwüstet ist, ohne Menschen und ohne Vieh, und in allen seinen Städten wird wieder eine Weide für die Hirten sein, die ihre Herde* lagern lassen*.", footnotes: ["w. Schafe", "℘ Kap. 31,24; 50,19; Jes 65,10; Hes 34,13; 36,35"] },
      { number: 13, text: "In den Städten des Gebirges, in den Städten der Niederung* und in den Städten des Südens und im Land Benjamin und in der Umgebung von Jerusalem und in den Städten Judas* werden wieder die Herden unter den Händen des Hirten, der sie zählt, vorüberziehen*, spricht der HERR!", footnotes: ["hebr. Schefelah; d. i. der Küstenstreifen zwischen Jafo und Gaza", "℘ Kap. 17,26", "℘ 3Mo 27,32"] },
      { number: 14, text: "Siehe, Tage kommen, spricht der HERR, da erfülle ich das gute Wort, das ich über das Haus Israel und über das Haus Juda geredet habe*.", footnotes: ["℘ Kap. 29,10; 32,42"] },
      { number: 15, text: "In diesen Tagen und zu dieser Zeit werde ich dem David einen Spross der Gerechtigkeit* hervorsprossen lassen*, der wird Recht und Gerechtigkeit üben im Land*.", footnotes: ["viell.: einen rechtmäßigen Nachkommen", "℘ Lk 20,41", "℘ Kap. 23,5.6; 50,7; Mk 11,10"] },
      { number: 16, text: "In jenen Tagen wird Juda gerettet, und Jerusalem wird in Sicherheit wohnen. Und das wird sein Name sein, mit dem man es benennt: »Der HERR, unsere Gerechtigkeit«*.", footnotes: ["℘ Kap. 23,5.6; 50,7; Mk 11,10"] },
      { number: 17, text: "Denn so spricht der HERR: Nie soll es dem David an einem Mann fehlen*, der auf dem Thron des Hauses Israel sitzt*.", footnotes: ["w. Nicht wird dem David (bzw. den Priestern, den Leviten) ausgerottet ein Mann", "℘ 2Sam 7,12-16; 2Kö 11,2; Ps 132,12"] },
      { number: 18, text: "Und den Priestern, den Leviten, soll es nie an einem Mann vor mir fehlen*, der Brandopfer opfert und Speisopfer in Rauch aufgehen lässt und Schlachtopfer zurichtet, alle Tage*.", footnotes: ["w. Nicht wird dem David (bzw. den Priestern, den Leviten) ausgerottet ein Mann", "℘ Kap. 35,19; Jes 61,6; Hes 43,19"] },
      { number: 19, text: "Und das Wort des HERRN geschah zu Jeremia:" },
      { number: 20, text: "So spricht der HERR: Wenn ihr jemals meinen Bund mit dem Tag und meinen Bund mit der Nacht brechen könnt, so dass Tag und Nacht nicht mehr zu ihrer Zeit sind*,", footnotes: ["℘ Kap. 31,35"] },
      { number: 21, text: "dann kann auch mein Bund mit meinem Knecht David gebrochen werden, dass er keinen Sohn hat, der auf seinem Thron König ist*, und auch mein Bund mit den Leviten, den Priestern, meinen Dienern.", footnotes: ["℘ 2Sam 23,5; Ps 89,36.37; Jes 66,22"] },
      { number: 22, text: "Wie das Heer des Himmels nicht gezählt und der Sand des Meeres nicht gemessen werden kann, ebenso werde ich die Nachkommen meines Knechtes David und die Leviten zahlreich machen, die mir dienen*.", footnotes: ["℘ 1Mo 15,5"] },
      { number: 23, text: "Und das Wort des HERRN geschah zu Jeremia:" },
      { number: 24, text: "Hast du nicht gesehen, was dieses Volk redet, indem es sagt: Die beiden Geschlechter*, die der HERR erwählt hatte, die hat er verworfen!* — und wie sie mein Volk schmähen, dass es vor ihnen keine Nation mehr sei?*", footnotes: ["d. h. Israel und Juda", "℘ Kap. 31,37", "℘ Ps 83,5; Hes 36,20"] },
      { number: 25, text: "So spricht der HERR: Wenn mein Bund mit dem Tag und der Nacht nicht mehr besteht, wenn ich die Ordnungen des Himmels und der Erde nicht festgesetzt habe*,", footnotes: ["℘ 1Mo 8,22; Ps 74,16"] },
      { number: 26, text: "dann werde ich auch die Nachkommen Jakobs und meines Knechtes David verwerfen*, dass ich nicht mehr von seinen Nachkommen Herrscher nehme über die Nachkommen Abrahams, Isaaks und Jakobs*. Denn ich werde ihr Geschick wenden* und mich über sie erbarmen*.", footnotes: ["℘ Kap. 31,35-37", "℘ 1Mo 49,10", "℘ V. 7.11", "℘ Kap. 31,20; Ps 126,1"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "*Das Wort, das durch den HERRN zu Jeremia geschah, als Nebukadnezar, der König von Babel, und sein ganzes Heer und alle Königreiche der Erde, die unter der Herrschaft seiner Hand waren, und alle Völker gegen Jerusalem und gegen alle seine Städte kämpften*:", heading: "Ankündigung des Schicksals des Königs Zedekia", footnotes: ["℘ Kap. 32,1-5", "℘ Kap. 1,15; 21,2; 39,1; 2Kö 25,1"] },
      { number: 2, text: "So spricht der HERR, der Gott Israels: Geh hin und sprich zu Zedekia, dem König von Juda, und sage ihm: So spricht der HERR: Siehe, ich gebe diese Stadt in die Hand des Königs von Babel, dass er sie mit Feuer verbrennt*!", footnotes: ["℘ V. 22; Kap. 21,10; 2Kö 25,9"] },
      { number: 3, text: "Und du, du wirst seiner Hand nicht entrinnen, sondern ganz bestimmt ergriffen und in seine Hand gegeben werden. Deine Augen werden die Augen des Königs von Babel sehen, und sein Mund wird mit deinem Mund reden, und du wirst nach Babel kommen*.", footnotes: ["℘ Kap. 38,18; 52,11; Hes 17,16"] },
      { number: 4, text: "Doch höre das Wort des HERRN, Zedekia, König von Juda! So spricht der HERR über dich: Du wirst nicht durch das Schwert sterben!*", footnotes: ["Andere üs.: Doch, so spricht der HERR über dich: Gehorche dem Wort des HERRN, Zedekia, König von Juda, dann wirst du nicht durchs Schwert sterben."] },
      { number: 5, text: "In Frieden wirst du sterben, und wie deinen Vätern, den früheren Königen, die vor dir gewesen sind, Totenfeuer* angezündet wurden, so wird man auch dir ein Totenfeuer anzünden*, und man wird über dich klagen: »Ach, Herr!« Denn ich habe das Wort geredet, spricht der HERR*.", footnotes: ["d. i. zur Verbrennung von Spezereien zu Ehren der toten Väter", "℘ 1Sam 31,12; 2Chr 16,14", "w. ist der Ausspruch des HERRN\n℘ Kap. 22,18"] },
      { number: 6, text: "Der Prophet Jeremia aber redete zu Zedekia, dem König von Juda, alle diese Worte in Jerusalem*,", footnotes: ["℘ Kap. 1,6-10"] },
      { number: 7, text: "während das Heer des Königs von Babel gegen Jerusalem und gegen alle übrig gebliebenen Städte Judas kämpfte, gegen Lachisch* und gegen Aseka; denn diese waren als befestigte Städte unter den Städten Judas übrig geblieben*.", footnotes: ["℘ Mi 1,13", "℘ 2Chr 11,5.9"] },
      { number: 8, text: "Das Wort, das von dem HERRN zu Jeremia geschah, nachdem der König Zedekia einen Bund mit dem ganzen Volk, das in Jerusalem lebte, geschlossen hatte, ihnen eine Freilassung auszurufen,", heading: "Treuebruch an den freigelassenen Sklaven in Jerusalem und Gerichtsankündigung" },
      { number: 9, text: "dass jeder seinen Sklaven und ein jeder seine Sklavin, und zwar Hebräer und Hebräerin, als Freie entlassen sollte, so dass niemand mehr seinen judäischen Volksgenossen* jemals als Sklaven hielt.", footnotes: ["w. so dass niemand sie, nämlich einen Judäer, seinen Bruder,"] },
      { number: 10, text: "Und es hörten alle Obersten und das ganze Volk, das den Bund eingegangen war, dass jeder seinen Sklaven und jeder seine Sklavin als Freie entlassen sollte, ohne sie länger als Sklaven zu halten. Sie gehorchten und entließen sie*.", footnotes: ["℘ 2Mo 21,2-4; 3Mo 25,10.41; Jak 2,6"] },
      { number: 11, text: "Aber sie wandten sich um und holten die Sklaven und Sklavinnen zurück, die sie als Freie entlassen hatten, und unterjochten sie wieder zu Sklaven und Sklavinnen*.", footnotes: ["℘ Mt 21,30"] },
      { number: 12, text: "Da geschah das Wort des HERRN von dem HERRN zu Jeremia:" },
      { number: 13, text: "So spricht der HERR, der Gott Israels: Ich habe einen Bund mit euren Vätern geschlossen an dem Tag, als ich sie aus dem Land Ägypten, aus dem Sklavenhaus, herausführte*, und habe gesprochen:", footnotes: ["℘ 2Mo 13,3.14; 5Mo 5,2"] },
      { number: 14, text: "Am Ende von sieben Jahren* sollt ihr jeder seinen hebräischen Bruder entlassen*, der sich dir verkauft hat; er soll sechs Jahre dein Sklave sein, dann sollst du ihn als Freien von dir entlassen*. Aber eure Väter hörten nicht auf mich und neigten ihr Ohr nicht zu mir*.", footnotes: ["d. h. alle sieben Jahre", "℘ 2Mo 21,2-4; 3Mo 25,10.41; Jak 2,6", "℘ 5Mo 15,1.9", "℘ Kap. 11,7.8"] },
      { number: 15, text: "Da seid ihr heute umgekehrt und habt getan, was in meinen Augen recht ist, dass jeder für seinen Nächsten Freilassung ausrief, und habt einen Bund vor mir geschlossen* in dem Haus, über dem mein Name ausgerufen ist*.", footnotes: ["℘ 2Kö 23,3", "℘ Kap. 7,10.30"] },
      { number: 16, text: "Dann aber habt ihr euch wieder umgewandt* und meinen Namen entweiht* und habt jeder seinen Sklaven und jeder seine Sklavin zurückgeholt, die ihr auf ihren Wunsch* als Freie entlassen hattet. Und ihr habt sie wieder unterjocht, dass sie Sklaven und Sklavinnen für euch sein sollen.", footnotes: ["℘ Mt 21,30", "℘ 3Mo 19,12", "d. h., dass sie gehen, wohin sie wollen, o. dass sie freie Verfügung über sich selbst haben; w. für ihr Leben, o. für ihre Seele"] },
      { number: 17, text: "Darum, so spricht der HERR: Ihr habt nicht auf mich gehört, eine Freilassung auszurufen, jeder für seinen Bruder und für seinen Nächsten. Siehe, so rufe ich für euch eine Freilassung aus, spricht der HERR*, für das Schwert, für die Pest und für den Hunger* und mache euch zum Entsetzen für alle Königreiche der Erde*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 32,24; Mt 7,2", "℘ Kap. 15,4; 29,17.18; 5Mo 28,25"] },
      { number: 18, text: "Und ich will die Männer, die meinen Bund übertreten haben, die die Worte des Bundes nicht gehalten, den sie vor mir geschlossen haben, wie das Kalb machen, das sie entzweigeschnitten und zwischen dessen Stücken sie hindurchgegangen sind*:", footnotes: ["D. i. ein uralter Brauch beim Abschließen von Bündnissen.\n℘ 1Mo 15,8-10.17"] },
      { number: 19, text: "die Obersten von Juda und die Obersten von Jerusalem, die Hofbeamten* und die Priester und das ganze Volk des Landes, die zwischen den Stücken des Kalbes hindurchgegangen sind*;", footnotes: ["w. Eunuchen", "℘ 1Mo 15,8-10.17"] },
      { number: 20, text: "die will ich in die Hand ihrer Feinde geben und in die Hand derer, die nach ihrem Leben trachten*. Und ihre Leichen sollen den Vögeln des Himmels und den Tieren der Erde zum Fraß dienen*.", footnotes: ["℘ Kap. 39,6", "℘ Kap. 7,33"] },
      { number: 21, text: "Zedekia aber, den König von Juda, und seine Obersten werde ich in die Hand ihrer Feinde geben und in die Hand derer, die nach ihrem Leben trachten, und in die Hand des Heeres des Königs von Babel, das von euch abgezogen ist*.", footnotes: ["℘ Kap. 37,5.11; Hes 17,12.16.20"] },
      { number: 22, text: "Siehe, ich gebe Befehl, spricht der HERR*, und bringe sie zu dieser Stadt zurück, damit sie gegen sie kämpfen und sie einnehmen und mit Feuer verbrennen*. Und ich werde die Städte Judas zur Öde machen, ohne einen Bewohner*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ V. 2", "℘ Kap. 2,15; 44,2.6"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "Das Wort, das von dem HERRN zu Jeremia geschah in den Tagen Jojakims, des Sohnes Josias, des Königs von Juda*:", heading: "Die Treue der Rechabiter im Gegensatz zur Untreue Judas", footnotes: ["℘ Kap. 25,1"] },
      { number: 2, text: "Geh zum Haus* der Rechabiter* und rede mit ihnen und bring sie in das Haus des HERRN in eine der Zellen* und gib ihnen Wein zu trinken!", footnotes: ["Das hebr. Wort für »Haus« kann auch »Familie« o. »Gemeinschaft« bedeuten.", "Die Rechabiter waren ein Zweig der Keniter.\n℘ 1Chr 2,55", "d. h. Nebengebäude in den Höfen des Tempels\n℘ 1Kö 6,5; 1Chr 28,12"] },
      { number: 3, text: "Da nahm ich Jaasanja, den Sohn Jirmejas, des Sohnes Habazzinjas, und seine Brüder und alle seine Söhne und das ganze Haus* der Rechabiter", footnotes: ["Das hebr. Wort für »Haus« kann auch »Familie« o. »Gemeinschaft« bedeuten."] },
      { number: 4, text: "und brachte sie in das Haus des HERRN, in die Zelle der Söhne Hanans, des Sohnes Jigdaljas, des Mannes Gottes, neben der Zelle der Obersten, die oberhalb der Zelle Maasejas* war, des Sohnes Schallums, des Hüters der Schwelle*.", footnotes: ["℘ Kap. 21,1", "℘ 1Chr 9,19-27"] },
      { number: 5, text: "Und ich setzte den Söhnen des Hauses* der Rechabiter Krüge, mit Wein gefüllt, und Becher vor und sagte zu ihnen: Trinkt Wein!", footnotes: ["Das hebr. Wort für »Haus« kann auch »Familie« o. »Gemeinschaft« bedeuten."] },
      { number: 6, text: "Sie aber sagten: Wir trinken keinen Wein. Denn Jonadab*, der Sohn Rechabs, unser Vater, hat uns befohlen und gesagt: Ihr sollt keinen Wein trinken, weder ihr noch eure Söhne, für ewig.", footnotes: ["℘ 2Kö 10,15"] },
      { number: 7, text: "Ihr sollt kein Haus bauen und keinen Samen säen und keinen Weinberg pflanzen noch sie besitzen. Sondern in Zelten sollt ihr wohnen* alle eure Tage, damit ihr viele Tage lebt auf dem Erdboden, wo ihr euch als Fremde aufhaltet.", footnotes: ["℘ Hebr 11,9"] },
      { number: 8, text: "Und wir haben der Stimme Jonadabs, des Sohnes Rechabs, unseres Vaters, gehorcht, nach allem, was er uns befohlen hat: keinen Wein zu trinken alle unsere Tage, weder wir noch unsere Frauen, noch unsere Söhne, noch unsere Töchter," },
      { number: 9, text: "und keine Häuser als Wohnung für uns zu bauen. Und wir besitzen weder Weinberg noch Feld noch Samen." },
      { number: 10, text: "So haben wir in Zelten gewohnt und haben gehorcht und getan nach allem, was unser Vater Jonadab uns befohlen hat." },
      { number: 11, text: "Und es geschah, als Nebukadnezar, der König von Babel, gegen dieses Land heraufzog, sagten wir: Kommt und lasst uns nach Jerusalem ziehen vor dem Heer der Chaldäer und vor dem Heer der Aramäer*! So wohnen wir nun in Jerusalem.", footnotes: ["℘ Kap. 25,9; 2Kö 24,2"] },
      { number: 12, text: "Und das Wort des HERRN geschah zu Jeremia:" },
      { number: 13, text: "So spricht der HERR der Heerscharen, der Gott Israels: Geh und sprich zu den Männern von Juda und zu den Bewohnern von Jerusalem: Wollt ihr keine Zucht annehmen, um auf meine Worte zu hören*?, spricht der HERR*.", footnotes: ["℘ Kap. 6,10; 32,33", "w. ist der Ausspruch des HERRN"] },
      { number: 14, text: "Die Worte Jonadabs, des Sohnes Rechabs, die er seinen Kindern befohlen hat, keinen Wein zu trinken, sind gehalten worden, und bis auf diesen Tag trinken sie keinen Wein; denn sie haben dem Gebot ihres Vaters gehorcht. Und ich habe zu euch geredet, früh mich aufmachend und redend; aber ihr habt nicht auf mich gehört*.", footnotes: ["℘ Kap. 7,13"] },
      { number: 15, text: "Und ich habe alle meine Knechte, die Propheten, zu euch gesandt, früh mich aufmachend und sendend, und gesprochen: Kehrt doch um, jeder von seinem bösen Weg und bessert eure Taten und lauft nicht andern Göttern nach, ihnen zu dienen, dann sollt ihr in dem Land wohnen, das ich euch und euren Vätern gegeben habe! Aber ihr habt euer Ohr nicht geneigt und nicht auf mich gehört*.", footnotes: ["℘ Kap. 7,3-7.25.26"] },
      { number: 16, text: "Ja, die Kinder Jonadabs, des Sohnes Rechabs, haben das Gebot ihres Vaters gehalten, das er ihnen geboten hat; aber dieses Volk hat nicht auf mich gehört*.", footnotes: ["℘ Kap. 7,3-7.25.26"] },
      { number: 17, text: "Darum, so spricht der HERR, der Gott der Heerscharen, der Gott Israels: Siehe, ich bringe über Juda und über alle Bewohner von Jerusalem all das Unheil, das ich über sie geredet habe, weil ich zu ihnen geredet, sie aber nicht gehört, und ich ihnen zugerufen, sie aber nicht geantwortet haben*.", footnotes: ["℘ Kap. 11,8-14; Jes 65,12"] },
      { number: 18, text: "Aber zum Haus* der Rechabiter sagte Jeremia: So spricht der HERR der Heerscharen, der Gott Israels: Weil ihr dem Gebot eures Vaters Jonadab gehorcht und alle seine Gebote bewahrt und getan habt nach allem, was er euch befohlen hat,", footnotes: ["Das hebr. Wort für »Haus« kann auch »Familie« o. »Gemeinschaft« bedeuten."] },
      { number: 19, text: "darum, so spricht der HERR der Heerscharen, der Gott Israels: Es soll Jonadab, dem Sohn des Rechab, nicht an einem Mann fehlen*, der vor mir steht, alle Tage*.", footnotes: ["w. Nicht werde dem Jonadab . . . ein Mann ausgerottet", "℘ Kap. 33,17.18; Ps 102,29"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und es geschah im vierten Jahr Jojakims, des Sohnes Josias, des Königs von Juda, da geschah dieses Wort von dem HERRN zu Jeremia*:", heading: "Niederschrift der Reden Jeremias, ihre Verlesung, Verbrennung und erneute Niederschrift", footnotes: ["℘ Kap. 25,1; 45,1"] },
      { number: 2, text: "Nimm dir eine Schriftrolle und schreib darauf all die Worte, die ich zu dir geredet habe* über Israel und über Juda und über alle Nationen*, von dem Tag an, da ich zu dir geredet habe, von den Tagen Josias an bis auf diesen Tag!", footnotes: ["℘ V. 18; Kap. 30,2; 45,1; Jes 30,8; Offb 1,11", "℘ Kap. 25,15-26"] },
      { number: 3, text: "Vielleicht wird das Haus Juda auf all das Unheil hören, das ich ihnen zu tun gedenke, dass sie umkehren, jeder von seinem bösen Weg, und ich ihre Schuld und ihre Sünde vergebe*. —", footnotes: ["℘ Kap. 18,8-11; Apg 3,19; Offb 2,5"] },
      { number: 4, text: "Da rief Jeremia Baruch* herbei, den Sohn des Nerija. Und Baruch schrieb aus dem Mund Jeremias all die Worte des HERRN, die er zu ihm geredet hatte*, auf eine Schriftrolle*.", footnotes: ["℘ Kap. 32,12", "℘ V. 18; Kap. 30,2; 45,1; Jes 30,8; Offb 1,11", "℘ Röm 16,22"] },
      { number: 5, text: "Und Jeremia befahl dem Baruch: Ich bin verhindert, ich kann nicht in das Haus des HERRN gehen." },
      { number: 6, text: "So geh du hin und lies am Tag des Fastens aus der Rolle vor, was du aus meinem Mund geschrieben hast, die Worte des HERRN, vor den Ohren des Volkes im Haus des HERRN am Tag des Fastens. Auch sollst du sie vor den Ohren aller Judäer* lesen, die aus ihren Städten kommen*.", footnotes: ["w. vor den Ohren von ganz Juda", "℘ Kap. 7,2"] },
      { number: 7, text: "Vielleicht fällt ihr Flehen vor dem HERRN nieder, und sie kehren um, jeder von seinem bösen Weg*; denn groß ist der Zorn und der Grimm, den der HERR diesem Volk angesagt hat*.", footnotes: ["℘ Joe 2,12-14", "℘ 2Kö 22,13"] },
      { number: 8, text: "Und Baruch, der Sohn des Nerija, tat nach allem, was der Prophet Jeremia ihm befohlen hatte, indem er aus dem Buch die Worte des HERRN im Haus des HERRN vorlas." },
      { number: 9, text: "Und es geschah im fünften Jahr Jojakims, des Sohnes Josias, des Königs von Juda, im neunten Monat, da rief man zu einem Fasten vor dem HERRN* das ganze Volk in Jerusalem auf und das ganze Volk, das aus den Städten Judas nach Jerusalem kam.", footnotes: ["℘ 2Chr 20,3; Jes 58,1-7; Joe 1,14"] },
      { number: 10, text: "Da las Baruch aus dem Buch die Worte Jeremias vor im Haus des HERRN, in der Zelle Gemarjas, des Sohnes Schafans*, des Schreibers, im oberen Vorhof, im Eingang des neuen Tores am Haus des HERRN vor den Ohren des ganzen Volkes.", footnotes: ["℘ Kap. 26,24; 2Kö 22,3"] },
      { number: 11, text: "Und Michaja, der Sohn Gemarjas, des Sohnes Schafans*, hörte alle Worte des HERRN aus dem Buch,", footnotes: ["℘ Kap. 26,24; 2Kö 22,3"] },
      { number: 12, text: "und er ging zum Haus des Königs hinab in die Zelle des Schreibers. Und siehe, dort saßen alle Obersten*: Elischama, der Schreiber, und Delaja, der Sohn Schemajas, und Elnatan, der Sohn Achbors*, und Gemarja, der Sohn Schafans*, und Zedekia, der Sohn Hananjas, und alle anderen Obersten*.", footnotes: ["d. h. die maßgebenden Männer von Jerusalem\n℘ Kap. 26,10", "℘ Kap. 26,22", "℘ Kap. 26,24; 2Kö 22,3", "d. h. die maßgebenden Männer von Jerusalem\n℘ Kap. 26,24; 2Kö 22,3"] },
      { number: 13, text: "Und Michaja berichtete ihnen all die Worte, die er gehört hatte, als Baruch vor den Ohren des Volkes aus dem Buch vorlas." },
      { number: 14, text: "Da sandten alle Obersten* Jehudi, den Sohn Netanjas, des Sohnes Schelemjas, des Sohnes Kuschis, zu Baruch und ließen ihm sagen: Die Rolle, aus der du vor den Ohren des Volkes vorgelesen hast, nimm sie in deine Hand und komm! Da nahm Baruch, der Sohn Nerijas, die Rolle in seine Hand und kam zu ihnen.", footnotes: ["d. h. die maßgebenden Männer von Jerusalem"] },
      { number: 15, text: "Und sie sagten zu ihm: Setz dich doch und lies sie vor unseren Ohren vor! Da las Baruch vor ihren Ohren vor." },
      { number: 16, text: "Und es geschah, als sie all die Worte gehört hatten, sahen sie einander erschrocken an* und sagten zu Baruch: Wir müssen dem König all diese Worte berichten*.", footnotes: ["℘ Kap. 23,9; 2Kö 22,11", "℘ V. 24"] },
      { number: 17, text: "Und sie fragten Baruch: Teile uns doch mit, wie du all diese Worte aus seinem Mund aufgeschrieben hast!" },
      { number: 18, text: "Da sprach Baruch zu ihnen: Aus seinem Mund sagte er mir all diese Worte vor, und ich schrieb sie mit Tinte in das Buch*.", footnotes: ["℘ V. 4"] },
      { number: 19, text: "Und die Obersten* sagten zu Baruch: Geh, verbirg dich, du und Jeremia, dass niemand erkennt, wo ihr seid*!", footnotes: ["d. h. die maßgebenden Männer von Jerusalem", "℘ Kap. 26,24; Spr 28,12"] },
      { number: 20, text: "Und sie gingen zum König in den Hof*. Die Rolle aber hatten sie in der Zelle des Schreibers Elischama niedergelegt. Und sie berichteten all die Worte vor den Ohren des Königs.", footnotes: ["d. h. in den inneren Hof des königlichen Palastes"] },
      { number: 21, text: "Da sandte der König den Jehudi, die Rolle zu holen. Und er holte sie aus der Zelle des Schreibers Elischama. Und Jehudi las sie vor den Ohren des Königs und vor den Ohren aller Obersten*, die um den König standen*.", footnotes: ["d. h. die maßgebenden Männer von Jerusalem", "℘ 2Kö 22,10"] },
      { number: 22, text: "Der König aber saß im Winterhaus* — es war im neunten Monat* —, und das Feuer im Kohlenbecken war* vor ihm angezündet.", footnotes: ["℘ Am 3,15", "℘ Esr 10,9", "So lesen LXX, die syr. und aram. Üs.; Mas. T.: das Kohlenbecken war"] },
      { number: 23, text: "Und es geschah, sooft Jehudi drei oder vier Spalten vorgelesen hatte, zerschnitt sie der König* mit dem Schreibermesser und warf sie in das Feuer, das auf dem Kohlenbecken war, bis die ganze Rolle im Feuer auf dem Kohlenbecken vernichtet war*.", footnotes: ["w. er", "℘ Ps 50,17"] },
      { number: 24, text: "Aber der König und alle seine Knechte, die all diese Worte hörten, erschraken nicht* und zerrissen ihre Kleider nicht*.", footnotes: ["℘ V. 16; Ps 36,2", "℘ 2Mo 7,23; 1Kö 21,27; 2Kö 22,11"] },
      { number: 25, text: "Und obwohl Elnatan, Delaja und Gemarja in den König drangen, dass er die Rolle nicht verbrennen solle, hörte er nicht auf sie." },
      { number: 26, text: "Und der König befahl Jerachmeel, dem Königssohn*, und Seraja, dem Sohn des Asriël, und Schelemja, dem Sohn des Abdeel, den Schreiber Baruch und den Propheten Jeremia festzunehmen*. Aber der HERR hatte sie verborgen*.", footnotes: ["d. h. einem Prinzen aus dem königlichen Geschlecht\n℘ Kap. 38,6; 1Kö 22,26; 2Kö 11,2", "℘ 2Chr 18,26", "℘ Kap. 26,24; Ps 105,15"] },
      { number: 27, text: "Und das Wort des HERRN geschah zu Jeremia, nachdem der König die Rolle und die Worte, die Baruch aus dem Mund Jeremias aufgeschrieben, verbrannt hatte:" },
      { number: 28, text: "Nimm dir noch einmal eine Rolle, eine andere, und schreibe darauf all die vorigen Worte, die auf der vorigen Rolle waren, die Jojakim, der König von Juda, verbrannt hat." },
      { number: 29, text: "Und über Jojakim, den König von Juda, sollst du sagen: So spricht der HERR: Du hast diese Rolle verbrannt und gesagt: Warum hast du darauf geschrieben: Der König von Babel wird ganz bestimmt kommen und dieses Land zerstören und aus ihm Menschen und Vieh verschwinden lassen*?", footnotes: ["℘ Kap. 21,7; 32,3"] },
      { number: 30, text: "Darum, so spricht der HERR über Jojakim, den König von Juda: Er wird niemanden als Nachkommen haben, der auf dem Thron Davids sitzt*. Und seine Leiche wird hingeworfen bleiben der Hitze bei Tag und der Kälte bei Nacht*.", footnotes: ["℘ Kap. 22,30", "℘ Kap. 22,18.19; Pred 6,3"] },
      { number: 31, text: "Und ich will an ihm und an seinen Nachkommen und an seinen Knechten ihre Schuld heimsuchen und will über sie und über die Bewohner von Jerusalem und über die Männer von Juda all das Unglück bringen, das ich über sie geredet habe*; aber sie haben nicht gehört*. —", footnotes: ["℘ Ps 94,23; Hes 7,8.9", "℘ Kap. 19,15"] },
      { number: 32, text: "Da nahm Jeremia eine andere Rolle und gab sie dem Schreiber Baruch, dem Sohn des Nerija. Und er schrieb darauf aus dem Mund Jeremias alle Worte des Buches, das Jojakim, der König von Juda, im Feuer verbrannt hatte. Und es wurden noch viele Worte wie diese hinzugefügt." },
    ]},
    { number: 37, verses: [
      { number: 1, text: "Und Zedekia, der Sohn des Josia*, den Nebukadnezar, der König von Babel, zum König gemacht hatte im Land Juda, regierte als König anstelle von Konja*, dem Sohn des Jojakim.", heading: "Ankündigung der Zerstörung Jerusalems — Jeremias Verhaftung und heimliche Befragung durch den König Zedekia", footnotes: ["℘ 1Chr 3,15; 2Chr 36,10", "℘ Kap. 22,24; 2Kö 24,17"] },
      { number: 2, text: "Und weder er noch seine Knechte noch das Volk des Landes hörten auf die Worte des HERRN, die er durch den Propheten Jeremia geredet hatte*.", footnotes: ["℘ 2Chr 36,11-16"] },
      { number: 3, text: "Und der König Zedekia sandte Juchal, den Sohn Schelemjas*, und Zefanja, den Sohn Maasejas*, den Priester, zum Propheten Jeremia und ließ ihm sagen: Bete doch für* uns zum HERRN, unserm Gott!", footnotes: ["℘ Kap. 38,1", "℘ Kap. 21,1", "℘ Kap. 2,27; 21,2; 1Sam 12,19; Apg 8,24"] },
      { number: 4, text: "Und Jeremia ging ein und aus mitten unter dem Volk, und man hatte ihn noch nicht ins Gefängnis gesetzt." },
      { number: 5, text: "Inzwischen war das Heer des Pharao aus Ägypten ausgezogen*. Und die Chaldäer, die Jerusalem belagerten, hatten die Nachricht von ihnen gehört und waren von Jerusalem abgezogen*.", footnotes: ["℘ Hes 17,15", "℘ V. 11; Kap. 34,21"] },
      { number: 6, text: "Und das Wort des HERRN geschah zu dem Propheten Jeremia:" },
      { number: 7, text: "So spricht der HERR, der Gott Israels: So sollt ihr dem König von Juda sagen, der euch zu mir gesandt hat, um mich zu befragen: Siehe, das Heer des Pharao, das euch zur Hilfe ausgezogen ist, wird in sein Land nach Ägypten zurückkehren*.", footnotes: ["℘ Kap. 2,36; 2Kö 24,7; Jes 30,3.7; 36,6"] },
      { number: 8, text: "Und die Chaldäer werden wiederkommen und gegen diese Stadt kämpfen, und sie werden sie einnehmen und mit Feuer verbrennen*.", footnotes: ["℘ Kap. 32,29; 38,3"] },
      { number: 9, text: "So spricht der HERR: Täuscht euch nicht selbst* und sagt nicht: Die Chaldäer werden endgültig von uns wegziehen! Denn sie werden nicht wegziehen.", footnotes: ["℘ Hi 15,31"] },
      { number: 10, text: "Denn wenn ihr auch das ganze Heer der Chaldäer schlagen würdet, die gegen euch kämpfen, und es blieben unter ihnen nur einige durchbohrte Männer übrig, so würden diese, jeder in seinem Zelt, aufstehen und diese Stadt mit Feuer verbrennen*.", footnotes: ["℘ Kap. 21,4-7"] },
      { number: 11, text: "Und es geschah, als das Heer der Chaldäer von Jerusalem vor dem Heer* des Pharao abgezogen war*,", footnotes: ["o. wegen des Heeres", "℘ V. 5"] },
      { number: 12, text: "da ging Jeremia aus Jerusalem hinaus, um in das Land Benjamin* zu gehen, um dort im Kreis der Familie* an einer Erbteilung teilzunehmen.", footnotes: ["℘ Kap. 1,1", "w. inmitten des Volkes. — Das hebr. Wort für »Volk« kann auch den Beiklang von »Familie« haben (wie z. B. 2Kö 4,13)."] },
      { number: 13, text: "Und als er im Tor Benjamin* war, wo ein Wachhabender* stand mit Namen Jirija, der Sohn Schelemjas, des Sohnes Hananjas, ergriff dieser den Propheten Jeremia und sagte: Du willst zu den Chaldäern überlaufen*.", footnotes: ["℘ Kap. 38,7; Sach 14,10", "w. Herr der Aufsicht", "℘ Kla 4,18"] },
      { number: 14, text: "Da sagte Jeremia: Lüge! Ich will nicht zu den Chaldäern überlaufen. Aber er hörte nicht auf ihn, und Jirija nahm Jeremia fest und brachte ihn zu den Obersten*.", footnotes: ["d. h. die maßgebenden Männer von Jerusalem"] },
      { number: 15, text: "Und die Obersten* gerieten in Zorn über Jeremia und schlugen ihn, und sie warfen ihn ins Gefängnis* im Haus des Schreibers Jonatan; denn das hatten sie zum Gefängnis* gemacht*.", footnotes: ["d. h. die maßgebenden Männer von Jerusalem", "℘ Kap. 20,2; 32,2; 39,15; Mt 21,35; Lk 3,20; Apg 4,3; Hebr 11,36", "o. Haus des Gefängnisses; w. Haus der Fessel", "℘ Kap. 38,26"] },
      { number: 16, text: "So* kam Jeremia in das Haus der Zisterne*, und zwar in die Gewölbe. Dort saß Jeremia viele Tage.", footnotes: ["so mit LXX; Mas. T.: Denn", "d. i. wahrscheinlich ein unterirdischer Kerker"] },
      { number: 17, text: "Dann sandte der König Zedekia hin und ließ ihn holen. Und der König fragte ihn in seinem Haus heimlich: Ist ein Wort vom HERRN da*? Und Jeremia sagte: Es ist eins da, nämlich: Du wirst in die Hand des Königs von Babel gegeben werden*.", footnotes: ["℘ Kap. 38,14", "℘ Kap. 21,7; 2Kö 25,7; Joh 18,23"] },
      { number: 18, text: "Und Jeremia sagte zum König Zedekia: Was habe ich an dir oder an deinen Knechten oder an diesem Volk gesündigt, dass ihr mich ins Gefängnis* gesetzt habt*?", footnotes: ["o. Haus des Gefängnisses; w. Haus der Fessel", "℘ Apg 25,11"] },
      { number: 19, text: "Wo sind denn eure Propheten, die euch geweissagt haben: Der König von Babel wird nicht über euch noch über dieses Land kommen*?", footnotes: ["℘ Kap. 14,13-15"] },
      { number: 20, text: "Und nun höre doch, mein Herr und König: Lass doch mein Flehen vor dich kommen* und bringe mich nicht in das Haus des Schreibers Jonatan zurück, damit ich dort nicht sterbe!", footnotes: ["w. vor dir niederfallen\n℘ Kap. 42,2; Ps 119,170"] },
      { number: 21, text: "Da gab der König Zedekia Befehl, und man verlegte Jeremia in den Wachhof. Und man gab ihm täglich ein Rundbrot* aus der Bäckerstraße, bis alles Brot in der Stadt aufgezehrt war*. So blieb Jeremia im Wachhof*.", footnotes: ["℘ Ps 33,18.19", "℘ Kap. 38,9.28; 52,6", "℘ Kap. 20,2; 32,2; 39,15; Mt 21,35; Lk 3,20; Apg 4,3; Hebr 11,36"] },
    ]},
    { number: 38, verses: [
      { number: 1, text: "Und Schefatja, der Sohn des Mattan, und Gedalja, der Sohn des Paschhur, und Juchal, der Sohn des Schelemja*, und Paschhur, der Sohn des Malkija*, hörten die Worte, die Jeremia zum ganzen Volk redete, indem er sagte:", heading: "Anschlag auf Jeremia und seine Rettung", footnotes: ["℘ Kap. 37,3", "℘ Kap. 21,1"] },
      { number: 2, text: "So spricht der HERR: Wer in dieser Stadt bleibt, wird sterben durch das Schwert, durch den Hunger und durch die Pest. Wer aber zu den Chaldäern hinausgeht, wird leben, und sein Leben* wird er zur Beute haben, so dass er lebt*.", footnotes: ["o. seine Seele", "℘ V. 17"] },
      { number: 3, text: "So spricht der HERR: Diese Stadt wird ganz gewiss in die Hand des Heeres des Königs von Babel gegeben werden, und er wird sie einnehmen*.", footnotes: ["℘ Kap. 21,9.10; 32,3; 37,8"] },
      { number: 4, text: "Und die Obersten sagten zum König: Dieser Mann muss getötet werden*, da er ja die Hände der Kriegsleute nur schlaff macht, die in dieser Stadt übrig geblieben sind, und die Hände des ganzen Volkes*, indem er nach all diesen Worten zu ihnen redet. Denn dieser Mann sucht nicht den Frieden*, sondern das Unheil dieses Volkes.", footnotes: ["℘ Kap. 26,11", "℘ Kap. 43,3; Am 7,10", "o. das Wohl"] },
      { number: 5, text: "Da sagte der König Zedekia: Siehe, er ist in eurer Hand, denn der König kann nichts gegen euch tun*.", footnotes: ["℘ Dan 6,16.17"] },
      { number: 6, text: "Da nahmen sie Jeremia und warfen ihn in die Zisterne* des Königssohnes Malkija*, die im Wachhof war, und sie ließen Jeremia mit Stricken hinab. In der Zisterne aber war kein Wasser*, sondern nur Schlamm, und Jeremia sank in den Schlamm ein.", footnotes: ["℘ Dan 6,16.17", "℘ Kap. 36,26", "℘ 1Mo 37,24; Kla 3,53"] },
      { number: 7, text: "Und Ebed-Melech, der Kuschit*, ein Hofbeamter*, der im Haus des Königs war, hörte, dass sie Jeremia in die Zisterne gebracht hatten. Der König aber saß im Tor Benjamin*.", footnotes: ["℘ Kap. 39,16", "w. ein Eunuch", "℘ Kap. 37,13"] },
      { number: 8, text: "Da ging Ebed-Melech aus dem Haus des Königs hinaus und redete zum König:" },
      { number: 9, text: "Mein Herr und König, diese Männer haben übel gehandelt in allem, was sie dem Propheten Jeremia angetan, den sie in die Zisterne geworfen haben. Er muss ja da, wo er ist, vor Hunger sterben, denn es ist kein Brot mehr in der Stadt*.", footnotes: ["o. sterben. — Denn es war kein Brot mehr in der Stadt.\n℘ Kap. 19,9; 37,21"] },
      { number: 10, text: "Und der König befahl Ebed-Melech, dem Kuschiten: Nimm von hier dreißig* Männer mit dir* und hole den Propheten Jeremia aus der Zisterne herauf, bevor er stirbt!", footnotes: ["Eine hebr. Handschr. liest »drei«.", "w. in deine Hand"] },
      { number: 11, text: "Da nahm Ebed-Melech die Männer mit sich* und ging in das Haus des Königs, unter die Vorratskammer, und er nahm von dort zerrissene Lappen und abgetragene Lumpen, und er ließ sie an Stricken zu Jeremia in die Zisterne hinab.", footnotes: ["w. in seine Hand"] },
      { number: 12, text: "Und der Kuschit Ebed-Melech sagte zu Jeremia: Lege doch diese zerrissenen Lappen und abgetragenen Lumpen unter die Achseln deiner Arme, unter die Stricke. Und Jeremia machte es so." },
      { number: 13, text: "So zogen sie Jeremia an den Stricken hoch und holten ihn aus der Zisterne herauf*. Jeremia aber blieb im Wachhof*.", footnotes: ["℘ 1Mo 37,28; Spr 29,10; Kla 3,58", "℘ Kap. 32,2"] },
      { number: 14, text: "Und der König Zedekia sandte hin und ließ den Propheten Jeremia zu sich holen in den dritten Eingang, der im Haus des HERRN war. Und der König sagte zu Jeremia: Ich will dich nach einem Wort* fragen*. Verschweige mir nichts*!", heading: "Erneute heimliche Befragung Jeremias durch den König Zedekia", footnotes: ["d. h. um ein Wort Gottes", "℘ Kap. 37,17", "℘ 1Sam 3,17"] },
      { number: 15, text: "Und Jeremia sagte zu Zedekia: Wenn ich es dir mitteile, wirst du mich dann nicht mit Sicherheit töten? Wenn ich dir aber einen Rat erteile, wirst du doch nicht auf mich hören*.", footnotes: ["℘ Lk 22,67.68"] },
      { number: 16, text: "Da schwor der König Zedekia dem Jeremia heimlich: So wahr der HERR lebt, der uns dieses Leben gegeben* hat*, wenn ich dich töte oder wenn ich dich in die Hand dieser Männer gebe, die nach deinem Leben trachten*!", footnotes: ["w. diese Seele gemacht", "℘ Jes 42,5", "Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde."] },
      { number: 17, text: "Und Jeremia sagte zu Zedekia: So spricht der HERR, der Gott der Heerscharen, der Gott Israels*: Wenn du zu den Obersten des Königs von Babel hinausgehst*, wird deine Seele am Leben bleiben*, und diese Stadt wird nicht mit Feuer verbrannt werden*; und du wirst am Leben bleiben, du und dein Haus.", footnotes: ["℘ Kap. 44,7; 1Chr 17,24", "d. h. dich ihnen ergibst", "℘ V. 2; Kap. 21,9", "℘ Kap. 21,10"] },
      { number: 18, text: "Wenn du aber nicht zu den Obersten des Königs von Babel hinausgehst, dann wird diese Stadt in die Hand der Chaldäer gegeben werden, und sie werden sie mit Feuer verbrennen; und du, du wirst nicht aus ihrer Hand entkommen*.", footnotes: ["℘ Kap. 32,4; 34,3; 39,5"] },
      { number: 19, text: "Und der König Zedekia sagte zu Jeremia: Ich fürchte mich vor den Judäern, die zu den Chaldäern übergelaufen sind, dass man mich in ihre Hand ausliefert und sie ihren Mutwillen an mir auslassen." },
      { number: 20, text: "Da sagte Jeremia: Man wird dich nicht ausliefern. Höre doch auf die Stimme des HERRN nach dem, was ich zu dir rede, dann wird es dir gut gehen, und deine Seele wird leben*!", footnotes: ["℘ Spr 4,4; Jes 55,3; Am 5,4.6"] },
      { number: 21, text: "Wenn du dich aber weigerst* hinauszugehen, so ist dies das Wort, das der HERR mich hat sehen lassen:", footnotes: ["℘ 2Chr 36,12"] },
      { number: 22, text: "Siehe, alle Frauen, die im Haus des Königs von Juda übrig geblieben sind, werden hinausgeführt werden zu den Obersten des Königs von Babel. Und sie werden sagen: »Verführt* und überwältigt haben dich die Männer deines Vertrauens. Während deine Füße im Sumpf versanken, haben sie sich davongemacht*!«", footnotes: ["℘ Kap. 27,14.15; Hi 6,15", "w. sind sie nach hinten gewichen"] },
      { number: 23, text: "Und alle deine Frauen und deine Söhne wird man zu den Chaldäern hinausführen. Und du, du wirst nicht aus ihrer Hand entkommen*, sondern wirst von der Hand des Königs von Babel ergriffen, und du wirst diese Stadt mit Feuer verbrennen*.", footnotes: ["℘ Kap. 21,10", "d. h. schuld daran sein, dass sie verbrannt wird; LXX und aram. Üs. lesen: wird mit Feuer verbrannt werden\n℘ Kap. 21,10"] },
      { number: 24, text: "Und Zedekia sagte zu Jeremia: Niemand darf von diesen Worten erfahren, damit du nicht stirbst!" },
      { number: 25, text: "Und wenn die Obersten hören, dass ich mit dir geredet habe, und sie zu dir kommen und zu dir sagen: Berichte uns doch, was du zum König geredet hast, verschweige es uns nicht, damit wir dich nicht töten! Was hat der König zu dir geredet?" },
      { number: 26, text: "— dann sollst du ihnen sagen: Ich habe mein Flehen vor dem König niedergelegt, dass er mich nicht in das Haus Jonatans zurückbringt, dass ich dort sterben muss*. —", footnotes: ["℘ Kap. 37,15.20"] },
      { number: 27, text: "Und alle Obersten kamen zu Jeremia und fragten ihn. Und er berichtete ihnen nach all jenen Worten, die der König geboten hatte. Und sie wandten sich schweigend von ihm ab, denn die Sache* war nicht weiter bekannt geworden.", footnotes: ["o. die Unterredung"] },
      { number: 28, text: "Und Jeremia blieb im Wachhof* bis zu dem Tag, an dem Jerusalem eingenommen wurde*.", footnotes: ["℘ Kap. 37,21", "℘ Kap. 39,14"] },
    ]},
    { number: 39, verses: [
      { number: 1, text: "*Und es geschah, als Jerusalem eingenommen wurde — im neunten Jahr Zedekias, des Königs von Juda, im zehnten Monat, war Nebukadnezar, der König von Babel, und sein ganzes Heer gegen Jerusalem gekommen, und sie belagerten es*;", heading: "Eroberung Jerusalems durch Nebukadnezar — Zweite Wegführung von Judäern nach Babel", footnotes: ["℘ Kap. 52,1-27; 2Kö 25,1-12; 2Chr 36,17-20", "℘ Kap. 6,6; 34,1; Hes 24,1.2"] },
      { number: 2, text: "im elften Jahr Zedekias*, im vierten Monat, am Neunten des Monats, wurde eine Bresche in die Stadtmauer gebrochen* —,", footnotes: ["℘ Kap. 1,3", "℘ Hes 33,21"] },
      { number: 3, text: "da zogen alle Obersten des Königs von Babel* ein und ließen sich im Mitteltor nieder: Nergal-Sarezer, Samgar-Nebu-Sar-Sechim*, der Rab-Saris* — Nergal-Sarezer aber war Rab-Mag* und alle übrigen Obersten des Königs von Babel.", footnotes: ["℘ V. 13; Kap. 21,4", "Andere üs. mit geringfügiger Textänderung: Nergal-Sarezer aus Sinmagir und Nebuschasban", "d. i. ein hoher Beamter; w. Obereunuch", "d. i. ein hoher Offizier"] },
      { number: 4, text: "Und es geschah, als Zedekia, der König von Juda, und alle Kriegsleute sie sahen, flohen sie und zogen nachts aus der Stadt hinaus* auf dem Weg zum Königsgarten, durch das Tor zwischen den beiden Mauern*. Und er zog hinaus auf dem Weg zur Ebene*.", footnotes: ["℘ Hes 12,12", "℘ 2Chr 32,5", "hebr. Araba; s. Anm. zu 5Mo 1,1"] },
      { number: 5, text: "Aber das Heer der Chaldäer jagte ihnen nach, und sie erreichten Zedekia in den Ebenen* von Jericho. Und sie nahmen ihn gefangen und führten ihn hinauf zu Nebukadnezar, dem König von Babel, nach Ribla im Land Hamat*; und er sprach das Urteil über ihn.", footnotes: ["o. Steppen", "℘ Kap. 38,18.23; Jes 22,3; Kla 4,20"] },
      { number: 6, text: "Und der König von Babel schlachtete die Söhne Zedekias in Ribla vor dessen Augen, und der König von Babel schlachtete alle Edlen von Juda*.", footnotes: ["℘ Kap. 34,19-22; Zef 1,8"] },
      { number: 7, text: "Und er blendete die Augen Zedekias, und er band ihn mit ehernen Fesseln*, um ihn nach Babel zu bringen*.", footnotes: ["w. bronzenen Doppelfesseln", "℘ Kap. 32,4.5; 44,30; Hes 12,13"] },
      { number: 8, text: "Und die Chaldäer verbrannten das Haus des Königs und die Häuser des Volkes mit Feuer und rissen die Mauern von Jerusalem nieder*.", footnotes: ["℘ Kap. 5,10; 21,10; Am 2,5"] },
      { number: 9, text: "Und den Rest des Volkes, die in der Stadt Übriggebliebenen, und die Überläufer, die zu ihm übergelaufen waren, und den Rest des Volkes — die Übriggebliebenen, führte Nebusaradan, der Oberste der Leibwache, nach Babel gefangen fort*.", footnotes: ["℘ Kap. 40,1.7"] },
      { number: 10, text: "Aber von dem Volk, den Geringen, die nichts hatten, ließ Nebusaradan, der Oberste der Leibwache, einen Rest im Land Juda zurück. Und er gab ihnen Weinberge und Äcker an jenem Tag." },
      { number: 11, text: "*Und über Jeremia gab Nebukadnezar, der König von Babel, durch Nebusaradan, den Obersten der Leibwache*, den Befehl:", heading: "Rettung Jeremias und Ebed-Melechs — Jeremia beim Statthalter Gedalja", footnotes: ["℘ Kap. 40,1-6", "℘ Kap. 52,12"] },
      { number: 12, text: "Nimm ihn und richte deine Augen auf ihn und tu ihm ja nichts Böses an, sondern wie er zu dir reden wird, so tu mit ihm*!", footnotes: ["℘ Kap. 15,11; Ps 105,15"] },
      { number: 13, text: "Da sandten Nebusaradan, der Oberste der Leibwache, und Nebuschasban, der Rab-Saris* und Nergal-Sarezer, der Rab-Mag*, und alle Großen des Königs von Babel* —", footnotes: ["d. i. ein hoher Beamter; w. Obereunuch", "d. i. ein hoher Offizier", "℘ V. 3"] },
      { number: 14, text: "sie sandten hin und ließen Jeremia aus dem Wachhof holen*. Und sie übergaben ihn Gedalja*, dem Sohn des Ahikam*, des Sohnes Schafans, dass er ihn ins Haus* hinausführe. Und so wohnte er mitten unter dem Volk.", footnotes: ["℘ Kap. 38,28", "℘ Kap. 40,7", "℘ Kap. 26,24", "d. h. das Haus, in dem Gedalja als Statthalter wohnte"] },
      { number: 15, text: "Und das Wort des HERRN war zu Jeremia geschehen, als er im Wachhof eingeschlossen war*:", footnotes: ["℘ Kap. 37,21"] },
      { number: 16, text: "Geh und sage zu Ebed-Melech, dem Kuschiten*: So spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich bringe meine Worte über diese Stadt zur Erfüllung, ihr zum Bösen und nicht zum Guten*, und sie werden an jenem Tag vor dir geschehen*!", footnotes: ["℘ Kap. 38,7-13", "℘ Kap. 21,10", "℘ Kap. 40,3; Dan 9,12; Sach 1,6"] },
      { number: 17, text: "Aber ich werde dich an jenem Tag retten, spricht der HERR*, und du wirst nicht in die Hand der Männer gegeben, vor denen du dich fürchtest*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 1Kö 18,15.16; 2Kö 6,16; Ps 41,2"] },
      { number: 18, text: "Denn ich werde dich gewiss entkommen lassen, und du wirst nicht durch das Schwert fallen. Und du sollst dein Leben* als Beute haben*, weil du auf mich vertraut hast, spricht der HERR*.", footnotes: ["o. deine Seele", "℘ Kap. 21,9; 45,5; Hi 5,20; Ps 91,7", "w. ist der Ausspruch des HERRN\n℘ 1Chr 5,20; Jes 26,3.4"] },
    ]},
    { number: 40, verses: [
      { number: 1, text: "*Das Wort, das von dem HERRN zu Jeremia geschah*, nachdem Nebusaradan, der Oberste der Leibwache, ihn von Rama* entlassen hatte, als er ihn holen ließ, — er war nämlich mit Ketten gebunden mitten unter allen Weggeführten von Jerusalem und Juda, die gefangen nach Babel weggeführt werden sollten*.", footnotes: ["℘ Kap. 39,11-14", "℘ Kap. 42,7", "℘ Kap. 31,15; 2Chr 16,1", "℘ Kap. 39,9"] },
      { number: 2, text: "Und der Oberste der Leibwache ließ Jeremia holen und sagte zu ihm: Der HERR, dein Gott, hat dieses Unheil über diesen Ort angesagt." },
      { number: 3, text: "Und der HERR hat es so kommen lassen und hat getan, wie er geredet hatte*. Denn ihr habt gegen den HERRN gesündigt und auf seine Stimme nicht gehört, darum ist das mit euch geschehen*.", footnotes: ["℘ Kap. 11,17; 39,16; Kla 2,17", "℘ Kap. 22,8.9; 50,7"] },
      { number: 4, text: "Und nun siehe, ich löse dich heute von den Ketten, die an deinen Händen sind. Wenn es gut ist in deinen Augen, mit mir nach Babel zu kommen, so komm, und ich werde mein Auge auf dich richten. Wenn es aber übel ist in deinen Augen, mit mir nach Babel zu kommen, so lass es. Siehe, das ganze Land ist vor dir. *Du kannst gehen, wohin du willst.* —", footnotes: ["w. Was zum Guten und zum Richtigen in deinen Augen dient, hinzugehen, dorthin gehe!", "w. Was zum Guten und zum Richtigen in deinen Augen dient, hinzugehen, dorthin gehe!"] },
      { number: 5, text: "Und da er sich noch nicht dahin oder dorthin wenden wollte, sagte er: So kehre zurück zu Gedalja, dem Sohn Ahikams, des Sohnes Schafans, den der König von Babel über die Städte Judas als Statthalter eingesetzt hat, und wohne bei ihm mitten unter dem Volk! Oder wohin irgend es recht ist in deinen Augen zu gehen, dahin gehe! Und der Oberste der Leibwache gab ihm Wegzehrung und ein Geschenk und entließ ihn." },
      { number: 6, text: "Und Jeremia kam zu Gedalja, dem Sohn Ahikams, nach Mizpa*. Und er wohnte bei ihm mitten unter dem Volk, das im Land übrig geblieben war.", footnotes: ["℘ Jos 18,26"] },
      { number: 7, text: "*Und als alle Heerobersten, die sich noch im offenen Land befanden*, sie und ihre Männer, hörten, dass der König von Babel Gedalja*, den Sohn Ahikams, zum Statthalter über das Land eingesetzt und dass er ihm Männer, Frauen und Kinder und Leute von den Geringen des Landes anvertraut hatte, von denen, die nicht gefangen nach Babel weggeführt worden waren*,", heading: "Gedaljas Statthalterschaft und seine Ermordung durch Ismael", footnotes: ["℘ V. 7-9: 2Kö 25,22-24", "d. h. die sich in das Innere des Landes geflüchtet hatten; w. die auf dem Feld waren", "℘ Kap. 39,14", "℘ Kap. 39,9.10; 41,10"] },
      { number: 8, text: "da kamen sie zu Gedalja nach Mizpa; nämlich Ismael*, der Sohn des Netanja, und Johanan* und Jonatan, die Söhne des Kareach, und Seraja, der Sohn des Tanhumet, und die Söhne Efais, des Netofatiters, und Jesanja, der Sohn des Maachatiters, sie und ihre Männer.", footnotes: ["℘ Kap. 41,1", "℘ Kap. 41,11; 42,1; 43,2"] },
      { number: 9, text: "Und Gedalja, der Sohn Ahikams, des Sohnes Schafans, schwor ihnen und ihren Männern: Fürchtet euch nicht, den Chaldäern zu dienen! Bleibt im Land und dient dem König von Babel, dann wird es euch gut gehen*!", footnotes: ["℘ Kap. 27,11"] },
      { number: 10, text: "Und ich, siehe, ich bleibe in Mizpa*, um vor den Chaldäern zu stehen*, die zu uns kommen werden. Ihr aber sammelt Wein, Sommerobst und Öl ein und tut sie in eure Gefäße! Und wohnt in euren Städten, die ihr in Besitz genommen habt!", footnotes: ["℘ Kap. 43,5", "d. h. um den Chaldäern zu dienen"] },
      { number: 11, text: "Und auch alle Judäer, die in Moab und unter den Söhnen Ammon und in Edom und die in allen diesen Ländern waren, hörten, dass der König von Babel einen Rest in Juda gelassen und dass er Gedalja, den Sohn Ahikams, des Sohnes Schafans, zum Statthalter über sie eingesetzt hatte." },
      { number: 12, text: "Da kehrten alle Judäer aus all den Orten zurück, wohin sie vertrieben worden waren, und sie kamen ins Land Juda zu Gedalja nach Mizpa. Und sie sammelten sehr viel Wein und Sommerobst ein." },
      { number: 13, text: "Und Johanan, der Sohn des Kareach, und alle Heerobersten, die sich noch im offenen Land aufgehalten hatten*, kamen zu Gedalja nach Mizpa,", footnotes: ["d. h. die sich in das Innere des Landes geflüchtet hatten; w. die auf dem Feld waren"] },
      { number: 14, text: "und sie sagten zu ihm: Weißt du auch, dass Baalis, der König der Söhne Ammon*, Ismael, den Sohn des Netanja, ausgesandt hat, um dich zu ermorden*? Aber Gedalja, der Sohn Ahikams, glaubte ihnen nicht.", footnotes: ["℘ Kap. 41,10", "℘ Kap. 41,1-3"] },
      { number: 15, text: "Und Johanan, der Sohn des Kareach, sagte heimlich zu Gedalja in Mizpa: Lass mich doch hingehen und Ismael, den Sohn des Netanja, erschlagen*, und niemand wird es erfahren! Warum soll er dich ermorden, dass alle Judäer*, die sich bei dir versammelt haben, zerstreut werden und der Rest von Juda verloren geht?", footnotes: ["℘ 1Sam 26,8", "w. ganz Juda"] },
      { number: 16, text: "Aber Gedalja, der Sohn Ahikams, sagte zu Johanan, dem Sohn des Kareach: Tu diese Sache nicht, denn du redest eine Lüge über Ismael!" },
    ]},
    { number: 41, verses: [
      { number: 1, text: "Und es geschah im siebten Monat, da kam Ismael, der Sohn Netanjas, des Sohnes Elischamas, einer von den königlichen Nachkommen, und die Großen des Königs und zehn Männer mit ihm zu Gedalja, dem Sohn Ahikams, nach Mizpa*. Und sie aßen dort zusammen in Mizpa.", footnotes: ["℘ Kap. 40,7.8"] },
      { number: 2, text: "Und Ismael, der Sohn Netanjas, stand auf und die zehn Männer, die mit ihm waren, und sie erschlugen Gedalja, den Sohn Ahikams, des Sohnes Schafans, mit dem Schwert. So tötete er den, den der König von Babel als Statthalter über das Land eingesetzt hatte*.", footnotes: ["℘ Kap. 40,14"] },
      { number: 3, text: "Und Ismael erschlug alle Judäer, die mit ihm bei Gedalja in Mizpa waren, und auch die Chaldäer, die Kriegsleute, die sich dort befanden*.", footnotes: ["℘ 2Kö 25,25"] },
      { number: 4, text: "Und es geschah am zweiten Tag, nachdem er Gedalja getötet hatte, als noch niemand davon wusste,", heading: "Weitere Morde und Gefangennahmen durch Ismael — Seine Vertreibung durch Johanan" },
      { number: 5, text: "da kamen Leute von Sichem, von Silo und von Samaria, achtzig Mann, die den Bart abgeschoren und die Kleider zerrissen und sich die Haut geritzt* hatten*, mit Speisopfern und Weihrauch in ihrer Hand, um es zum Haus des HERRN zu bringen.", footnotes: ["d. i. zum Ausdruck der Trauer über die Zerstörung des Tempels", "℘ Kap. 16,6"] },
      { number: 6, text: "Und Ismael, der Sohn des Netanja, zog von Mizpa aus ihnen entgegen, ging und weinte immerzu. Und es geschah, als er sie traf, sagte er zu ihnen: Kommt zu Gedalja, dem Sohn Ahikams!" },
      { number: 7, text: "Und es geschah, als sie in die Stadt hineingekommen waren, da schlachtete sie Ismael, der Sohn des Netanja, und warf sie in die Zisterne, er und die Männer, die mit ihm waren." },
      { number: 8, text: "Es befanden sich aber unter ihnen zehn Männer, die zu Ismael sagten: Töte uns nicht! Denn wir haben verborgene Vorräte im Feld: Weizen, Gerste, Öl und Honig*. Da ließ er ab und tötete sie nicht inmitten ihrer Brüder.", footnotes: ["℘ Hi 2,4; Spr 13,8"] },
      { number: 9, text: "Und die Zisterne, in die Ismael alle Leichen der Männer, die er erschlagen hatte, warf, war eine große Zisterne, diejenige, die* der König Asa wegen* Baschas, des Königs von Israel, gemacht hatte*. Diese füllte Ismael, der Sohn des Netanja, mit den Erschlagenen.", footnotes: ["so mit LXX; Mas. T.: die er erschlagen hatte durch die Hand Gedaljas, war diejenige, die", "o. aus Furcht vor", "℘ 1Kö 15,22"] },
      { number: 10, text: "Dann führte Ismael den ganzen Rest des Volkes, der in Mizpa war, gefangen weg: die Königstöchter und das ganze Volk, das in Mizpa übrig geblieben war und das Nebusaradan, der Oberste der Leibwache, Gedalja, dem Sohn des Ahikam, anvertraut hatte*. Und Ismael, der Sohn des Netanja, führte sie gefangen weg und zog hin, um zu den Söhnen Ammon hinüberzugehen*.", footnotes: ["℘ Kap. 40,7; 43,6", "℘ Kap. 40,14"] },
      { number: 11, text: "Und als Johanan*, der Sohn des Kareach, und alle Heerobersten, die mit ihm waren, all das Böse hörten, das Ismael, der Sohn des Netanja, verübt hatte,", footnotes: ["℘ Kap. 40,8"] },
      { number: 12, text: "nahmen sie alle ihre Männer und zogen hin, um gegen Ismael, den Sohn Netanjas, zu kämpfen. Und sie fanden ihn an dem großen Wasser, das bei Gibeon ist*.", footnotes: ["℘ 2Sam 2,13"] },
      { number: 13, text: "Und es geschah, als das ganze Volk, das bei Ismael war, Johanan, den Sohn des Kareach, sah und alle Heerobersten, die mit ihm waren, da freuten sie sich." },
      { number: 14, text: "Und das ganze Volk, das Ismael von Mizpa gefangen weggeführt hatte, wandte sich und machte kehrt und ging zu Johanan, dem Sohn des Kareach, über." },
      { number: 15, text: "Ismael aber, der Sohn Netanjas, entkam vor Johanan mit acht Männern und ging zu den Söhnen Ammon." },
      { number: 16, text: "Da nahmen Johanan, der Sohn des Kareach, und alle Heerobersten, die mit ihm waren, den ganzen Rest des Volkes, den er von Ismael, dem Sohn Netanjas, von Mizpa zurückgebracht hatte* — nachdem dieser den Gedalja, den Sohn des Ahikam, erschlagen hatte —, die Männer, die Kriegsleute, die Frauen und die Kinder und die Hofbeamten*, die er von Gibeon zurückgebracht hatte;", footnotes: ["Viell. ist der Mas. T. fehlerhaft überliefert; daher lesen andere: die Ismael, der Sohn des Netanja, aus Mizpa gefangen weggeführt hatte", "w. die Eunuchen"] },
      { number: 17, text: "und sie zogen hin und machten halt in der Herberge des Kimham*, die bei Bethlehem ist, um fortzuziehen, damit sie nach Ägypten kämen*,", footnotes: ["℘ 2Sam 19,38-41", "℘ Kap. 43,5-7"] },
      { number: 18, text: "aus Furcht vor den Chaldäern. Denn sie fürchteten sich vor ihnen*, weil Ismael, der Sohn Netanjas, Gedalja, den Sohn des Ahikam, erschlagen hatte, den der König von Babel zum Statthalter über das Land eingesetzt hatte*.", footnotes: ["℘ Kap. 42,11", "℘ 2Kö 25,22"] },
    ]},
    { number: 42, verses: [
      { number: 1, text: "Da traten heran alle Heerobersten und Johanan, der Sohn des Kareach, und Jesanja, der Sohn des Hoschaja*, und das ganze Volk, vom Kleinsten bis zum Größten,", heading: "Die Flucht der restlichen Judäer nach Ägypten", footnotes: ["℘ Kap. 40,8; 43,2"] },
      { number: 2, text: "und sagten zum Propheten Jeremia: Lass doch unser Flehen vor dich kommen* und bete für uns zum HERRN, deinem Gott, für diesen ganzen Rest* — denn nur wenige sind wir, die von vielen übrig geblieben sind, wie deine Augen sehen* —,", footnotes: ["w. vor dir niederfallen\n℘ Kap. 37,20", "℘ Kap. 2,27; 1Sam 7,8; Jes 37,4", "so mit LXX und syr. Üs.; Mas. T.: wie deine Augen uns sehen\n℘ 5Mo 28,62"] },
      { number: 3, text: "dass der HERR, dein Gott, uns den Weg mitteilt, auf dem wir gehen, und die Sache, die wir tun sollen*!", footnotes: ["℘ Esr 8,21"] },
      { number: 4, text: "Und der Prophet Jeremia sagte zu ihnen: Ich habe es gehört. Siehe, ich will zum HERRN, eurem Gott, beten nach euren Worten*. Und es soll geschehen, jedes Wort, das der HERR euch antwortet, werde ich euch mitteilen; ich werde euch kein Wort vorenthalten*.", footnotes: ["℘ 1Sam 12,23", "℘ Kap. 23,28; Apg 20,20.27"] },
      { number: 5, text: "Und sie sagten zu Jeremia: Der HERR sei ein wahrhaftiger und zuverlässiger Zeuge gegen uns*, wenn wir nicht nach jedem Wort, mit dem der HERR, dein Gott, dich zu uns senden wird, so handeln werden*.", footnotes: ["℘ 1Mo 31,50", "℘ V. 20; 5Mo 5,27; Ri 11,10"] },
      { number: 6, text: "Es sei Gutes oder Böses, wir wollen hören auf die Stimme des HERRN, unseres Gottes, zu dem wir dich senden, damit es uns gut geht, wenn wir auf die Stimme des HERRN, unseres Gottes, hören*.", footnotes: ["℘ Kap. 7,23; Ps 78,36.37"] },
      { number: 7, text: "Und es geschah am Ende von zehn Tagen, da geschah das Wort des HERRN zu Jeremia*.", footnotes: ["℘ Kap. 40,1"] },
      { number: 8, text: "Und er berief Johanan, den Sohn des Kareach, und alle Heerobersten, die mit ihm waren, und das ganze Volk, vom Kleinsten bis zum Größten," },
      { number: 9, text: "und sagte zu ihnen: So spricht der HERR, der Gott Israels, zu dem ihr mich gesandt habt, um euer Flehen vor ihn kommen zu lassen*:", footnotes: ["w. vor ihm niederfallen zu lassen"] },
      { number: 10, text: "Wenn ihr in diesem Land wohnen bleibt, dann werde ich euch aufbauen und nicht abbrechen und euch pflanzen und nicht ausreißen*. Denn das Unglück reut mich, das ich euch angetan habe*.", footnotes: ["℘ Kap. 24,6; 31,28", "℘ Kap. 18,8; 5Mo 32,36; 2Sam 24,16; Am 7,3.6; Jon 3,4.10"] },
      { number: 11, text: "Fürchtet euch nicht vor dem König von Babel, vor dem ihr euch jetzt fürchtet! Fürchtet euch nicht vor ihm*!, spricht der HERR*. Denn ich bin mit euch, um euch aus seiner Hand zu retten und zu befreien*.", footnotes: ["℘ Kap. 41,18", "w. ist der Ausspruch des HERRN", "℘ Kap. 1,19"] },
      { number: 12, text: "Und ich werde euch Erbarmen geben, dass er sich über euch erbarmt und euch in euer Land zurückkehren lässt*.", footnotes: ["℘ Ps 106,46"] },
      { number: 13, text: "Wenn ihr aber sagt: »Wir wollen nicht in diesem Land bleiben«, und, ohne auf die Stimme des HERRN, eures Gottes, zu hören," },
      { number: 14, text: "sagt: »Nein, sondern wir wollen ins Land Ägypten ziehen*, wo wir keinen Krieg sehen und den Schall des Signalhorns nicht hören und nicht nach Brot hungern werden*, und dort wollen wir wohnen!« —", footnotes: ["℘ 4Mo 14,3.4; 5Mo 17,16", "℘ 4Mo 11,5; Jes 30,2"] },
      { number: 15, text: "nun denn, darum hört das Wort des HERRN, ihr Rest von Juda! So spricht der HERR der Heerscharen, der Gott Israels: Wenn ihr euer Gesicht wirklich dahin richtet, nach Ägypten zu ziehen, und hinzieht, um euch dort als Fremde aufzuhalten," },
      { number: 16, text: "dann wird es geschehen, dass das Schwert, vor dem ihr euch fürchtet, euch dort, im Land Ägypten, erreichen wird. Und der Hunger, vor dem euch bange ist, wird dort, in Ägypten, hinter euch her sein; und ihr werdet dort sterben*.", footnotes: ["℘ Kap. 44,13.27; Hes 11,8"] },
      { number: 17, text: "Und es wird geschehen, alle Männer, die ihr Gesicht dahin gerichtet haben, nach Ägypten zu ziehen, um sich dort als Fremde aufzuhalten, werden sterben durch das Schwert, durch den Hunger und durch die Pest. Und sie werden keinen Entronnenen und Entkommenen haben vor dem Unheil, das ich über sie bringen werde*.", footnotes: ["℘ Kap. 44,13.27; Hes 11,8"] },
      { number: 18, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Ebenso wie sich mein Zorn und mein Grimm über die Bewohner von Jerusalem ergossen haben*, so wird sich mein Grimm über euch ergießen, wenn ihr nach Ägypten zieht. Und ihr werdet zum Fluch, zum Entsetzen, zur Verwünschung und zur Schmach werden* und werdet diesen Ort nicht wiedersehen*.", footnotes: ["℘ Kap. 7,20; Kla 2,4-6", "℘ Kap. 24,9; Hos 7,16", "℘ Kap. 22,10-12"] },
      { number: 19, text: "Der HERR hat zu euch geredet, ihr Rest von Juda: Zieht nicht nach Ägypten! Ihr sollt genau wissen, dass ich euch heute gewarnt habe*.", footnotes: ["℘ 4Mo 14,3.4; 5Mo 17,16"] },
      { number: 20, text: "Denn ihr habt um den Preis eures Lebens* geirrt*. Denn ihr selbst habt mich zum HERRN, eurem Gott, gesandt und gesagt: Bete für uns zum HERRN, unserm Gott! Und nach allem, was der HERR, unser Gott, sagen wird, so teile uns mit, und wir werden es tun*!", footnotes: ["o. eurer Seelen", "℘ 4Mo 17,3", "℘ V. 2-6"] },
      { number: 21, text: "Ich habe es euch heute mitgeteilt*, ihr aber habt nicht auf die Stimme des HERRN, eures Gottes, gehört und auf alles, womit er mich zu euch gesandt hat.*", footnotes: ["℘ 5Mo 30,15", "V. 20 und 21 lassen sich auch übersetzen: Denn ihr habt . . . geirrt, wenn ihr mich zum HERRN . . . gesandt und gesagt habt: . . . nach allem, was der HERR . . . sagen wird . . . werden wir tun, 21 und wenn ich es euch heute mitgeteilt habe, ihr aber nicht auf die Stimme des HERRN . . . gehört habt.\n℘ Kap. 43,7; Ps 81,12; Hes 33,31.32; Sach 7,11.12"] },
      { number: 22, text: "Und nun sollt ihr genau wissen, dass ihr sterben werdet durch das Schwert, durch den Hunger und durch die Pest an dem Ort, wohin ihr zu ziehen wünscht, um euch dort als Fremde aufzuhalten*.", footnotes: ["℘ Kap. 24,10; Hes 6,11.12; Hos 9,6"] },
    ]},
    { number: 43, verses: [
      { number: 1, text: "Und es geschah, als Jeremia zum ganzen Volk alle Worte des HERRN, ihres Gottes, zu Ende geredet hatte, mit denen ihn der HERR, ihr Gott, zu ihnen gesandt hatte, alle jene Worte*,", footnotes: ["℘ Kap. 1,7"] },
      { number: 2, text: "da sagte Asarja*, der Sohn des Hoschaja, und Johanan*, der Sohn des Kareach, und alle frechen Männer* — sie sagten zu Jeremia: Du redest Lüge! Der HERR, unser Gott, hat dich nicht gesandt und gesagt: Ihr sollt nicht nach Ägypten ziehen, um euch dort als Fremde aufzuhalten! —", footnotes: ["wahrscheinlich ist zu lesen: Jesanja\n℘ Kap. 40,8; 42,1", "℘ Kap. 43,7; Ps 81,12; Hes 33,31.32; Sach 7,11.12", "℘ Jes 9,8"] },
      { number: 3, text: "sondern Baruch*, der Sohn des Nerija, hetzt dich gegen uns auf*, um uns in die Hand der Chaldäer zu geben, damit sie uns töten* oder uns nach Babel gefangen wegführen.", footnotes: ["℘ Kap. 32,12", "w. verführt dich zum Bösen gegen uns", "℘ Kap. 38,4"] },
      { number: 4, text: "Und so hörten Johanan, der Sohn des Kareach, und alle Heerobersten und das ganze Volk nicht auf den Befehl* des HERRN, im Land Juda zu bleiben.", footnotes: ["w. die Stimme"] },
      { number: 5, text: "Und Johanan, der Sohn des Kareach, und alle Heerobersten nahmen den ganzen Rest von Juda, die aus allen Nationen, in die sie vertrieben worden, zurückgekehrt waren, um sich im Land Juda aufzuhalten*:", footnotes: ["℘ Kap. 40,11.12; 41,10"] },
      { number: 6, text: "die Männer, die Frauen, die Kinder und die Königstöchter und alle Seelen, die Nebusaradan, der Oberste der Leibwache, bei Gedalja, dem Sohn Ahikams, des Sohnes Schafans, zurückgelassen hatte*, und auch den Propheten Jeremia und Baruch, den Sohn des Nerija.", footnotes: ["℘ Kap. 40,11.12; 41,10"] },
      { number: 7, text: "Und sie zogen nach Ägypten, denn sie hörten nicht auf die Stimme des HERRN*. Und sie kamen nach Tachpanhes*.", footnotes: ["℘ Kap. 42,21", "℘ Kap. 2,16; 41,17; 44,1; 2Kö 25,26; Hes 30,18"] },
      { number: 8, text: "*Und das Wort des HERRN geschah zu Jeremia in Tachpanhes:", heading: "Jeremia prophezeit die Besetzung Oberägyptens durch Nebukadnezar", footnotes: ["℘ V. 8-13: Hes 29-32"] },
      { number: 9, text: "Nimm große Steine in deine Hand und vergrabe* sie in der Sandbettung* in der Ziegelterrasse*, die am Eingang des Hauses des Pharao in Tachpanhes ist, vor den Augen der judäischen Männer*!", footnotes: ["o. verbirg", "o. im Lehmboden. — 3 griech. Üs. und die lat. Üs. lesen: verscharre sie im Verborgenen", "o. Mastaba; d. i. ein altägyptischer Grabbau", "℘ Kap. 13,1"] },
      { number: 10, text: "Und sage zu ihnen: So spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich sende hin und hole meinen Knecht Nebukadnezar, den König von Babel, und setze* seinen Thron auf diese Steine, die ich vergraben* habe. Und er wird seinen Prachtteppich* über ihnen ausbreiten*.", footnotes: ["LXX und syr. Üs.: er wird setzen", "o. verborgen; dasselbe Wort wie in Kap. 13,4.5", "o. Baldachin. — Die Bedeutung des Wortes ist unsicher.", "℘ Kap. 27,6"] },
      { number: 11, text: "Und er wird kommen und das Land Ägypten schlagen*: Wer zum Tod bestimmt ist, verfällt dem Tod; und wer zur Gefangenschaft, der Gefangenschaft; und wer zum Schwert, dem Schwert*.", footnotes: ["℘ Kap. 46,13; Hes 30,10", "℘ Kap. 15,2; 44,12.13; Offb 13,10"] },
      { number: 12, text: "Und ich werde* ein Feuer anzünden in den Häusern der Götter Ägyptens, und er wird sie verbrennen und wird sie wegführen*. Und er wird das Land Ägypten um sich wickeln, wie der Hirt sein Oberkleid um sich wickelt*. Dann wird er unbehelligt* von dort wegziehen*.", footnotes: ["LXX: er wird", "℘ Kap. 10,11.15; 25,19; 46,25; Jes 19,1; Hes 30,13", "o. und wird das Land Ägypten lausen, wie der Hirte sein Gewand entlaust", "w. in Frieden", "℘ Hes 29,19.20"] },
      { number: 13, text: "Und er wird die Säulen* von Bet-Schemesch* im Land Ägypten zerschlagen und die Häuser der Götter Ägyptens mit Feuer verbrennen*.", footnotes: ["d. h. die Obelisken", "Bet-Schemesch (Sonnenstadt) ist die hebr. Üs. des heiligen Namens der Stadt On (Heliopolis), die durch ihre dem Sonnengott geweihten Tempel berühmt war.\n℘ 1Mo 41,45; Hes 30,17", "℘ Kap. 10,11.15; 25,19; 46,25; Jes 19,1; Hes 30,13"] },
    ]},
    { number: 44, verses: [
      { number: 1, text: "Das Wort, das zu Jeremia geschah an alle* Judäer, die im Land Ägypten wohnten*, die in Migdol* und in Tachpanhes* und in Nof* und im Land Patros* wohnten:", heading: "Jeremias Gerichtswort über den Opferkult für die »Himmelskönigin« wird zurückgewiesen", footnotes: ["o. betreffs aller", "℘ Kap. 24,8", "d. i. an der nördlichen Grenze Ägyptens\n℘ Hes 29,10", "℘ Hes 30,18", "d. i. Memfis\n℘ Kap. 43,7; 46,14.19; Jes 19,13", "d. i. Oberägypten\n℘ V. 15; Jes 11,11; Hes 29,14"] },
      { number: 2, text: "So spricht der HERR der Heerscharen, der Gott Israels: Ihr habt all das Unheil gesehen, das ich über Jerusalem und über alle Städte Judas gebracht habe — und siehe, sie sind am heutigen Tag eine Trümmerstätte, und niemand wohnt darin*,", footnotes: ["℘ V. 22; Kap. 8,3; 34,22; Kla 1,1; 5,18; Sach 1,6"] },
      { number: 3, text: "um ihrer Bosheit willen, die sie verübt haben, um mich zu reizen, indem sie hingingen, Rauchopfer darzubringen und anderen Göttern zu dienen, die sie nicht kannten, weder sie noch ihr noch eure Väter*.", footnotes: ["℘ Kap. 16,10.11; 19,3.4; 5Mo 29,25"] },
      { number: 4, text: "Und ich habe alle meine Knechte, die Propheten, zu euch gesandt, früh mich aufmachend und sendend*, indem ich sprach: Tut doch nicht diesen Gräuel, den ich hasse*!", footnotes: ["℘ Kap. 7,25; 29,19", "℘ Kap. 7,17-19; Hes 18,31"] },
      { number: 5, text: "Aber sie haben nicht gehört* und ihr Ohr nicht geneigt, dass sie von ihrer Bosheit umgekehrt wären und anderen Göttern keine Rauchopfer mehr darbrächten*.", footnotes: ["℘ Neh 9,30.34", "℘ Kap. 11,13.17; Hos 11,2.7; Offb 2,21"] },
      { number: 6, text: "Da ergoss sich mein Grimm und mein Zorn, und er brannte in den Städten Judas und auf den Straßen von Jerusalem. Und sie sind zur Trümmerstätte, zur Öde geworden, wie es an diesem Tag ist*.", footnotes: ["℘ V. 22; Kap. 8,3; 34,22; Kla 1,1; 5,18; Sach 1,6"] },
      { number: 7, text: "Und nun, so spricht der HERR, der Gott der Heerscharen, der Gott Israels*: Warum richtet ihr ein so großes Unheil gegen eure Seelen an, um euch Mann und Frau, Kind und Säugling aus Juda auszurotten*, so dass ihr euch keinen Rest übrig lasst,", footnotes: ["℘ Kap. 38,17", "℘ Kap. 25,6.7; 5Mo 32,25; Hes 9,6; 33,11"] },
      { number: 8, text: "dadurch, dass ihr mich mit den Werken eurer Hände reizt*, dadurch, dass ihr anderen Göttern Rauchopfer darbringt im Land Ägypten, wohin ihr gekommen seid, um euch dort als Fremde aufzuhalten, so dass ihr euch ausrottet und zum Fluch und zur Schmach werdet unter allen Nationen der Erde*?", footnotes: ["℘ Kap. 32,30", "℘ Kap. 25,6.7; 5Mo 32,25; Hes 9,6; 33,11"] },
      { number: 9, text: "Habt ihr die bösen Taten eurer Väter vergessen und die bösen Taten der Könige von Juda und die bösen Taten ihrer Frauen und eure eigenen bösen Taten und die bösen Taten eurer Frauen, die sie im Land Juda und auf den Straßen von Jerusalem getan haben*?", footnotes: ["℘ 5Mo 9,7; Esr 9,7.13.14"] },
      { number: 10, text: "Bis auf diesen Tag haben sie sich* nicht gedemütigt*, und sie haben sich nicht gefürchtet* und haben nicht in meinem Gesetz gelebt* und in meinen Ordnungen, die ich euch und euren Vätern vorgelegt habe*. —", footnotes: ["w. sind sie", "w. sind sie nicht zerschlagen o. zerknirscht\n℘ Kap. 5,3", "℘ Pred 8,12.13", "w. sind nicht . . . gegangen", "℘ Jes 42,24"] },
      { number: 11, text: "Darum, so spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich will mein Angesicht gegen euch richten zum Unheil und zur Ausrottung von ganz Juda*.", footnotes: ["℘ Kap. 21,10; 3Mo 20,5"] },
      { number: 12, text: "Und ich werde den Rest von Juda wegraffen, alle, die ihre Gesichter darauf gerichtet haben, in das Land Ägypten zu ziehen, um sich dort als Fremde aufzuhalten. Und sie sollen alle vollständig aufgerieben werden, im Land Ägypten sollen sie fallen. Durch das Schwert, durch den Hunger sollen sie aufgerieben werden, vom Kleinsten bis zum Größten; durch das Schwert und durch den Hunger sollen sie sterben*. Und sie sollen zum Fluch, zum Entsetzen und zur Verwünschung und zur Schmach werden.", footnotes: ["℘ Kap. 24,9; 42,15-18.22; 43,11; Hos 9,6"] },
      { number: 13, text: "Und ich will die im Land Ägypten Wohnenden heimsuchen, wie ich Jerusalem heimgesucht habe durch das Schwert, durch den Hunger und durch die Pest*.", footnotes: ["℘ Kap. 24,9; 42,15-18.22; 43,11; Hos 9,6"] },
      { number: 14, text: "Und der Rest von Juda, diejenigen, die in das Land Ägypten gekommen sind, um sich dort als Fremde aufzuhalten, wird keinen Entkommenen und Entronnenen haben*, um in das Land Juda zurückzukehren, wohin sie sich sehnen zurückzukehren, um dort zu wohnen; denn sie werden nicht zurückkehren, außer einigen Entkommenen.", footnotes: ["℘ V. 26.28; Hes 20,38"] },
      { number: 15, text: "Und alle Männer, die wussten, dass ihre Frauen anderen Göttern Rauchopfer darbrachten*, und alle Frauen, die in großer Menge dastanden, und das ganze Volk, das im Land Ägypten, in Patros*, wohnte, antworteten dem Jeremia:", footnotes: ["℘ 5Mo 13,7-12", "℘ V. 1"] },
      { number: 16, text: "Was das Wort betrifft, das du im Namen des HERRN zu uns geredet hast, so werden wir nicht auf dich hören*,", footnotes: ["℘ Kap. 6,16; 18,18; 1Sam 8,19"] },
      { number: 17, text: "sondern wir wollen bestimmt all das tun, was aus unserem eigenen Mund hervorgegangen ist, der Königin des Himmels Rauchopfer darbringen und ihr Trankopfer spenden*, so wie wir es getan haben, wir und unsere Väter, unsere Könige und unsere Obersten, in den Städten Judas und auf den Straßen von Jerusalem*. Da hatten wir Brot in Fülle, und es ging uns gut, und wir sahen kein Unglück*.", footnotes: ["℘ V. 25; Hes 20,32", "℘ Kap. 7,17.18", "℘ Hos 2,7.10"] },
      { number: 18, text: "Aber seitdem wir aufgehört haben, der Königin des Himmels Rauchopfer darzubringen und ihr Trankopfer zu spenden, haben wir an allem Mangel gehabt und sind durch das Schwert und durch den Hunger aufgerieben worden*.", footnotes: ["℘ Mal 3,14"] },
      { number: 19, text: "Und wenn wir der Königin des Himmels Rauchopfer darbrachten und ihr Trankopfer spendeten, haben wir ihr da etwa ohne unsere Männer* Kuchen bereitet, um sie so nachzubilden, und ihr Trankopfer gespendet?*", footnotes: ["d. h. ohne die Zustimmung unserer Männer", "℘ 4Mo 30,7-9"] },
      { number: 20, text: "Und Jeremia sagte zum ganzen Volk, zu den Männern, zu den Frauen und zum ganzen Volk, das ihm Antwort gegeben hatte*:", footnotes: ["℘ Hes 2,3-7"] },
      { number: 21, text: "Das Rauchopfer, das ihr in den Städten Judas und auf den Straßen von Jerusalem dargebracht habt*, ihr und eure Väter, eure Könige und eure Obersten und das Volk des Landes* — hat der HERR nicht daran gedacht, und hat er es nicht gemerkt*?", footnotes: ["w. als Rauch habt aufsteigen lassen", "℘ Kap. 11,13", "w. ist es nicht in sein Herz aufgestiegen\n℘ Am 8,7"] },
      { number: 22, text: "Und der HERR konnte es nicht mehr ertragen* wegen der Bosheit eurer Taten, wegen der Gräuel, die ihr verübt habt. Darum ist euer Land zur Trümmerstätte, zum Entsetzen und zum Fluch geworden, ohne Bewohner, wie es an diesem Tag ist*.", footnotes: ["℘ Kap. 5,9; 15,6", "℘ 2Kö 17,15; Dan 9,11"] },
      { number: 23, text: "Weil ihr Rauchopfer dargebracht und gegen den HERRN gesündigt und auf die Stimme des HERRN nicht gehört und seinem Gesetz und in seinen Ordnungen und in seinen Zeugnissen nicht gelebt habt*, darum ist euch dieses Unheil widerfahren, wie es an diesem Tag ist. —", footnotes: ["w. nicht gegangen seid"] },
      { number: 24, text: "Und Jeremia sagte zum ganzen Volk und zu allen Frauen: Hört das Wort des HERRN, alle Judäer*, die ihr im Land Ägypten seid!", footnotes: ["w. ganz Juda"] },
      { number: 25, text: "So spricht der HERR der Heerscharen, der Gott Israels: Ihr und eure Frauen, ihr habt es mit eurem Mund geredet und es mit euren Händen ausgeführt und gesagt: Wir wollen unsere Gelübde bestimmt erfüllen, die wir gelobt haben, der Königin des Himmels Rauchopfer darzubringen und ihr Trankopfer zu spenden. So haltet nun eure Gelübde und erfüllt nur eure Gelübde!*", footnotes: ["℘ V. 16.17"] },
      { number: 26, text: "Darum hört das Wort des HERRN, alle Judäer*, die ihr im Land Ägypten wohnt! Siehe, ich habe bei meinem großen Namen geschworen*, spricht der HERR: Wenn im ganzen Land Ägypten jemals wieder mein Name im Mund irgendeines Mannes von Juda genannt wird, dass er etwa sagt: »So wahr der Herr, HERR, lebt!«*", footnotes: ["w. ganz Juda", "℘ Kap. 22,5; 49,13; 51,14", "Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde\n℘ V. 11-14"] },
      { number: 27, text: "Siehe, ich wache über sie zum Bösen und nicht zum Guten*. Und alle Männer von Juda, die im Land Ägypten sind, sollen durch das Schwert und durch den Hunger aufgerieben werden, bis sie vernichtet sind*.", footnotes: ["℘ Kap. 21,10; Dan 9,14", "℘ Kap. 9,15"] },
      { number: 28, text: "Doch dem Schwert Entkommene werden aus dem Land Ägypten in das Land Juda zurückkehren, ein geringes Häuflein*. Und der ganze Rest von Juda, die, die ins Land Ägypten gekommen sind, um sich dort als Fremde aufzuhalten, werden erkennen, welches Wort sich bestätigen wird, meines oder ihres.", footnotes: ["w. gezählte Männer\n℘ V. 14; Jes 10,22"] },
      { number: 29, text: "Und dies sei euch das Zeichen, spricht der HERR*, dass ich euch an diesem Ort heimsuchen werde, damit ihr erkennt, dass meine Worte über euch* sich ganz gewiss bestätigen werden zum Unheil —", footnotes: ["w. ist der Ausspruch des HERRN", "o. an euch"] },
      { number: 30, text: "so spricht der HERR: Siehe, ich gebe den Pharao Hofra, den König von Ägypten, in die Hand seiner Feinde und in die Hand derer, die nach seinem Leben trachten*, ebenso wie ich Zedekia, den König von Juda, in die Hand seines Feindes Nebukadnezar gegeben habe, des Königs von Babel, der nach seinem Leben trachtete*.", footnotes: ["℘ Kap. 46,13.25.26; Hes 29,2.3", "℘ Kap. 39,5-7"] },
    ]},
    { number: 45, verses: [
      { number: 1, text: "Das Wort, das der Prophet Jeremia zu Baruch*, dem Sohn des Nerija, redete, als er diese Worte aus dem Mund Jeremias in ein Buch schrieb*, im vierten Jahr Jojakims, des Sohnes Josias, des Königs von Juda*, als er sagte:", heading: "Gottes Antwort an Baruch", footnotes: ["℘ Kap. 32,12", "℘ Kap. 36,2.4", "℘ Kap. 36,1"] },
      { number: 2, text: "So spricht der HERR, der Gott Israels, über dich, Baruch:" },
      { number: 3, text: "Du hast gesagt: Wehe mir! Denn der HERR hat Kummer zu meinem Schmerz hinzugefügt. Ich bin müde von meinem Seufzen, und Ruhe finde ich nicht*.", footnotes: ["℘ Ps 6,7.8"] },
      { number: 4, text: "So sollst du zu ihm sagen: So spricht der HERR: Siehe, was ich gebaut habe, breche ich ab; und was ich gepflanzt habe, reiße ich aus, und zwar das ganze Land*.", footnotes: ["℘ Jes 5,5; Kla 2,6; Hos 2,14"] },
      { number: 5, text: "Und du, du trachtest nach großen Dingen für dich? Trachte nicht danach*! Denn siehe, ich bringe Unheil über alles Fleisch*, spricht der HERR*, aber dir gebe ich dein Leben* zur Beute an allen Orten, wohin du ziehen wirst*.", footnotes: ["℘ 2Kö 5,26; 2Tim 2,3.4", "℘ Kap. 25,15.16", "w. ist der Ausspruch des HERRN", "o. deine Seele", "℘ Kap. 39,18"] },
    ]},
    { number: 46, verses: [
      { number: 1, text: "Was als Wort des HERRN zu dem Propheten Jeremia geschah gegen* die Nationen*:", heading: "Zwei Unheilsworte über Ägypten — Zwei verlorene Kriege gegen Babylon", footnotes: ["o. über", "℘ Kap. 25,15"] },
      { number: 2, text: "*Über Ägypten: Gegen* die Heeresmacht des Pharao Necho, des Königs von Ägypten*, die zu Karkemisch* war, am Strom Euphrat, die Nebukadnezar, der König von Babel, schlug* im vierten Jahr Jojakims, des Sohnes Josias, des Königs von Juda*:", footnotes: ["℘ V. 2-26: Jes 19; 20; Hes 29-32", "o. über", "℘ Kap. 25,19", "℘ Jes 10,9", "℘ 2Kö 23,29; 24,7", "℘ Kap. 25,1"] },
      { number: 3, text: "Rüstet Kleinschild und Langschild und rückt heran zum Kampf*!", footnotes: ["℘ V. 14; Jes 8,9; Joe 4,9-11"] },
      { number: 4, text: "Spannt die Pferde an und besteigt die Reitpferde*! Und stellt euch auf mit Helmen, schärft die Lanzen, zieht die Panzer an*!", footnotes: ["Andere üs.: und sitzt auf, ihr Reiter", "℘ V. 14; Jes 8,9; Joe 4,9-11"] },
      { number: 5, text: "Warum sehe ich sie bestürzt zurückweichen? Und ihre Helden sind zerschlagen, und sie ergreifen die Flucht und sehen sich nicht um* — Schrecken ringsum*!, spricht der HERR*.", footnotes: ["℘ Nah 2,9; Zef 1,14", "℘ Kap. 6,25", "w. ist der Ausspruch des HERRN"] },
      { number: 6, text: "Der Schnelle soll nicht entfliehen und der Held nicht entkommen*; nach Norden zu, am Ufer des Stromes Euphrat, sind sie gestürzt und gefallen*.", footnotes: ["℘ Pred 9,11", "℘ 2Kö 23,29; 24,7"] },
      { number: 7, text: "Wer ist es, der heraufsteigt wie der Nil, wie Ströme wogt sein Wasser*?", footnotes: ["℘ Kap. 47,2; Jes 8,7"] },
      { number: 8, text: "Ägypten steigt herauf wie der Nil, und wie Ströme wogt sein Wasser, und es spricht: Ich will hinaufsteigen, will die Erde bedecken, die Städte zugrunde richten und ihre Bewohner." },
      { number: 9, text: "Steigt hinauf*, ihr Pferde, fahrt wie toll*, ihr Wagen! Und ausziehen sollen die Helden, Kusch und Put*, die den Schild fassen, und die Luditer*, die den Bogen fassen und spannen!", footnotes: ["o. Bäumt euch auf", "w. führt euch wie toll auf; vgl. Kap. 25,16", "℘ Hes 27,10", "Put und Lud waren nordafrikanische Völkerschaften.\n℘ 1Mo 10,6.13; Hes 30,4.5; Nah 3,9"] },
      { number: 10, text: "Aber dieser Tag gehört dem Herrn, dem HERRN der Heerscharen, ein Tag der Rache, sich zu rächen an seinen Gegnern*. Fressen wird das Schwert* und sich sättigen und sich satt trinken an ihrem Blut. Denn der Herr, der HERR der Heerscharen, hat ein Schlachtopfer* im Land des Nordens, am Strom Euphrat bereitet*.", footnotes: ["℘ Jes 2,12; Lk 21,22", "℘ 5Mo 32,42", "℘ Jes 34,5.6; Hes 39,17; Offb 19,17", "Gemeint ist die Schlacht bei Karkemisch (605 v. Chr.), wo Pharao Necho die Schlacht gegen Babel verlor."] },
      { number: 11, text: "Geh hinauf nach Gilead und hole Balsam*, du Jungfrau, Tochter Ägyptens! Vergeblich häufst du die Heilmittel auf; es ist keine heilende Haut* für dich da*.", footnotes: ["℘ Kap. 8,22; 51,8", "w. kein Überzug. — Gemeint ist die Hautschicht, die eine heilende Wunde überzieht.", "℘ Hes 30,21"] },
      { number: 12, text: "Die Nationen haben deine Schande gehört, und die Erde ist voll von deinem Klagegeschrei. Denn ein Held ist über den andern gestürzt, sie sind beide miteinander gefallen*.", footnotes: ["℘ Hes 32,12"] },
      { number: 13, text: "Das Wort, das der HERR zum Propheten Jeremia redete über die Ankunft Nebukadnezars, des Königs von Babel, um das Land Ägypten zu schlagen*:", footnotes: ["℘ Kap. 43,10.11; 44,30"] },
      { number: 14, text: "Verkündigt es in Ägypten und lasst es hören in Migdol* und lasst es hören in Nof und in Tachpanhes*! Sagt: Stell dich auf und rüste dich*! Denn das Schwert frisst alles rings um dich her.", footnotes: ["℘ 2Mo 14,2", "℘ Kap. 2,16; 44,1", "℘ V. 3.4"] },
      { number: 15, text: "Warum sind deine Starken niedergeworfen? Keiner hielt stand, denn der HERR hat sie niedergestoßen*.", footnotes: ["℘ Ps 68,2.3"] },
      { number: 16, text: "Er hat viele stürzen lassen. Ja, einer fiel über den andern*, und sie sagten: Auf, und lasst uns zurückkehren zu unserm Volk und zu unserm Geburtsland vor dem gewalttätigen Schwert!", footnotes: ["℘ 3Mo 26,37"] },
      { number: 17, text: "Man rief dort: Der Pharao, der König von Ägypten, ist ein »Getöse«*, das den rechten Zeitpunkt hat vorübergehen lassen*!*", footnotes: ["d. h. jemand, der sich mit viel Aufwand brüstet", "℘ Pred 3,1", "Andere üs. mit LXX und Vulg.: Gebt dem Pharao . . . den Namen »Getöse, das den rechten Zeitpunkt hat vorübergehen lassen«."] },
      { number: 18, text: "So wahr ich lebe, spricht der König*, HERR der Heerscharen ist sein Name*: Wie der Tabor* unter den Bergen und wie der Karmel* am Meer wird er* kommen*!", footnotes: ["w. ist der Ausspruch des Königs", "℘ Kap. 10,16; 48,15; 51,57; Am 4,13", "℘ Ri 4,6.12", "℘ 1Kö 18,42", "d. h. der alle anderen überragende König von Babel", "℘ Kap. 4,7.13"] },
      { number: 19, text: "Mach dir das Gepäck zur Wegführung zurecht, du Bewohnerin, Tochter Ägyptens*! Denn Nof* wird zur Wüste* werden und verbrannt, ohne Bewohner.", footnotes: ["℘ Jes 20,4", "℘ Kap. 44,1; Hes 30,13", "w. zum Schreckensort"] },
      { number: 20, text: "Eine sehr schöne junge Kuh ist Ägypten. Eine Bremse kommt von Norden geflogen, sie kommt*.", footnotes: ["℘ Kap. 25,9; 47,2"] },
      { number: 21, text: "Auch seine Söldner in seiner Mitte sind wie gemästete Kälber. Ja, auch sie wandten sich um und sind allesamt geflohen, haben nicht standgehalten. Denn der Tag ihres Unglücks ist über sie gekommen, die Zeit ihrer Heimsuchung*.", footnotes: ["℘ Kap. 48,44; 50,27"] },
      { number: 22, text: "Sein* Geräusch ist wie das Geräusch der Schlange*, die davoneilt. Denn sie* ziehen mit Heeresmacht einher und kommen über Ägypten* mit Beilen, wie Holzhauer.", footnotes: ["Gemeint ist Ägypten.", "w. ist wie die Schlange", "Gemeint sind wohl die Chaldäer.", "w. es"] },
      { number: 23, text: "Sie haben seinen Wald umgehauen, spricht der HERR*, — ja, unerforschlich ist es*. Denn sie sind mehr als die Heuschrecken, und ohne Zahl sind sie*.", footnotes: ["w. ist der Ausspruch des HERRN", "Andere üs.: obgleich er undurchdringlich ist", "℘ Ri 6,5"] },
      { number: 24, text: "Die Tochter Ägyptens ist zuschanden geworden, sie ist in die Hand des Volkes aus dem Norden gegeben." },
      { number: 25, text: "Es spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich suche heim den Amon von No*, den Pharao und Ägypten, seine Götter* und seine Könige, ja, den Pharao und die auf ihn vertrauen*.", footnotes: ["d. h. von Theben, wo der Gott Amon verehrt wurde\n℘ Hes 30,14; Nah 3,8", "℘ Kap. 43,12.13", "℘ Jes 20,5.6; 30,3"] },
      { number: 26, text: "Und ich gebe sie in die Hand derer, die nach ihrem Leben trachten, und zwar in die Hand Nebukadnezars, des Königs von Babel, und in die Hand seiner Knechte*. Später aber soll es wieder bewohnt werden* wie in den Tagen der Vorzeit, spricht der HERR*.", footnotes: ["℘ Kap. 44,30; Hes 32,11", "℘ Hes 29,13", "w. ist der Ausspruch des HERRN"] },
      { number: 27, text: "*Du aber, fürchte dich nicht, mein Knecht Jakob, und sei nicht niedergeschlagen, Israel! Denn siehe, ich will dich retten aus der Ferne und deine Nachkommen aus dem Land ihrer Gefangenschaft. Und Jakob wird zurückkehren und ruhig und sicher sein, und niemand wird ihn aufschrecken.", heading: "Ein Trostwort für Israel im Exil", footnotes: ["℘ Kap. 30,10.11; Hes 16,53"] },
      { number: 28, text: "Du, mein Knecht Jakob, fürchte dich nicht!, spricht der HERR*. Denn ich bin mit dir. Denn allen Nationen, zu denen ich dich vertrieben habe, werde ich ein Ende machen, aber dir werde ich nicht ein Ende machen, sondern dich mit Maßen* züchtigen und dich keineswegs ungestraft lassen.", footnotes: ["w. ist der Ausspruch des HERRN", "w. nach dem Recht"] },
    ]},
    { number: 47, verses: [
      { number: 1, text: "*Was als Wort des HERRN zu dem Propheten Jeremia geschah über* die Philister*, ehe der Pharao Gaza* schlug:", heading: "Ausspruch über die Philister: Eroberung ihrer Städte", footnotes: ["℘ Hes 25,15-17; Am 1,6-8; Zef 2,4-7", "o. gegen", "℘ Kap. 25,20", "℘ Apg 8,26"] },
      { number: 2, text: "So spricht der HERR: Siehe, Wasser steigt herauf von Norden her* und wird zu einem überschwemmenden Wildbach*. Und es überschwemmt das Land und seine Fülle, die Städte und ihre Bewohner. Und es schreien die Menschen um Hilfe, und alle Bewohner des Landes heulen", footnotes: ["℘ Kap. 6,22; 46,20", "℘ Kap. 46,7.8; Offb 17,15"] },
      { number: 3, text: "vor dem lauten Stampfen* der Hufe seiner starken Pferde, vor dem Getöse seiner Wagen, dem Rasseln seiner Räder* — Väter sehen sich nicht um nach den Söhnen, weil ihre Hände schlaff geworden sind* —,", footnotes: ["w. vor der Stimme, dem Laut des Stampfens", "℘ Jes 5,28; Nah 3,2", "w. vor Erschlaffung der Hände"] },
      { number: 4, text: "wegen des Tages, der kommt, um alle Philister zu vernichten und auch den letzten Helfer* für Tyrus und Sidon auszurotten. Denn der HERR vernichtet die Philister, den Rest, der von der Insel Kaftor* gekommen ist.", footnotes: ["w. jedem hilfebringenden Entkommenen", "℘ 1Mo 10,14; Am 9,7"] },
      { number: 5, text: "Kahlheit ist über Gaza gekommen, vernichtet ist Aschkelon*. Du Rest der Enakiter*, wie lange willst du dich ritzen*? —", footnotes: ["℘ Sach 9,5", "so mit LXX mit Jos 11,23; Mas. T.: ihrer Talebene", "℘ Kap. 16,6; 1Kö 18,28"] },
      { number: 6, text: "Wehe! Schwert des HERRN, wie lange noch willst du nicht Ruhe geben*? Fahre zurück in deine Scheide, halte dich ruhig und bleibe still!", footnotes: ["℘ Kap. 12,12"] },
      { number: 7, text: "Wie sollte es ruhig bleiben, da doch der HERR ihm geboten hat*? Gegen Aschkelon und gegen die Küste des Meeres, dorthin hat er es bestellt.", footnotes: ["℘ Hes 14,17; 21,9.10.14"] },
    ]},
    { number: 48, verses: [
      { number: 1, text: "*Über Moab*: So spricht der HERR der Heerscharen, der Gott Israels: Wehe über Nebo*! Denn es ist verwüstet. Zuschanden geworden, eingenommen ist Kirjatajim*; zuschanden geworden ist die Felsenburg und schreckerfüllt*.", heading: "Ausspruch über Moab: Verwüstung als Strafe für Götzendienst, für Hochmut und Spott über Israel", footnotes: ["℘ 4Mo 24,17; Jes 15; 16; Hes 25,8-11; Am 2,1-3; Zef 2,8-11", "℘ Kap. 25,21", "℘ 4Mo 32,3", "℘ 1Mo 14,5; 4Mo 32,37", "o. zerbrochen\n℘ Jes 25,12"] },
      { number: 2, text: "Moabs Ruhm ist dahin. In Heschbon* hat man Böses gegen es geplant: »Kommt und lasst es uns ausrotten, dass es keine Nation mehr ist!« Auch du, Madmen, wirst vernichtet werden; das Schwert läuft hinter dir her.", footnotes: ["Zur Zeit Jeremias gehörte Heschbon den Ammonitern (vgl. Kap. 49,3).\n℘ 4Mo 21,26"] },
      { number: 3, text: "Horch! Ein Geschrei aus Horonajim: Verwüstung und großer Zusammenbruch!" },
      { number: 4, text: "Moab ist zerbrochen, seine Geringen haben ein lautes Geschrei erhoben." },
      { number: 5, text: "Denn die Anhöhe* von Luhit steigt man mit Weinen hinauf, mit Weinen; ja, am Abhang* von Horonajim hat man Angstgeschrei über den Zusammenbruch gehört.", footnotes: ["w. den Aufgang", "o. Abstieg"] },
      { number: 6, text: "Flieht, rettet euer Leben* und werdet wie ein Wacholderstrauch* in der Wüste*!", footnotes: ["℘ Kap. 51,6; 1Mo 19,17", "Andere nehmen hier einen Abschreibfehler an und üs.: Wildesel", "℘ Kap. 17,6"] },
      { number: 7, text: "Denn weil du auf deine Werke und auf deine Schätze vertrautest*, sollst auch du eingenommen werden. Und Kemosch* wird in die Gefangenschaft* ziehen, seine Priester zusammen mit seinen Obersten*.", footnotes: ["℘ 1Tim 6,17", "d. i. die Hauptgottheit der Moabiter\n℘ Ri 11,24", "w. in die Wegführung", "℘ Kap. 49,3.4; Jes 46,1.2"] },
      { number: 8, text: "Und der Verwüster wird über jede Stadt kommen, und keine Stadt wird entrinnen. Und das Tal wird zugrunde gehen und die Hochebene vernichtet werden, wie der HERR gesprochen hat." },
      { number: 9, text: "Gebt Moab Flügel, denn eilend wird es fliehen. Und seine Städte werden zur Wüste* werden, so dass niemand darin wohnt.", footnotes: ["o. zum Schreckensort"] },
      { number: 10, text: "Verflucht sei, wer das Werk des HERRN lässig treibt, und verflucht, wer sein Schwert vom Blut zurückhält*!", footnotes: ["℘ Jos 10,19; Ri 5,23"] },
      { number: 11, text: "Sorglos war Moab von seiner Jugend an, und still lag es auf seinen Weinhefen* und wurde nie umgegossen von Fass zu Fass, und in die Gefangenschaft* ist es nie gezogen. Daher ist sein Geschmack ihm geblieben, und sein Geruch hat sich nicht verändert.", footnotes: ["℘ Zef 1,12", "w. in die Wegführung"] },
      { number: 12, text: "Darum siehe, Tage kommen, spricht der HERR*, da ich ihm Küfer senden werde, die es umfüllen* und seine Fässer ausleeren und seine* Krüge zerschmettern werden.", footnotes: ["w. ist der Ausspruch des HERRN", "w. seine Stürzer senden werde, die es umstürzen", "so mit einer griech. Üs.; Mas. T.: ihre"] },
      { number: 13, text: "Und Moab wird zuschanden werden an Kemosch*, wie das Haus Israel zuschanden geworden ist an Bethel*, seiner Zuversicht.", footnotes: ["℘ 2Chr 25,15; Jes 16,12; 45,20", "℘ 1Kö 12,29; Am 5,5"] },
      { number: 14, text: "Wie sagt ihr: Wir sind Helden und tapfere Männer für den Kampf?" },
      { number: 15, text: "Moab ist verwüstet, und seine Städte hat man erstiegen, und die Auslese seiner jungen Männer ist zur Schlachtung hinabgestiegen*, spricht der König*; HERR der Heerscharen ist sein Name*.", footnotes: ["℘ Jes 40,30", "w. ist der Ausspruch des Königs", "℘ Kap. 46,18; 50,34"] },
      { number: 16, text: "Moabs Verderben steht nahe bevor und sein Unheil eilt schnell herbei." },
      { number: 17, text: "Bekundet ihm euer Beileid*, ihr, seine Nachbarn alle, und alle, die ihr seinen Namen kennt! Sagt: Wie ist zerbrochen das Zepter der Macht, der Stab der Majestät*!", footnotes: ["w. Schüttelt seinetwegen den Kopf zum Zeichen der Trauer", "℘ Jes 14,4-6"] },
      { number: 18, text: "Steige herab von der Herrlichkeit und wohne in der Dürre*, du Bewohnerin, Tochter Dibons*! Denn Moabs Verwüster ist gegen dich heraufgezogen, hat deine Festungen zerstört.", footnotes: ["w. im Durst. — Andere üs. mit geringfügiger Textänderung: im Kot", "℘ 4Mo 21,30"] },
      { number: 19, text: "Stelle dich auf die Straße und halte Ausschau, Bewohnerin von Aroër*! Frage den Flüchtling und die Entkommenen! Sprich: Was ist geschehen?", footnotes: ["℘ Ri 11,26"] },
      { number: 20, text: "Moab ist zuschanden geworden, ja, es ist schreckerfüllt. Heult und schreit um Hilfe, verkündet am Arnon, dass Moab verwüstet ist!" },
      { number: 21, text: "Und das Gericht ist gekommen über das Land der Hochebene, über Holon und über Jahaz und über Mefaat*", footnotes: ["℘ 4Mo 32,38; Jos 13,17.18"] },
      { number: 22, text: "und über Dibon und über Nebo und über Bet-Diblatajim*", footnotes: ["℘ 4Mo 33,46"] },
      { number: 23, text: "und über Kirjatajim und über Bet-Gamul und über Bet-Meon*", footnotes: ["℘ 4Mo 32,38; Jos 13,17.18"] },
      { number: 24, text: "und über Kerijot und über Bozra* und über alle Städte des Landes Moab, die fernen und die nahen.", footnotes: ["℘ Kap. 49,13; Jes 63,1"] },
      { number: 25, text: "Das Horn Moabs ist abgehauen*, und sein Arm ist zerschmettert*, spricht der HERR*.", footnotes: ["℘ Ps 75,11; Sach 2,1-4", "℘ Ps 37,17; Hes 30,21", "w. ist der Ausspruch des HERRN"] },
      { number: 26, text: "Macht es betrunken* — denn gegen den HERRN hat es großgetan* —, damit Moab hineinschlägt in sein Erbrochenes* und auch selbst zum Gelächter wird!", footnotes: ["℘ Kap. 25,15-17", "℘ Kap. 50,29; Hi 15,25", "℘ Jes 19,14"] },
      { number: 27, text: "Oder war dir Israel nicht zum Gelächter? Ist es etwa unter Dieben ertappt worden, dass du, sooft du von ihm sprichst, den Kopf schüttelst?" },
      { number: 28, text: "Verlasst die Städte und wohnt in den Felsen, ihr Bewohner von Moab, und seid wie die Taube, die an den Rändern des Abgrundes nistet*!", footnotes: ["℘ Kap. 49,8; Hl 2,14"] },
      { number: 29, text: "Vernommen haben wir den Hochmut Moabs, des sehr hochmütigen, seinen Stolz und seinen Hochmut und seinen Dünkel und das Großtun* seines Herzens.", footnotes: ["o. Hochmut; w. Höhe"] },
      { number: 30, text: "Ich kenne wohl seine Überheblichkeit, spricht der HERR*, und sein unaufrichtiges Geschwätz*; unaufrichtig haben sie gehandelt.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Ps 75,6"] },
      { number: 31, text: "Darum jammere ich über Moab, und wegen ganz Moab schreie ich um Hilfe; über die Leute von Kir-Heres* seufzt man.", footnotes: ["℘ 2Kö 3,25"] },
      { number: 32, text: "Mehr als über* Jaser* weine ich über dich, du Weinstock von Sibma*. Deine Ranken gingen über das Meer, sie reichten bis zum Meer von Jaser. Über dein Sommerobst und deinen Ernteertrag* ist der Verwüster hergefallen,", footnotes: ["w. Mehr als mit dem Weinen um", "℘ 4Mo 32,1.3.38", "℘ Kap. 50,29; Hi 15,25", "so mit 11 hebr. Handschr.; Mas. T.: deine Boten, o. Götzen"] },
      { number: 33, text: "und verschwunden sind Freude und Jubel aus dem Fruchtgarten und aus dem Land Moab. Und den Wein aus den Kelterkufen habe ich verschwinden lassen: man tritt nicht mehr die Kelter unter Jubelruf; der laute Ruf ist kein Jubelruf*.", footnotes: ["d. h. der Jubelruf (w. der laute Ruf ) der Keltertreter hat sich in den Schlachtruf des Verwüsters (V. 32) verwandelt.\n℘ Joe 1,12"] },
      { number: 34, text: "Vom Geschrei Heschbons an bis Elale, bis Jahaz* haben sie ihre Stimme erhoben, von Zoar bis Horonajim, bis Eglat-Schelischija; denn auch das Wasser von Nimrim soll zu Wüsten werden.", footnotes: ["viell.: Er kommt vom Geschrei Heschbons. Bis Elale, bis Jahaz"] },
      { number: 35, text: "Und ich beseitige von Moab, spricht der HERR*, den, der auf eine Höhe steigt und seinen Göttern Rauchopfer darbringt.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 36, text: "Deshalb klagt wie Flötenklage mein Herz um Moab und klagt wie Flötenklage mein Herz um die Leute von Kir-Heres*. Deshalb sind die Ersparnisse, die es gemacht hat, auch verloren.", footnotes: ["℘ 2Kö 3,25"] },
      { number: 37, text: "Ja, jedes Haupt ist kahl und jeder Bart abgeschoren. Auf allen Händen sind Ritzwunden*, und Sacktuch ist an den Hüften.", footnotes: ["℘ Kap. 16,6"] },
      { number: 38, text: "Auf allen Dächern Moabs und auf seinen Plätzen ist lauter Klage. Denn ich habe Moab zerbrochen wie ein Gefäß, an dem man kein Gefallen hat*, spricht der HERR*.", footnotes: ["℘ Kap. 22,28; Jes 30,14", "w. ist der Ausspruch des HERRN"] },
      { number: 39, text: "Wie ist es schreckerfüllt! Heult*! Wie hat Moab den Rücken gewendet, ist zuschanden geworden*! Und allen seinen Nachbarn wird Moab zum Gelächter und zum Schrecken sein.", footnotes: ["o. Wie heulen sie", "w. den Rücken gewandt, ist beschämt worden"] },
      { number: 40, text: "Denn so spricht der HERR: Siehe, wie der Adler fliegt er daher und breitet seine Flügel aus über Moab*.", footnotes: ["℘ Kap. 4,13; 49,22"] },
      { number: 41, text: "Kerijot ist eingenommen, und die Festungen sind erobert. Und das Herz der Helden Moabs wird an jenem Tag sein wie das Herz einer Frau in Kindesnöten*.", footnotes: ["℘ Kap. 6,24; 49,24"] },
      { number: 42, text: "Und Moab wird ausgetilgt werden, dass es kein Volk mehr ist, weil es großgetan hat gegen den HERRN*.", footnotes: ["℘ Ps 83,6.7"] },
      { number: 43, text: "Grauen und Grube und Garn über dich, du Bewohner von Moab!, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 44, text: "Wer vor dem Grauen flieht, wird in die Grube fallen, und wer aus der Grube heraufsteigt, wird im Garn gefangen*. Denn ich bringe über sie*, über Moab, das Jahr ihrer Heimsuchung*, spricht der HERR*.", footnotes: ["℘ Jes 24,17.18", "w. über es", "℘ Kap. 23,12; 46,21; 49,8", "w. ist der Ausspruch des HERRN"] },
      { number: 45, text: "Im Schatten Heschbons bleiben Flüchtlinge erschöpft stehen. Denn ein Feuer ist ausgegangen von Heschbon und eine Flamme mitten aus Sihon* und hat die Schläfe Moabs verzehrt und den Scheitel der Söhne des Lärms*.", footnotes: ["5 hebr. Handschr. lesen: eine Flamme aus Sihons Haus", "℘ 4Mo 21,28.29"] },
      { number: 46, text: "Wehe dir, Moab! Verloren ist das Volk des Kemosch*! Denn deine Söhne sind in die Gefangenschaft weggeführt und deine Töchter in die Verbannung. —", footnotes: ["℘ Ri 11,24"] },
      { number: 47, text: "Aber ich werde die Gefangenschaft Moabs wenden am Ende der Tage*, spricht der HERR*. Bis hierher geht das Gerichtswort über Moab*.", footnotes: ["℘ Kap. 49,6.39; Jes 45,20", "w. ist der Ausspruch des HERRN", "℘ Jes 25,11"] },
    ]},
    { number: 49, verses: [
      { number: 1, text: "*Über die Söhne Ammon*: So spricht der HERR: Hat denn Israel keine Söhne, oder hat es keinen Erben? Warum hat ihr König* Gad in Besitz genommen, und warum wohnt sein Volk in dessen Städten?", heading: "Ausspruch über die Söhne Ammon: Strafe wegen Feindschaft gegen Israel", footnotes: ["℘ Hes 21,33-37; 25,1-7; Am 1,13-15; Zef 2,8-11", "℘ Kap. 25,21", "hebr. melech; wohl zugleich eine Anspielung auf den Götzen Milhan (Molech); so auch V. 3"] },
      { number: 2, text: "Darum siehe, Tage kommen, spricht der HERR*, da werde ich gegen das Rabba der Söhne Ammon* Kriegsgeschrei erschallen lassen. Und es soll zum Schutthaufen* werden, und seine Tochterstädte sollen mit Feuer verbrannt werden. Und Israel wird seine Erben beerben*, spricht der HERR.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ 5Mo 3,11; Hes 21,25", "w. zum Hügel der Öde", "℘ Jes 11,14; 14,2"] },
      { number: 3, text: "Heule, Heschbon, denn Ai ist verwüstet! Schreit, ihr Töchter von Rabba, gürtet euch Sacktuch um! Klagt* und lauft hin und her innerhalb der Viehhürden*! Denn ihr König* wird in die Gefangenschaft* gehen, seine Priester und Obersten miteinander*.", footnotes: ["℘ Jes 15,2-4", "o. innerhalb der Stadtmauern; o. mit Änderung eines Buchstabens: lauft hin und her mit Ritzwunden", "hebr. melech; wohl zugleich eine Anspielung auf den Götzen Milhan (Molech); so auch V. 3", "w. Wegführung", "℘ Kap. 48,7"] },
      { number: 4, text: "Was rühmst du dich der Täler*, und dass dein Tal überfließt, du abtrünnige Tochter, die auf ihre Schätze vertraut*: »Wer sollte an mich herankommen*?«", footnotes: ["℘ Kap. 21,13", "℘ Kap. 48,7", "℘ Kap. 48,7"] },
      { number: 5, text: "Siehe, ich lasse Schrecken über dich kommen von all deinen Nachbarn*, spricht der Herr, der HERR* der Heerscharen: Und ihr sollt vertrieben werden, jeder für sich, und niemand wird die Flüchtigen sammeln. —", footnotes: ["℘ V. 29", "w. ist der Ausspruch des Herrn, des HERRN"] },
      { number: 6, text: "Aber nachher werde ich das Geschick der Söhne Ammon wenden*, spricht der HERR*.", footnotes: ["℘ V. 39; Kap. 48,47", "w. ist der Ausspruch des HERRN"] },
      { number: 7, text: "*Über Edom*: So spricht der HERR der Heerscharen: Ist keine Weisheit mehr in Teman?* Ist den Verständigen der Rat verloren gegangen, ist ihre Weisheit verdorben?*", heading: "Ausspruch über Edom: Strafe wegen Vermessenheit", footnotes: ["℘ (Jes 21,11.12); Jes 34,5-17; Kla 4,21.22; Hes 25,12-14; 35; Am 1,11.12; Ob", "℘ Kap. 25,21; Ps 137,7; Mal 1,3.4", "℘ Hi 4,1; Hab 3,3", "℘ Hi 5,12.13; Jes 29,14"] },
      { number: 8, text: "Flieht, wendet euch zur Flucht, verkriecht euch tief, Bewohner von Dedan*! Denn Esaus Verderben habe ich über ihn gebracht, die Zeit, da ich ihn heimsuche*.", footnotes: ["℘ Kap. 25,23; 48,28; Jes 21,13", "℘ Kap. 48,44"] },
      { number: 9, text: "Wenn Winzer über dich kommen, werden sie keine Nachlese übrig lassen — wenn Diebe in der Nacht, so vernichten sie euch, bis sie genug haben." },
      { number: 10, text: "Denn ich, ich habe Esau entblößt, ich habe seine Verstecke aufgedeckt. Und will er sich verbergen, kann er es nicht*. Vernichtet ist seine Nachkommenschaft und seine Brüder und seine Nachbarn, sie sind nicht mehr.", footnotes: ["℘ Kap. 23,24"] },
      { number: 11, text: "Verlass deine Waisen, ich nur werde sie am Leben erhalten — und deine Witwen sollen auf mich vertrauen*!", footnotes: ["℘ 5Mo 10,18; 1Tim 5,5"] },
      { number: 12, text: "Denn so spricht der HERR: Siehe, die nicht verurteilt waren, den Becher zu trinken, die müssen ihn trinken. Und du solltest der sein, der ungestraft bleibt? Du wirst nicht ungestraft bleiben, sondern du sollst ihn ganz trinken*.", footnotes: ["℘ Kap. 25,28.29; Kla 4,21"] },
      { number: 13, text: "Denn ich habe bei mir geschworen*, spricht der HERR*, dass Bozra zum Entsetzen, zur Schmach, zur Verwüstung und zum Fluch werden soll* und alle seine Städte zu ewigen Trümmerstätten.", footnotes: ["℘ Kap. 44,26", "w. ist der Ausspruch des HERRN", "℘ Kap. 48,24"] },
      { number: 14, text: "Eine Kunde habe ich vom HERRN vernommen, und ein Bote ist unter die Nationen gesandt: Sammelt euch und kommt gegen es* und macht euch auf zum Krieg!", footnotes: ["d. i. Edom"] },
      { number: 15, text: "Denn siehe, ich habe dich klein gemacht unter den Nationen, verachtet unter den Menschen." },
      { number: 16, text: "Deine Furchtbarkeit*, der Übermut deines Herzens haben dich getäuscht*, dich, der in den Schlupfwinkeln der Felsen wohnt, den Gipfel des Hügels besetzt hält. Wenn du dein Nest hoch baust wie der Adler*, ich werde dich von dort hinabstürzen*, spricht der HERR*.", footnotes: ["d. i. deine furchterweckende Macht", "o. betrogen; o. verführt", "℘ Hi 39,27.28", "℘ Kap. 51,53; Am 9,2", "w. ist der Ausspruch des HERRN"] },
      { number: 17, text: "Und Edom soll zum Entsetzen werden. Jeder, der an ihm vorüberzieht, wird sich entsetzen und zischen* über all seine Wunden*.", footnotes: ["o. pfeifen; als Ausdruck der Verachtung oder der Furcht\n℘ Kap. 18,16", "o. Plagen\n℘ Kap. 50,13"] },
      { number: 18, text: "Wie nach der Umkehrung von Sodom und Gomorra und ihrer Nachbarstädte, spricht der HERR, wird niemand dort wohnen und kein Menschenkind sich darin aufhalten*.", footnotes: ["℘ V. 33; Kap. 50,40; 5Mo 29,22; Jes 34,10"] },
      { number: 19, text: "*Siehe, wie ein Löwe* steigt er von der Pracht* des Jordan* herauf zum Weideplatz am immerfließenden Bach. Ja, ich werde es* plötzlich daraus vertreiben* und den, der auserkoren ist,* über es* bestellen*. Denn wer ist mir gleich, und wer will mich vorladen*? Und wer ist der Hirte, der vor mir bestehen könnte*?", footnotes: ["℘ V. 19-21: Kap. 50,44-46", "℘ Kap. 4,7", "Gemeint ist das Dickicht am Jordan.", "℘ Kap. 12,5; Sach 11,3", "d. i. Edom", "w. ich werde es im Nu zum Laufen bringen", "T.; Mas. T.: und wer ist ein junger Mann?", "T.; Mas. T.: und wer ist ein junger Mann?", "℘ Kap. 25,9", "d. h. vor Gericht", "℘ 2Chr 20,6; Ps 76,8"] },
      { number: 20, text: "Darum hört den Ratschluss des HERRN, den er über Edom beschlossen hat, und seine Gedanken, die er über die Bewohner von Teman denkt*: Wahrlich, man wird sie fortschleppen, auch die Geringen der Herde*; wahrlich, ihr Weideplatz* wird sich über sie entsetzen!", footnotes: ["o. seine Pläne, die er . . . plant", "Andere üs.: die Geringen der Herde werden sie fortschleppen", "o. ihre Wohnstätte"] },
      { number: 21, text: "Von dem Getöse ihres Falles erbebt die Erde*; Geschrei — noch am Schilfmeer wird sein Schall vernommen.", footnotes: ["℘ Hes 26,15"] },
      { number: 22, text: "Siehe, wie der Adler zieht er herauf und fliegt und breitet seine Flügel aus über Bozra. Und das Herz der Helden Edoms wird an jenem Tag sein wie das Herz einer Frau in Kindesnöten*.", footnotes: ["℘ Kap. 48,40.41"] },
      { number: 23, text: "*Über Damaskus: Zuschanden geworden sind Hamat und Arpad*; denn sie haben eine böse Nachricht vernommen. *Sie verzagen. Am Meer ist Besorgnis, man* kann sich nicht beruhigen*.", heading: "Ausspruch über Damaskus: Angst, Tod und Feuersbrunst", footnotes: ["℘ Jes 17,1-11; Am 1,3-5", "℘ 2Kö 18,34; Jes 10,9; Sach 9,1.2", "Andere üs. mit Textänderung: Ihr Herz bebt vor Sorge, es", "Andere üs. mit Textänderung: Ihr Herz bebt vor Sorge, es", "℘ Jes 57,20"] },
      { number: 24, text: "Damaskus ist schlaff geworden. Es hat sich umgewandt, um zu fliehen, und Schrecken hat es ergriffen. Angst und Wehen haben es erfasst wie eine Gebärende*.", footnotes: ["℘ Kap. 48,41; 50,43"] },
      { number: 25, text: "Wie ist sie verlassen*, die Stadt des Ruhms, die Stadt meiner Freude!", footnotes: ["so mit der lat. Üs.; Mas. T.: Wie ist sie nicht verlassen"] },
      { number: 26, text: "Darum werden an jenem Tag ihre jungen Männer auf ihren Plätzen fallen und alle Kriegsmänner umkommen, spricht der HERR* der Heerscharen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 50,30"] },
      { number: 27, text: "Und ich werde ein Feuer anzünden in den Mauern von Damaskus, und es wird die Paläste Ben-Hadads verzehren." },
      { number: 28, text: "*Über Kedar* und über die Königreiche Hazors, die Nebukadnezar, der König von Babel, schlug*: So spricht der HERR: Macht euch auf, zieht hinauf gegen Kedar und überwältigt die Söhne des Ostens*!", heading: "Ausspruch über Kedar und Hazor: Verwüstung durch Nebukadnezar", footnotes: ["℘ Jes 21,13-17", "℘ Kap. 2,10; 25,24; Ps 120,5", "℘ Kap. 25,23.24", "℘ Ri 6,3"] },
      { number: 29, text: "Ihre Zelte und ihre Schafe werden sie wegnehmen, ihre Zeltdecken und all ihre Geräte und ihre Kamele holen sie sich. Und sie werden über sie ausrufen: Schrecken ringsum*!", footnotes: ["℘ V. 5; Kap. 6,25"] },
      { number: 30, text: "Flieht, flüchtet schnell, verkriecht euch tief, Bewohner von Hazor!, spricht der HERR*. Denn Nebukadnezar, der König von Babel, hat einen Beschluss gegen euch gefasst und einen Anschlag* gegen euch geplant.", footnotes: ["w. ist der Ausspruch des HERRN", "w. Plan"] },
      { number: 31, text: "Macht euch auf, zieht hinauf gegen eine sorglose Nation, die in Sicherheit wohnt!, spricht der HERR*. Sie hat weder Tore noch Riegel, sie wohnen für sich*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Hes 38,11"] },
      { number: 32, text: "Und ihre Kamele sollen zum Raub und die Menge ihrer Herden zur Beute werden. Und ich werde sie, die mit geschorenen Haarrändern*, in alle Winde hin zerstreuen und werde ihnen von allen Seiten her Verderben bringen, spricht der HERR*.", footnotes: ["℘ Kap. 9,25", "w. ist der Ausspruch des HERRN"] },
      { number: 33, text: "Und Hazor wird zur Wohnung der Schakale werden*, zur Öde für ewig. Niemand wird sich dort niederlassen, und kein Menschenkind wird sich darin aufhalten*.", footnotes: ["℘ Jes 34,13.14", "℘ V. 18"] },
      { number: 34, text: "*Das Wort des HERRN, das zu Jeremia, dem Propheten, geschah* über* Elam* im Anfang der Regierung Zedekias, des Königs von Juda:", heading: "Ausspruch über Elam: Zerstreuung in alle Länder", footnotes: ["℘ Hes 32,24.25", "w. Was als Wort des HERRN zu dem Propheten Jeremia geschah", "o. gegen", "d. i. die persische Provinz, deren Hauptstadt Susa war\n℘ Kap. 25,25"] },
      { number: 35, text: "So spricht der HERR der Heerscharen: Siehe, ich zerbreche den Bogen Elams*, seine wesentliche Stärke*.", footnotes: ["℘ Jes 21,2; Ps 46,10", "w. den Anfang ihrer Stärke"] },
      { number: 36, text: "Und ich werde die vier Winde von den vier Enden des Himmels* her über Elam bringen und es in alle diese Winde zerstreuen. Und es soll keine Nation geben, wohin nicht Vertriebene Elams kommen werden.", footnotes: ["℘ Offb 7,1"] },
      { number: 37, text: "Und ich werde Elam verzagt machen vor seinen* Feinden und vor denen, die nach seinem* Leben trachten, und werde Unheil über sie bringen, die Glut meines Zorns, spricht der HERR*. Und ich werde das Schwert hinter ihnen herschicken, bis ich sie vernichtet habe*.", footnotes: ["w. ihren bzw. ihrem", "w. ihren bzw. ihrem", "w. ist der Ausspruch des HERRN", "℘ Kap. 9,15"] },
      { number: 38, text: "Und ich werde meinen Thron in Elam aufstellen* und werde König und Oberste daraus verloren geben, spricht der HERR*. —", footnotes: ["℘ Ps 9,5.9", "w. ist der Ausspruch des HERRN"] },
      { number: 39, text: "Aber es wird geschehen am Ende der Tage, da werde ich das Geschick Elams wenden*, spricht der HERR*.", footnotes: ["℘ V. 6", "w. ist der Ausspruch des HERRN"] },
    ]},
    { number: 50, verses: [
      { number: 1, text: "*Das Wort, das der HERR über Babel, über das Land der Chaldäer, durch den Propheten Jeremia geredet hat*:", heading: "Ausspruch über Babel: Sein Sturz und dessen Folgen für Israel und Juda", footnotes: ["℘ Kap. 51; Jes 13; 14; 21,1-10; 47,1-15", "℘ Kap. 25,12.26"] },
      { number: 2, text: "Verkündigt es unter den Nationen und lasst es hören und richtet ein Feldzeichen auf! Lasst es hören, verschweigt es nicht! Sagt: Babel ist eingenommen, Bel zuschanden geworden*, Merodach* schreckerfüllt! Ihre Götzenbilder sind zuschanden geworden*, ihre Götzen* sind schreckerfüllt!", footnotes: ["℘ Kap. 10,11; Jes 46,1", "Bel-Merodach war die Schutzgottheit Babylons.", "℘ Kap. 48,7", "w. ihre Klötze"] },
      { number: 3, text: "Denn gegen es ist eine Nation heraufgezogen von Norden her*: Die wird sein Land zur Wüste* machen, dass kein Bewohner mehr darin sein wird. Sowohl Menschen als Vieh sind entflohen, weggezogen*.", footnotes: ["℘ V. 9.41", "o. Stätte des Entsetzens", "℘ V. 39; Kap. 51,62"] },
      { number: 4, text: "In jenen Tagen und zu jener Zeit, spricht der HERR*, werden die Söhne Israel kommen, sie und die Söhne Juda zusammen*. Immerfort weinend* werden sie gehen und den HERRN, ihren Gott, suchen*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 3,18", "℘ Kap. 31,9", "℘ Kap. 29,12-14; 2Chr 7,14; Hos 3,5; 11,10"] },
      { number: 5, text: "Sie werden nach Zion fragen, auf den Weg dahin ist ihr Gesicht gerichtet: Kommt und schließt euch an den HERRN an in einem ewigen Bund*, der nicht vergessen wird!", footnotes: ["℘ Kap. 32,40"] },
      { number: 6, text: "Mein Volk war eine verloren gehende Schafherde*; ihre Hirten leiteten sie irre auf verführerische Berge*. Sie gingen von Berg zu Hügel, vergaßen ihre Lagerstätte*.", footnotes: ["℘ Ps 119,176; Jes 53,6; Hes 34,5.6; Mt 9,36; 10,6; 18,12; 1Petr 2,25", "Schreibform des Mas. T.: abtrünnige Berge; d. i. eine Anspielung auf den Höhenkultus", "℘ Kap. 23,1.2; Jes 1,3"] },
      { number: 7, text: "Alle, die sie fanden, fraßen sie*. Und ihre Gegner* sagten: Wir werden nicht schuldig! — deshalb, weil sie gegen den HERRN gesündigt haben*, die Weide der Gerechtigkeit*, und gegen den HERRN, die Hoffnung ihrer Väter*.", footnotes: ["℘ Ps 79,7", "o. Bedränger", "℘ Kap. 40,2.3; Sach 11,5", "℘ Kap. 31,23; 33,16", "℘ Kap. 14,8; Ps 22,5"] },
      { number: 8, text: "Flieht aus Babel hinaus und zieht aus dem Land der Chaldäer* und seid wie die Leitböcke vor den Schafen her!", footnotes: ["℘ Jes 48,20; Sach 2,11"] },
      { number: 9, text: "Denn siehe, ich erwecke und führe herauf gegen Babel eine Versammlung großer Nationen aus dem Land des Nordens*, und sie werden sich gegen es aufstellen; von dort aus wird es eingenommen werden. Ihre Pfeile sind wie die eines geschickten* Helden, keiner kehrt mit leeren Händen zurück*.", footnotes: ["℘ V. 3.41", "so mit 20 hebr. Handschr. und LXX; Mas. T.: eines kinderlosen", "o. eines . . . Helden, der nicht mit leeren Händen zurückkehrt; d. h. nicht ohne Beute\n℘ 2Sam 1,22"] },
      { number: 10, text: "Und Chaldäa wird zum Raub werden*. Alle, die es berauben, sollen satt werden, spricht der HERR*.", footnotes: ["℘ V. 37", "w. ist der Ausspruch des HERRN"] },
      { number: 11, text: "Ja, freut euch nur, ja, jubelt nur*, ihr Plünderer meines Erbteils, ja, hüpft nur wie eine dreschende junge Kuh* und wiehert wie starke Pferde!", footnotes: ["℘ Hab 1,15", "LXX und lat. Üs.: wie Kälber im Gras"] },
      { number: 12, text: "Sehr beschämt ist eure Mutter, in ihrer Hoffnung getäuscht, eure Gebärerin. Siehe, es* ist die letzte der Nationen, eine Wüste, eine Dürre und eine Steppe*.", footnotes: ["d. i. Chaldäa", "℘ V. 39; Kap. 51,62"] },
      { number: 13, text: "Vor dem Grimm des HERRN wird es nicht mehr bewohnt werden, sondern ganz und gar verödet bleiben*. Jeder, der an Babel vorüberzieht, wird sich entsetzen und zischen* über all seine Plagen*.", footnotes: ["w. wird eine vollständige Öde sein\n℘ Kap. 25,12", "o. pfeifen; als Ausdruck der Verachtung oder der Furcht", "o. Wunden\n℘ Kap. 18,16; Zef 2,15"] },
      { number: 14, text: "Stellt euch ringsum auf gegen Babel, alle, die ihr den Bogen spannt*! Schießt nach ihm, spart die Pfeile nicht! Denn gegen den HERRN hat es gesündigt*.", footnotes: ["℘ V. 7.29", "℘ V. 39; Kap. 51,62"] },
      { number: 15, text: "Erhebt das Kriegsgeschrei gegen es ringsum! Es hat sich ergeben*. Gefallen sind seine Festungswerke, niedergerissen seine Mauern. Denn es ist die Rache des HERRN*. Rächt euch an ihm! So wie es getan hat, tut ihm*!", footnotes: ["w. Es hat seine Hand gegeben; d. h. als Zeichen der Unterwerfung; vgl. 1Chr 29,24; 2Chr 30,8", "℘ V. 28; Jes 63,4; Nah 1,2", "℘ V. 29; Jes 59,18; Offb 18,6"] },
      { number: 16, text: "Rottet aus Babel den Sämann aus und den, der die Sichel führt zur Erntezeit! Vor dem gewalttätigen Schwert werden sie sich jeder zu seinem Volk wenden und jeder in sein Land fliehen." },
      { number: 17, text: "Israel ist ein versprengtes Schaf, das Löwen verscheucht haben. Zuerst hat der König von Assur es gefressen*, und nun zuletzt hat Nebukadnezar, der König von Babel, ihm die Knochen abgenagt*.", footnotes: ["℘ 2Kö 17,6", "o. zerbrochen\n℘ Kap. 21,7; 51,34"] },
      { number: 18, text: "Darum, so spricht der HERR der Heerscharen, der Gott Israels: Siehe, ich suche heim den König von Babel und sein Land, ebenso wie ich den König von Assur heimgesucht habe*.", footnotes: ["℘ 5Mo 32,41; Jes 10,12; Hab 2,8"] },
      { number: 19, text: "Und ich will Israel zu seinem Weideplatz zurückbringen*, dass es auf dem Karmel und in Baschan weidet und seine Seele sich sättigt auf dem Gebirge Ephraim und in Gilead*.", footnotes: ["℘ Kap. 23,3; 33,12", "℘ Kap. 33,12; 4Mo 32,1.4; Hes 34,13; Mi 7,14"] },
      { number: 20, text: "In jenen Tagen und zu jener Zeit, spricht der HERR*, wird Israels Schuld gesucht werden, und sie wird nicht da sein — und die Sünden Judas, und sie werden nicht gefunden werden*; denn ich will denen vergeben, die ich übrig lasse*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ Kap. 31,34; 33,8; Ps 103,12; Jes 43,25; 44,22; Kla 4,22; Sach 3,9", "℘ Ps 85,3; Jes 10,21; 33,24; Zef 3,12"] },
      { number: 21, text: "Gegen das Land Meratajim*, gegen es ziehe hinauf und gegen die Bewohner von Pekod*! Mache sie nieder und vollstrecke den Bann hinter ihnen her, spricht der HERR*, und tu nach allem, was ich dir geboten habe*!", footnotes: ["d. h. Doppelte Bitterkeit", "d. h. Heimsuchung", "w. ist der Ausspruch des HERRN", "℘ 5Mo 33,27; Jes 48,14"] },
      { number: 22, text: "Kriegslärm im Land und großer Zusammenbruch!" },
      { number: 23, text: "Wie ist zerhauen und zertrümmert der Hammer der ganzen Erde! Wie ist Babel zum Entsetzen geworden unter den Nationen!" },
      { number: 24, text: "Ich habe dir eine Falle gestellt*, und du bist auch gefangen worden, Babel, ohne dass du es erkannt hast. Du bist gefunden und auch gefasst, weil du Krieg mit dem HERRN angefangen hast*.", footnotes: ["w. dich wie einen Vogel mit dem Stellholz gefangen", "℘ Hi 15,25"] },
      { number: 25, text: "Der HERR hat seine Rüstkammer* aufgetan und die Waffen seines Grimms hervorgeholt; denn Arbeit gibt es für den Herrn, den HERRN der Heerscharen, im Land der Chaldäer*.", footnotes: ["w. seine Vorräte", "℘ Jes 13,5"] },
      { number: 26, text: "Kommt über es vom äußersten Ende*, öffnet seine Scheunen, schüttet es auf wie Garbenhaufen und vollstreckt den Bann an ihm! Nicht bleibe ihm ein Rest!", footnotes: ["o. ohne Ende; andere mit einer griech. Üs.: ohne Ausnahme"] },
      { number: 27, text: "Stecht alle seine Stiere nieder*, zur Schlachtung sollen sie hinsinken*! Wehe über sie! Denn ihr Tag ist gekommen, die Zeit ihrer Heimsuchung*.", footnotes: ["w. Macht . . . nieder", "℘ Jes 34,6.7", "℘ Kap. 27,7; 46,21"] },
      { number: 28, text: "Horch! Flüchtlinge und Entkommene aus dem Land Babel, um in Zion zu verkünden die Rache des HERRN, unseres Gottes, die Rache seines Tempels!*", footnotes: ["℘ V. 15; Dan 5,23.30"] },
      { number: 29, text: "Ruft Schützen herbei gegen Babel, alle, die den Bogen spannen*! Belagert es ringsum, niemand darf entkommen! Vergeltet ihm nach seinem Tun, tut ihm nach allem, was es getan hat*! Denn es hat vermessen gehandelt gegen den HERRN, gegen den Heiligen Israels*.", footnotes: ["℘ V. 14", "℘ V. 15; Kap. 25,14; Ps 137,8; Mt 7,2", "℘ V. 14.24; Kap. 48,26; Kla 1,9"] },
      { number: 30, text: "Darum sollen seine jungen Männer auf seinen Plätzen fallen und alle seine Kriegsmänner umkommen an jenem Tag*, spricht der HERR*.", footnotes: ["℘ Kap. 49,26", "w. ist der Ausspruch des HERRN"] },
      { number: 31, text: "Siehe, ich will an dich, du Stolze*, spricht der Herr, HERR* der Heerscharen. Denn gekommen ist dein Tag, die Zeit, da ich dich heimsuche*.", footnotes: ["im Hebr. hier als Eigenname: Stolz, o. Übermut", "w. ist der Ausspruch des Herrn, des HERRN", "℘ Jes 2,12"] },
      { number: 32, text: "Dann wird die Stolze* stürzen und fallen, und niemand wird sie aufrichten. Und ich werde ein Feuer anzünden in ihren Städten, dass es ihre ganze Umgebung frisst*.", footnotes: ["im Hebr. hier als Eigenname: Stolz, o. Übermut", "℘ Spr 16,18"] },
      { number: 33, text: "So spricht der HERR der Heerscharen: Die Söhne Israel und die Söhne Juda sind alle zusammen Unterdrückte. Und alle, die sie gefangen weggeführt, haben sie festgehalten, haben sich geweigert, sie loszulassen*.", footnotes: ["℘ Sach 1,15"] },
      { number: 34, text: "Ihr Erlöser ist stark*, HERR der Heerscharen ist sein Name*. Er wird ihre Rechtssache bestimmt führen*, um dem Land Ruhe zu verschaffen, aber den Bewohnern von Babel Unruhe*.", footnotes: ["℘ Hi 19,25; Spr 23,11; Offb 18,8", "℘ Kap. 10,16; 48,15", "℘ 2Chr 6,39; Spr 22,23; Jes 51,22; Kla 3,58", "℘ Kap. 30,20"] },
      { number: 35, text: "Das Schwert über die Chaldäer, spricht der HERR*, und über die Bewohner von Babel und über seine Obersten und über seine Weisen!", footnotes: ["w. ist der Ausspruch des HERRN"] },
      { number: 36, text: "Das Schwert über die Orakelpriester, dass sie zu Toren werden!* Das Schwert über seine Helden, dass sie schreckerfüllt sind!", footnotes: ["℘ Jes 44,25"] },
      { number: 37, text: "Das Schwert über seine Pferde und über seine Wagen und über das ganze Mischvolk, das in seiner Mitte ist, dass sie zu Weibern werden!* Das Schwert über seine Schätze, dass sie geplündert werden*!", footnotes: ["℘ Nah 3,13", "℘ V. 10"] },
      { number: 38, text: "Dürre über seine Gewässer, dass sie austrocknen*! Denn es ist ein Land der geschnitzten Bilder, und durch ihre Schreckbilder werden sie toll.", footnotes: ["℘ Jes 44,27; Offb 16,12"] },
      { number: 39, text: "Darum werden Wüstentiere mit wilden Hunden darin wohnen, und Strauße werden darin wohnen. Und es soll in Ewigkeit nicht mehr bewohnt werden und keine Wohnstätte sein von Generation zu Generation*.", footnotes: ["℘ V. 3; Offb 18,2"] },
      { number: 40, text: "Wie nach der Umkehrung Sodoms und Gomorras und ihrer Nachbarstädte durch Gott*, spricht der HERR*, wird niemand dort wohnen, und kein Menschenkind wird sich darin aufhalten*.", footnotes: ["℘ Am 4,11", "w. ist der Ausspruch des HERRN", "℘ Kap. 49,18"] },
      { number: 41, text: "Siehe, ein Volk kommt von Norden her, und eine große Nation und viele Könige machen sich auf* vom äußersten Ende der Erde*.", footnotes: ["w. regen sich", "℘ V. 3.9"] },
      { number: 42, text: "Bogen und Kurzschwert führen sie, sie sind grausam und ohne Erbarmen. Ihre Stimme braust wie das Meer, und auf Pferden reiten sie: gerüstet gegen dich, Tochter Babel, wie ein Mann zum Krieg*.", footnotes: ["℘ Kap. 6,22.23"] },
      { number: 43, text: "Der König von Babel hat die Nachricht von ihnen vernommen, und seine Hände sind schlaff geworden*. Angst hat ihn ergriffen, Wehen wie bei der Gebärenden*.", footnotes: ["℘ Dan 5,5.6", "℘ Kap. 49,22.24"] },
      { number: 44, text: "Siehe, wie ein Löwe steigt er von der Pracht* des Jordan* herauf zum Weideplatz am immerfließenden Bach. Ja, ich werde sie* plötzlich daraus vertreiben und den, der auserkoren ist*, über es* bestellen*. Denn wer ist mir gleich, und wer will mich vorladen? Und wer ist der Hirte, der vor mir bestehen könnte?", footnotes: ["w. von dem Hohen; d. i. das Dickicht am Jordan", "℘ Kap. 12,5", "d. h. die Babylonier", "T.; Mas. T.: und wer ein junger Mann ist", "d. i. Babel", "℘ Jes 46,11; 48,14.15"] },
      { number: 45, text: "Darum hört den Ratschluss des HERRN, den er über Babel beschlossen hat, und seine Gedanken, die er über das Land der Chaldäer denkt*: Wahrlich, man wird sie fortschleppen, auch die Geringen der Herde*! Wahrlich, der Weideplatz* wird sich über sie entsetzen!", footnotes: ["o. seine Pläne, die er . . . plant", "Andere üs.: die Geringen der Herde werden sie fortschleppen", "o. ihre Wohnstätte"] },
      { number: 46, text: "Von dem Ruf: Babel ist erobert!, erzittert die Erde. Ein Geschrei wird unter den Nationen vernommen*.", footnotes: ["℘ Kap. 49,19-21; Offb 18,9.10"] },
    ]},
    { number: 51, verses: [
      { number: 1, text: "*So spricht der HERR: Siehe, ich erwecke gegen Babel und gegen die, die im Herzen meiner Widersacher* wohnen, einen Geist des Verderbens*.", heading: "Ausspruch über Babel: Seine Macht und sein Sturz, seine Schuld und Strafe", footnotes: ["℘ V. 1-58: Kap. 50; Jes 13; 14; 21,1-10; 47,1-15", "hebr. leb kamai; durch eine künstliche Buchstabenversetzung des Wortes Kasdim soll damit das Land Chaldäa bezeichnet werden; vgl. Kap. 25,26", "o. Verderben bringenden Wind\n℘ Kap. 4,11.12"] },
      { number: 2, text: "Und ich sende nach Babel Fremde*, die es worfeln* und sein Land ausleeren werden. Denn sie werden ringsumher gegen es vorgehen am Tag des Unheils.", footnotes: ["LXX und die lat. Üs.: Worfler", "o. zerstreuen\n℘ Kap. 15,7; Jes 41,16; 43,14"] },
      { number: 3, text: "Der Schütze spanne seinen Bogen gegen den, der da spannt, und gegen den, der sich in seinem Panzer erhebt! Und habt kein Mitleid mit seinen jungen Männern, vollstreckt den Bann an seinem ganzen Heer!*", footnotes: ["℘ V. 53"] },
      { number: 4, text: "Und Erschlagene sollen fallen im Land der Chaldäer und Durchbohrte auf seinen Straßen*.", footnotes: ["℘ V. 53"] },
      { number: 5, text: "Denn nicht verwitwet ist Israel noch Juda von seinem Gott, von dem HERRN der Heerscharen*; denn deren Land ist voll Schuld wegen des Heiligen Israels.", footnotes: ["℘ V. 19; Kap. 14,19; Jes 49,15; 51,15; Hos 2,1-3; Sach 2,16"] },
      { number: 6, text: "Flieht aus Babel hinaus und rettet euch, jeder rette sein Leben*, dass ihr in seiner Schuld nicht umkommt*! Denn es ist die Zeit der Rache des HERRN; was es getan hat, vergilt er ihm*.", footnotes: ["o. seine Seele\n℘ V. 45.50; Kap. 48,6; Offb 18,4", "o. haltet nicht still in seiner Schuld\n℘ 4Mo 16,26", "℘ V. 56; Ps 94,1"] },
      { number: 7, text: "Babel war ein goldener Becher in der Hand des HERRN, der die ganze Erde berauschte. Von seinem Wein haben die Nationen getrunken, darum sind die Nationen wie toll geworden*.", footnotes: ["℘ Kap. 25,16.27; Offb 14,8"] },
      { number: 8, text: "Plötzlich ist Babel gefallen und zertrümmert. Jammert über es! Holt Balsam für seinen Schmerz*! Vielleicht wird es geheilt werden!", footnotes: ["℘ Kap. 46,11"] },
      { number: 9, text: "»Wir haben Babel heilen wollen, aber es war nicht zu heilen. Verlasst es und lasst uns jeder in sein Land ziehen! Denn sein Gericht reicht bis an den Himmel und erhebt sich bis zu den Wolken*.«", footnotes: ["℘ Offb 18,5"] },
      { number: 10, text: "Der HERR hat unsere Gerechtigkeiten ans Licht gebracht*. Kommt und lasst uns in Zion die Tat des HERRN, unseres Gottes, erzählen!*", footnotes: ["℘ Ps 37,6; Mi 7,9", "℘ Ps 66,16; 118,17; Jes 24,14"] },
      { number: 11, text: "Schärft die Pfeile, fasst die Schilde! Der HERR hat den Geist der Könige von Medien erweckt*. Denn gegen Babel ist sein Plan gerichtet, es zu zerstören; denn es ist die Rache des HERRN, die Rache für seinen Tempel.", footnotes: ["℘ V. 28"] },
      { number: 12, text: "Richtet das Feldzeichen* gegen die Mauern von Babel auf, verschärft die Bewachung*, stellt Wächter auf, bereitet die Hinterhalte! Denn wie der HERR es sich vorgenommen, so führt er aus, was er über die Bewohner von Babel geredet hat*.", footnotes: ["℘ Jes 11,12", "o. Belagerung", "℘ V. 29"] },
      { number: 13, text: "Die du an vielen Wassern wohnst*, reich an Schätzen, dein Ende ist gekommen, das Maß deines ungerechten Gewinns*.", footnotes: ["℘ Ps 137,1; Offb 17,1.15", "w. die Elle deines Schnittes; d. h. viell. auch: die Elle, mit der dein Leben abgeschnitten wird\n℘ Hab 2,8"] },
      { number: 14, text: "Der HERR der Heerscharen hat bei sich selbst geschworen*: Wenn ich dich auch mit Menschen angefüllt habe wie mit Heuschrecken*, so wird man doch Triumphgeschrei* über dich anstimmen.", footnotes: ["℘ Kap. 44,26; Am 6,8", "hebr. jäläq; das sind kriechende, noch ungeflügelte Heuschrecken\n℘ Ri 6,5", "o. den Kriegsruf"] },
      { number: 15, text: "*Er ist es, der die Erde gemacht hat durch seine Kraft, der den Erdkreis gegründet durch seine Weisheit und den Himmel ausgespannt durch seine Einsicht*,", footnotes: ["℘ V. 15-19: Kap. 10,12-16", "℘ Jes 44,24; 48,13; Röm 4,17"] },
      { number: 16, text: "auf dessen Befehl sich die Menge des Wassers am Himmel ergießt*, der Wolken aufsteigen lässt vom Ende der Erde, Blitze macht für den Regen und den Wind aus seinen Kammern* herauslässt!", footnotes: ["T.; andere üs. mit Textänderung: Wenn er die Stimme erhebt, gibt es Wasserrauschen am Himmel; Mas. T.: Bei der Stimme seines Erhebens gibt es eine Menge (o. ein Rauschen) des Wassers am Himmel", "w. aus seinen Vorräten o. Vorratskammern"] },
      { number: 17, text: "Dumm steht da jeder Mensch, ohne Erkenntnis, beschämt jeder Goldschmied wegen des Götterbildes. Denn Lüge sind seine gegossenen Bilder, Leben haben sie nicht*.", footnotes: ["o. Denn ein Trugbild hat er gegossen, es ist kein Atem darin\n℘ Ps 115,5-7"] },
      { number: 18, text: "Ein Nichts sind sie, ein Werk zum Gespött: zur Zeit ihrer Heimsuchung sind sie verloren*.", footnotes: ["℘ Kap. 10,11; Jes 2,18; 57,12; Hes 6,6"] },
      { number: 19, text: "Jakobs Anteil ist nicht wie diese*. Denn er, der HERR, ist es, der das All gebildet hat* und den Stamm seines Erbteils*. Jahwe der Heerscharen ist sein Name*.", footnotes: ["℘ Ps 135,4", "℘ Jes 51,13", "viell. ist zu lesen wie Kap. 10,16: Israel ist der Stamm seines Erbteils", "℘ V. 5"] },
      { number: 20, text: "Du bist mir ein Hammer, eine Kriegswaffe, und mit dir zerhämmere ich Nationen, und mit dir zerstöre ich Königreiche," },
      { number: 21, text: "und mit dir zerhämmere ich Ross und Reiter, und mit dir zerhämmere ich den Wagen und seinen Lenker*,", footnotes: ["w. und den darauf Fahrenden"] },
      { number: 22, text: "und mit dir zerhämmere ich Mann und Frau, und mit dir zerhämmere ich Greis und Knaben, und mit dir zerhämmere ich Jüngling und die Jungfrau*,", footnotes: ["℘ Kla 2,21"] },
      { number: 23, text: "und mit dir zerhämmere ich den Hirten und seine Herde, und mit dir zerhämmere ich den Bauern und sein Gespann, und mit dir zerhämmere ich Statthalter und Befehlshaber." },
      { number: 24, text: "Und ich will Babel und allen Bewohnern Chaldäas all ihr Böses, das sie an Zion verübt haben, vor euren Augen vergelten*, spricht der HERR*.", footnotes: ["℘ V. 35.49; Ps 79,10", "w. ist der Ausspruch des HERRN"] },
      { number: 25, text: "Siehe, ich will an dich, spricht der HERR*, du Berg des Verderbens, der die ganze Erde verdirbt*. Und ich will meine Hand gegen dich ausstrecken und dich von den Felsen hinabwälzen und dich zu einem verbrannten Berg machen*,", footnotes: ["w. ist der Ausspruch des HERRN", "o. verdarb", "℘ Kap. 25,12"] },
      { number: 26, text: "so dass man von dir weder Eckstein noch Grundstein nehmen kann. Denn eine ewige Trümmerstätte* sollst du sein*, spricht der HERR*.", footnotes: ["w. ewige Einöden", "℘ Kap. 25,12", "w. ist der Ausspruch des HERRN"] },
      { number: 27, text: "Richtet das Feldzeichen im Land auf, stoßt ins Horn unter den Nationen! Heiligt Nationen gegen es zum Krieg*, ruft gegen es die Königreiche Ararat*, Minni* und Aschkenas* herbei! Bestellt Kriegsoberste* gegen es, lasst Pferde heraufziehen wie furchtbare* Heuschrecken*!", footnotes: ["℘ Kap. 25,14", "℘ 1Mo 8,4; Jes 37,38", "d. i. ein Name von Armenien", "d. i. eine Landschaft in der Nähe von Armenien\n℘ 1Mo 10,3", "d. i. ein assyr. Beamtentitel; w. Schreiber; hier aber im Gegensatz zu Nah 3,17 militärisch gemeint", "o. borstige", "hebr. jäläq; das sind kriechende, noch ungeflügelte Heuschrecken"] },
      { number: 28, text: "Heiligt Nationen gegen es zum Krieg, die Könige von Medien*, dessen Statthalter und alle seine Befehlshaber und das ganze Land ihrer* Herrschaft!", footnotes: ["℘ V. 11; Dan 5,28; 6,1", "w. seiner; d. i. des obersten Königs der Meder"] },
      { number: 29, text: "Da erbebt und erzittert die Erde*. Denn die Pläne des HERRN erfüllen sich gegen Babel*, um das Land Babel zu einer Wüste* zu machen, ohne Bewohner*.", footnotes: ["℘ Jes 24,20", "℘ V. 12", "o. zum Schreckensort", "℘ V. 26.37"] },
      { number: 30, text: "Babels Helden haben aufgehört zu kämpfen, sie sitzen in den Bergfestungen. Versiegt ist ihre Kraft, sie sind zu Weibern geworden*. Man hat ihre Wohnungen angezündet, ihre Riegel sind zerbrochen*.", footnotes: ["℘ Jes 19,16", "℘ Jes 45,2; Nah 3,13"] },
      { number: 31, text: "Ein Läufer läuft dem anderen entgegen* und der Bote dem Boten, um dem König von Babel die Botschaft zu bringen, dass seine Stadt von allen Seiten her eingenommen ist.", footnotes: ["w. entgegen einem Läufer; d. h. sie kommen von allen Seiten her"] },
      { number: 32, text: "Und die Übergänge sind besetzt, und die Festungen* hat man mit Feuer ausgebrannt, und die Kriegsleute sind vor Schrecken erstarrt. —", footnotes: ["o. Schilfteiche"] },
      { number: 33, text: "Denn so spricht der HERR der Heerscharen, der Gott Israels: Die Tochter Babel ist wie eine Tenne zur Zeit, da man sie stampft. Noch kurze Zeit*, dann kommt die Zeit der Ernte für sie*.", footnotes: ["w. Um ein Kleines", "℘ Joe 4,13; Mi 4,12"] },
      { number: 34, text: "Nebukadnezar, der König von Babel, hat mich gefressen, hat mich vernichtet, hat mich weggestellt als leeres Gefäß*. Er verschlang mich wie ein Ungeheuer, füllte seinen Bauch mit meinen Leckerbissen*, stieß mich fort.", footnotes: ["d. h. menschenleer gemacht", "℘ V. 44; Kap. 50,17; Kla 2,16"] },
      { number: 35, text: "Die an mir begangene Gewalttat und meine Zerfleischung* komme über Babel — soll die Bewohnerin von Zion sagen — und mein Blut über die Bewohner von Chaldäa, soll Jerusalem sagen*.", footnotes: ["w. Fleisch", "℘ V. 24; Kla 1,22"] },
      { number: 36, text: "Darum, so spricht der HERR: Siehe, ich will deinen Rechtsstreit führen und deine Rache vollziehen*, und ich werde sein Meer* austrocknen und seine Quelle versiegen lassen*.", footnotes: ["℘ 5Mo 32,43", "d. i. eine im Altertum gebräuchliche Bezeichnung für große Ströme; hier ist der Euphrat gemeint; vgl. Anm. zu Jes 18,2 und 19,5", "℘ Jes 19,5; Offb 16,12"] },
      { number: 37, text: "Und Babel soll zum Steinhaufen, zur Wohnung der Schakale, zum Entsetzen und zum Gezisch* werden, ohne Bewohner*.", footnotes: ["Gemeint ist wohl ein Pfeifen oder Zischen, das angesichts eines erschreckenden Anblicks Verachtung oder Furcht ausdrücken soll.", "℘ V. 29; Kap. 18,16; Jes 34,13.14"] },
      { number: 38, text: "Sie brüllen alle zusammen wie Junglöwen, knurren wie die Jungen der Löwinnen." },
      { number: 39, text: "Wenn sie erhitzt sind, richte ich ihnen ein Trinkgelage an und mache sie betrunken, so dass sie jubeln und entschlafen zu ewigem Schlaf und nicht mehr erwachen, spricht der HERR*.", footnotes: ["w. ist der Ausspruch des HERRN\n℘ V. 57; Dan 5,1-4.30; Nah 3,18"] },
      { number: 40, text: "Wie Lämmer führe ich sie zur Schlachtung hinab, wie Widder zusammen mit den Böcken. —" },
      { number: 41, text: "Wie ist Scheschach* eingenommen* und der Ruhm der ganzen Erde erobert! Wie ist Babel zum Entsetzen geworden unter den Nationen!", footnotes: ["d. i. eine durch künstliche Buchstabenversetzung entstandene Bezeichnung für Babel", "℘ Kap. 25,26"] },
      { number: 42, text: "Das Meer ist heraufgestiegen über Babel; mit dem Brausen seiner Wellen ist es bedeckt*.", footnotes: ["℘ Jes 8,7.8; Hes 26,3; Dan 7,2"] },
      { number: 43, text: "Seine Städte sind zur Wüste* geworden, ein dürres Land und eine Steppe, ein Land, worin niemand wohnt* und durch das kein Menschenkind zieht*.", footnotes: ["o. zum Schreckensort", "℘ V. 62", "℘ V. 29; Kap. 18,16; Jes 34,13.14"] },
      { number: 44, text: "Und ich werde den Bel zu Babel heimsuchen und aus seinem Maul herausnehmen, was er verschlungen hat*; und Nationen sollen nicht mehr zu ihm strömen. Auch die Mauer von Babel ist gefallen*.", footnotes: ["℘ V. 34; Hi 20,15", "℘ V. 58"] },
      { number: 45, text: "Zieht aus ihm hinaus*, mein Volk, und rettet euch, jeder sein Leben, vor der Zornesglut des HERRN*!", footnotes: ["℘ 2Kor 6,17; Offb 18,4", "℘ V. 6"] },
      { number: 46, text: "Und dass euer Herz nicht zaghaft werde und ihr euch nicht fürchtet vor der Nachricht, die im Land vernommen wird! Denn in dem einen Jahr kommt diese Nachricht und in dem Jahr danach jene Nachricht. Und Gewalttat ist im Land, Herrscher folgt auf Herrscher*.", footnotes: ["℘ Mk 13,7.8"] },
      { number: 47, text: "Darum siehe, Tage kommen, da werde ich die Götterbilder Babels heimsuchen*. Sein ganzes Land wird zuschanden werden, und alle seine Erschlagenen werden in seiner Mitte fallen.", footnotes: ["℘ V. 52; Jes 21,9"] },
      { number: 48, text: "Und Himmel und Erde, und alles, was in ihnen ist, werden jubeln über Babel*. Denn von Norden her kommen ihm die Verwüster, spricht der HERR*.", footnotes: ["℘ Spr 11,10; Offb 18,20", "w. ist der Ausspruch des HERRN"] },
      { number: 49, text: "Wie Babel darauf ausging, dass Erschlagene Israels fielen, so werden wegen Babel Erschlagene auf der ganzen Erde fallen*. —", footnotes: ["℘ V. 24"] },
      { number: 50, text: "Ihr, die dem Schwert Entkommenen, geht, bleibt nicht stehen*! Denkt an den HERRN aus der Ferne, und Jerusalem komme euch in den Sinn!* —", footnotes: ["℘ V. 6", "℘ Kap. 29,12-14; Ps 137,5.6; Hes 6,9; Dan 6,11"] },
      { number: 51, text: "Wir sind beschämt, denn wir haben Verhöhnung gehört*; Schmach hat unser Gesicht bedeckt*. Denn Fremde sind über die Heiligtümer des Hauses des HERRN gekommen*. —", footnotes: ["℘ Ps 79,4", "℘ Kla 5,1", "℘ Ps 79,1; Kla 1,10"] },
      { number: 52, text: "Darum siehe, Tage kommen, spricht der HERR*, da ich seine Götzenbilder heimsuchen werde. Und tödlich Verwundete werden stöhnen in seinem ganzen Land*.", footnotes: ["w. ist der Ausspruch des HERRN", "℘ V. 47.49"] },
      { number: 53, text: "Wenn auch Babel bis zum Himmel hinaufstiege und seine starke Höhe unersteigbar machte, so würden ihm von mir her doch Verwüster kommen*, spricht der HERR*.", footnotes: ["℘ V. 1-4; Kap. 49,16; Hab 2,9", "w. ist der Ausspruch des HERRN"] },
      { number: 54, text: "Horch! Ein Geschrei aus Babel und großer Zusammenbruch vom Land der Chaldäer her!" },
      { number: 55, text: "Denn der HERR verwüstet Babel und lässt aus ihm den lauten Schall verloren gehen. Und es brausen seine Wogen wie gewaltige Wasser, es ertönt der Schall ihres Tosens." },
      { number: 56, text: "Denn über es, über Babel, kommt ein Verwüster. Und seine Helden werden gefangen, ihre Bogen sind zerbrochen*. Denn ein Gott der Vergeltung ist der HERR, er wird bestimmt vergelten*.", footnotes: ["℘ 1Sam 2,4; Ps 37,15", "℘ V. 6.24; Ps 94,1.2; Kla 3,64"] },
      { number: 57, text: "Und ich mache seine Obersten betrunken und seine Weisen, seine Statthalter und seine Befehlshaber und seine Helden, dass sie entschlafen zu ewigem Schlaf und nicht mehr erwachen*, spricht der König*, HERR der Heerscharen ist sein Name*.", footnotes: ["℘ V. 39", "w. ist der Ausspruch des Königs", "℘ Kap. 46,18"] },
      { number: 58, text: "So spricht der HERR der Heerscharen: Die Mauern des großen Babel* sollen vollständig geschleift* und seine hohen Tore mit Feuer verbrannt werden. — Und so mühen sich Völker für nichts und Völkerschaften fürs Feuer, und sie ermüden*.", footnotes: ["o. Die weiten Mauern von Babel", "℘ V. 44", "℘ Hab 2,13"] },
      { number: 59, text: "Das Wort, das der Prophet Jeremia Seraja, dem Sohn Nerijas*, des Sohnes Machsejas, befahl, als der mit Zedekia, dem König von Juda, im vierten Jahr seiner Regierung nach Babel zog*; Seraja war Reisemarschall*.", heading: "Jeremias Anweisung, die Unheilsschrift über Babel nach ihrer Verlesung im Euphrat zu versenken", footnotes: ["℘ Kap. 32,12", "℘ Esr 5,12", "w. Oberster des Ruheortes"] },
      { number: 60, text: "Und Jeremia schrieb in ein einziges Buch* all das Unheil, das über Babel kommen sollte, alle diese Worte, die gegen Babel geschrieben sind*.", footnotes: ["℘ Kap. 30,2", "℘ Kap. 50; 51,1-58"] },
      { number: 61, text: "Und Jeremia sagte zu Seraja: Wenn du nach Babel kommst, so sieh zu und lies all diese Worte" },
      { number: 62, text: "und sprich: HERR, du selbst hast gegen diesen Ort geredet, dass du ihn ausrotten wirst, so dass kein Bewohner mehr darin sein soll, weder Mensch noch Vieh, sondern dass er zu einer ewigen Trümmerstätte* werden soll*.", footnotes: ["w. zu ewigen Einöden", "℘ V. 29.43; Kap. 25,12; 50,3.12"] },
      { number: 63, text: "Und es soll geschehen, wenn du dieses Buch zu Ende gelesen hast, so binde einen Stein daran und wirf es mitten in den Euphrat*", footnotes: ["℘ Kap. 13,4; 19,10; Offb 18,21"] },
      { number: 64, text: "und sage: So wird Babel versinken und nicht wieder hochkommen wegen des Unheils, das ich über es bringe; und sie werden ermüden*. Bis hierher gehen die Worte Jeremias.", footnotes: ["℘ Kap. 13,4; 19,10; Offb 18,21"] },
    ]},
    { number: 52, verses: [
      { number: 1, text: "*Einundzwanzig Jahre war Zedekia alt, als er König wurde, und er regierte elf Jahre in Jerusalem. Und der Name seiner Mutter war Hamutal, die Tochter Jirmejas aus Libna.", heading: "Belagerung Jerusalems — Flucht und Gefangennahme des Königs Zedekia", footnotes: ["℘ V. 1-27: Kap. 39,1-10; V. 1-30: 2Kö 24,18-20; 25,1-21; 2Chr 36,11-21"] },
      { number: 2, text: "Und er tat, was böse war in den Augen des HERRN, nach allem, was Jojakim getan hatte." },
      { number: 3, text: "Denn wegen des Zornes des HERRN kam es in Jerusalem und Juda dahin, dass er sie von seinem Angesicht verwarf*. Und Zedekia empörte sich gegen den König von Babel.", footnotes: ["℘ 2Kö 17,20.23; Esr 4,15"] },
      { number: 4, text: "Und es geschah im neunten Jahr seiner Regierung, im zehnten Monat, am Zehnten des Monats, da kamen Nebukadnezar, der König von Babel, er und sein ganzes Heer, gegen Jerusalem und belagerte es*; und sie bauten Belagerungstürme gegen es ringsumher*.", footnotes: ["w. und schlugen ihre Zelte gegen es auf", "℘ Kap. 4,17; 21,2; Hes 21,27"] },
      { number: 5, text: "So kam die Stadt in Belagerung bis ins elfte Jahr des Königs Zedekia." },
      { number: 6, text: "Im vierten Monat*, am Neunten des Monats, als der Hunger in der Stadt überhand genommen hatte und kein Brot mehr da war für das Volk des Landes*,", footnotes: ["℘ Sach 8,19", "℘ Kap. 37,21; Kla 1,11"] },
      { number: 7, text: "da wurde die Stadtmauer aufgebrochen. Und alle Kriegsleute flohen und zogen nachts aus der Stadt hinaus auf dem Weg durch das Tor, das zwischen den beiden Mauern beim Garten des Königs war — die Chaldäer aber waren rings um die Stadt her —, und sie zogen den Weg zur Steppe*.", footnotes: ["hebr. Araba; s. Anm. zu 5Mo 1,1"] },
      { number: 8, text: "Aber das Heer der Chaldäer jagte dem König nach, und sie holten Zedekia ein in den Steppen von Jericho; und sein ganzes Heer zerstreute sich von ihm weg." },
      { number: 9, text: "Und sie ergriffen den König und führten ihn hinauf zum König von Babel, nach Ribla im Land Hamat*, und der sprach das Urteil über ihn.", footnotes: ["℘ Kla 4,20"] },
      { number: 10, text: "Und der König von Babel schlachtete die Söhne Zedekias vor dessen Augen, und er schlachtete auch alle Obersten von Juda in Ribla*.", footnotes: ["℘ Hes 11,10"] },
      { number: 11, text: "Und er blendete die Augen Zedekias und band ihn mit ehernen Fesseln*. Und der König von Babel brachte ihn nach Babel und setzte ihn in Gewahrsam* bis zum Tag seines Todes*.", footnotes: ["w. bronzenen Doppelfesseln", "w. in das Haus der Wachen", "℘ Kap. 21,7; 34,3; Kla 2,6; Hes 12,13; 23,24"] },
      { number: 12, text: "Und im fünften Monat, am Zehnten des Monats — das war das neunzehnte Jahr des Königs Nebukadnezar, des Königs von Babel — kam Nebusaradan, der Oberste der Leibwache*, der vor dem König von Babel stand*, nach Jerusalem.", heading: "Zerstörung Jerusalems und des Tempels — Wegführung nach Babel", footnotes: ["℘ Kap. 39,11", "d. h. der persönlich Zutritt zum König hatte"] },
      { number: 13, text: "Und er verbrannte das Haus des HERRN und das Haus des Königs; und alle Häuser von Jerusalem und jedes große Haus verbrannte er mit Feuer*.", footnotes: ["℘ Kap. 6,5; 32,29; Ps 74,7; Jes 64,10; Hes 16,41"] },
      { number: 14, text: "Und das ganze Heer der Chaldäer, das bei dem Obersten der Leibwache war, riss alle Mauern von Jerusalem ringsum nieder*.", footnotes: ["℘ Kla 2,6-8"] },
      { number: 15, text: "Und von den Geringen des Volkes und den Rest des Volkes, die in der Stadt Übriggebliebenen, und die Überläufer, die zum König von Babel übergelaufen waren, und den Rest der Handwerker* führte Nebusaradan, der Oberste der Leibwache, gefangen fort*.", footnotes: ["syr. und lat. Üs.: den Rest der Menge", "℘ Kap. 1,3; Hes 12,11"] },
      { number: 16, text: "Aber von den Geringen des Landes ließ Nebusaradan, der Oberste der Leibwache, einige zurück als Weingärtner und als Ackerleute." },
      { number: 17, text: "Und die bronzenen Säulen, die am Haus des HERRN waren, und die Gestelle und das bronzene Meer, die im Haus des HERRN waren, zerschlugen die Chaldäer und nahmen alle Bronze davon mit nach Babel*.", footnotes: ["℘ Kap. 27,22"] },
      { number: 18, text: "Und sie nahmen die Töpfe mit und die Schaufeln und die Messer* und die Sprengschalen und die Schalen und alle bronzenen Geräte, mit denen man den Dienst verrichtete.", footnotes: ["Das sind Messer zum Putzen des Armleuchters."] },
      { number: 19, text: "Auch die Becken, die Feuerbecken* und die Sprengschalen*, die Töpfe, die Leuchter, die Schalen und die Opferschalen, von dem, was aus reinem Gold und was aus reinem Silber war, nahm der Oberste der Leibwache mit.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "℘ 2Chr 4,8"] },
      { number: 20, text: "Ferner die beiden Säulen, das eine Meer und die zwölf bronzenen Rinder darunter und die Gestelle, die der König Salomo für das Haus des HERRN gemacht hatte. Die Bronze all dieser Geräte war nicht zu wiegen." },
      { number: 21, text: "Und die Säulen*: Achtzehn Ellen war die Höhe der einen Säule, und eine Schnur von zwölf Ellen umfasste sie; und ihre Dicke war vier Fingerbreit, sie war hohl.", footnotes: ["℘ 1Kö 7,15-22"] },
      { number: 22, text: "Und ein Kapitell aus Bronze war darauf, und die Höhe des einen Kapitells betrug fünf Ellen. Und Flechtwerk und Granatäpfel waren an dem Kapitell ringsum, alles aus Bronze. Und genauso war es an der anderen Säule, und Granatäpfel waren daran." },
      { number: 23, text: "Es waren 96 Granatäpfel außen angebracht*; zusammen waren hundert Granatäpfel am Flechtwerk ringsum.", footnotes: ["w. nach dem Wind hin"] },
      { number: 24, text: "Und der Oberste der Leibwache nahm den Oberpriester Seraja und Zefanja, den zweiten Priester, und die drei Hüter der Schwelle." },
      { number: 25, text: "Und aus der Stadt nahm er einen Hofbeamten*, der über die Kriegsleute eingesetzt war, und sieben Männer von denen, die ständig um den König waren*, die sich in der Stadt fanden, und den Schreiber des Heerobersten, der das Volk des Landes zum Heeresdienst aushob, und sechzig Mann vom Volk des Landes, die sich in der Stadt fanden.", footnotes: ["w. Eunuchen", "w. die das Gesicht des Königs sahen"] },
      { number: 26, text: "Und Nebusaradan, der Oberste der Leibwache, nahm sie und brachte sie zum König von Babel nach Ribla." },
      { number: 27, text: "Und der König von Babel schlug sie und tötete sie in Ribla im Land Hamat*. — So wurde Juda aus seinem Land gefangen weggeführt.", footnotes: ["℘ Kap. 20,4; 21,7; Jes 43,28"] },
      { number: 28, text: "Das ist das Volk, das Nebukadnezar gefangen weggeführt hat*: Im 7. Jahr 3 023 Judäer,", footnotes: ["℘ Kap. 13,19; 2Kö 24,14-16; Kla 1,5"] },
      { number: 29, text: "im 18. Jahr Nebukadnezars* 832 Seelen aus Jerusalem,", footnotes: ["℘ Kap. 32,1"] },
      { number: 30, text: "im 23. Jahr Nebukadnezars führte Nebusaradan, der Oberste der Leibwache, von den Judäern 745 Seelen gefangen fort; alle Seelen zusammen waren 4 600." },
      { number: 31, text: "*Und es geschah im 37. Jahr der Wegführung Jojachins, des Königs von Juda, im 12. Monat, am 25. des Monats, da erhob Ewil-Merodach, der König von Babel, im ersten Jahr seiner Königsherrschaft das Haupt Jojachins, des Königs von Juda, und führte ihn aus dem Gefängnis.", heading: "Begnadigung des Königs Jojachin", footnotes: ["℘ 2Kö 25,27-30"] },
      { number: 32, text: "Und er redete gütig mit ihm und setzte seinen Thron über den Thron der Könige*, die bei ihm in Babel waren.", footnotes: ["o. und wies ihm seinen Sitz oberhalb des Sitzes der Könige an"] },
      { number: 33, text: "Und Jojachin* durfte seine Gefängniskleidung ablegen. Und er aß beständig vor ihm, alle Tage seines Lebens.", footnotes: ["w. er"] },
      { number: 34, text: "Und sein Unterhalt, ein beständiger Unterhalt, wurde ihm vom König von Babel gegeben, so viel er täglich nötig hatte*, bis zum Tag seines Todes, alle Tage seines Lebens.", footnotes: ["w. das Tägliche an seinem Tag"] },
    ]},
  ]
};
